                string text5Loc = string.Concat(new string[] { text2Loc, " ", text5LocCardName, " wird auf deiner Hand erzeugt. ", text3Loc });
                Translate(GUID, null, text5, text5Loc, Language.German);
                Translate(GUID, null, "While " + value.DisplayedNameLocalized + " is on the board, remove ally Terrain and Pelt cards and transform the rest into random Apostles.", "Solange " + value.DisplayedNameLocalized + " auf dem Brett ist, entferne verbündete Gelände- und Fellkarten und verwandle die übrigen in zufällige Apostel.", Language.German);
                Translate(GUID, null, "[c:bR]The Clock[c:] and your [c:bR]" + value.DisplayedNameLocalized + "[c:] will remain in that abandoned time.", "[c:bR]Die Uhr[c:] und deine Karte [c:bR]" + value.DisplayedNameLocalized + "[c:] bleiben in jener verlassenen Zeit.", Language.German);
                Translate(GUID, null, "False " + value.DisplayedNameLocalized, "Fälschung: " + value.DisplayedNameLocalized, Language.German);
                Translate(GUID, null, "[c:bB]That " + value.DisplayedNameLocalized + " costs more energy than you have.[c:]", "[c:bB]Du hast nicht genug Energie, um " + value.DisplayedNameLocalized + " auszuspielen.[c:]", Language.German);
            }
            if (source == null)
            for (int max = 1; max <= 10; max++)
            {
                Translate(GUID, null, "[c:bB]Do you still not get it? It costs " + max.ToString() + " energy and you don't have enough.[c:]", "[c:bB]Verstehst du es immer noch nicht? Das kostet " + max.ToString() + " Energie, und du hast nicht genug.[c:]", Language.German);
                for (int count = 0; count < max; count++)
                {
                    Translate(GUID, null, "[c:bB]That costs " + max.ToString() + " energy and you have " + count.ToString() + ".[c:]", "[c:bB]Das kostet " + max.ToString() + " Energie, und du hast " + count.ToString() + ".[c:]", Language.German);
                }
            }


            // LifeCostAPI
            if (source == null) Debug.Log("Post Register Translations for LifeCostAPI");
            foreach (var value in cards)
            {
                if (!value.HasDisplayedNameEnglish) continue;
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your [c:bG]Scales[c:] are too tipped to play [c:bG]" + value.DisplayedNameLocalized + "[c:].", "Deine [c:bG]Waage[c:] ist zu stark geneigt, um [c:bG]" + value.DisplayedNameLocalized + "[c:] auszuspielen.", Language.German);
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bG]" + value.DisplayedNameLocalized + "[c:] requires you to pay in life, in which you can not fullfill without killing yourself.", "[c:bG]" + value.DisplayedNameLocalized + "[c:] kostet Leben; du kannst nicht bezahlen, ohne zu sterben.", Language.German);
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You would kill yourself if you played [c:bG]" + value.DisplayedNameLocalized + "[c:]. Your [c:bG]Scales[c:] are too tipped", "Wenn du [c:bG]" + value.DisplayedNameLocalized + "[c:] ausspielst, stirbst du. Deine [c:bG]Waage[c:] ist zu stark geneigt.", Language.German);
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your [c:bG]Scales[c:] are too tipped and you lack the [c:gray]Foils[c:] to play " + value.DisplayedNameLocalized + ".", "Deine [c:bG]Waage[c:] ist zu stark geneigt und dir fehlen [c:gray]Folienkarten[c:], um " + value.DisplayedNameLocalized + " auszuspielen.", Language.German);
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You lack the foils to play that [c:gray]" + value.DisplayedNameLocalized + "[c:].", "Du hast nicht genug Folienkarten, um [c:gray]" + value.DisplayedNameLocalized + "[c:] auszuspielen.", Language.German);
                for (int count = 0; count <= 20; count++)
                {
                    Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:gray]" + value.DisplayedNameLocalized + "[c:] requires you pay it's cost in [c:gray]foils[c:], that which you have [c:gray]" + count.ToString() + "[c:].", "[c:gray]" + value.DisplayedNameLocalized + "[c:] kostet [c:gray]Folienkarten[c:]; du hast [c:gray]" + count.ToString() + "[c:].", Language.German);
                    Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That [c:gray]" + value.DisplayedNameLocalized + "[c:] has the cost of [c:gray]" + count.ToString() + "[c:] foils, which you do not have.", "[c:gray]" + value.DisplayedNameLocalized + "[c:] kostet [c:gray]" + count.ToString() + "[c:] " + (count == 1 ? "Folienkarte" : "Folienkarten") + ", und du hast nicht genug.", Language.German);
                }
            }

            // Sire_MoDeers
            if (source == null) Debug.Log("Post Register Translations for Sire_MoDeers");
            foreach (var value in cards)
            {
                if (!value.HasDisplayedNameEnglish) continue;
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, value.DisplayedName + "'s Protector", "Schutzgeist der Karte „" + value.DisplayedNameLocalized + "“", Language.German);
            }

            if (source == null) Debug.Log("Post Register Translations Ended");
            stopwatch.Stop();
            if (source == null) Debug.Log($"PostRegisterTranslations 执行时间: {stopwatch.ElapsedMilliseconds} ms");
        }

        private static List<PostRegisterCardData> CachePostRegisterCardData(IEnumerable<CardInfo> source)
        {
            var cards = new List<PostRegisterCardData>();
            foreach (var card in source)
            {
                if (card.SafeIsUnityNull()) continue;
                var value = new PostRegisterCardData(card, card.IsBaseGameCard());
                if (MultilingualTranslationRuntime.IncludeCardForPostRegistration(Language.German, value.Name,
                    value.DisplayedName, value.DisplayedNameEnglish, value.DisplayedNameLocalized,
                    value.Attack, value.Health, value.Abilities, value.Description))
                {
                    cards.Add(value);
                }
            }
            return cards;
        }

        private sealed class PostRegisterCardData
        {
            public PostRegisterCardData(CardInfo card, bool isBaseGameCard)
            {
                IsBaseGameCard = isBaseGameCard;
                DisplayedNameEnglish = card.DisplayedNameEnglish;
                DisplayedNameLocalized = card.DisplayedNameLocalized;
                DisplayedName = card.displayedName;
                Description = card.description;
                Name = card.name;
                Attack = card.Attack;
                Health = card.Health;
                Abilities = card.Abilities?.ToArray() ?? Array.Empty<Ability>();
            }

            public bool IsBaseGameCard { get; }
            public string DisplayedNameEnglish { get; }
            public string DisplayedNameLocalized { get; }
            public string DisplayedName { get; }
            public string Description { get; }
            public string Name { get; }
            public int Attack { get; }
            public int Health { get; }
            public Ability[] Abilities { get; }
            public bool HasDisplayedNameEnglish => DisplayedNameEnglish != null;
            public bool HasDisplayedName => DisplayedName != null;
        }
        private static bool NameStartsWithVowel(string name)
        {
            if (string.IsNullOrEmpty(name))
            {
                return false;
            }
            char c = name.ToLowerInvariant()[0];
            return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
        }

    }

