            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PUSH YOUR LUCK FOR ONE MORE ABILITY?\nOR PULL AWAY?", "DEIN GLÜCK FÜR EINE WEITERE FÄHIGKEIT HERAUSFORDERN?\nODER ZURÜCKZIEHEN?", Language.German);

