            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The fourth turn of every battle, all your cards will be Frozen Away.", "Im vierten Zug jedes Kampfes erhalten alle deine Karten Eingefroren.", Language.German);
