    public class MagnificusMod
    {
        public static Dictionary<string, string> Cards = new();
        public static Dictionary<string, List<KeyValuePair<string, string>>> CardsDescription = new();

        public static Dictionary<string, string> Abilities = new();

        public static void RegisterCard(string en, string zh, string desen, string deszh)
        {
            if (!Cards.ContainsKey(en))
            {
                Cards.Add(en, zh);
            }
            if (!CardsDescription.ContainsKey(en))
            {
                CardsDescription[en] = new List<KeyValuePair<string, string>>();
            }
            CardsDescription[en].Add(new KeyValuePair<string, string>(desen, deszh));
        }

        public static void RegisterAbility(string en, string zh)
        {
            Abilities.Add(en, zh);
        }

        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Magnificus Mod");
            // SetText
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "New Magnificus Run", "NEUER MAGNIFICUS-DURCHGANG", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NEW MAGNIFICUS RUN", "NEUER MAGNIFICUS-DURCHGANG", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "View Deck", "Stapel ansehen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TOWER OF MAGICKS", "TURM DER MAGIE", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GOO DUNGEON", "SCHLEIMVERLIES", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LAVA DUNGEON", "LAVAVERLIES", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "VOID DUNGEON", "VERLIES DER LEERE", Language.German);

            // Config
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Automatically unlocks every challenge and starter deck in Magnificus' Kaycees Mod. This does NOT change your magnificus challenge point value. If you have a change of heart and decide to unlock the challenges fairly, your challenge points will remain the same.", "Schaltet automatisch alle Herausforderungen und Startstapel in Magnificus' Kaycee-Mod frei. Deine Magnificus-Herausforderungspunkte werden dadurch NICHT verändert. Wenn du es dir anders überlegst und die Herausforderungen ehrlich freischalten willst, bleiben deine Herausforderungspunkte unverändert.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Base wizard cards from act 2 will keep their original statlines.", "Die normalen Zaubererkarten aus Akt 2 behalten ihre ursprünglichen Werte.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Use the old 2D flat card designs instead of the new 3D models.", "Verwendet die alten flachen 2D-Kartendesigns statt der neuen 3D-Modelle.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Add paint splashes to the background of every card (like in the original magnificus finale).", "Fügt dem Hintergrund jeder Karte Farbspritzer hinzu, wie im ursprünglichen Magnificus-Finale.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Third person perspective for magnificus' game. Disable if you want the classic first person experience.", "Dritte-Person-Perspektive für Magnificus' Spiel. Deaktiviere sie für die klassische Ansicht aus der ersten Person.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Show a grid around the player in tabletop mode.", "Zeigt im Tischmodus ein Raster um den Spieler.", Language.German);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blank Mox", "Leerer Mox", Language.German);
            RegisterAbility("Blank Mox", "Leerer Mox");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is drawn, it will materialize into a random Mox Crystal. \n When on another card, the card will generate a random Mox Crystal.", "Wenn eine Karte mit diesem Siegel gezogen wird, verwandelt sie sich in einen zufälligen Mox-Kristall. \n Auf einer anderen Karte lässt dieses Siegel die Karte einen zufälligen Mox-Kristall erzeugen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undecided Mox", "Unentschlossener Mox", Language.German);
            RegisterAbility("Undecided Mox", "Unentschlossener Mox");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, select a mox type for this card to provide.", "Wenn eine Karte mit diesem Siegel ausgespielt wird, wähle einen Mox-Typ, den sie bereitstellt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Heart", "Rubinherz", Language.German);
            RegisterAbility("Ruby Heart", "Rubinherz");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates a Ruby Mox in its place.", "Wenn eine Karte mit diesem Siegel stirbt, erzeugt sie an ihrer Stelle einen Rubin-Mox.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sapphire Heart", "Saphirherz", Language.German);
            RegisterAbility("Sapphire Heart", "Saphirherz");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates a Sapphire Mox in its place.", "Wenn eine Karte mit diesem Siegel stirbt, erzeugt sie an ihrer Stelle einen Saphir-Mox.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Marrow", "Knochenmark", Language.German);
            RegisterAbility("Bone Marrow", "Knochenmark");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When one of your non-gem cards perishes, a card bearing this sigil gains 1 power, maxing out at 5.", "Wenn eine deiner Karten, die kein Edelstein ist, stirbt, erhält eine Karte mit diesem Siegel 1 Kraft, bis zu einem Maximum von 5.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stimulation", "Stimulation", Language.German);
            RegisterAbility("Stimulation", "Stimulation");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, a card bearing this sigil gains 1 power, maxing out at 4.", "Am Ende jedes Zugs erhält eine Karte mit diesem Siegel 1 Kraft, bis zu einem Maximum von 4.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stimulation (Health)", "Gesundheitsstimulation", Language.German);
            RegisterAbility("Stimulation (Health)", "Gesundheitsstimulation");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, a card bearing this sigil gains 2 health, maxes out at 10.", "Am Ende jedes Zugs erhält eine Karte mit diesem Siegel 2 Gesundheit, bis zu einem Maximum von 10.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Draw", "Todeszug", Language.German);
            RegisterAbility("Dead Draw", "Todeszug");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-gem card dies, draw a card from your deck.", "Wenn eine Karte stirbt, die kein Edelstein ist, ziehe eine Karte von deinem Stapel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Heart", "Smaragdherz", Language.German);
            RegisterAbility("Emerald Heart", "Smaragdherz");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates an Emerald Mox in its place.", "Wenn eine Karte mit diesem Siegel stirbt, erzeugt sie an ihrer Stelle einen Smaragd-Mox.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gooey", "Schleimig", Language.German);
            RegisterAbility("Gooey", "Schleimig");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is struck, the striker loses 1 attack.", "Wenn eine Karte mit diesem Siegel getroffen wird, verliert der Angreifer 1 Kraft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mental Gemnastics", "Edelstein-Meditation", Language.German);
            RegisterAbility("Mental Gemnastics", "Edelstein-Meditation");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw cards from your deck based on how many Gems are on the board.", "Wenn eine Karte mit diesem Siegel ausgespielt wird, ziehe für jeden Edelstein auf dem Brett eine Karte von deinem Stapel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loot", "Plünderer", Language.German);
            RegisterAbility("Loot", "Plünderer");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals direct damage, draw cards from your deck based on how much damage was dealt.", "Wenn eine Karte mit diesem Siegel direkten Schaden zufügt, ziehe für jeden zugefügten Schadenspunkt eine Karte von deinem Stapel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Life Steal", "Lebensraub", Language.German);
            RegisterAbility("Life Steal", "Lebensraub");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals direct damage, the amount dealt will be healed to the owner of this card.", "Wenn eine Karte mit diesem Siegel direkten Schaden zufügt, wird ihr Besitzer um die zugefügte Menge geheilt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Knockback Hit", "Rückstoßtreffer", Language.German);
            RegisterAbility("Knockback Hit", "Rückstoßtreffer");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil hits an opposing card, the opposing card will be kicked in the direction inscrybed in the sigil.", "Wenn eine Karte mit diesem Siegel eine gegnerische Karte trifft, wird diese in die auf dem Siegel angegebene Richtung gestoßen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Impaled", "Aufspießen", Language.German);
            RegisterAbility("Impaled", "Aufspießen");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates a Spear in its placed. A spear is defined as Sharp, 0 power, 3 health.", "Wenn eine Karte mit diesem Siegel stirbt, erzeugt sie an ihrer Stelle einen Speer. Ein Speer hat Spitze Stacheln, 0 Kraft und 3 Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magnus Mox", "Magnus Mox", Language.German);
            RegisterAbility("Magnus Mox", "Magnus Mox");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While a card bearing this sigil is on the board, it provides an orange gem, a blue gem and a green gem to its owner.", "Solange eine Karte mit diesem Siegel auf dem Brett ist, stellt sie ihrem Besitzer einen orangen, einen blauen und einen grünen Edelstein bereit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Resurrection", "Auferstehung", Language.German);
            RegisterAbility("Resurrection", "Auferstehung");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-gem card perishes, the dead card will be brought back to life, but this card loses 3 health.", "Wenn eine Karte stirbt, die kein Edelstein ist, wird die tote Karte wiederbelebt. Die Karte mit diesem Siegel verliert dabei 3 Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rerolls", "Würfelwiederholungen", Language.German);
            RegisterAbility("Rerolls", "Würfelwiederholungen");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, a card bearing this sigils' base power will be increased by a random value between 0 and 3.", "Am Ende jedes Zugs wird die Grundkraft einer Karte mit diesem Siegel auf einen zufälligen Wert zwischen 0 und 3 gesetzt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Steel Trap", "Stahlfalle", Language.German);
            RegisterAbility("Steel Trap", "Stahlfalle");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, the opposing card also perishes.", "Wenn eine Karte mit diesem Siegel stirbt, stirbt auch die gegenüberliegende Karte.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Shield", "Edelsteinschild", Language.German);
            RegisterAbility("Gem Shield", "Edelsteinschild");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, all gems on the board gain a shield.", "Wenn eine Karte mit diesem Siegel ausgespielt wird, erhalten alle Edelsteine auf dem Brett einen Schild.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plating Work", "Beschichtungsarbeit", Language.German);
            RegisterAbility("Plating Work", "Beschichtungsarbeit");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While a card bearing this sigil is on the board, all gems on your side of the board gain the Sharp Quills sigil, and 2 health.", "Solange eine Karte mit diesem Siegel auf dem Brett ist, erhalten alle Edelsteine auf deiner Brettseite das Siegel Spitze Stacheln und 2 Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Animator", "Puppenspieler", Language.German);
            RegisterAbility("Animator", "Puppenspieler");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While a card bearing this sigil is on the board, all non-mox cards with 0 power gain 2 power", "Solange eine Karte mit diesem Siegel auf dem Brett ist, erhalten alle Nicht-Mox-Karten mit 0 Kraft zusätzlich 2 Kraft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Absorber", "Edelsteinabsorber", Language.German);
            RegisterAbility("Gem Absorber", "Edelsteinabsorber");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, all gems on your side of the board will perish. For each gem absorbed, gain 1 power and 2 health.", "Wenn eine Karte mit diesem Siegel ausgespielt wird, sterben alle Edelsteine auf deiner Brettseite. Für jeden absorbierten Edelstein erhält diese Karte 1 Kraft und 2 Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Submerge", "Abtauchen", Language.German);
            RegisterAbility("Submerge", "Abtauchen");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, a card bearing this sigil will submerge. Upon resubmerging, this card will become a random Tentacle Card.", "Am Ende des Zugs taucht eine Karte mit diesem Siegel ab. Wenn sie wieder auftaucht, wird sie zu einer zufälligen Tentakelkarte.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Familiar", "Vertrauter", Language.German);
            RegisterAbility("Familiar", "Vertrauter");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will perish if there are no non-gem cards on the board.", "Eine Karte mit diesem Siegel stirbt, wenn keine Karten auf dem Brett sind, die keine Edelsteine sind.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fading", "Verblassen", Language.German);
            RegisterAbility("Fading", "Verblassen");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will perish at the end of the turn.", "Eine Karte mit diesem Siegel stirbt am Ende des Zugs.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Morph", "Wandel", Language.German);
            RegisterAbility("Morph", "Wandel");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, it will mimic the card opposing it. If there is no card opposing it, this card will perish.", "Wenn eine Karte mit diesem Siegel ausgespielt wird, ahmt sie die gegenüberliegende Karte nach. Gibt es dort keine Karte, stirbt sie.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiplication", "Matrixmultiplikation", Language.German);
            RegisterAbility("Multiplication", "Matrixmultiplikation");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw another of this card, but with a different gem cost.", "Wenn eine Karte mit diesem Siegel ausgespielt wird, ziehe eine weitere Ausführung dieser Karte mit anderen Edelsteinkosten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Cycle", "Moxkreislauf", Language.German);
            RegisterAbility("Mox Cycle", "Moxkreislauf");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, all the mox on the board will cycle into different gems.", "Am Ende jedes Zugs wechseln alle Mox auf dem Brett zyklisch zu anderen Edelsteinen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Strafe", "Moxspur", Language.German);
            RegisterAbility("Mox Strafe", "Moxspur");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, this card will move to the direction inscrybed on the sigil, and leave behind a mox.", "Am Ende des Zugs zieht diese Karte in die auf dem Siegel angegebene Richtung und lässt einen Mox zurück.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Purist", "Purismus", Language.German);
            RegisterAbility("Purist", "Purismus");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Any card directly opposing this one will have all it's sigils removed.", "Jede dieser Karte direkt gegenüberliegende Karte verliert alle ihre Siegel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brewery", "Brauerei", Language.German);
            RegisterAbility("Brewery", "Brauerei");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, you automatically draw a mox card from your side deck.", "Am Ende jedes Zugs ziehst du automatisch eine Mox-Karte von deinem Nebenstapel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignite", "Entfachen", Language.German);
            RegisterAbility("Ignite", "Entfachen");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, every empty opposing slot will be filled with flames. A flame is defined as a 0/1, Annoying.", "Wenn eine Karte mit diesem Siegel ausgespielt wird, wird jedes leere gegnerische Feld mit Magischen Flammen gefüllt. Eine Magische Flamme ist eine 0/1-Karte mit Nervig.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Projection", "Sternenprojektion", Language.German);
            RegisterAbility("Projection", "Sternenprojektion");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is stuck, it will move and leave behind an astral projection of itself.", "Wenn eine Karte mit diesem Siegel getroffen wird, bewegt sie sich und lässt eine Astralprojektion ihrer selbst zurück.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell Book", "Zauberbuch", Language.German);
            RegisterAbility("Spell Book", "Zauberbuch");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw a random spell card.", "Wenn eine Karte mit diesem Siegel ausgespielt wird, ziehe eine zufällige Zauberkarte.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scholar", "Zaubergelehrter", Language.German);
            RegisterAbility("Scholar", "Zaubergelehrter");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw a random one of Bleene's Books.", "Wenn eine Karte mit diesem Siegel ausgespielt wird, ziehe zufällig eines von Blüns Büchern.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Midas' Touch", "Midasberührung", Language.German);
            RegisterAbility("Midas' Touch", "Midasberührung");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil attacks another card, the attacked card will lose all of it's attack and turn to gold.", "Wenn eine Karte mit diesem Siegel eine andere Karte angreift, verliert die angegriffene Karte ihre gesamte Kraft und wird zu Gold.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Made of Gold", "Aus Gold", Language.German);
            RegisterAbility("Made of Gold", "Aus Gold");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, the killer will gain 2 crystals.", "Wenn eine Karte mit diesem Siegel stirbt, erhält ihr Mörder 2 Kristalle.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summon Runes", "Beschwörungsrunen", Language.German);
            RegisterAbility("Summon Runes", "Beschwörungsrunen");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, it will summon two runes beside it. A rune is defined as 0 power, 1 health, Detonator.", "Wenn eine Karte mit diesem Siegel ausgespielt wird, beschwört sie zwei Runen neben sich. Eine Rune hat 0 Kraft, 1 Gesundheit und Explosiv.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Health", "Gesundheitszauber", Language.German);
            RegisterAbility("Spell of Health", "Gesundheitszauber");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards on your side of the board gain +2 health.", "Wenn ein Zauber mit diesem Siegel ausgespielt wird, erhalten alle Karten auf deiner Brettseite +2 Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Attack", "Angriffszauber", Language.German);
            RegisterAbility("Spell of Attack", "Angriffszauber");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards on your side of the board gain +1 attack.", "Wenn ein Zauber mit diesem Siegel ausgespielt wird, erhalten alle Karten auf deiner Brettseite +1 Kraft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frost Spell", "Frostzauber", Language.German);
            RegisterAbility("Frost Spell", "Frostzauber");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards belonging to the opponent will have their attack set to 0, but given +2 health.", "Wenn ein Zauber mit diesem Siegel ausgespielt wird, wird die Kraft aller gegnerischen Karten auf 0 gesetzt, aber sie erhalten +2 Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Wind", "Windzauber", Language.German);
            RegisterAbility("Spell of Wind", "Windzauber");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards on your side of the board will become airborne.", "Wenn ein Zauber mit diesem Siegel ausgespielt wird, erhalten alle Karten auf deiner Brettseite Flugfähig.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruckus", "Uhrzeigertrubel", Language.German);
            RegisterAbility("Ruckus", "Uhrzeigertrubel");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, all cards on the board will move clockwise.", "Wenn eine Karte mit diesem Siegel ausgespielt wird, bewegen sich alle Karten auf dem Brett im Uhrzeigersinn.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Water", "Wasserzauber", Language.German);
            RegisterAbility("Spell of Water", "Wasserzauber");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, every card on the board will have their sigils erased.", "Wenn ein Zauber mit diesem Siegel ausgespielt wird, werden die Siegel aller Karten auf dem Brett gelöscht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Flame", "Flammenzauber", Language.German);
            RegisterAbility("Spell of Flame", "Flammenzauber");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a side of the board, every card on that side will lose 2 health (without perishing) and have their attack increased by 1.", "Wähle eine Brettseite. Jede Karte auf dieser Seite verliert 2 Gesundheit, ohne zu sterben, und erhält 1 Kraft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Set Ablaze", "In Brand setzen", Language.German);
            RegisterAbility("Set Ablaze", "In Brand setzen");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every card on the opposite side will lose 2 health (without perishing) and have their attack increased by 1.", "Jede Karte auf der gegenüberliegenden Seite verliert 2 Gesundheit, ohne zu sterben, und erhält 1 Kraft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One Time Spell", "Einmalzauber", Language.German);
            RegisterAbility("One Time Spell", "Einmalzauber");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When the turn ends, a spell bearing this sigil will perish and be removed from your deck.", "Wenn der Zug endet, stirbt ein Zauber mit diesem Siegel und wird aus deinem Stapel entfernt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vase of Greed", "Vase der Gier", Language.German);
            RegisterAbility("Vase of Greed", "Vase der Gier");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, discard your current hand and draw 4 new cards.", "Wenn ein Zauber mit diesem Siegel ausgespielt wird, lege deine aktuellen Handkarten ab und ziehe dann 4 neue Karten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gnomification", "Gnomifizierung", Language.German);
            RegisterAbility("Gnomification", "Gnomifizierung");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a slot to summon a Gnome card in.", "Wähle ein Feld, auf dem eine Gnom-Karte beschworen wird.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cursed", "Verflucht", Language.German);
            RegisterAbility("Cursed", "Verflucht");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, it will immediately perish.", "Wenn ein Zauber mit diesem Siegel ausgespielt wird, stirbt er sofort.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inspiration", "Inspiration", Language.German);
            RegisterAbility("Inspiration", "Inspiration");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to give Airborne + Looter for 1 turn.", "Wähle eine Karte, die für 1 Zug Flugfähig + Plünderer erhält.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Calculus", "Infinitesimalrechnung", Language.German);
            RegisterAbility("Calculus", "Infinitesimalrechnung");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to swap stats.", "Wähle eine Karte, deren Werte vertauscht werden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rage", "Wut", Language.German);
            RegisterAbility("Rage", "Wut");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to kill. The opponent of the card will recieve damage equal to the amount of health the card had.", "Wähle eine Karte zum Töten. Der Gegner dieser Karte erleidet Schaden in Höhe der Gesundheit, die sie hatte.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fireball", "Feuerball", Language.German);
            RegisterAbility("Fireball", "Feuerball");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to take 2 damage.", "Wähle eine Karte, die 2 Schaden erleidet.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cold to the Touch", "Eisige Berührung", Language.German);
            RegisterAbility("Cold to the Touch", "Eisige Berührung");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigils attack another card, that card will lose 1 attack.", "Wenn eine Karte mit diesem Siegel eine andere Karte angreift, verliert diese 1 Kraft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frozen", "Eingefroren", Language.German);
            RegisterAbility("Frozen", "Eingefroren");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn, this card will lose its frozen health. When all frozen health is depleted, or this card is struck, it will defrost.", "Am Ende jedes Zugs verliert diese Karte ihre gefrorene Gesundheit. Ist die gesamte gefrorene Gesundheit aufgebraucht oder wird diese Karte getroffen, taut sie auf.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strong Pull", "Starker Zug", Language.German);
            RegisterAbility("Strong Pull", "Starker Zug");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every opposing card will be inclined to hit this card instead of any other.", "Jede gegnerische Karte wird bevorzugt diese Karte statt einer anderen treffen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Displacement", "Verdrängung", Language.German);
            RegisterAbility("Displacement", "Verdrängung");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is drawn, another of this card will be added randomly into your deck", "Wenn eine Karte mit diesem Siegel gezogen wird, wird eine weitere Ausführung dieser Karte an einer zufälligen Stelle in deinen Stapel eingefügt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Reckoning", "Edelsteinabrechnung", Language.German);
            RegisterAbility("Gem Reckoning", "Edelsteinabrechnung");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn, if the owner of this card does not control any gems, the leftmost card in your hand is discarded.", "Wenn der Besitzer dieser Karte am Ende eines Zugs keine Edelsteine kontrolliert, wird die Karte ganz links auf deiner Hand abgeworfen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Power", "Moxkraft", Language.German);
            RegisterAbility("Mox Power", "Moxkraft");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of Mox Cards that the owner has on their side of the table.", "Der Wert dieses Siegels entspricht der Anzahl der Mox-Karten, die der Besitzer auf seiner Brettseite hat.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Health", "Moxgesundheit", Language.German);
            RegisterAbility("Mox Health", "Moxgesundheit");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of Mox Cards that the owner has on their side of the table.", "Der Wert dieses Siegels entspricht der Anzahl der Mox-Karten, die der Besitzer auf seiner Brettseite hat.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Candle Proximity", "Kerzennähe", Language.German);
            RegisterAbility("Candle Proximity", "Kerzennähe");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to how close this card is to the Candle on the table.", "Der Wert dieses Siegels entspricht der Nähe dieser Karte zur Kerze auf dem Tisch.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Murder Power", "Mordkraft", Language.German);
            RegisterAbility("Murder Power", "Mordkraft");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal the total amount of power on the opponents board.", "Der Wert dieses Siegels entspricht der gesamten Kraft auf der gegnerischen Brettseite.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to half the total amount of power on your board.", "Der Wert dieses Siegels entspricht der Hälfte der gesamten Kraft auf deiner Brettseite.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell Power", "Zauberkraft", Language.German);
            RegisterAbility("Spell Power", "Zauberkraft");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to total amount of spells played during this current dungeon.", "Der Wert dieses Siegels entspricht der Gesamtzahl der im aktuellen Verlies ausgespielten Zauber.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to total amount of spells played during the battle.", "Der Wert dieses Siegels entspricht der Gesamtzahl der in diesem Kampf ausgespielten Zauber.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Counterbattery Power", "Gegenfeuerkraft", Language.German);
            RegisterAbility("Counterbattery Power", "Gegenfeuerkraft");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the amount of damage taken by you this battle, divided by two.", "Der Wert dieses Siegels entspricht dem Schaden, den du in diesem Kampf erlitten hast, geteilt durch zwei.", Language.German);
            foreach (Ability ability in Enum.GetValues(typeof(Ability)))
            {
                var info = AbilitiesUtil.GetInfo(ability);
                if (info == null || info.rulebookName == null || Abilities.ContainsKey(info.rulebookName))
                {
                    Debug.LogWarning($"Ability {ability} 没有有效的info，已跳过。");
                    continue;
                }
                if (info.rulebookName == null || Abilities.ContainsKey(info.rulebookName))
                {
                    Debug.LogWarning($"Ability {ability} 没有有效的rulebookName，或本身已注册，已跳过。");
                    continue;
                }
                RegisterAbility(info.rulebookName, GermanLanguagePack.Localize(info.rulebookName));
            }

