            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cyclone", "Wirbelsturm", Language.German);
            RegisterCard("Cyclone", "Wirbelsturm", "This spell shall summon a whirlwind that boosts your cards into the air.", "Dieser Zauber beschwört einen Wirbelwind, der deine Karten in die Luft hebt.");
