            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flood", "Flut", Language.German);
            RegisterCard("Flood", "Flut", "When used, it will summon a tsunami that wipes away the sigils of every card on the board.", "Beschwört bei Verwendung einen Tsunami, der die Siegel aller Karten auf dem Brett wegspült.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When used, it will summon a tsunami that wipes away the sigils of every card on the board.", "Beschwört bei Verwendung einen Tsunami, der die Siegel aller Karten auf dem Brett wegspült.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Engulf", "Verschlingen", Language.German);
            RegisterCard("Engulf", "Verschlingen", "Select a side of the board to be set ablaze.", "Wähle eine Brettseite, die in Brand gesetzt wird.");
