            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ethereal Gems", "Ätherische Edelsteine", Language.German);
            RegisterCard("Ethereal Gems", "Ätherische Edelsteine", "A frail spirit of a late magnus mox.. Only sustains for a turn.", "Der gebrechliche Geist eines verstorbenen Magnus Mox ... Er hält sich nur einen Zug lang.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A frail spirit of a late magnus mox.. Only sustains for a turn.", "Der gebrechliche Geist eines verstorbenen Magnus Mox ... Er hält sich nur einen Zug lang.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vase of Greed", "Vase der Gier", Language.German);
            RegisterCard("Vase of Greed", "Vase der Gier", "The vase of greed.. Look at its smug face..", "Die Vase der Gier ... Sieh dir ihr selbstgefälliges Gesicht an ...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vase of greed.. Look at its smug face..", "Die Vase der Gier ... Sieh dir ihr selbstgefälliges Gesicht an ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gnomification", "Gnomifizierung", Language.German);
            RegisterCard("Gnomification", "Gnomifizierung", "Conjure a plain old garden gnome on the board..", "Beschwöre einen ganz gewöhnlichen alten Gartengnom auf dem Brett ...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conjure a plain old garden gnome on the board..", "Beschwöre einen ganz gewöhnlichen alten Gartengnom auf dem Brett ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cursed Skull", "Verfluchter Schädel", Language.German);
            RegisterCard("Cursed Skull", "Verfluchter Schädel", "Hmm, a cursed skull. Handle it with care.", "Hm, ein verfluchter Schädel. Geh vorsichtig damit um.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm, a cursed skull. Handle it with care.", "Hm, ein verfluchter Schädel. Geh vorsichtig damit um.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inspiration", "Inspiration", Language.German);
            RegisterCard("Inspiration", "Inspiration", "A culmination of the great Master Orlu's essence.", "Die geballte Essenz der großen Meisterin Orau.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A culmination of the great Master Orlu's essence.", "Die geballte Essenz der großen Meisterin Orau.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rage", "Zorn", Language.German);
            RegisterCard("Rage", "Zorn", "The embodiement of the tenacious Master Goranj.", "Die Verkörperung des unnachgiebigen Meisters Grange.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The embodiement of the tenacious Master Goranj.", "Die Verkörperung des unnachgiebigen Meisters Grange.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Calculus", "Infinitesimalrechnung", Language.German);
            RegisterCard("Calculus", "Infinitesimalrechnung", "The spirit of the brave Master Bleene.", "Der Geist des tapferen Meisters Blün.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The spirit of the brave Master Bleene.", "Der Geist des tapferen Meisters Blün.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fireball", "Feuerball", Language.German);
            RegisterCard("Fireball", "Feuerball", "Conjure up a fireball, and shoot it towards your enemy.", "Beschwöre einen Feuerball und schieße ihn auf deinen Feind.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conjure up a fireball, and shoot it towards your enemy.", "Beschwöre einen Feuerball und schieße ihn auf deinen Feind.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Potion", "Trank", Language.German);
            RegisterCard("Potion", "Trank", "Conjure up a fireball, and shoot it towards your enemy.", "Beschwöre einen Feuerball und schieße ihn auf deinen Feind.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conjure up a fireball, and shoot it towards your enemy.", "Beschwöre einen Feuerball und schieße ihn auf deinen Feind.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gnome", "Gnom", Language.German);
