            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "joem", "Joem", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scuba Gnome", "Tauchergnom", Language.German);
            RegisterCard("Scuba Gnome", "Tauchergnom", "Huber", "Huber");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Huber", "Huber", Language.German);
            RegisterCard("Free Legs", "Freie Beine", "", "");
            RegisterCard("Unsealed Body", "Entsiegelter Körper", "", "");
            RegisterCard("Released Arms", "Befreite Arme", "", "");
            RegisterCard("Unleashed Tyrant", "Entfesselter Tyrann", "", "");
            foreach (var kvp in Cards)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "~" + kvp.Key + "~", "~" + kvp.Value + "~", Language.German);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cardpack sapphire", "Saphir-Kartenpaket", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cardpack ruby", "Rubin-Kartenpaket", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cardpack emerald", "Smaragd-Kartenpaket", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fill In Minimap", "Minikarte aufdecken", Language.German);

            // Achievement
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magnificus Mod Achievements", "Erfolge des Magnificus-Mods", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magical Labyrinth", "Magisches Labyrinth", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defeat the final boss.", "Besiege den letzten Boss.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crystal Skull", "Kristallschädel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Complete a run with every challenge active, and no anti challenges. (You may use the map)", "Schließe einen Durchlauf mit allen Herausforderungen und ohne Anti-Herausforderungen ab. (Du darfst die Karte benutzen.)", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Humanoid Slime", "Humanoider Schleim", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defeat the first boss without having any cards get their power reduced at the start of phase 2.", "Besiege den ersten Boss, ohne dass zu Beginn von Phase 2 eine deiner Karten Kraft verliert.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Headless Knight", "Kopfloser Ritter", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defeat the second boss without triggering any Enchanted Spears.", "Besiege den zweiten Boss, ohne einen verzauberten Speer auszulösen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quick Summon", "Schnelle Beschwörung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defeat the third boss without letting the turn timer expire once.", "Besiege den dritten Boss, ohne den Zugtimer auch nur einmal ablaufen zu lassen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mischief of the Time Goddess", "Streich der Zeitgöttin", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let the third boss's timer run out 5 times, and still win the fight.", "Lass den Timer des dritten Bosses 5 Mal ablaufen und gewinne den Kampf trotzdem.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rush Recklessly", "Kopfloser Ansturm", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defeat the first boss after using only 3 or less events.", "Besiege den ersten Boss, nachdem du höchstens 3 Ereignisse genutzt hast.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crowning of the Emperor", "Krönung des Kaisers", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue Eyes White Dragon", "Blauäugiger w. Drache", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deal 10 damage in a single turn.", "Verursache 10 Schaden in einem einzigen Zug.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Card of Sacrifice", "Karte des Opfers", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have 10 or less cards by the time you reach the final boss.", "Habe höchstens 10 Karten, wenn du den letzten Boss erreichst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Owl of the Black Forest", "Eule des Schwarzwalds", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Banish the Ficticious Master Magnus.", "Verbanne den fiktiven Höchsten Meister.", Language.German);

            // Consumable

            // ShowUntilInput
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT? BUT DON'T I GET TO LEAVE?", "WAS? DARF ICH DENN NICHT GEHEN?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I STILL HAVE SO MUCH STIMULATION TO GET!!", "ES GIBT NOCH SO VIEL STIMULATION FÜR MICH!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g2]PLEASE, CHALLENGER,[c:] YOU HAVE TO GET ME-", "[c:g2]BITTE, HERAUSFORDERER,[c:] DU MUSST MICH HIER RAUS—", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hush.", "Still.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm?", "Hm?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Did you expect me to restore your [c:g1]life painting[c:]?", "Hast du erwartet, dass ich dein [c:g1]Lebensgemälde[c:] wiederherstelle?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm.. That's not how it works here, challenger..", "Hm ... So läuft das hier nicht, Herausforderer ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bleach is not easily restorable.", "Was gebleicht wurde, lässt sich nicht leicht wiederherstellen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You may only pick a [c:g3]rare card[c:].", "Du darfst nur eine [c:g3]seltene Karte[c:] wählen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As you engage in combat, you notice ethereal runes surrounding you..", "Als du den Kampf beginnst, bemerkst du ätherische Runen um dich herum ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems as though they were placing a [c:g2]pact[c:] on you..", "Es scheint, als würden sie dir einen [c:g2]Pakt[c:] auferlegen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your olden sigils shant be of any use in this battle.", "Deine alten Siegel werden dir in diesem Kampf nichts nützen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As the smoke of combat clears, the mysterious runes reveal themselves to you.", "Als sich der Rauch des Kampfes lichtet, offenbaren sich dir die geheimnisvollen Runen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah, but this one does not interest the runes.", "Ah, aber diese hier weckt das Interesse der Runen nicht.", Language.German);
            foreach (var kvp in Cards)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The pact takes its effect on your " + kvp.Key + "..", "Der Pakt wirkt auf deine Karte " + kvp.Value + " ...", Language.German);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sigil, replaced, for better or for worse.", "Das Siegel wurde ersetzt, zum Guten oder zum Schlechten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g3]Hmm..?[c:] [c:g1]Another[c:] [c:g3]student[c:] [c:g1]here?[c:]", "[c:g3]Hm ...?[c:] [c:g1]Noch[c:] [c:g3]ein Schüler[c:] [c:g1]hier?[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g3]Have[c:] [c:g1]you[c:] [c:g3]come[c:] [c:g1]to[c:] [c:g3]assist[c:] [c:g1]my[c:] [c:g3]studies?[c:]", "[c:g3]Bist[c:] [c:g1]du[c:] [c:g3]gekommen,[c:] [c:g1]um[c:] [c:g3]mir[c:] [c:g1]beim Studium[c:] [c:g3]zu helfen?[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g3]Hmm..[c:] [c:g1]I[c:] [c:g3]think[c:] [c:g1]it's[c:] [c:g3]time[c:] [c:g1]to[c:] [c:g3]play[c:] [c:g1]some[c:] [c:g3]more...[c:]  [c:g2]forbidden[c:] [c:g1]books[c:]", "[c:g3]Hm ...[c:] [c:g1]Ich[c:] [c:g3]glaube,[c:] [c:g1]es[c:] [c:g3]ist[c:] [c:g1]Zeit,[c:] [c:g3]wieder[c:] [c:g1]ein paar[c:] [c:g3]weitere ...[c:] [c:g2]verbotene[c:] [c:g1]Bücher auszuspielen.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g3]An[c:] [c:g1]excellent[c:] [c:g3]portrait[c:] [c:g1]by[c:] [c:g3]the[c:] [c:g1]Master.[c:]", "[c:g3]Ein[c:] [c:g1]ausgezeichnetes[c:] [c:g3]Kartenbild[c:] [c:g1]aus[c:] [c:g3]der Hand des[c:] [c:g1]Meisters.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g3]Looks[c:] [c:g1]like[c:] [c:g3]you[c:] [c:g1]got[c:] [c:g3]a[c:] [c:g1]hound[c:] [c:g3]of[c:] [c:g1]your[c:] [c:g3]own![c:]", "[c:g3]Sieht[c:] [c:g1]ganz[c:] [c:g3]so aus,[c:] [c:g1]als hättest[c:] [c:g3]du[c:] [c:g1]einen Jagdhund[c:] [c:g3]ganz[c:] [c:g1]für dich[c:] [c:g3]allein![c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g3]Oh[c:] [c:g1]yes,[c:] [c:g3]I[c:] [c:g1]do[c:] [c:g3]love[c:] [c:g1]a[c:] [c:g3]good[c:] [c:g1]book.[c:]", "[c:g3]Oh[c:] [c:g1]ja,[c:] [c:g3]ich[c:] [c:g1]liebe[c:] [c:g3]wirklich[c:] [c:g1]ein[c:] [c:g3]gutes[c:] [c:g1]Buch.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g3]Let[c:] [c:g1]me[c:] [c:g3]share[c:] [c:g1]some[c:] [c:g3]of[c:] [c:g1]my[c:] [c:g3]favourites[c:] [c:g1]with[c:] [c:g3]you.[c:]", "[c:g3]Lass[c:] [c:g1]mich[c:] [c:g3]doch[c:] [c:g1]ein paar[c:] [c:g3]meiner[c:] [c:g1]liebsten[c:] [c:g3]Bücher[c:] [c:g1]mit dir[c:] [c:g3]teilen.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just imagine.. You are an ice cube, slowly melting in a hot pan..", "Stell dir vor ... Du bist ein Eiswürfel, der langsam in einer heißen Pfanne schmilzt ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "These enchanted spears won't just damage your cards..", "Diese verzauberten Speere werden deinen Karten nicht bloß Schaden zufügen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hah! Using one of my own spells against me?", "Ha! Du setzt einen meiner eigenen Zauber gegen mich ein?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't you think those cards are a little too powerful?", "Findest du diese Karten nicht ein wenig zu mächtig?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's better.", "Schon besser.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]How did you get that?[c:]", "[c:g1]Wie bist du daran gekommen?[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, ".. Where on earth is my [c:g1]Goo Mage[c:]?", "... Wo steckt bloß mein [c:g1]Schleimmagier[c:]?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have your.. Modifications removed him?", "Haben deine ... Modifikationen ihn entfernt?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This tampering has gone on for far too long. I shall not allow it anymore.", "Diese Manipulationen gehen schon viel zu lange. Ich werde sie nicht länger dulden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When we face off, I won't be holding myself back.", "Wenn wir gegeneinander antreten, werde ich mich nicht zurückhalten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]Halt![c:] [c:g2]A[c:] [c:g1]challenger[c:] [c:g2]dare[c:] [c:g1]approach?![c:]", "[c:g1]Halt![c:] [c:g2]Ein[c:] [c:g1]Herausforderer[c:] [c:g2]wagt es,[c:] [c:g1]sich zu nähern?![c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]Quaint,[c:] [c:g2]I[c:] [c:g1]shall[c:] [c:g2]make[c:] [c:g1]mince[c:] [c:g2]meat[c:] [c:g1]out[c:] [c:g2]of[c:] [c:g1]you.[c:]", "[c:g1]Drollig,[c:] [c:g2]ich[c:] [c:g1]werde[c:] [c:g2]dich[c:] [c:g1]ganz[c:] [c:g2]und[c:] [c:g1]gar[c:] [c:g2]zu[c:] [c:g1]Hackfleisch verarbeiten.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]Irritating,[c:] [c:g2]you[c:] [c:g1]persist.[c:] [c:g2]You[c:] [c:g1]have[c:] [c:g2]bound[c:] [c:g1]me[c:] [c:g2]to[c:] [c:g1]excert[c:] [c:g2]my[c:] [c:g1]blade.[c:]", "[c:g1]Lästig,[c:] [c:g2]du[c:] [c:g1]gibst nicht auf.[c:] [c:g2]Du[c:] [c:g1]hast[c:] [c:g2]mich[c:] [c:g1]dazu[c:] [c:g2]gezwungen,[c:] [c:g1]meine[c:] [c:g2]Klinge[c:] [c:g1]einzusetzen.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]Eh?[c:] [c:g2]Some[c:] [c:g1]sort[c:] [c:g2]of[c:] [c:g1]immitation[c:] [c:g2]of[c:] [c:g1]me?[c:]", "[c:g1]Hm?[c:] [c:g2]So[c:] [c:g1]etwas[c:] [c:g2]wie[c:] [c:g1]eine Nachahmung[c:] [c:g2]von[c:] [c:g1]mir?[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "c:g1]Pathetic.[c:] [c:g2]My[c:] [c:g1]Drake[c:] [c:g2]was[c:] [c:g1]much[c:] [c:g2]grander[c:] [c:g1]than[c:] [c:g2]that.[c:]", "[c:g1]Erbärmlich.[c:] [c:g2]Mein[c:] [c:g1]Drache[c:] [c:g2]war[c:] [c:g1]weitaus[c:] [c:g2]prächtiger[c:] [c:g1]als[c:] [c:g2]das.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "W-What? A challenger?", "W-Was? Ein Herausforderer?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FINALLY!! STIMULATION!", "ENDLICH!! STIMULATION!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'M STILL NOT STIMULATED ENOUGH!!", "ICH BIN IMMER NOCH NICHT GENUG STIMULIERT!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I HAVE THE URGE TO SEARCH A CARD PILE!", "ICH MUSS UNBEDINGT EINEN KARTENSTAPEL DURCHSUCHEN!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'M GROWING IMPATIENT!\nI NEED MORE STIMULATION!!", "ICH WERDE UNGEDULDIG!\nICH BRAUCHE MEHR STIMULATION!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WOW!! I REMEMBER BREWING THAT!", "WOW!! ICH WEISS NOCH, WIE ICH DAS GEBRAUT HABE!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HEY.. YOU DON'T HAVE ANY CARDS LEFT?", "HE ... DU HAST GAR KEINE KARTEN MEHR?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BORING!", "LANGWEILIG!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WOW! COOL CARD!!", "WOW! COOLE KARTE!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FINDERS KEEPERS!", "WER'S FINDET, DARF'S BEHALTEN!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm afraid you've doomed us all, challenger..", "Ich fürchte, du hast uns alle ins Verderben gestürzt, Herausforderer ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps I am slowing down with age..", "Vielleicht werde ich im Alter langsamer ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I must use the brush to my advantage yet again.", "Ich muss mir erneut den Pinsel zunutze machen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have impressed me, you truly have..", "Du hast mich beeindruckt, wirklich ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "2 lives down now.", "Jetzt sind 2 Leben verloren.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unfortunately for you, I still have a few tricks up my sleeve.", "Zu deinem Pech habe ich noch ein paar Asse im Ärmel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I could never allow myself to go down that easily.", "Ich könnte mich niemals so leicht geschlagen geben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Utter folly.. Getting outside assitance, are we?", "Ausgemachte Torheit ... Wir holen uns also Hilfe von außen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Free Legs", "Freie Beine", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unsealed Body", "Entsiegelter Körper", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Released Arms", "Befreite Arme", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unleashed Tyrant", "Entfesselter Tyrann", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just what do you think you're doing?", "Was glaubst du eigentlich, was du da tust?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do not.", "Lass das.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trying to pull a trick as dirty as that..", "So einen schmutzigen Trick zu versuchen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...", "…", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Upsetting. I seem to be losing.", "Ärgerlich. Ich scheine zu verlieren.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How about a new rule.", "Wie wäre es mit einer neuen Regel?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everytime [c:g2]you[c:] play a mox, [c:g2]I[c:] restore 1 health.", "Jedes Mal, wenn [c:g2]du[c:] einen Mox ausspielst, stelle [c:g2]ich[c:] 1 Gesundheit wieder her.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frustrating. I must use my last resort.", "Frustrierend. Ich muss zu meinem letzten Mittel greifen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]We[c:] [c:g2]have[c:] [c:g3]become[c:] four!", "[c:g1]Wir[c:] [c:g2]sind[c:] [c:g3]nun[c:] zu viert!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g2]Hmm?[c:] [c:g3]An[c:] [c:g2]opponent..?[c:]", "[c:g2]Hm?[c:] [c:g3]Ein[c:] [c:g2]Gegner ...?[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g2]I[c:] [c:g3]haven't[c:] [c:g2]had[c:] [c:g3]a[c:] [c:g2]duel[c:] [c:g3]in[c:] [c:g2]a[c:] [c:g3]century![c:]", "[c:g2]Ich[c:] [c:g3]habe[c:] [c:g2]seit[c:] [c:g3]einem[c:] [c:g2]Jahrhundert[c:] [c:g3]kein[c:] [c:g2]Duell[c:] [c:g3]mehr bestritten![c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g2]Have[c:] [c:g3]at[c:] [c:g2]thee![c:]", "[c:g2]Nimm[c:] [c:g3]dich[c:] [c:g2]in Acht![c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g2]A[c:] [c:g3]fierce[c:] [c:g2]opponent[c:] [c:g3]you[c:] [c:g2]are![c:]", "[c:g2]Du[c:] [c:g3]bist[c:] [c:g2]ein[c:] [c:g3]erbitterter[c:] [c:g2]Gegner![c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g2]I'll[c:] [c:g3]just[c:] [c:g2]have[c:] [c:g3]to[c:] [c:g2]use[c:] [c:g3]some[c:] [c:g2]more[c:] [c:g3]dirty[c:] [c:g2]tricks[c:] [c:g3]to[c:] [c:g2]beat[c:] [c:g3]you![c:]", "[c:g2]Dann[c:] [c:g3]muss[c:] [c:g2]ich[c:] [c:g3]eben[c:] [c:g2]noch[c:] [c:g3]ein[c:] [c:g2]paar[c:] [c:g3]schmutzige[c:] [c:g2]Tricks[c:] [c:g3]anwenden,[c:] [c:g2]um dich[c:] [c:g3]zu schlagen![c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g2]And[c:] [c:g3]something[c:] [c:g2]else,[c:] [c:g3]why[c:] [c:g2]not.[c:]", "[c:g2]Und[c:] [c:g3]noch[c:] [c:g2]etwas anderes,[c:] [c:g3]warum[c:] [c:g2]nicht.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g2]Ooh![c:] [c:g3]What[c:] [c:g2]a[c:] [c:g3]great[c:] [c:g2]portrait![c:]", "[c:g2]Ooh![c:] [c:g3]Was[c:] [c:g2]für ein[c:] [c:g3]großartiges[c:] [c:g2]Kartenbild![c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g2]A[c:] [c:g3]replica[c:] [c:g2]of[c:] [c:g3]my[c:] [c:g2]loyal[c:] [c:g3]phoenix,[c:] [c:g2]isn't[c:] [c:g3]she[c:] [c:g2]absolutely[c:] [c:g3]stunning?[c:]", "[c:g2]Eine[c:] [c:g3]Nachbildung[c:] [c:g2]meines[c:] [c:g3]treuen[c:] [c:g2]Phönix,[c:] [c:g3]ist[c:] [c:g2]sie[c:] [c:g3]nicht[c:] [c:g2]absolut[c:] [c:g3]atemberaubend?[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g2]I[c:] [c:g3]see[c:] [c:g2]you've[c:] [c:g3]done[c:] [c:g2]a[c:] [c:g3]fair[c:] [c:g2]bit[c:] [c:g3]of[c:] [c:g2]damage![c:]", "[c:g2]Ich[c:] [c:g3]sehe,[c:] [c:g2]du[c:] [c:g3]hast[c:] [c:g2]eine[c:] [c:g3]ziemlich[c:] [c:g2]ordentliche[c:] [c:g3]Menge[c:] [c:g2]Schaden verursacht![c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g2]Don't[c:] [c:g3]mind[c:] [c:g2]if[c:] [c:g3]I[c:] [c:g2]just[c:] [c:g3]place[c:] [c:g2]my[c:] [c:g3]thieves..[c:]", "[c:g2]Du[c:] [c:g3]hast[c:] [c:g2]sicher[c:] [c:g3]nichts dagegen,[c:] [c:g2]wenn ich[c:] [c:g3]einfach[c:] [c:g2]meine[c:] [c:g3]Diebe aufstelle ...[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Out of cards..", "Keine Karten mehr ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dissapointing. I had high hopes for you.", "Enttäuschend. Ich hatte große Hoffnungen in dich gesetzt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such a tiny collection of cards..", "So eine winzige Kartensammlung ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I highly doubt you will win.", "Ich bezweifle stark, dass du gewinnen wirst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With a blaze of Magick, you end the battle. You managed to deal more damage than needed.", "Mit einem Auflodern der Magie beendest du den Kampf. Du hast mehr Schaden verursacht als nötig.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The excess Magick you cast turns into [c:g3] Crystals. [c:] You may spend them at any meek store you happen to find.", "Die überschüssige Magie, die du gewirkt hast, wird zu [c:g3]Kristallen[c:]. Du kannst sie in jedem bescheidenen Laden ausgeben, den du findest.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Welcome back.", "Willkommen zurück.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're the first in a while to get this far.", "Du bist seit Langem der Erste, der es so weit geschafft hat.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I will now bestow upon you, the highest honour I can possibly give.", "Ich werde dir nun die höchste Ehre zuteilwerden lassen, die ich vergeben kann.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "To be painted, and immortalised forever, as a card.", "Gemalt und für immer als Karte verewigt zu werden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The dummy stares lifelessly back at you.", "Die Attrappe starrt dich leblos an.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Then, suddenly it springs to motion!", "Dann setzt sie sich plötzlich in Bewegung!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The dummy's hinges creak back into position, and it returns to it's lifeless stare.", "Die Scharniere der Attrappe knarren zurück in ihre Position, und sie starrt wieder leblos vor sich hin.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So you finally arrive..", "Da bist du ja endlich ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hopefully you have prepared yourself well enough to face the Scrybe of Magicks.", "Hoffentlich hast du dich gut genug auf den Wahrschreiber der Magie vorbereitet.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This will be your final exam.", "Dies wird deine Abschlussprüfung sein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let us dance.", "Lass uns tanzen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g2]You[c:] are finally here.", "[c:g2]Du[c:] bist endlich hier.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope you realise that this is truly it.", "Ich hoffe, dir ist klar, dass dies wirklich das Ende ist.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You may have removed my student's battles,", "Du magst die Kämpfe meiner Schüler entfernt haben,", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You may have tampered with my entire game..", "Du magst mein ganzes Spiel manipuliert haben ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is time.", "Es ist Zeit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greetings, challenger.", "Sei gegrüßt, Herausforderer.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It appears that all of your mox has been erased.", "Es scheint, als wären all deine Mox ausgelöscht worden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Curiosity killed the cat..", "Neugier ist der Katze Tod ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's a shame you got defeated so early..", "Schade, dass du so früh besiegt wurdest ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's a shame you got defeated so easily.", "Schade, dass du so leicht besiegt wurdest.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's a shame you got defeated so far in.", "Schade, dass du nach so einem weiten Weg besiegt wurdest.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I had such high hopes, but you lost it all..", "Ich hatte so große Hoffnungen, aber du hast alles verloren ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems my slime mage got the best of you. How dissapointing.", "Anscheinend war mein Schleimmagier dir überlegen. Wie enttäuschend.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It looks like my pike mage tactically took you out..", "Anscheinend hat mein Speermagier dich taktisch ausgeschaltet ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looks like that lonely mage got to you..", "Anscheinend hat dieser einsame Magier dich erwischt ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though it does not matter.", "Doch das spielt keine Rolle.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I do not have any more use for you.", "Ich habe keine Verwendung mehr für dich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please, take your leave.", "Bitte geh nun.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looking for something?", "Suchst du etwas?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm afraid the object you seek has been.. [c:g1]relocated[c:]..", "Ich fürchte, das Objekt, das du suchst, wurde ... [c:g1]verlegt[c:] ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Look at what you've unleashed..", "Sieh nur, was du entfesselt hast ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Was it truly worth finding?", "War es wirklich wert, gefunden zu werden?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmph.. I did not intend for you to get out here..", "Hmpf ... Ich hatte nicht vor, dich hier herauszulassen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have forseen it though. Despite my best attempts you persist.", "Doch ich habe es vorausgesehen. Trotz all meiner Bemühungen machst du weiter.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We shall duel here..", "Wir werden uns hier duellieren ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though, lets up the stakes.", "Doch erhöhen wir den Einsatz.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you lose here, your entire [c:g1]life painting[c:] will get bleached..", "Wenn du hier verlierst, wird dein gesamtes [c:g1]Lebensgemälde[c:] gebleicht ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Step forth if you dare.", "Tritt vor, wenn du dich traust.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You persist again?", "Du machst schon wieder weiter?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I see..", "Ich verstehe ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We shall duel again!", "Duellieren wir uns erneut!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah.. Finally, you arrive.", "Ah ... Endlich bist du da.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've been watching you from up here, for your entire journey.", "Ich habe dich von hier oben während deiner gesamten Reise beobachtet.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You've come a long way, challenger.", "Du hast einen weiten Weg hinter dir, Herausforderer.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unfortunately, that will all come to an end here.", "Leider wird das alles hier ein Ende finden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One last duel, to decide your fate..", "Ein letztes Duell, das über dein Schicksal entscheidet ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is time to put an end to this.. [c:g1]foolery[c:] of yours.", "Es ist Zeit, diesem ... [c:g1]Unfug[c:] von dir ein Ende zu setzen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you consider these cheats fair, then I might as well use some cheats of my own.", "Wenn du diese Schummeleien fair findest, kann ich ebenso gut selbst ein wenig schummeln.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Normally, I would have you expelled right on the spot.. But I'm feeling generous.", "Normalerweise würde ich dich auf der Stelle hinauswerfen ... Aber ich bin großzügig gestimmt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let us duel.", "Lass uns duellieren.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whats the matter? Stumped?", "Was ist los? Kommst du nicht weiter?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Try searching around the dungeon.. There may be certain [c:g1]markings[c:] you missed..", "Such dich im Verlies um ... Vielleicht hast du bestimmte [c:g1]Markierungen[c:] übersehen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm?", "Hm?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you wondering what this book is for?", "Fragst du dich, wozu dieses Buch da ist?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That is your [c:g1]spell book[c:]. You may use it to draw one of your [c:g3]spell cards[c:].", "Das ist dein [c:g1]Zauberbuch[c:]. Du kannst damit eine deiner [c:g3]Zauberkarten[c:] ziehen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But only [c:g1]one[c:] per turn..", "Aber nur [c:g1]eine[c:] pro Zug ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You land in a sticky puddle of goo, stretching out into what seems like an endless void..", "Du landest in einer klebrigen Schleimpfütze, die sich in eine scheinbar endlose Leere erstreckt ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruined pillars and ancient walls surround your vision, overtaken by yet more slime..", "Zerstörte Säulen und uralte Mauern füllen dein Sichtfeld, von noch mehr Schleim überwuchert ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The glistening heavens above shine brightly unto you.", "Der schimmernde Himmel über dir strahlt dich hell an.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You arrive in the..", "Du erreichst ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A sudden influx of heat surrounds you..", "Ein plötzlicher Hitzeschwall umgibt dich ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dimly lit and dingy chambers spread out as far as you can see.", "Düster beleuchtete, schäbige Kammern erstrecken sich, so weit du sehen kannst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Long forgotten echoes of ancient sparring fill the room.", "Längst vergessene Echos uralter Übungskämpfe erfüllen den Raum.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You find yourself in the..", "Du findest dich wieder in ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A dusty old smell fills your nostrills..", "Ein alter, staubiger Geruch steigt dir in die Nase ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hundreds of walls containing books, laying untouched for eons, fill the quiet landscape.", "Hunderte von Wänden voller Bücher, seit Ewigkeiten unberührt, füllen die stille Landschaft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ethereal runes, containing lost, forbidden knowledge surround you.", "Ätherische Runen, die verlorenes, verbotenes Wissen bergen, umgeben dich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You awake in the..", "Du erwachst in ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmmm. It seems a new student is woven onto my canvas.", "Hmmm. Anscheinend wurde ein neuer Schüler in meine Leinwand eingewebt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you look behind yourself, you may see a [c:g1]shop[c:].", "Wenn du hinter dich blickst, siehst du vielleicht einen [c:g1]Laden[c:].", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You may view your deck and rearange your side deck.", "Du kannst deinen Stapel ansehen und deinen Nebenstapel neu ordnen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though, do not be alarmed. You may find a shop later on your adventures.", "Aber keine Sorge. Vielleicht findest du später auf deinen Abenteuern einen Laden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you are ready to proceed, you may step forth and enter into the unknown.", "Wenn du bereit bist weiterzugehen, tritt vor und wage dich ins Unbekannte.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm.. A young student appears,", "Hm ... Ein junger Schüler erscheint,", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So foolish, your predesscor didn't even manage to get past my [c:g1]Goo Mage[c:].", "Wie töricht. Dein Vorgänger hat es nicht einmal an meinem [c:g1]Schleimmagier[c:] vorbeigeschafft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah well.. Maybe you will manage such a feat.", "Nun ja ... Vielleicht gelingt dir diese Leistung.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Another appears.", "Da erscheint noch einer.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maybe you will manage to get further than those before you.", "Vielleicht kommst du weiter als die vor dir.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You young understudies still have much to learn.", "Ihr jungen Lehrlinge habt noch viel zu lernen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah. I had expectations for my previous mage,", "Ah. Ich hatte Erwartungen an meinen vorherigen Magier,", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They even managed to get past my [c:g2]Pike Mage[c:].", "Es gelang ihm sogar, meinen [c:g2]Speermagier[c:] zu überwinden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A great feat, it seems now you must follow in their footsteps...", "Eine große Leistung. Nun musst du wohl in seine Fußstapfen treten ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So, yet another steps up to be my student.", "Also tritt noch jemand vor, um mein Schüler zu werden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You must learn yourself, to overcome my many obstacles and challenges.", "Du musst selbst lernen, meine vielen Hindernisse und Herausforderungen zu überwinden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you do succeed, I shall bestow upon you a great honour..", "Solltest du Erfolg haben, werde ich dir eine große Ehre erweisen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm.. Something feels off..", "Hm ... Irgendetwas stimmt nicht ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have you [c:g1]modded[c:] my game, challenger?", "Hast du mein Spiel [c:g1]gemoddet[c:], Herausforderer?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmph! How disrespectful!", "Hmpf! Wie respektlos!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Was my game not enough for you?", "War mein Spiel dir etwa nicht genug?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alas, I have no choice but to allow it..", "Leider bleibt mir nichts anderes übrig, als es zu erlauben ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just what is going on here..?", "Was geht hier bloß vor ...?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "These cards,", "Diese Karten,", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Did that [c:g2]foul little..[c:] get in here..?", "Ist dieses [c:g2]widerliche kleine ...[c:] hier eingedrungen ...?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I believe you are in the wrong place, challenger.", "Ich glaube, du bist am falschen Ort, Herausforderer.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hold still.", "Halt still.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You are a simpleton for expecting scales.", "Du bist ein Einfaltspinsel, wenn du eine Waage erwartest.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is a simple race to 0.", "Das ist ein schlichtes Wettrennen bis 0.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOW ITS TIME FOR ME TO PRACTICE MY BREWING MAGICKS!!", "JETZT IST ES ZEIT, MEINE BRAUMAGIE ZU ÜBEN!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT IS DONE!!! GO TAKE IT!!", "FERTIG!!! HOL SIE DIR!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GO!!", "LOS!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g2]GET OUT OF HERE!![c:]", "[c:g2]RAUS HIER!![c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WOAH! LOOKS LIKE SOMETHING YOU PUT INTO THE POTION MADE IT A BIT.. [c:g1]PRICY[c:]..", "WOW! ANSCHEINEND HAT ETWAS, DAS DU IN DEN TRANK GEGEBEN HAST, IHN ETWAS ... [c:g1]TEUER[c:] GEMACHT ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "W-What? Am I finally free?", "W-Was? Bin ich endlich frei?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A break from that endless darkness?", "Eine Pause von dieser endlosen Dunkelheit?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nevermind.. It's just potion making..", "Schon gut ... Es geht nur ums Tränkebrauen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, Hi Challenger!!", "Oh, hallo, Herausforderer!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wow, someone new!!", "Wow, jemand Neues!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just give me two cards of yours and we'll make a potion out of them!!", "Gib mir einfach zwei deiner Karten, und wir machen einen Trank daraus!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can later give this potion to your cards and they gain some silly effects!", "Du kannst diesen Trank später deinen Karten geben, damit sie ein paar alberne Effekte erhalten!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Come on!! It will be fun!!", "Komm schon!! Das wird lustig!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And stimulating..", "Und stimulierend ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So stimulating", "So stimulierend", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hello there challenger!!", "Hallo da, Herausforderer!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You know how this works now", "Du weißt jetzt, wie es funktioniert", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just give me two cards and we'll make a potion!", "Gib mir einfach zwei Karten, und wir machen einen Trank!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woah.. What.. Is this place?", "Wow ... Was ... ist das hier für ein Ort?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So bright..", "So hell ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, Hi there!!", "Oh, hallo da!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's make some potions!!", "Lass uns Tränke brauen!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just hand over two cards and we'll be done with it..", "Gib einfach zwei Karten her, dann sind wir fertig ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WAIT!! YOUR SPELLBOOK IS FULL", "WARTE!! DEIN ZAUBERBUCH IST VOLL", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GET RID OF ONE OF YOUR SPELLS, OR YOU WONT BE ABLE TO TAKE OUR POTION!!", "WIRF EINEN DEINER ZAUBER WEG, SONST KANNST DU UNSEREN TRANK NICHT MITNEHMEN!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your card's cost has been changed..", "Die Kosten deiner Karte wurden geändert ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you have a card that has a cost you are unsatisfied with?", "Hast du eine Karte, mit deren Kosten du unzufrieden bist?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No. It appears not.", "Nein. Anscheinend nicht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LETS SEE HERE..", "SEHEN WIR MAL ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HMM?", "HM?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT DO YOU THINK?", "WAS MEINST DU?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WELL?", "UND?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT WOULD THE MASTER THINK?", "WAS WÜRDE DER MEISTER DENKEN?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WOULD THE MASTER BE PROUD?", "WÄRE DER MEISTER STOLZ?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IS IT GOOD?", "IST ES GUT?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GRREETINGS CHALLENGER!", "SEI GEGRRÜSST, HERAUSFORDERER!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU'RE ALREADY HERE?", "DU BIST SCHON HIER?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I DON'T REALLY RECALL US BATTLING..", "ICH KANN MICH NICHT WIRKLICH AN UNSEREN KAMPF ERINNERN ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WELL ANYWAYS.. WHAT CARD WHOULD I PRACTICE ON?", "WIE AUCH IMMER ... AN WELCHER KARTE SOLL ICH ÜBEN?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT WOULD SEEM THAT YOU HAVE DISGRACED ME!", "ANSCHEINEND HAST DU MICH BESCHÄMT!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BUT IT IS ALRIGHT, I FORGIVE YOU.", "ABER SCHON GUT, ICH VERGEBE DIR.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SAY, CHALLENGER, I WOULD LIKE TO PRACTICE MY [c:g2]ART[c:]..", "SAG MAL, HERAUSFORDERER, ICH WÜRDE GERN MEINE [c:g2]KUNST[c:] ÜBEN ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ONE DAY I MIGHT EVEN BE AS GOOD AS THE MASTER!", "EINES TAGES BIN ICH VIELLEICHT SOGAR SO GUT WIE DER MEISTER!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU WOULDN'T MIND GIVING ME ONE OF YOUR THERE CARDS, RIGHT?", "DU HAST DOCH NICHTS DAGEGEN, MIR EINE DEINER KARTEN ZU GEBEN, ODER?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT CARD SHOULD I PRACTICE ON?", "AN WELCHER KARTE SOLL ICH ÜBEN?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'LL NEED A CARD TO HONE MY SKILLS ON.", "ICH BRAUCHE EINE KARTE, AN DER ICH MEINE FÄHIGKEITEN VERFEINERN KANN.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I DON'T THINK WE'VE MET BEFORE!", "ICH GLAUBE NICHT, DASS WIR UNS SCHON KENNEN!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU ARENT SUPPOSED TO SEE ME UNTILL LATER, BUT..", "DU SOLLTEST MICH EIGENTLICH ERST SPÄTER SEHEN, ABER ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, ".. It appears you have nothing else to offer..", "... Anscheinend hast du sonst nichts anzubieten ...", Language.German);
            foreach (var value in Cards.Values)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your" + value + " sits on the enchanted grounds...\nYou could either leave it there, to enchant it..", "Deine Karte " + value + " liegt auf dem verzauberten Boden ...\nDu kannst sie dort lassen, um sie zu verzaubern ...", Language.German);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Or you can slaughter it to improve the enchantment, dictated by the [c:g1]Ethereal Sigils[c:].", "Oder du kannst sie schlachten, um die Verzauberung zu verbessern, wie es die [c:g1]ätherischen Siegel[c:] vorgeben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The choice is yours.", "Die Wahl liegt bei dir.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]Ethereal Sigils[c:] hover around the grounds.", "[c:g1]Ätherische Siegel[c:] schweben um die Stätte.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You may use them to predict a possible outcome..", "Du kannst sie nutzen, um einen möglichen Ausgang vorherzusehen ...", Language.German);
            foreach (var value in Cards.Values)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your " + value + " has been burdened with Glass Cannon!", "Deine Karte " + value + " hat den Fluch Glaskanone erhalten!", Language.German);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your " + value + " has been burdened with Tank!", "Deine Karte " + value + " hat den Fluch Tank erhalten!", Language.German);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your " + value + " has been blessed!", "Deine Karte " + value + " wurde gesegnet!", Language.German);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your " + value + " has been burdened!", "Deine Karte " + value + " wurde verflucht!", Language.German);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your " + value + " is now free.. But more unstable..", "Deine Karte " + value + " ist jetzt kostenlos ... aber instabiler ...", Language.German);
                foreach (var kvp in Abilities)
                {
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your" + value + " has been blessed with " + kvp.Key + "!", "Deine Karte " + value + " hat den Segen " + kvp.Value + " erhalten!", Language.German);
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your" + value + " has been burdened with " + kvp.Key + "!", "Deine Karte " + value + " hat den Fluch " + kvp.Value + " erhalten!", Language.German);
                }
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The [c:g1]Sacrifical Grounds[c:] stand before you.\nLegends tell of cards growing exponentially in power here, under the right circumstances..", "Die [c:g1]Opferstätte[c:] liegt vor dir.\nLegenden erzählen von Karten, deren Kraft hier unter den richtigen Umständen exponentiell wächst ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, ".. However, it appears that you don't have anything to offer to the enchanted grounds..", "... Allerdings hast du der verzauberten Stätte anscheinend nichts anzubieten ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Enchanted Grounds seem to be slightly improved.", "Die Verzauberte Stätte scheint sich leicht verbessert zu haben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Enchanted Grounds are unsatisfied..", "Die Verzauberte Stätte ist unzufrieden ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Enchanted Grounds dimly light up with sacrifical energy.", "Die Verzauberte Stätte leuchtet schwach vor Opferenergie.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Enchanted Grounds are displeased..", "Die Verzauberte Stätte ist verstimmt ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Enchanted Grounds light up with supernatural energy.", "Die Verzauberte Stätte leuchtet vor übernatürlicher Energie.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Enchanted Grounds are angered..", "Die Verzauberte Stätte ist erzürnt ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Enchanted Grounds The Enchanted Grounds are absolutely bursting with sacrifical energy.", "Die Verzauberte Stätte birst geradezu vor Opferenergie.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Enchanted Grounds The Enchanted Grounds are furious.", "Die Verzauberte Stätte ist rasend vor Wut.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eurgh.. This place is disgusting..", "Igitt ... Dieser Ort ist widerlich ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seems like I'm forced to train spellcasting in here.", "Anscheinend muss ich hier das Zaubern üben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Give me a [c:g1]spell[c:] of yours, and make it quick.", "Gib mir einen deiner [c:g1]Zauber[c:], und zwar schnell.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greetings..", "Sei gegrüßt ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Give me one of your [c:g1]spells[c:]", "Gib mir einen deiner [c:g1]Zauber[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Give me one of your [c:g1]spells[c:].", "Gib mir einen deiner [c:g1]Zauber[c:].", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh.. Greetings... I don't believe we've been introduced..", "Oh ... Sei gegrüßt ... Ich glaube nicht, dass wir einander vorgestellt wurden ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've been force- er.. asked to train my spellcasting here.", "Ich wurde gezwun— äh ... gebeten, hier das Zaubern zu üben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why don't you give me some of your [c:g1]spells[c:]?", "Wie wäre es, wenn du mir ein paar deiner [c:g1]Zauber[c:] gibst?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm? Oh, hello again.. We still haven't been formally introduced.", "Hm? Oh, hallo wieder ... Wir wurden einander immer noch nicht förmlich vorgestellt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll need one of your [c:g1]spells[c:] for my training..", "Für mein Training brauche ich einen deiner [c:g1]Zauber[c:] ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh.. Hello there.", "Oh ... Hallo da.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The master asked me to practice my spellcasting..", "Der Meister hat mich gebeten, das Zaubern zu üben ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh.. Spellcasting. Right..", "Oh ... Zaubern. Richtig ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What? Oh.. This must be.. [c:g3]his[c:] area..", "Was? Oh ... Das muss ... [c:g3]sein[c:] Bereich sein ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well, anyway.. The master asked me to train my spellcasting.", "Wie auch immer ... Der Meister hat mich gebeten, das Zaubern zu üben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm..?", "Hm ...?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here already? We haven't even battled..", "Schon hier? Wir haben noch nicht einmal gekämpft ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well anyways, just hand over a [c:g1]spell[c:].", "Wie auch immer, gib einfach einen [c:g1]Zauber[c:] her.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh.. You don't have any spells?", "Oh ... Du hast gar keine Zauber?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I guess I could give you one of my upgraded ones.. Hopefully they're good.", "Ich könnte dir wohl einen meiner verbesserten geben ... Hoffentlich sind sie gut.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now your spell will last forever..", "Jetzt wird dein Zauber ewig halten ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So, you truly wish to release that tyrant..", "Du willst diesen Tyrannen also wirklich freilassen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope you understand the type of power you are dealing with..", "Ich hoffe, du begreifst, mit welcher Art von Macht du es zu tun hast ...", Language.German);
            foreach (var kvp in Cards)
            {
                foreach (var kvp2 in Abilities)
                {
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your " + kvp.Key + " is now free of its " + kvp2.Key + "...", "Deine Karte " + kvp.Value + " ist nun frei von " + kvp2.Value + " ...", Language.German);
                }
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm.. The essence of that sigil does not resonate with your card..", "Hm ... Die Essenz dieses Siegels harmoniert nicht mit deiner Karte ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "..It appears nothing was gained", "... Anscheinend wurde nichts gewonnen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The essence of the sigil has imbued the card with more power.", "Die Essenz des Siegels hat die Karte gestärkt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The essence of the sigil has imbued the card with more gourd.", "Die Essenz des Siegels hat die Gesundheit der Karte erhöht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The essence of the sigil has imbued the card with more strength.", "Die Essenz des Siegels hat die Kraft der Karte erhöht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmph.. My bleach.. failed?", "Hmpf ... Mein Bleichmittel ... hat versagt?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Was this your doing, challenger?", "War das dein Werk, Herausforderer?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmph..", "Hmpf ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to imbue with a lost sigils strength..", "Wähle eine Karte, die mit der Stärke eines verlorenen Siegels erfüllt werden soll ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here I will allow you to [c:g1]bleach[c:] a card of one of its sigils..", "Hier erlaube ich dir, eines der Siegel einer Karte [c:g1]wegzubleichen[c:] ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When bleached, the card will imbue the power of its lost sigil,", "Nach dem Bleichen nimmt die Karte die Macht ihres verlorenen Siegels auf,", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "and get much [c:g2]stronger[c:] depending on the sigils raw strength.", "und wird je nach roher Stärke des Siegels deutlich [c:g2]stärker[c:].", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah, but your [c:g1]spell book[c:] is full...", "Ah, aber dein [c:g1]Zauberbuch[c:] ist voll ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You step foot into a small store.. A brief respite from your winding travels.", "Du betrittst einen kleinen Laden ... Eine kurze Rast auf deiner verschlungenen Reise.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You step foot into a small store...", "Du betrittst einen kleinen Laden ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your [c:g1]deck[c:] is stored in this pile.. ", "Dein [c:g1]Stapel[c:] liegt in diesem Haufen ... ", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, ".. And your [c:g1]side deck[c:] is stored here, where you can adjust it as you see fit. ", "... Und dein [c:g1]Nebenstapel[c:] liegt hier. Du kannst ihn nach Belieben anpassen. ", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, ".. Hmmph, I guess it was not meant to be..", "... Hmpf, es sollte wohl nicht sein ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Twisted and warped by the fungi, a new card emerges. Only through pain can one grow…", "Von den Pilzen verdreht und verzerrt, kommt eine neue Karte hervor. Nur durch Schmerz kann man wachsen…", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now the mushrooms require a card that they will attach.. Increasing the stats of the host.", "Nun brauchen die Pilze eine Karte, an die sie sich heften ... Dabei erhöhen sie die Werte des Wirts.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You encounter the abnormally disgusting fungi that infests this dungeon.", "Du stößt auf die außergewöhnlich widerlichen Pilze, die dieses Verlies befallen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is said to possess strange properties..", "Man sagt, sie hätten seltsame Eigenschaften ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mushrooms yearn for a card they can use as a.. [c:g1]host[c:] of sorts.", "Die Pilze sehnen sich nach einer Karte, die ihnen als eine Art ... [c:g1]Wirt[c:] dienen kann.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One that they will attack to.", "Eine, an die sie sich heften können.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You encounter the disgusting fungi yet again..", "Du stößt erneut auf die widerlichen Pilze ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The fungi yearn for a card they can use as a [c:g1]host[c:].. to attach to.", "Die Pilze sehnen sich nach einer Karte, die ihnen als [c:g1]Wirt[c:] dienen kann ... an die sie sich heften können.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yet... It seems you do not have two cards worthy of the fungi's touch. Wearisome.", "Doch ... Anscheinend hast du keine zwei Karten, die der Berührung der Pilze würdig sind. Ermüdend.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have the honours of naming it.", "Du hast die Ehre, ihr einen Namen zu geben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Finished?", "Fertig?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The [c:g1]cost[c:] and [c:g2]portrait[c:] I will handle myself..", "Um die [c:g1]Kosten[c:] und das [c:g2]Kartenbild[c:] kümmere ich mich selbst ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It was nice meeting you, my student.", "Es war schön, dich kennenzulernen, mein Schüler.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But this is where we say farewell..", "Doch hier müssen wir Abschied nehmen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just hold still for a second.", "Halt nur einen Augenblick still.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I will base it off of cards in your deck.", "Ich werde mich dabei an den Karten in deinem Stapel orientieren.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "First, the stats.", "Zuerst die Werte.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The [c:g1]sigils[c:].", "Die [c:g1]Siegel[c:].", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm.. You're out of paint.", "Hm ... Deine Farbe ist aufgebraucht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can bleach your drawing.. or consider it finished.", "Du kannst dein Bild bleichen ... oder es als fertig betrachten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A neccesary part of each student's training is art..", "Kunst ist ein notwendiger Teil der Ausbildung jedes Schülers ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's start with the portrait..", "Beginnen wir mit dem Kartenbild ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can use the bleach on the left to wipe your work..", "Du kannst dein Werk mit dem Bleichmittel links wegwischen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You are currently holding a [c:g1]replica brush[c:].. If you feel you need a smaller one, you can grab the one on the right.", "Du hältst gerade einen [c:g1]Nachbildungspinsel[c:] ... Wenn du einen kleineren brauchst, kannst du den rechts nehmen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Use that brush in the back to change your color.", "Benutze den Pinsel hinten, um deine Farbe zu wechseln.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My pupil's portraits never fail to amuse me..", "Die Kartenbilder meiner Schüler amüsieren mich jedes Mal ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now let's choose which card's [c:g1]stats[c:] to imbue.", "Wählen wir nun, von welcher Karte wir die [c:g1]Werte[c:] übernehmen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now, the [c:g1]sigils[c:].", "Nun die [c:g1]Siegel[c:].", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah, but your spell book is full..", "Ah, aber dein Zauberbuch ist voll ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Either discard this one...", "Entweder wirfst du diese hier ab ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Or, remove one of your spells..", "Oder du entfernst einen deiner Zauber ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You don't have any cards to use that [c:g1]potion[c:] on.", "Du hast keine Karten, auf die du diesen [c:g1]Trank[c:] anwenden kannst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You won't have any cards to use that spell on.", "Du wirst keine Karten haben, auf die du diesen Zauber anwenden kannst.", Language.German);
            foreach (var value in Cards.Values)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your " + value + " wields no mana.", "Deine Karte " + value + " besitzt kein Mana.", Language.German);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That doesn't have any mana.", "Das hat kein Mana.", Language.German);
            foreach (var value in Cards.Values)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The " + value + " has no mana.", "Die Karte " + value + " besitzt kein Mana.", Language.German);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can not draw mana from that.", "Daraus kannst du kein Mana ziehen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Through this maze of paintings and illusions, there may be some that deign to join your deck.\nChoose carefully.", "In diesem Labyrinth aus Gemälden und Illusionen könnten sich manche dazu herablassen, deinem Stapel beizutreten.\nWähle mit Bedacht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "... Curious.", "... Seltsam.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I thought I had completely removed this.. [c:g2]filth[c:].", "Ich dachte, ich hätte diesen ... [c:g2]Unrat[c:] restlos entfernt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You humor me challenger..", "Du amüsierst mich, Herausforderer ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Did you expect your measely [c:g1]hammer[c:] to work on such a creature as the [c:g1]ouroberyl[c:]?", "Hast du erwartet, dass dein mickriger [c:g1]Hammer[c:] bei einer Kreatur wie dem [c:g1]Ouroberyll[c:] funktioniert?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How foolish.", "Wie töricht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your hammer is now [c:g1]broken[c:], and may not be used for the remainder of the battle.", "Dein Hammer ist nun [c:g1]zerbrochen[c:] und kann für den Rest des Kampfes nicht mehr benutzt werden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems that you lost..", "Anscheinend hast du verloren ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "See this portrait?", "Siehst du dieses Kartenbild?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This portrait will act as your life counter.", "Dieses Kartenbild dient als dein Lebenszähler.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once all the [c:g1]m[c:][c:g2]o[c:][c:g3]x[c:] [c:g1]g[c:][c:g2]e[c:][c:g3]m[c:][c:g1]s[c:] go out.. You lose the game.", "Sobald alle [c:g1]M[c:][c:g2]o[c:][c:g3]x[c:]-[c:g1]Edel[c:][c:g2]ste[c:][c:g3]in[c:][c:g1]e[c:] erlöschen ... verlierst du das Spiel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Since you lost.. I will have to remove one gem.", "Da du verloren hast ... muss ich einen Edelstein entfernen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The deed has been done.", "Es ist vollbracht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looks like you have been knocked down by your opponent.", "Anscheinend hat dein Gegner dich zu Boden geworfen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stand tall, and continue forth.", "Richte dich auf und geh weiter.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems as though you should study up on mox.", "Du solltest dich wohl eingehender mit Mox beschäftigen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though you should not lose hope, as you still have 2 more lives.", "Doch verliere nicht die Hoffnung, denn du hast noch 2 Leben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You make a last effort to succeed, yet fail. It seems you lose, again.", "Du unternimmst einen letzten Versuch zu siegen, scheiterst jedoch. Anscheinend verlierst du schon wieder.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You shall continue forward.", "Du wirst weitergehen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It takes just one more blow for you to fall to the ground.", "Nur ein weiterer Schlag genügt, um dich zu Boden zu strecken.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Losing a life, you must continue forward.", "Du hast ein Leben verloren und musst weitergehen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems the show shall end… for now..", "Anscheinend endet die Vorstellung… vorerst ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just what is going on here?", "Was geht hier eigentlich vor?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "'Master Magnus'..", "„Höchster Meister“ ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is [c:g2]NO[c:] such master!", "Einen solchen Meister gibt es [c:g2]NICHT[c:]!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Argh.. I guess, if you truly wish to play with such additions, I am truly unable to stop you.", "Argh ... Wenn du wirklich mit solchen Zusätzen spielen willst, kann ich dich wohl wirklich nicht aufhalten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though, I do NOT approve of this.", "Doch ich billige das NICHT.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It appears that the ficticious Master Magnus has showed itself.", "Anscheinend hat sich der fiktive Höchste Meister gezeigt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That horrid [c:g1]thing[c:] rears it's ugly head.", "Dieses grauenhafte [c:g1]Ding[c:] reckt seinen hässlichen Kopf empor.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The released Master Magnus approaches.", "Der befreite Höchste Meister nähert sich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Careful. That horrible master is here.", "Vorsicht. Dieser schreckliche Meister ist hier.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Magnus has arrived. Be cautious.", "Der Höchste Meister ist eingetroffen. Sei vorsichtig.", Language.German);
            foreach (var kvp in Cards)
            {
                var key = kvp.Key;
                var value = kvp.Value;
                foreach (var kv in CardsDescription[key])
                {
                    var descKey = kv.Key;
                    var descValue = kv.Value;
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You glance at a " + key + ". " + descKey, "Du wirfst einen Blick auf die Karte " + value + ". " + descValue, Language.German);
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A " + key + " appears from within the portrait. " + descKey, "Die Karte " + value + " erscheint aus dem Porträt. " + descValue, Language.German);
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You gaze at a " + key + ". " + descKey, "Du betrachtest die Karte " + value + ". " + descValue, Language.German);
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You glance at an " + key + ". " + descKey, "Du wirfst einen Blick auf die Karte " + value + ". " + descValue, Language.German);
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An " + key + " appears from within the portrait. " + descKey, "Die Karte " + value + " erscheint aus dem Porträt. " + descValue, Language.German);
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You gaze at an " + key + ". " + descKey, "Du betrachtest die Karte " + value + ". " + descValue, Language.German);
                }
            }

            // ShowThenClear
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose wisely.", "Wähle weise.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ARRGH!!!", "AAARGH!!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]STRIKE![c:]", "[c:g1]SCHLAG ZU![c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g2]STRIKE![c:]", "[c:g2]SCHLAG ZU![c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Au Revoir", "Auf Wiedersehen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How reckless.", "Wie leichtsinnig.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm.. I see..", "Hm ... Ich verstehe ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But you'll [c:g2]NEVER[c:] delete me, the Scrybe of Magicks!", "Aber du wirst mich, den Wahrschreiber der Magie, [c:g2]NIEMALS[c:] löschen!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GRRAHH!!", "GRRAAAH!!", Language.German);
            Dictionary<GemType, string> gemTypesEn = new Dictionary<GemType, string>
            {
                { GemType.Orange, "Orange" },
                { GemType.Blue, "Blau" },
                { GemType.Green, "Grün" },
            };
            Dictionary<GemType, string> gemTypes = new Dictionary<GemType, string>
            {
                { GemType.Orange, "Orange" },
                { GemType.Blue, "Blau" },
                { GemType.Green, "Grün" },
            };
            foreach (var gemType in gemTypes.Keys)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You don't have two " + HintsHandler.GetColorCodeForGem(gemType) + gemTypesEn[gemType] + "</color> gems to play that.", "Du hast keine zwei Edelsteine der Farbe " + HintsHandler.GetColorCodeForGem(gemType) + gemTypes[gemType] + "</color>, um diese Karte auszuspielen.", Language.German);
                foreach (var value in Cards.Values)
                {
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You'll need two " + HintsHandler.GetColorCodeForGem(gemType) + gemTypesEn[gemType] + "</color> gems to play your " + value + ".", "Du brauchst zwei Edelsteine der Farbe " + HintsHandler.GetColorCodeForGem(gemType) + gemTypes[gemType] + "</color>, um deine Karte " + value + " auszuspielen.", Language.German);
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You don't have enough " + HintsHandler.GetColorCodeForGem(gemType) + gemTypesEn[gemType] + "</color> gems on the board to play that " + value + ".", "Auf dem Brett liegen nicht genug Edelsteine der Farbe " + HintsHandler.GetColorCodeForGem(gemType) + gemTypes[gemType] + "</color>, um " + value + " auszuspielen.", Language.German);
                }
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You need two " + HintsHandler.GetColorCodeForGem(gemType) + gemTypesEn[gemType] + "</color> gems on the board.", "Auf dem Brett werden zwei Edelsteine der Farbe " + HintsHandler.GetColorCodeForGem(gemType) + gemTypes[gemType] + "</color> benötigt.", Language.German);
            }

            // ShowMessage
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "whats up", "was geht", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My [c:g1]Goo Mage[c:] falls by your hands.. I expected more from him..", "Mein [c:g1]Schleimmagier[c:] fällt durch deine Hand ... Ich hatte mehr von ihm erwartet ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmph.. My [c:g1]Goo Mage[c:] dissapoints me again..", "Hmpf ... Mein [c:g1]Schleimmagier[c:] enttäuscht mich schon wieder ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yet again, my pathetic [c:g1]Goo Mage[c:] falls..", "Wieder einmal fällt mein erbärmlicher [c:g1]Schleimmagier[c:] ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]What..?[c:] [c:g2]Me,[c:] [c:g1]defeated..?[c:]", "[c:g1]Was ...?[c:] [c:g2]Ich,[c:] [c:g1]besiegt ...?[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]Blargh..[c:] [c:g2]I've[c:] [c:g1]been[c:] [c:g2]taken[c:] [c:g1]out[c:] [c:g2]by[c:] [c:g1]you??[c:] ", "[c:g1]Argh ...[c:] [c:g2]Ich[c:] [c:g1]wurde[c:] [c:g2]also[c:] [c:g1]tatsächlich[c:] [c:g2]von[c:] [c:g1]dir besiegt??[c:] ", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]Impossible..[c:] [c:g2]I've[c:] [c:g1]been[c:] [c:g2]defeated..[c:]", "[c:g1]Unmöglich ...[c:] [c:g2]Ich[c:] [c:g1]wurde[c:] [c:g2]besiegt ...[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ahh.. I see you've defeated my [c:g2]Pike Mage[c:]..", "Ah ... Du hast also meinen [c:g2]Speermagier[c:] besiegt ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My [c:g2]Pike Mage[c:] falls.. Dissapointing.", "Mein [c:g2]Speermagier[c:] fällt ... Enttäuschend.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll admit challenger.. You've gotten farther than most.", "Ich gebe es zu, Herausforderer ... Du bist weiter gekommen als die meisten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g2]A[c:] [c:g3]fantastic[c:] [c:g2]duel[c:] [c:g3]we[c:] [c:g2]had![c:]", "[c:g2]Ein[c:] [c:g3]fantastisches[c:] [c:g2]Duell[c:] [c:g3]war[c:] [c:g2]das![c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g2]'Twas[c:] [c:g3]an[c:] [c:g2]excellent[c:] [c:g3]battle.[c:]", "[c:g2]Das war[c:] [c:g3]ein[c:] [c:g2]ausgezeichneter[c:] [c:g3]Kampf.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g2]Great[c:] [c:g3]fighting,[c:] [c:g2]young[c:] [c:g3]mage.[c:]", "[c:g2]Gut[c:] [c:g3]gekämpft,[c:] [c:g2]junger[c:] [c:g3]Magier.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well challenger.. Now that you have defeated the [c:g3]Lonely Mage[c:]. You may now face me.", "Nun, Herausforderer ... Da du den [c:g3]Einsamen Magier[c:] besiegt hast, kannst du nun gegen mich antreten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You've defeated all my students.. I will await your arrival.", "Du hast all meine Schüler besiegt ... Ich erwarte deine Ankunft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My [c:g3]Lonely Mage[c:] falls.. this is unexpected.. But now, I await your arrival.", "Mein [c:g3]Einsamer Magier[c:] fällt ... Das ist unerwartet ... Doch nun erwarte ich deine Ankunft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g3]An[c:] [c:g1]excellent[c:] [c:g3]fight![c:]", "[c:g3]Ein[c:] [c:g1]ausgezeichneter[c:] [c:g3]Kampf![c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g3]Despite[c:] [c:g1]my[c:] [c:g3]deadliest[c:] [c:g1]books,[c:] [c:g3]you[c:] [c:g1]still[c:] [c:g3]won![c:]", "[c:g3]Trotz[c:] [c:g1]meiner[c:] [c:g3]tödlichsten[c:] [c:g1]Bücher[c:] [c:g3]hast du[c:] [c:g1]trotzdem[c:] [c:g3]gewonnen![c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g3]You[c:] [c:g1]managed[c:] [c:g3]to[c:] [c:g1]overcome[c:] [c:g3]my[c:] [c:g1]deadliest[c:] [c:g3]tomes,[c:] [c:g1]impressive![c:]", "[c:g3]Du[c:] [c:g1]hast es geschafft,[c:] [c:g3]meine[c:] [c:g1]aller[c:] [c:g3]tödlichsten[c:] [c:g1]Folianten[c:] [c:g3]zu überwinden,[c:] [c:g1]beeindruckend![c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g3]Whoops![c:] [c:g1]Looks[c:] [c:g3]you[c:] [c:g1]need[c:] [c:g3]to[c:] [c:g1]study[c:] [c:g3]up[c:] [c:g1]on[c:] [c:g3]mox.[c:]", "[c:g3]Hoppla![c:] [c:g1]Anscheinend[c:] [c:g3]musst du[c:] [c:g1]dich[c:] [c:g3]noch[c:] [c:g1]eingehender[c:] [c:g3]mit[c:] [c:g1]den[c:] [c:g3]Mox beschäftigen.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My Pike Mage bests another opponent...", "Mein Speermagier besiegt einen weiteren Gegner ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dissapointing...", "Enttäuschend ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]Yet[c:] [c:g2]another[c:] [c:g1]soul[c:] [c:g2]I[c:] [c:g1]claim.[c:] [c:g2]Banish[c:] [c:g1]yourself[c:] [c:g2]to[c:] [c:g1]the[c:] [c:g2]depths,[c:] [c:g1]and[c:] [c:g2]do[c:] [c:g1]not[c:] [c:g2]return.[c:]", "[c:g1]Wieder[c:] [c:g2]eine weitere[c:] [c:g1]Seele,[c:] [c:g2]die ich[c:] [c:g1]beanspruche.[c:] [c:g2]Verbanne[c:] [c:g1]dich[c:] [c:g2]in[c:] [c:g1]die[c:] [c:g2]Tiefe[c:] [c:g1]und[c:] [c:g2]kehre[c:] [c:g1]nicht[c:] [c:g2]zurück.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yet another student, hit off guard by my Lonely Mage..", "Noch ein Schüler, den mein Einsamer Magier unvorbereitet erwischt hat ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You got so far.....", "Du warst so weit gekommen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weak.", "Schwach.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g2]Farewell,[c:] [c:g3]young[c:] [c:g2]mage![c:] [c:g3]'Twas[c:] [c:g2]a[c:] [c:g3]fantastic[c:] [c:g2]duel.[c:]", "[c:g2]Leb wohl,[c:] [c:g3]junger[c:] [c:g2]Magier![c:] [c:g3]Es war[c:] [c:g2]ein[c:] [c:g3]fantastisches[c:] [c:g2]Duell.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "~ Goo Dungeon ~", "~ Schleimverlies ~", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "~ Lava Dungeon ~", "~ Lavaverlies ~", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "~ Void Dungeon ~", "~ Verlies der Leere ~", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "~ Tower of Magicks ~", "~ Turm der Magie ~", Language.German);
            for (int currency = 0; currency <= 100; currency++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g3]~ " + currency + " Crystals ~[c:]", "[c:g3]~ " + currency + " " + (currency == 1 ? "Kristall" : "Kristalle") + " ~[c:]", Language.German);
            }

            // Challenge
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blank Mox", "Leerer Mox", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your sidedeck's mox is completely random.", "Die Mox in deinem Nebenstapel sind völlig zufällig.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weaker Bleach", "Schwächeres Bleichmittel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bleaching Event can no longer remove negative sigils.", "Das Bleichereignis kann keine negativen Siegel mehr entfernen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Turn Wipeout", "Zugvernichtung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When you ring the bell past turn 6 (12 on bosses) you take 1 damage.", "Wenn du nach Zug 6 (12 bei Bossen) die Glocke läutest, erleidest du 1 Schaden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stronger Opponent", "Stärkerer Gegner", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your battle opponent starts with 5 extra health points.", "Dein Kampfgegner beginnt mit 5 zusätzlicher Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tiny Spellbook", "Winziges Zauberbuch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your spellbook can only hold 4 spells instead of 8.", "Dein Zauberbuch fasst nur 4 Zauber statt 8.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Displeased Spirits", "Unzufriedene Geister", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The enchanted grounds will always be displeased.", "Die Verzauberte Stätte wird stets verstimmt sein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Armored Shell", "Gepanzerte Hülle", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your opponent cant take more than 4 damage per turn.", "Dein Gegner kann pro Zug höchstens 4 Schaden erleiden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Iron Maiden", "Eiserne Jungfrau", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every turn, each mox on your side of the board takes 1 damage.", "In jedem Zug erleidet jeder Mox auf deiner Seite des Bretts 1 Schaden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magickal Paint", "Magische Farbe", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Queued cards will occasionally get additional sigils painted on them.", "Auf Karten in der Warteschlange werden gelegentlich zusätzliche Siegel gemalt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fleeting Life", "Flüchtiges Leben", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have 75 health, but it does not replenish inbetween battles.", "Du hast 75 Gesundheit, die sich zwischen Kämpfen jedoch nicht auffüllt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Intrusive Presence", "Aufdringliche Präsenz", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An unwelcome prescence will follow you into card battles.", "Eine unerwünschte Präsenz folgt dir in die Kartenkämpfe.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Bosses", "Meisterbosse", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every bossfight is replaced with one of the Mox Masters.", "Jeder Bosskampf wird durch einen der Mox-Meister ersetzt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Dependant Starters", "Edelsteinabhängiger Start", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards in your starting deck have the gem dependant sigil.", "Die Karten in deinem Startstapel haben das Siegel Auf Edelsteine angewiesen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magnificus Challenge Level: {0}", "Magnificus-Herausforderungsstufe: {0}", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magnificus Challenge Points: {0}", "Magnificus-Herausforderungspunkte: {0}", Language.German);

        }
    }

    public class UndeadTempleINKCMMod
    {

        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for UndeadTempleINKCM Mod");
            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Banshee", "Erwachte Todesfee", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A pile of bones, paying for bones in exchange for strength.", "Ein Knochenhaufen, der Knochen gegen Stärke eintauscht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Bone Heap", "Erwachter Knochenhaufen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Bonehound", "Erwachter Knochenhund", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even after being dead, it remains loyal.", "Selbst nach dem Tod bleibt er treu.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Dead Hand", "Erwachte Tote Hand", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The hand of death, but with life.", "Die Hand des Todes, doch voller Leben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Draugr", "Erwachter Draugr", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frozen ghouls, break and come out.", "Gefrorene Ghule brechen aus und kommen hervor.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened DrownedSoul", "Erwachte Ertrunkene Seele", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The drowned soul wanders with resentment in the water.", "Die ertrunkene Seele streift voller Groll durch das Wasser.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Family", "Erwachte Familie", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A family that died unexpectedly.", "Eine Familie, die unerwartet starb.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frankenstein.", "Frankenstein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A ghost ship that produces a steady stream of skeletons.", "Ein Geisterschiff, das unablässig Skelette hervorbringt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Ghost Ship", "Erwachtes Geisterschiff", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Frank & Stein", "Erwachte Frank & Stein", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Gravedigger", "Erwachter Totengräber", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A diligent gravedigger, he constantly supplies bones.", "Ein fleißiger Totengräber, der ständig Knochen liefert.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death Knight, the assassin in hell.", "Der Todesritter, der Assassine der Hölle.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Knight", "Erwachter Ritter", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Horn", "Erwachtes Horn", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the bonelord sheds its old horns, they take on a life of their own, to one day usurp their masters.", "Der Knochenfürst wirft seine alten Hörner ab. Sie erwachen zu eigenem Leben, um eines Tages ihren Herrn zu stürzen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mummy God", "Mumiengott", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The King of Terror.", "Der König des Schreckens.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Necromancer", "Erwachter Nekromant", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Born solely for revenge.", "Einzig zur Rache geboren.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Revenant", "Erwachter Wiedergänger", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A formidable sarcophagus with terrifying creations sealed inside.", "Ein gewaltiger Sarkophag, in dem furchterregende Schöpfungen versiegelt sind.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Pile", "Knochenhaufen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Bone Pile", "Erwachter Knochenhaufen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Tomb Robber", "Erwachte Grabräuberin", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even if he dies, he still robs tombs.", "Selbst nach dem Tod werden noch Gräber geplündert.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A desperate man.", "Ein verzweifelter Mann.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Zombie", "Erwachter Zombie", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Devouring Soul", "Verschlingende Seele", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A skeleton devouring the soul.", "Ein Skelett, das die Seele verschlingt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Devouring Soul", "Erwachte Verschlingende Seele", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Dead Eye", "Erwachtes Totenauge", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Both Deadeye and Dead Hand are said to be body parts of the same, now dead, god.", "Totenauge und Tote Hand sollen beide Körperteile desselben, inzwischen verstorbenen Gottes sein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ferry Crow", "Fährkrähe", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Ferry Crow", "Erwachte Fährkrähe", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mournful cry of looking down upon the undead after death.", "Nach dem Tod blickt sie auf die Untoten herab und stößt einen klagenden Ruf aus.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grave", "Grabstein", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope no one will disturb it.", "Hoffentlich stört niemand seine Ruhe.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Headless Man", "Kopfloser Mann", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An incompetent headless person, as if searching for something he had lost.", "Ein unfähiger Kopfloser, der nach etwas Verlorenem zu suchen scheint.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Kennel", "Erwachter Zwinger", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A dog house, hopefully no one will mess with the things inside.", "Eine Hundehütte. Hoffentlich legt sich niemand mit dem an, was darin ist.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pharmacist", "Apotheker", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Pharmacist", "Erwachter Apotheker", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A dead pharmacist who poisons all creations that oppose him.", "Ein toter Apotheker, der alle Schöpfungen vergiftet, die sich ihm widersetzen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleader", "Skelettanführer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A skeleton leader, once on stage, is surrounded by skeletons.", "Ein Skelettanführer, der beim Betreten des Spiels von Skeletten umringt wird.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Skeleader", "Erwachter Skelettanführer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleton Sniper", "Skelettscharfschütze", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A dead sniper.", "Ein toter Scharfschütze.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Skeleton Sniper", "Erwachter Skelettscharfschütze", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Threaded Skeleton", "Fadenskelett", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Some people are born puppets, while others still control others after death.", "Manche werden als Marionetten geboren, andere kontrollieren ihre Mitmenschen noch nach dem Tod.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Threaded Skeleton", "Erwachtes Fadenskelett", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undead Elk", "Untoter Hirsch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The undead elk, a former husk of of what it once was.", "Der untote Hirsch, nur noch eine Hülle seines früheren Selbst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undead Elk Cub", "Untotes Hirschkalb", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even death carries vitality and desire.", "Selbst im Tod bleiben Lebenskraft und Verlangen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undead Moose", "Untoter Elch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A rotting carcass of a long-departed imposing beast.", "Der verrottende Kadaver einer längst verstorbenen, imposanten Bestie.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Undead Moose", "Erwachter Untoter Elch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undead Predator", "Untotes Raubtier", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warriors who die in war will never bow down.", "Krieger, die im Krieg sterben, werden sich niemals beugen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Undead Predator", "Erwachtes Untotes Raubtier", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undead RedHart", "Untoter Rothirsch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "its decaying mind retains the strength of sacrifice.", "Sein verwesender Geist bewahrt die Kraft des Opfers.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Undead RedHart", "Erwachter Untoter Rothirsch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undead Snapper", "Untote Schnappschildkröte", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Undead Snapper", "Erwachte Untote Schnappschildkröte", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The corpse of a stiff terrestrial creation.", "Die Leiche einer starren Landschöpfung.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleton Dragon", "Skelettdrache", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleton Dragon, its remaining skeletons still roar with the destructive fury of old.", "Der Skelettdrache. Seine verbliebenen Knochen brüllen noch immer vor der zerstörerischen Wut vergangener Zeiten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Skeleton Dragon", "Erwachter Skelettdrache", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Free Revenant", "Freier Wiedergänger", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Free Revenant", "Erwachter Freier Wiedergänger", Language.German);


            // Ability / Pack
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleader", "Skelettanführer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When placing [creature], skeleton cards will appear in nearby empty spaces. Skeleton has: 1 power, 1 health, Brittle.", "Wenn du [creature] platzierst, erscheinen Skelettkarten auf benachbarten leeren Feldern. Ein Skelett hat 1 Kraft, 1 Gesundheit und Brüchig.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Original Undead Card", "Originale Untotenkarten", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cards for the Undead Tribe are in the original game.(ACT2)", "Die Karten der Untotenfamilie aus dem Originalspiel. (AKT 2)", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NonOriginal Undead Card", "NonOriginal-Untotenkartenpaket", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The expansion cards for the Undead Tribe are not in the original game.", "Die Erweiterungskarten der Untotenfamilie, die nicht im Originalspiel enthalten sind.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cards for the Undead Tribe are in the ACT2 original game, It contains [count] cards.", "Die Karten der Untotenfamilie aus Akt 2 des Originalspiels. Enthält [count] Karten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The expansion cards for the Undead Tribe are not in the original game, It contains [count] cards.", "Die Erweiterungskarten der Untotenfamilie, die nicht im Originalspiel enthalten sind. Enthält [count] Karten.", Language.German);

        }
    }

    public class WildernessLegendMod
    {

        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for WildernessLegend Mod");
            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amalgam Pup", "Mischwesenjunges", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When you grow up, you can see that it is terrible.", "Wenn es heranwächst, wirst du sehen, wie furchtbar es ist.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chicken", "Huhn", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dud Egg", "Unbrauchbares Ei", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An egg that doesn't grow? Maybe you can help it.", "Ein Ei, das nicht wächst? Vielleicht kannst du ihm helfen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Funny chiking", "Lustiges Hühnchen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A very stinky chicken, but it has a sharp beak.", "Ein sehr stinkendes Huhn, aber mit einem scharfen Schnabel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Roc", "Roch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stinky Chiking", "Stinkendes Hühnchen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every chicken has a dream.", "Jedes Hühnchen hat einen Traum.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Annoying Dog", "Nerviger Hund", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such an annoying dog, perhaps, is the author of a certain pixel game.", "So ein nerviger Hund. Vielleicht ist er der Autor eines gewissen Pixelspiels.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Arctic Fox", "Polarfuchs", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A solitary Vulpes lagopus with great strength.", "Ein einzelgängerischer Polarfuchs von großer Stärke.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Dog", "Knochensuchhund", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Running and running, just to find its bones.", "Er rennt und rennt, nur um seine Knochen zu finden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fox", "Fuchs", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hyena", "Hyäne", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone seeking bandits in the wilderness.", "Knochensuchende Banditen der Wildnis.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Loky", "Wolfskönig Loky", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The king of the whole pack of wolves, very, very powerful.", "Der König des ganzen Wolfsrudels, sehr, sehr mächtig.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pastoral Dog", "Chinesischer Landhund", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loyal Chinese pastoral dogs, they guard and protect their owners' houses.", "Treue chinesische Landhunde, die die Häuser ihrer Besitzer bewachen und beschützen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spotted Hyena", "Tüpfelhyäne", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spotted hyenas searching for bones, they grow stronger with their thirst for blood.", "Tüpfelhyänen auf Knochensuche. Ihr Blutdurst macht sie stärker.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lion", "Löwe", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A strong lion with a fairly strong attack.", "Ein kräftiger Löwe mit einem ziemlich starken Angriff.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lioness", "Löwin", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The lioness guarding the lion herd are always on guard against external invasions.", "Die Löwinnen, die das Rudel bewachen, sind stets vor Eindringlingen auf der Hut.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lynx", "Luchs", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The solitary Lynx attacks with its sharp claws and teeth.", "Der einzelgängerische Luchs greift mit seinen scharfen Krallen und Zähnen an.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Puma", "Puma", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strong Puma, the leader among feline animals.", "Ein kräftiger Puma, ein Anführer unter den Katzenartigen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Puma Cub", "Pumajunges", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The immature Puma cub. It will grow into a Puma after a turn.", "Ein unreifes Pumajunges. Nach einem Zug wächst es zu einem Puma heran.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thunder Tiger", "Donnertiger", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They came with thunder and then suddenly left.", "Er kam mit dem Donner und verschwand dann plötzlich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Axolotl", "Axolotl", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This cute little guy has a very special tail.", "Dieses niedliche Kerlchen hat einen ganz besonderen Schwanz.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Axolotl Tail", "Axolotlschwanz", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carp", "Karpfen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The fish in the Chinese totem is said to have unfathomable powers.", "Dem Fisch der chinesischen Totems werden unergründliche Kräfte nachgesagt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coral Polyp", "Korallenpolyp", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They coexist with the terrain.", "Sie leben mit dem Gelände zusammen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Globefish", "Kugelfisch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Any creature that dreams of harming it will regret it.", "Jede Kreatur, die davon träumt, ihm zu schaden, wird es bereuen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shark Egg", "Haiei", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've never seen a shark egg look like this before.", "Ich habe noch nie zuvor ein Haiei gesehen, das so aussieht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Squidge", "Kalmar", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What kind of creature will the little one grow into?", "Zu welcher Kreatur wird das Kleine heranwachsen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Poor little ones......", "Arme Kleine ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Joannes", "Joannes", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A peculiar creature that only exists in nightmares.", "Eine eigentümliche Kreatur, die nur in Albträumen existiert.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "God Joannes", "Gott Joannes", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Miemie Method", "Miemie Method", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A little cute who can write code.", "Ein niedliches Kerlchen, das programmieren kann.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Potato Elk", "Kartoffelhirsch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The potatoes have sprouted.", "Die Kartoffeln sind gekeimt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Potato Elk Cub", "Kartoffelhirschkalb", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A deer with potatoes on its antlers, it seems that the potato is the owner.", "Ein Hirsch mit Kartoffeln auf dem Geweih. Anscheinend ist die Kartoffel der Besitzer.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wapiti", "Wapiti", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A strong and vital deer.", "Ein kräftiger und lebhafter Hirsch.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cicada", "Zikade", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They gather in groups, calling on friends, which is annoying.", "Sie versammeln sich in Gruppen und rufen ihre Freunde. Wie lästig.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dragonfly", "Libelle", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dragonflies that point to where to hit.", "Libellen, die genau dort zuschlagen, wohin man zeigt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant Centipede", "Riesenhundertfüßer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The giant centipedes hidden deep underground use their sharp fangs to defend their territory.", "Tief unter der Erde verborgene Riesenhundertfüßer verteidigen ihr Revier mit scharfen Kieferklauen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leafcutter ant", "Blattschneiderameise", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They have sharp claws.", "Sie haben scharfe Krallen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Locust swarms", "Heuschreckenschwarm", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A large number of locusts swept in, and it was a disaster for the peasants.", "Eine große Menge Heuschrecken fiel ein. Für die Bauern war es eine Katastrophe.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shield bug", "Stinkwanze", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Disgusting stink bugs, no one wants to approach them.", "Widerliche Stinkwanzen, denen niemand nahekommen will.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soldier Ant", "Soldatenameise", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soldier Ant that point to where to hit.", "Soldatenameisen, die genau dort zuschlagen, wohin man zeigt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acorn", "Eichel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Armadillo", "Gürteltier", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The 'Shield Dwarves' of the wilderness have both offense and defense when curled up.", "Die „Schildzwerge“ der Wildnis vereinen Angriff und Verteidigung, wenn sie sich zusammenrollen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CowBoy", "Revolverheld", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The skilled marksman cowboy who hits every shot.", "Ein Cowboy und meisterhafter Schütze, der mit jedem Schuss trifft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elephant", "Elefant", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The largest creation on land, it has tenacious vitality and defense.", "Die größte Landschöpfung, mit zäher Lebenskraft und robuster Verteidigung.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grizzly Cub", "Grizzlyjunges", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The little bear has not yet grown up, but it is already prepared to face the darkness.", "Der kleine Bär ist noch nicht ausgewachsen, aber schon bereit, sich der Dunkelheit zu stellen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Honey badger", "Honigdachs", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vengeful honey badgers never feel afraid.", "Die rachsüchtigen Honigdachse kennen keine Angst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Meerkat", "Erdmännchen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The watchful Meerkat, it attacks swiftly upon detecting a threat.", "Das wachsame Erdmännchen greift blitzschnell an, sobald es eine Bedrohung bemerkt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mongoose", "Manguste", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The incorruptable Mongoose is resistent to most toxins.", "Die unverwesliche Manguste ist gegen die meisten Gifte resistent.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stunted Grizzly", "Verkümmerter Grizzly", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such a poor, scarred beast- what must have befallen it?", "So eine arme, vernarbte Bestie ... Was muss ihr nur widerfahren sein?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Uri", "Uri", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Abandoned children learn to be independent outside.", "Verlassene Kinder lernen draußen, selbstständig zu sein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Uryli", "Uryli", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A wild man who has learned to be independent.", "Ein wilder Mann, der gelernt hat, selbstständig zu sein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chipmunk", "Streifenhörnchen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A small striped rodent of the forest, carrying an acorn with it as a meal.", "Ein kleines gestreiftes Waldnagetier, das eine Eichel als Mahlzeit bei sich trägt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pushing Mouse", "Schiebemaus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A huge southern mouse.", "Eine riesige Maus aus dem Süden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rat Cub", "Rattenjunges", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A weak rat can grow into a noble rat king.", "Eine schwache Ratte kann zu einem edlen Rattenkönig heranwachsen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Buff Frog", "Muskelprotzfrosch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mutated frog that has gained power.", "Ein mutierter Frosch, der an Kraft gewonnen hat.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "God Frog", "Froschgott", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creeper", "Creeper", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A terrifying creature from the world of Minecraft.", "Eine furchterregende Kreatur aus der Welt von Minecraft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crocodile", "Krokodil", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An animal with a strong biting force.", "Ein Tier mit gewaltiger Beißkraft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rattler egg", "Klapperschlangenei", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A snake egg that is about to hatch, although it is very fragile.", "Ein Schlangenei, das kurz vor dem Schlüpfen steht, aber sehr zerbrechlich ist.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sea Turtle", "Meeresschildkröte", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vibrant sea turtles will not die even after being sacrificed.", "Lebenskräftige Meeresschildkröten sterben selbst dann nicht, wenn sie geopfert werden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thorny Devil", "Dornteufel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This guy's characteristics are just like its name.", "Seine Eigenschaften entsprechen genau seinem Namen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thorny Devil Tail", "Dornteufelschwanz", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Free Rattler egg", "Kostenloses Klapperschlangenei", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amalgam Egg", "Mischwesenei", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Walking Stone", "Wandernder Stein", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A stone that has traveled over mountains and rivers.", "Ein Stein, der über Berge und Flüsse gewandert ist.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stone Deer", "Steinhirsch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A stone deer statue carved by skilled craftsmen.", "Eine steinerne Hirschstatue, von geschickten Handwerkern gemeißelt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stone Wolf", "Steinwolf", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A stone wolf statue carved by skilled craftsmen.", "Eine steinerne Wolfsstatue, von geschickten Handwerkern gemeißelt.", Language.German);

            // Other
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wilderness Legend", "Wildnislegende", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Add some simple cards based on the original imprint.", "Fügt einige einfache Karten auf Grundlage der ursprünglichen Siegel hinzu.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acorns", "Eicheln", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When placing [creature], draw an acorn.", "Wenn du [creature] platzierst, ziehe eine Eichel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cutting Wings", "Flügelstutzer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flying cards struck by [creature] will take 1 damage each time it declares an attack, and renders their wings useless.", "Fliegende Karten, die von [creature] getroffen werden, verlieren ihre Fähigkeit zu fliegen und erleiden jedes Mal 1 Schaden, wenn sie einen Angriff ansagen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Swarm", "Schwarm", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "when [creature] is placed, the remaining slots on the owner's side are filled with cicadas", "Wenn [creature] platziert wird, werden die übrigen leeren Felder auf der Seite des Besitzers mit Zikaden gefüllt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Terrain Creator", "Geländeerschaffer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When placing [creature] on the field, randomly draw a terrain card.", "Wenn du [creature] auf dem Feld platzierst, ziehe eine zufällige Geländekarte.", Language.German);

            //WLD-DLC
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Azure Dragon", "Azurdrache", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The head of the four divine beasts, it has absolute suppressive power.", "Das Oberhaupt der vier göttlichen Bestien, mit absolut überwältigender Macht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chinese Loong", "Chinesischer Drache", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Chinese Loong in myths and legends is the master of all things.", "Der chinesische Drache aus Mythen und Legenden ist der Herr über alle Dinge.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "God long", "Göttlicher Drache", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Andrealphus", "Andrealphus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sixty-fifth demon god of King Solomon.", "Der fünfundsechzigste Dämonengott König Salomons.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Ostrich", "Erwachter Strauß", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Black-tailed Gull", "Schwarzschwanzmöwe", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The black tailed gull at the dock will entrust its soul to the next destined person.", "Die Schwarzschwanzmöwe am Kai wird ihre Seele der nächsten vom Schicksal bestimmten Person anvertrauen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Black tailed gulls at the dock", "Schwarzschwanzmöwen am Kai", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning Egg", "Brennendes Ei", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After hatching, there is eternity.", "Nach dem Schlüpfen folgt die Ewigkeit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eagle", "Adler", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A powerful eagle overlooking the underground.", "Ein mächtiger Adler, der auf die Erde hinabblickt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Falcon", "Wanderfalke", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eager peregrine falcons, they attack as soon as they are laid down.", "Begierige Wanderfalken, die angreifen, sobald sie platziert werden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hot Chiking", "Scharfes Hühnchen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The chicken that is about to become a god.", "Das Huhn, das kurz davorsteht, ein Gott zu werden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ling Bird", "Ling-Vogel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A soaring divine bird will bless a friend to inherit its attributes after death.", "Wenn dieser hoch fliegende Göttervogel stirbt, segnet er einen Verbündeten und vererbt ihm seine Werte.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Night Owl", "Nachteule", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They become stronger when faced with strength.", "Sie werden stärker, wenn sie auf Stärke treffen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ostrich", "Strauß", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ostrich running around, its behavior is unpredictable.", "Der Strauß rennt umher und verhält sich unberechenbar.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pelican", "Pelikan", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The insatiable pelican swallowed the entire creation without digesting it.", "Der unersättliche Pelikan verschlingt die ganze Kreatur, ohne sie zu verdauen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pigeon", "Taube", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The dove symbolizes peace, and its harm depends on the birds on the field.", "Die Taube steht für Frieden. Ihr Schaden hängt von den Vögeln auf dem Feld ab.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rosefinch", "Zinnobervogel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One of the four great mythical beasts in Chinese mythology, constantly burning itself.", "Eine der vier großen göttlichen Bestien der chinesischen Mythologie, die ständig selbst brennt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fire God Rosefinch", "Zinnobervogel, Gott des Feuers", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Secular Bird", "Unsterblicher Vogel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "God Secular Bird", "Göttlicher Unsterblicher Vogel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Super Chiking", "Superhühnchen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The chicken that became a god.", "Das Huhn, das ein Gott geworden ist.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "God Chiking", "Götterhuhn", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Hawk", "Zerbrochener Habicht", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "These broken cards remind me of my past life, even though they are far weaker than regular cards.", "Diese zerbrochenen Karten erinnern mich an mein früheres Leben, obwohl sie viel schwächer als gewöhnliche Karten sind.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Raven", "Zerbrochener Rabe", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Grizzly", "Zerbrochener Grizzly", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Grizzly Cub", "Zerbrochenes Grizzlyjunges", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Hunter", "Zerbrochener Jäger", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Stoat", "Zerbrochenes Hermelin", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Wolf", "Zerbrochener Wolf", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Wolf Cub", "Zerbrochenes Wolfsjunges", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Elk", "Zerbrochener Hirsch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Adder", "Zerbrochene Natter", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Barghest", "Barghest", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Barghest from hell love to see blood.", "Die Barghests aus der Hölle sehen gern Blut.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hell Barghest", "Höllenbarghest", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Furry Man", "Pelziger Mann", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why is this guy furry?", "Warum ist dieser Kerl so pelzig?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ikungagaga", "ikungagaga", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An excellent dog with eternal strengthening and leadership.", "Ein hervorragender Hund mit dauerhafter Verstärkung und Führungsstärke.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ni Tian God Dog", "Himmelstrotzender Götterhund", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lone Wolf", "Einsamer Wolf", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A wolf who is out of the pack, but loneliness will give him strength.", "Ein Wolf fern seines Rudels, dem die Einsamkeit Kraft verleiht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Naughty dog", "Frecher Hund", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mischievous little dog, if there is no creation on the other side, he will run to the other side.", "Ein schelmischer kleiner Hund, der auf die andere Seite läuft, wenn ihm keine Kreatur gegenübersteht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rabid Dog", "Tollwütiger Hund", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Angry dogs, whoever dares to provoke him will be doubly rewarded.", "Ein wütender Hund, der jedem, der ihn reizt, alles doppelt heimzahlt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Werewolf", "Werwolf", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zuo Dog", "Zuo-Hund", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bones and blood are both essential for it.", "Knochen und Blut sind für ihn gleichermaßen unentbehrlich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jun Zuo Dog", "Jun-Zuo-Hund", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cheetah", "Gepard", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Agile cheetahs will attack immediately upon their appearance.", "Wendige Geparde greifen sofort an, sobald sie das Feld betreten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hua Miao", "Hua Miao", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Dark One who masters the full challenge proficiently, everything is under his control.", "Die geheimnisvolle Katze beherrscht sämtliche Herausforderungen meisterhaft. Alles steht unter ihrer Kontrolle.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leopard", "Leopard", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A ferocious Leopard with speed and damage.", "Ein wilder Leopard, schnell und mit hohem Schaden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Smilodon", "Smilodon", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The smilodon, a beast of prehistoric origin.", "Der Smilodon, eine Bestie aus prähistorischen Zeiten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Smilodon Cub", "Smilodonjunges", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weak saber toothed tiger cubs, they help their mother collect bones.", "Schwache Säbelzahntigerjunge helfen ihrer Mutter, Knochen zu sammeln.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "White Tiger", "Weißer Tiger", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One of the four divine beasts, it has the most precious blood.", "Eine der vier göttlichen Bestien, mit dem kostbarsten Blut.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yin Tiger", "Yin-Tiger", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A strong tiger that is good at hunting from behind.", "Ein kräftiger Tiger, der geschickt von hinten jagt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Yin Tiger", "Erwachter Yin-Tiger", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ziqi Cat", "Ziqi-Katze", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A cat with strong auxiliary abilities is the overlord of cats.", "Eine Katze mit starken Unterstützungsfähigkeiten, die Herrscherin aller Katzen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ziqi God Cat", "Göttliche Ziqi-Katze", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Papyrus", "Papyrus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A little angel from the underworld.", "Ein kleiner Engel aus der Unterwelt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sans", "Sans", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A lazy bone and its hellish joke.", "Ein faules Gerippe und sein höllischer Witz.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Doom Trepang", "Unheilsseegurke", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An exploding Doom Trepang has always been devastating.", "Eine explodierende Unheilsseegurke ist stets verheerend.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Electric Eel", "Zitteraal", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Electric eels can cause damage to creations that attack their location.", "Zitteraale können Kreaturen Schaden zufügen, die ihr Feld angreifen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Humpback", "Buckelwal", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Those who possess absolute power in water.", "Wesen mit absoluter Macht im Wasser.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Paper Boat", "Papierboot", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A paper boat full of bones is enough to make all animals salivate.", "Ein Papierboot voller Knochen genügt, um allen Tieren das Wasser im Mund zusammenlaufen zu lassen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Biker", "Motorradfahrer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sailfish", "Fächerfisch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sailfish that can't wait will attack as soon as they get on the field.", "Ungeduldige Fächerfische greifen an, sobald sie das Feld betreten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dunhuang deer", "Heiliger Hirsch von Dunhuang", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dunhuang deer from the East.", "Der heilige Hirsch von Dunhuang aus dem Osten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Jackalop with unlimited appreciation is a destroyer of ecology.", "Der Jackalope vermehrt sich unbegrenzt und zerstört das Ökosystem.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ovis Ammon", "Argali-Wildschaf", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The earth shaking ram kills its creations in exchange for power.", "Der erderschütternde Widder sucht im tödlichen Ansturm auf seine Feinde neue Stärke.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ovis Aries", "Hausschaf", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weak sheep attract other predators to hunt.", "Schwache Schafe locken andere Raubtiere zur Jagd an.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rhinoceros", "Nashorn", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They carry thick skin, which is not easily damaged by ordinary creations.", "Ihre dicke Haut lässt sich von gewöhnlichen Kreaturen nicht leicht verletzen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tibetan Antelope", "Tibetantilope", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The strong Tibetan antelope is a dancer on the plateau.", "Die kräftige Tibetantilope ist eine Tänzerin des Hochlands.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "God Antelope", "Göttliche Antilope", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wildebeest", "Gnu", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Herd wildebeest, they unite to resist predators.", "Gnus leben in Herden und schließen sich zusammen, um Raubtieren zu widerstehen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ant King", "Ameisenkönig", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ant king who commands the army of ants.", "Der Ameisenkönig, der das Heer der Ameisen befehligt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boss Z", "Boss Z", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This guy is greedy but selfless.", "Dieser Kerl ist gierig, aber selbstlos.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big Boss Z", "Großer Boss Z", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Butterfly", "Schmetterling", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Butterflies that love flowers, they fly everywhere.", "Blumenliebende Schmetterlinge fliegen überall umher.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rockivores", "Steinfresser", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This insect can feed on terrain.", "Dieses Insekt kann sich von Gelände ernähren.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trilobite", "Trilobit", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ancient trilobites secreted acid.", "Die uralten Trilobiten sonderten Säure ab.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gluttonous Stoat", "Gefräßiges Hermelin", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Keep eating and eating.", "Immer weiter fressen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hao Maomao", "Hao Maomao", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Agile monkeys are good at imitating.", "Wendige Affen sind gut im Nachahmen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hao Jiji", "Hao Jiji", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Isaac", "Isaac", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The tragedy and suffering experienced in another world.", "Die Tragödien und Leiden, die in einer anderen Welt durchlebt wurden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kylin", "Qilin", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kylin steps on auspicious clouds, which are difficult to dispel in the human world.", "Der Qilin schreitet auf glückverheißenden Wolken und vertreibt die Nöte der Menschenwelt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mammoths", "Mammuts", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A terrifying artifact from ancient times.", "Eine furchterregende Schöpfung aus uralten Zeiten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Man with Big Life", "Kleiner Mann, großes Leben", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As a small person, having a big life.", "Ein kleiner Mensch mit einem großen Leben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mini Moon", "Minimond", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh! How did such a tiny moon come about?", "Oh! Wie ist so ein winziger Mond entstanden?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "God Moon", "Göttlicher Mond", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lunar debris", "Mondtrümmer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Panda", "Großer Panda", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "China's nationally protected animal, with rare blood, as well as its lazy nature.", "Ein in China geschütztes Tier mit seltenem Blut und einem trägen Wesen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Picky Bear", "Wählerischer Bär", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A picky eating grizzly bear.", "Ein Grizzly, der beim Fressen wählerisch ist.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chinchilla", "Chinchilla", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cute Chinchilla, attacking its creatures will make it feel guilty.", "Ein niedliches Chinchilla. Kreaturen, die es angreifen, fühlen sich schuldig.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hamster", "Hamster", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cute hamster invites friends.", "Der niedliche Hamster lädt Freunde ein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Muscle Mouse", "Muskelmaus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you have difficulties, it will come to help you.", "Wenn du Schwierigkeiten hast, kommt sie dir zu Hilfe.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rat Queen", "Rattenkönigin", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They gather in groups and obey the commands of the Rat Queen.", "Sie versammeln sich in Gruppen und gehorchen den Befehlen der Rattenkönigin.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scientist Rat", "Wissenschaftlerratte", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This scientist discovered a method to search for tribes.", "Dieser Wissenschaftler hat eine Methode entdeckt, um Familien zu finden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snake Eater", "Schlangenfresser", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even prey can become hunters.", "Selbst Beutetiere können zu Jägern werden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Black Tortoise", "Schwarze Schildkröte", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One of the four divine beasts with the strongest defense.", "Eine der vier göttlichen Bestien, mit der stärksten Verteidigung.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "God Tortoise", "Göttliche Schildkröte", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alligator", "Alligator", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The more eat, the stronger it becomes.", "Je mehr er frisst, desto stärker wird er.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hydrophis", "Seeschlange", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A deadly venomous snake in the sea.", "Eine tödlich giftige Schlange im Meer.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snake Eye", "Schlangenauge", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Luck is also part of strength.", "Glück gehört auch zur Stärke.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jackal", "Schakal", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As long as it is in the wolf pack, it has great power.", "Solange er im Wolfsrudel ist, besitzt er große Kraft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Avoider", "Ausweicher", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Survival or death, that's the question.", "Überleben oder sterben, das ist hier die Frage.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Avoider", "Erwachter Ausweicher", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Lotus", "Blutlotus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A unique blood lotus about to bloom.", "Ein einzigartiger Blutlotus, der kurz vor der Blüte steht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Make a song for you", "Ein Lied für dich", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fishing Cat", "Fischkatze", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All diving creatures cannot escape its eyes.", "Keine tauchende Kreatur entgeht seinem Blick.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cloud Leopard", "Nebelparder", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They are doctors among feline animals.", "Sie sind die Ärzte unter den Katzenartigen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Panther", "Schwarzer Panther", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The greedy black panther will perish without bones.", "Der gierige schwarze Panther stirbt ohne Knochen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bandit Parrot", "Banditenpapagei", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The appearance of a skeleton parrot before its death They burned, killed, and looted everywhere together with pirates.", "Der Skelettpapagei vor seinem Tod ... Gemeinsam mit Piraten zog er brennend, mordend und plündernd umher.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Capybara", "Wasserschwein", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The docile little ones don't like to fight.", "Die zahmen Kleinen kämpfen nicht gern.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elaphe Taeniura", "Elaphe taeniura", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The black browed snake, who loves squirrels, can unleash its true power by catering to its preferences.", "Die schwarzbrauige Natter liebt Eichhörnchen. Erfülle ihre Vorlieben, um ihre wahre Kraft zu entfesseln.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Juvenile Lammergeier", "Junger Lämmergeier", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ambitious Juvenile Lammergeier store food and have a promising future ahead.", "Ehrgeizige junge Lämmergeier legen Nahrungsvorräte an. Ihnen steht eine vielversprechende Zukunft bevor.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mutated Hamster", "Mutierter Hamster", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moon Cat", "Mondkatze", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The moon cat with mysterious words on its forehead.", "Die Mondkatze mit geheimnisvollen Schriftzeichen auf der Stirn.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wolf Magpie", "Wolfselster", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The physique of wolves and the posture of magpies combine bravery and agility.", "Der Körper eines Wolfs und die Gestalt einer Elster vereinen Tapferkeit und Wendigkeit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleton Grizzly", "Skelettgrizzly", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "For some reason, even death cannot stop its thirst for food and blood.", "Aus irgendeinem Grund kann nicht einmal der Tod seinen Hunger nach Nahrung und Blut stillen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Skeleton Grizzly", "Erwachter Skelettgrizzly", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Will there still be people who sympathize with the nameless dead?", "Wird es noch Menschen geben, die mit den namenlosen Toten mitfühlen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nameless Dead", "Namenloser Toter", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Name", "Name", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slow Cooling Bone", "Langsam abkühlender Knochen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Slow Cooling Bone", "Erwachter Langsam abkühlender Knochen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Who can comprehend the true meaning of death? Even Grimora cannot comprehend it.", "Wer kann die wahre Bedeutung des Todes begreifen? Nicht einmal Grimora vermag es.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Green Anaconda", "Grüne Anakonda", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The parthenogenetic Green Anaconda can swallow humans.", "Die zur Jungfernzeugung fähige grüne Anakonda kann Menschen verschlingen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ghost Rider", "Geisterreiter", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Ghost Rider who emphasizes killing justice will burn away the sins of all things with anger.", "Der Geisterreiter, der seine Gerechtigkeit durch Töten vollstreckt, wird mit seinem Zorn alle Sünden verbrennen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Ghost Rider", "Erwachter Geisterreiter", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ghost Fire", "Geisterfeuer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Ghost Fire", "Erwachtes Geisterfeuer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big Black Mouse", "Große schwarze Ratte", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The big black rats, who are home everywhere, are insatiable and helpless like weeds on the wall.", "Die großen schwarzen Ratten sind überall zu Hause. Unersättlich und haltlos sind sie wie Unkraut an einer Mauer.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Camel", "Kamel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Camels who work tirelessly are frequent visitors on the Silk Road.", "Unermüdlich arbeitende Kamele sind häufige Reisende auf der Seidenstraße.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thin Camel", "Dünnes Kamel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A thin and shapeless camel, I don't know who could draw such a picture.", "Ein bis zur Unförmigkeit abgemagertes Kamel. Wer hat nur so ein Bild gemalt?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Thin Camel", "Erwachtes Dünnes Kamel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Board Tentacle", "Bretttentakel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't remember taking a photo of it.", "Ich erinnere mich nicht daran, es fotografiert zu haben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Golden Tentacle", "Goldener Tentakel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They traded death for their hands.", "Sie tauschten den Tod gegen ihre Hände.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Item Tentacle", "Gegenstandstentakel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They become excited when they see props.", "Beim Anblick von Gegenständen werden sie ganz aufgeregt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scaleten Tentacle", "Waagententakel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Viscera Tentacle", "Eingeweidetentakel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strengthen Eagle", "Verstärkter Adler", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bomb Mechanical Dog", "Bombenroboterhund", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Is sacrificing one's life for something insignificant the purpose of creating machinery?", "Ist es der Zweck erschaffener Maschinen, ihr Leben für etwas Unbedeutendes zu opfern?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bomb Mechanical Dog 2.0", "Bombenroboterhund 2.0", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Salt Fish", "Salzfisch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's just a dead fish...", "Es ist nur ein toter Fisch ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Turning over salt fish", "Sich wendender Salzfisch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ice scaled Snow Snake", "Eisschuppige Schneeschlange", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ice cast scales, cold snake hearts.", "Aus Eis geformte Schuppen, eisige Schlangenherzen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Joyful Wolf", "Fröhlicher Wolf", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They always have a strange smile on their faces.", "Sie haben immer ein seltsames Lächeln im Gesicht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frankenstein's Sheep", "Frankensteins Schaf", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Highly aggressive scientific monsters, as if their eyes are only focused on killing.", "Höchst aggressive wissenschaftliche Monster, die offenbar nur das Töten im Sinn haben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Smoke Knight", "Nebelritter", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ever-changing Smoke Knight, perhaps the old woman is right, death is not the end.", "Der Nebelritter wandelt sich ständig. Vielleicht hat die alte Frau recht: Der Tod ist nicht das Ende.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Smoke Knight", "Erwachter Nebelritter", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maneki-neko", "Winkekatze", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pirate Crab", "Piratenkrabbe", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Excellent pirates never doubt their own value.", "Hervorragende Piraten zweifeln nie an ihrem eigenen Wert.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Echo of MaoDie", "Echo von MaoDie", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Someone found an inexplicable sentence in its epitaph: \"Hakimi's green beans from north to south\".", "Jemand fand in seiner Grabinschrift einen unerklärlichen Satz: „Hakimis grüne Bohnen von Nord nach Süd.“", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Killer Beehive", "Killerbienenstock", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's endless, endless.", "Endlos, endlos.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Wolf", "Blutwolf", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This wolf is crazily craving for blood, to the point of endangering its life.", "Dieser Wolf dürstet so wahnsinnig nach Blut, dass er sein eigenes Leben gefährdet.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fallen Hugag", "Gestürzter Hugag", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hugag", "Hugag", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The top-heavy guy may not be the same when it is reversed.", "Dieser kopflastige Kerl ist umgedreht vielleicht kaum wiederzuerkennen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "World Turtle", "Weltschildkröte", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Three mud turtles support the earth.", "Drei Schlammschildkröten tragen die Erde.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Is it just an ordinary squirrel?", "Ist es nur ein gewöhnliches Eichhörnchen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shiba Inu", "Shiba-Inu", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cerberus", "Zerberus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guardian of the Underworld—no living soul may enter, no dead soul may leave.", "Wächter der Unterwelt: Keine lebende Seele darf hinein, keine tote Seele hinaus.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pi Xiu", "Pixiu", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If fierce beasts lie ahead, carry the Pi Xiu as your guardians.", "Wenn wilde Bestien vor dir lauern, führe Pixiu als deine Wächter mit dir.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sea Urchin", "Seeigel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you accidentally stumble upon this, you might regret it.", "Wenn du es versehentlich berührst, könntest du es bereuen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goose and Duck", "Gans und Ente", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They turn a deaf ear to others' words.Talking past each other—sometimes useless conflicts are just senseless.", "Sie stellen sich bei den Worten anderer taub und reden aneinander vorbei. Manchmal sind unnötige Konflikte einfach sinnlos.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hellcat", "Höllenkatze", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A cat of blazing hell, it walks upon fire;All foes who gaze upon it shall be reduced to scorched earth.", "Eine Katze der lodernden Hölle schreitet auf Feuer; alle Feinde, die sie erblicken, werden zu verbrannter Erde.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cactus cat", "Kaktuskatze", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such indescribable creations are destined to be inaccessible to humans.", "Solch unbeschreibliche Schöpfungen bleiben den Menschen unnahbar.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elder Goose and Elder Duck", "Ältestengans und Ältestenente", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Purgatory Cat", "Fegefeuerkatze", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bamboo Hat Panda", "Panda mit Bambushut", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignoring the affairs of the world, I only revel in the fragrance of bamboo; beneath the bamboo hat lies the panda's lazy jianghu.", "Das Weltgeschehen kümmert mich nicht, ich berausche mich nur am Duft des Bambus; unter seinem Bambushut lebt der Panda sein gemächliches Wanderleben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chang Qi Jin Xi", "Chang Qi Jin Xi", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ShadoWood Wolf", "Schattenwaldwolf", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shadows creep through the woods; the wind is its stride.", "Schatten schleichen durch den Wald; der Wind ist sein Schritt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rhinoceros Beetle", "Nashornkäfer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clad in iron armor, armed with twin prongs,a fearless warrior of the woods.", "In eiserne Rüstung gehüllt und mit zwei Spitzen bewaffnet: ein furchtloser Krieger des Waldes.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ant Egg", "Ameisenei", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An abandoned ant egg, once hatched, can return to its home.", "Ein verlassenes Ameisenei, das nach dem Schlüpfen in seine Heimat zurückkehren kann.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feathered Serpent", "Gefiederte Schlange", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This snake does not belong to the ordinary world; its illusory nature and existence are indistinguishable.", "Diese Schlange gehört nicht zur gewöhnlichen Welt; ihr Trugbild und ihre Existenz lassen sich nicht unterscheiden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quetzalcoatl", "Quetzalcoatl", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Twin Varanoids", "Zwillingswarane", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A matched pair of savage giant lizards, hunting together and bringing double the terror.", "Ein Paar wilder riesiger Zwillingswarane jagt gemeinsam und verbreitet doppelten Schrecken.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aether Serpent", "Ätherschlange", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Celestial serpent that soars through the clouds, untethered by earthly bounds.", "Eine Himmelsschlange, die durch die Wolken fliegt, frei von irdischen Fesseln.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "VeggieMew", "VeggieMew", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whose pet is this that ran out?", "Wem ist denn dieses Haustierchen davongelaufen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snapper Egg", "Schnappschildkrötenei", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snapping turtle eggs found in the swamp may attract little attention.", "Im Sumpf gefundene Schnappschildkröteneier erregen vielleicht kaum Aufmerksamkeit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hedgehog", "Igel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Timid hedgehogs steal bones yet dare not attack head-on.", "Ängstliche Igel stehlen Knochen, wagen aber keinen Frontalangriff.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Echidna", "Ameisenigel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fearless echidnas sacrifice themselves to stab hostile creatures.", "Furchtlose Ameisenigel opfern sich, um feindliche Kreaturen aufzuspießen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strange Tadpole", "Seltsame Kaulquappe", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The tadpole seems to have grown legs.", "Der Kaulquappe scheinen Beine gewachsen zu sein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hippo", "Nilpferd", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strong hippos keep hunting and strengthening themselves.", "Kräftige Nilpferde jagen ständig und werden immer stärker.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rusty Bear", "Rostiger Bär", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rusty Face", "Rostiges Gesicht", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Is this a living or a dead thing? No one knows why rust would grow on that face.", "Ist es etwas Lebendes oder Totes? Niemand weiß, warum auf diesem Gesicht Rost wächst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flerken", "Flerken", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beneath its fluffy rounded hide lies an enormous maw capable of devouring anything.", "Unter seiner rundlichen, flauschigen Haut lauert ein riesiger Schlund, der alles verschlingen kann.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WayneSA", "WayneSA", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mosquito", "Stechmücke", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Annoying mosquitoes, disgusting bloodsuckers in summer.", "Lästige Stechmücken, die widerlichen Blutsauger des Sommers.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acheron Viper", "Acheronviper", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It revives from the other shore, seeking its origin amid the hatred of the deceased.", "Sie kehrt vom anderen Ufer ins Leben zurück und sucht ihren Ursprung im Hass der Verstorbenen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ferry of Souls Snake", "Seelenfährschlange", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "old SA", "Alter SA", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lycoris", "Lycoris", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Razor Clam", "Schwertmuschel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An elongated shellfish dwelling in silt, its two thin shells forming its iconic razor shape.", "Ein längliches, im Schlick lebendes Schalentier, dessen zwei dünne Schalen seine typische Rasiermesserform bilden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Razor Clman", "Schwertmuschelmann", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frenzied Rat", "Rasende Ratte", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant-Toothed Beaver", "Riesenzahnbiber", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A colossal beaver creature armed with massive tusks.", "Eine kolossale Biberkreatur, bewaffnet mit gewaltigen Hauern.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kangaroo Rat", "Kängururatte", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Equipped with large cheek pouches, the kangaroo rat is a master storer of desert seeds and barely needs to drink liquid water its whole life.", "Mit seinen großen Backentaschen ist die Kängururatte eine Meisterin im Horten von Wüstensamen und muss fast ihr ganzes Leben lang kein flüssiges Wasser trinken.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plague Rat", "Pestratte", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A rodent creature stricken with plague, festering blight spreads all around its body.", "Eine von der Pest befallene Nagetierkreatur, deren Körper faulige Seuchen verbreitet.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rat Corpse", "Rattenleiche", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sharp Dam", "Scharfer Damm", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mangrove", "Mangrovenbaum", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mangrove creature rooted in estuary mud, tangled roots binding silt and tides.", "Ein im Mündungsschlamm verwurzelter Mangrovenbaum, dessen verschlungene Wurzeln Schlick und Gezeiten binden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant ocean seabird, gliding endlessly on winds across vast seas.", "Ein riesiger Hochseevogel, der endlos auf den Winden über weite Meere gleitet.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Electro Tiger", "Elektrotiger", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Arcs leap across its fur, and thunder follows its charge.", "Lichtbögen springen über sein Fell, und Donner folgt seinem Ansturm.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It lurks in the corners of liminal spaces, silently staring at every intruder.", "Sie lauert in den Ecken liminaler Räume und starrt jeden Eindringling schweigend an.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its arrival is regarded as an auspice, bringing fortune to its owner.", "Seine Ankunft gilt als gutes Omen und bringt seinem Besitzer Glück.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Liminal Cat", "Liminalkatze", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hallucigenia", "Hallucigenia", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mucus", "Schleim", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Auspice Rat", "Glücksratte", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Buffalo", "Wasserbüffel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A ferocious giant of the savanna. Its helmet‑like massive horns strike fear into predators.", "Ein wilder Riese der Savanne. Seine gewaltigen, helmartigen Hörner jagen Raubtieren Angst ein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fu Zhu", "Fuzhu", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A spirit‑deer of pure, mild mien, yet it bears the ill omen of incoming floods.", "Ein Geisterhirsch von reinem, sanftem Wesen, der dennoch das Unheilszeichen nahender Fluten trägt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Great Bustard", "Großtrappe", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A giant bird pacing the grasslands. Its great bulk is a heavy fetter for flight.", "Ein riesiger Vogel durchstreift das Grasland. Sein gewaltiger Körper ist eine schwere Fessel für den Flug.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All squirrels of the wood bow to its crown, willing to be offered.", "Alle Eichhörnchen des Waldes beugen sich seiner Krone und lassen sich bereitwillig opfern.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sun Wu Kong", "Sun Wukong", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The monkey king who once shook heaven, holds ruin even in stillness.", "Der Affenkönig, der einst den Himmel erschütterte, birgt selbst in der Ruhe vernichtende Macht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Great Sage Equal to Heaven", "Großer Weiser, dem Himmel ebenbürtig", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The strong shall reign, and that throne is mine; Among heroes, only I dare take the lead.", "Der Stärkste soll herrschen, und dieser Thron ist mein; unter Helden wage nur ich, voranzugehen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Where my staff strikes, neither gods nor buddhas may stand.", "Wo mein Stab zuschlägt, können weder Götter noch Buddhas standhalten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beyond the Three Realms, unbound by the Five Elements.", "Jenseits der Drei Reiche, ungebunden von den Fünf Elementen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strike the Southern Heaven, shatter the Firmament. If I return not, then return not I.", "Stürme den südlichen Himmel, zerschmettere das Firmament. Und kehre ich nicht zurück, so soll es sein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fiery eyes pierce illusion; one staff shapes all fate.", "Feurige Augen durchdringen Täuschungen; ein einziger Stab formt jedes Schicksal.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tiny in form, yet dares snarl at giants.", "Winzig von Gestalt, doch mutig genug, Riesen anzuknurren.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Northern Raccoon Dog", "Nördlicher Marderhund", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Masked in dark fur, it haunts woods, dwelling in one mound.", "Mit dunklem Fell maskiert streift er durch die Wälder und wohnt in einem Hügel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tao Tie", "Taotie", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It devours all it touches, never sated.", "Es verschlingt alles, was es berührt, und wird niemals satt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cauldron’s Dread Mask", "Schreckensmaske des Kessels", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bark beetle", "Borkenkäfer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parrot", "Papagei", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It repeats the words it has heard, speaking unheard secrets through human voices.", "Er wiederholt gehörte Worte und erzählt mit menschlicher Stimme Geheimnisse, die niemand kennt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It carves tunnels beneath tree bark, burying rot and its brood deep within the wood.", "Er gräbt Gänge unter die Baumrinde und vergräbt Fäulnis und Brut tief im Holz.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stump borer", "Stumpfbohrer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the opponent's turn, if [creature] is on the board, generate a Stump in the owner's hand.", "Am Ende des gegnerischen Zugs wird ein Stumpf in der Hand des Besitzers erzeugt, falls [creature] auf dem Brett ist.", Language.German);

            //WLDLC-other
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cowardly Aquasquirrel", "Feiges Aquahörnchen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frail Squirrel", "Gebrechliches Eichhörnchen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Injured Goat", "Verletzte Ziege", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Legendary Squirrel", "Legendäres Eichhörnchen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nightmare Aquasquirrel", "Albtraum-Aquahörnchen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DLC_Fairy_Tale", "Wildnislegenden-DLC: Märchen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Added some cards based on myths, legends, and fictional elements.", "Fügt Karten auf Grundlage von Mythen, Legenden und fiktiven Elementen hinzu.", Language.German);

        }
    }

