    public class CustomSideDeckMod
    {

        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for CustomSideDeck Mod");
            // Config
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How the mod should handle side deck card backs for side decks that don't add their own custom card back. If enabled, automatically generates a unique card back based on the side deck's main card's portrait. Otherwise, the default squirrel back will be used.", "Legt fest, wie der Mod Kartenrückseiten für Nebenstapel ohne eigene Rückseite behandelt. Wenn aktiviert, wird anhand des Kartenbilds der Hauptkarte des Nebenstapels automatisch eine einzigartige Rückseite erstellt. Andernfalls wird die standardmäßige Eichhörnchenrückseite verwendet.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whether to automatically add an Aqua version of all custom side decks. Buggy, not recommended.", "Fügt automatisch eine Aqua-Version aller eigenen Nebenstapel hinzu. Fehlerhaft, nicht empfohlen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whether or not Aquasquirrels and custom side decks marked as `CSDIsAqua` should be shown as options even when the Squirrel Fish challenge isn't on.", "Zeigt Aquahörnchen und mit `CSDIsAqua` markierte eigene Nebenstapel auch dann als Optionen an, wenn die Herausforderung Hörnchenfische nicht aktiv ist.", Language.German);

            // ShowText
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select Side Deck", "Nebenstapel wählen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Configure Side Deck", "Nebenstapel konfigurieren", Language.German);
            for (int point = 0; point <= 100; point++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CURRENT SIDE DECK: <color=#eef4c6>" + point.ToString() + "</color> Challenge Points", "AKTUELLER NEBENSTAPEL: <color=#eef4c6>" + point.ToString() + "</color> " + (point == 1 ? "Herausforderungspunkt" : "Herausforderungspunkte"), Language.German);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CURRENT SIDE DECK: <color=#eef4c6>+" + point.ToString() + "</color> Challenge Points", "AKTUELLER NEBENSTAPEL: <color=#eef4c6>+" + point.ToString() + "</color> " + (point == 1 ? "Herausforderungspunkt" : "Herausforderungspunkte"), Language.German);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Total Challenge Points: <color=#eef4c6>" + point.ToString() + "</color>", "Herausforderungspunkte insgesamt: <color=#eef4c6>" + point.ToString() + "</color>", Language.German);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "\nContains {0} cards", "\nEnthält {0} Karten", Language.German); // todo

        }
    }

    public class PackManagementMod
    {

        public static Dictionary<string, string> EncountersTitle = new();
        public static Dictionary<string, KeyValuePair<string, string>> EncountersDescription = new();

        public static void RegisterEncounter(string en, string zh, string endes, string zhdes)
        {
            EncountersTitle.Add(en, zh);
            EncountersDescription.Add(en, new KeyValuePair<string, string>(endes, zhdes));
        }
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for PackManagement Mod");
            // SetText
