            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select Encounter Packs", "Begegnungspakete wählen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose Active Packs", "Aktive Pakete wählen", Language.German);

            // Packs
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inscryption: Beastly Card Expansion Pack", "Inscryption: Bestien-Kartenerweiterung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The original set of cards featured in Leshy's cabin. Featuring wolves, mantises, and the occasional cockroach.", "Die ursprüngliche Kartenauswahl aus Leshys Hütte. Mit Wölfen, Gottesanbeterinnen und gelegentlich einer Kakerlake.", Language.German);
            RegisterEncounter("Inscryption: Beastly Card Expansion Pack", "Inscryption: Bestien-Kartenerweiterung", "The original set of cards featured in Leshy's cabin. Featuring wolves, mantises, and the occasional cockroach.", "Die ursprüngliche Kartenauswahl aus Leshys Hütte. Mit Wölfen, Gottesanbeterinnen und gelegentlich einer Kakerlake.");
