            RegisterEncounter("Inscryption: Techno Card Expansion Pack", "Inscryption: Techno-Kartenerweiterung", "The original set of robotic cards, exclusively using the energy mechanic.", "Die ursprüngliche Auswahl an Roboterkarten, die ausschließlich die Energiemechanik nutzt.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inscryption: Undead Card Expansion Pack", "Inscryption: Untoten-Kartenerweiterung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GrimoraMod", "Grimora-Mod", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Powered by the bones of the dead, these cards have come back from the grave to fight for you.", "Von den Knochen der Toten angetrieben, kehren diese Karten aus dem Grab zurück, um für dich zu kämpfen.", Language.German);
            RegisterEncounter("Inscryption: Undead Card Expansion Pack", "Inscryption: Untoten-Kartenerweiterung", "Powered by the bones of the dead, these cards have come back from the grave to fight for you.", "Von den Knochen der Toten angetrieben, kehren diese Karten aus dem Grab zurück, um für dich zu kämpfen.");
            RegisterEncounter("GrimoraMod", "Grimora-Mod", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inscryption: Magickal Card Expansion Pack", "Inscryption: Magie-Kartenerweiterung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harness the might of the moxen to summon forth apprentices and fight in the most honorable of duels.", "Nutze die Macht der Mox, um Lehrlinge zu beschwören und die ehrenhaftesten Duelle zu bestreiten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harness the might of the moxen to summon forth apprentices and fight in the most honorable of duels. (Magnificus Mod Cards)", "Nutze die Macht der Mox, um Lehrlinge zu beschwören und die ehrenhaftesten Duelle zu bestreiten. (Karten des Magnificus-Mods)", Language.German);
            RegisterEncounter("Inscryption: Magickal Card Expansion Pack", "Inscryption: Magie-Kartenerweiterung", "Harness the might of the moxen to summon forth apprentices and fight in the most honorable of duels.", "Nutze die Macht der Mox, um Lehrlinge zu beschwören und die ehrenhaftesten Duelle zu bestreiten.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Miscellaneous Community Cards", "Verschiedene Gemeinschaftskarten", Language.German);
