            RegisterEncounter("Hallownest Expansion", "Hallownest-Erweiterung", "A large expansion containing [count] creatures from Hollow Knight. Up from peaceful Crossroads, down into the Abyss.", "Eine große Erweiterung mit [count] Kreaturen aus Hollow Knight. Von der friedlichen Vergessenen Wegkreuzung bis tief hinab in den Abgrund.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bitty's Regions", "Bittys Regionen", Language.German);
