            RegisterEncounter("Void Region Expansion", "Erweiterung der Leerenregion", "This region expansion from Void adds [summary].", "Neuer Inhalt in dieser Regionenerweiterung von Void: [summary].");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eri's Card Pack Encounters", "Begegnungen aus Eris Kartenpaket", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This expansion adds [summary] featuring cards from Eri's Card Expansion.", "Diese Erweiterung ergänzt Inhalte mit Karten aus Eris Kartenerweiterung: [summary].", Language.German);
