    public class MagicExpansionMod
    {

        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for MagicExpansion Mod");
            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Angry Witch", "Zornige Hexe", Language.German);
            MagnificusMod.RegisterCard("Angry Witch", "Zornige Hexe", "The witch in charge of anger will ignite flames in the opposite battlefield.", "Die Hexe, die über den Zorn herrscht, setzt die gegnerische Seite des Schlachtfelds in Brand.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of anger will ignite flames in the opposite battlefield.", "Die Hexe, die über den Zorn herrscht, setzt die gegnerische Seite des Schlachtfelds in Brand.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Arrogant Witch", "Hochmütige Hexe", Language.German);
            MagnificusMod.RegisterCard("Arrogant Witch", "Hochmütige Hexe", "The witch who mastered the power of arrogance appeared with the demon.", "Die Hexe, die die Macht des Hochmuts beherrscht, erscheint in Begleitung eines Dämons.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch who mastered the power of arrogance appeared with the demon.", "Die Hexe, die die Macht des Hochmuts beherrscht, erscheint in Begleitung eines Dämons.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coffee Mage", "Kaffeemagier", Language.German);
            MagnificusMod.RegisterCard("Coffee Mage", "Kaffeemagier", "Mages who love coffee use gems to regulate their breath.", "Kaffeeliebende Magier nutzen Edelsteine, um ihren Atem zu regulieren.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mages who love coffee use gems to regulate their breath.", "Kaffeeliebende Magier nutzen Edelsteine, um ihren Atem zu regulieren.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Funny MagiChiking", "Lustiges Zauberhuhn", Language.German);
            MagnificusMod.RegisterCard("Funny MagiChiking", "Lustiges Zauberhuhn", "A smelly Rooster who has learned magic.", "Ein stinkender Hahn, der Magie gelernt hat.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A smelly Rooster who has learned magic.", "Ein stinkender Hahn, der Magie gelernt hat.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gluttonous Witch", "Gefräßige Hexe", Language.German);
            MagnificusMod.RegisterCard("Gluttonous Witch", "Gefräßige Hexe", "The witch in charge of gluttony committed a terrible sin.", "Die Hexe, die über die Völlerei herrscht, hat eine schreckliche Sünde begangen.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of gluttony committed a terrible sin.", "Die Hexe, die über die Völlerei herrscht, hat eine schreckliche Sünde begangen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greedy Witch", "Habgierige Hexe", Language.German);
            MagnificusMod.RegisterCard("Greedy Witch", "Habgierige Hexe", "The witch who controls the power of greed, unfortunately, can only bring value to us after death.", "Die Hexe, die die Macht der Gier beherrscht, kann uns leider erst nach ihrem Tod von Nutzen sein.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch who controls the power of greed, unfortunately, can only bring value to us after death.", "Die Hexe, die die Macht der Gier beherrscht, kann uns leider erst nach ihrem Tod von Nutzen sein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inquisitive Witch", "Wissbegierige Hexe", Language.German);
            MagnificusMod.RegisterCard("Inquisitive Witch", "Wissbegierige Hexe", "Nothing is more powerful than her curiosity.", "Nichts ist mächtiger als ihre Neugier.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing is more powerful than her curiosity.", "Nichts ist mächtiger als ihre Neugier.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jealous Witch", "Neidische Hexe", Language.German);
            MagnificusMod.RegisterCard("Jealous Witch", "Neidische Hexe", "The witch in charge of jealousy has powerful magic and power.", "Die Hexe, die über den Neid herrscht, verfügt über mächtige Magie und große Kraft.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of jealousy has powerful magic and power.", "Die Hexe, die über den Neid herrscht, verfügt über mächtige Magie und große Kraft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lazy Witch", "Träge Hexe", Language.German);
            MagnificusMod.RegisterCard("Lazy Witch", "Träge Hexe", "The witch in charge of the power of laziness is really a lazy guy.", "Die Hexe, die die Macht der Trägheit beherrscht, ist wirklich ein Faulpelz.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of the power of laziness is really a lazy guy.", "Die Hexe, die die Macht der Trägheit beherrscht, ist wirklich ein Faulpelz.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lust Witch", "Wollüstige Hexe", Language.German);
            MagnificusMod.RegisterCard("Lust Witch", "Wollüstige Hexe", "The witch in charge of lust, don't look into her eyes.", "Die Hexe, die über die Wollust herrscht … Sieh ihr nicht in die Augen.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of lust, don't look into her eyes.", "Die Hexe, die über die Wollust herrscht … Sieh ihr nicht in die Augen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nine Color Deer", "Neunfarbenhirsch", Language.German);
            MagnificusMod.RegisterCard("Nine Color Deer", "Neunfarbenhirsch", "The colorful nine color deer has precious value.", "Der farbenprächtige Neunfarbenhirsch ist von unschätzbarem Wert.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The colorful nine color deer has precious value.", "Der farbenprächtige Neunfarbenhirsch ist von unschätzbarem Wert.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stinky MagiChiking", "Stinkendes Zauberhuhn", Language.German);
            MagnificusMod.RegisterCard("Stinky MagiChiking", "Stinkendes Zauberhuhn", "Hatched by magic eggs.", "Aus einem magischen Ei geschlüpft.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hatched by magic eggs.", "Aus einem magischen Ei geschlüpft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bomb Maniac", "Bombenfanatiker", Language.German);
            MagnificusMod.RegisterCard("Bomb Maniac", "Bombenfanatiker", "Even if it detonates itself, it never surrenders to others.", "Selbst wenn er sich in die Luft sprengt, wird er sich niemals ergeben.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even if it detonates itself, it never surrenders to others.", "Selbst wenn er sich in die Luft sprengt, wird er sich niemals ergeben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Earl Bunny", "Graf Hase", Language.German);
            MagnificusMod.RegisterCard("Earl Bunny", "Graf Hase", "The versatile Earl Bunny, not everyone can comprehend this art.", "Der vielseitige Graf Hase … Nicht jeder kann diese Kunst begreifen.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The versatile Earl Bunny, not everyone can comprehend this art.", "Der vielseitige Graf Hase … Nicht jeder kann diese Kunst begreifen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chinese Loong", "Chinesischer Drache", Language.German);
            MagnificusMod.RegisterCard("Chinese Loong", "Chinesischer Drache", "Diving into the abyss will bring peace to the four seas, flying will protect all things and bring peace, and the dragon's journey of thousands of miles is a sign of good fortune.", "Taucht der Drache in die Tiefe, kehrt auf den vier Meeren Frieden ein. Steigt er zum Himmel auf, schützt er alles Leben. Seine Reise über Tausende Meilen verheißt allerorts Glück.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Diving into the abyss will bring peace to the four seas, flying will protect all things and bring peace, and the dragon's journey of thousands of miles is a sign of good fortune.", "Taucht der Drache in die Tiefe, kehrt auf den vier Meeren Frieden ein. Steigt er zum Himmel auf, schützt er alles Leben. Seine Reise über Tausende Meilen verheißt allerorts Glück.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cheese Wizard", "Käsezauberer", Language.German);
            MagnificusMod.RegisterCard("Cheese Wizard", "Käsezauberer", "A humorous wizard who is proficient in cooking, his cheese has magical power.", "Ein humorvoller Zauberer und begabter Koch, dessen Käse magische Kräfte besitzt.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A humorous wizard who is proficient in cooking, his cheese has magical power.", "Ein humorvoller Zauberer und begabter Koch, dessen Käse magische Kräfte besitzt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frost Golem", "Frostgolem", Language.German);
            MagnificusMod.RegisterCard("Frost Golem", "Frostgolem", "Once on the field, there is a strong sense of oppression.", "Sobald er das Brett betritt, ist seine erdrückende Präsenz zu spüren.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once on the field, there is a strong sense of oppression.", "Sobald er das Brett betritt, ist seine erdrückende Präsenz zu spüren.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baseball Mage", "Baseballmagier", Language.German);
            MagnificusMod.RegisterCard("Baseball Mage", "Baseballmagier", "His soul is bound under sportswear and can never be liberated.", "Seine Seele ist in Sportkleidung gefangen und kann niemals befreit werden.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "His soul is bound under sportswear and can never be liberated.", "Seine Seele ist in Sportkleidung gefangen und kann niemals befreit werden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raid Mage", "Überfallmagier", Language.German);
            MagnificusMod.RegisterCard("Raid Mage", "Überfallmagier", "You will understand how terrifying it is for a robber to master magic.", "Du wirst verstehen, wie furchterregend ein Räuber sein kann, der Magie beherrscht.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will understand how terrifying it is for a robber to master magic.", "Du wirst verstehen, wie furchterregend ein Räuber sein kann, der Magie beherrscht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jade Turtle", "Jadeschildkröte", Language.German);
            MagnificusMod.RegisterCard("Jade Turtle", "Jadeschildkröte", "A turtle draped in emeralds from head to toe—I can't help but marvel that such a painting even exists.", "Eine Schildkröte, von Kopf bis Fuß mit Smaragden bedeckt … Ich kann nur staunen, dass es ein solches Gemälde gibt.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A turtle draped in emeralds from head to toe—I can't help but marvel that such a painting even exists.", "Eine Schildkröte, von Kopf bis Fuß mit Smaragden bedeckt … Ich kann nur staunen, dass es ein solches Gemälde gibt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magic Cheese", "Zauberkäse", Language.German);
            MagnificusMod.RegisterCard("Magic Cheese", "Zauberkäse", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scarlet Cuckoo", "Scharlachkuckuck", Language.German);
            MagnificusMod.RegisterCard("Scarlet Cuckoo", "Scharlachkuckuck", "The success or failure of the angry magic bird often depends on its face.", "Ob du Erfolg hast oder scheiterst, hängt bei diesem wütenden Zaubervogel oft von seiner Laune ab.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The success or failure of the angry magic bird often depends on its face.", "Ob du Erfolg hast oder scheiterst, hängt bei diesem wütenden Zaubervogel oft von seiner Laune ab.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spear Apprentice", "Speerlehrling", Language.German);
            MagnificusMod.RegisterCard("Spear Apprentice", "Speerlehrling", "Apprentices of Spear Mages, wise people will leave behind their backs to prepare.", "Die Lehrlinge der Speermagier … Wer klug ist, hat immer einen Plan in Reserve.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Apprentices of Spear Mages, wise people will leave behind their backs to prepare.", "Die Lehrlinge der Speermagier … Wer klug ist, hat immer einen Plan in Reserve.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Eye of Darkness", "Das Auge der Dunkelheit", Language.German);
            MagnificusMod.RegisterCard("The Eye of Darkness", "Das Auge der Dunkelheit", "This precious pearl was once the devil's eye.", "Diese kostbare Perle war einst das Auge des Teufels.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This precious pearl was once the devil's eye.", "Diese kostbare Perle war einst das Auge des Teufels.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Forest Spell", "Waldzauber", Language.German);
            MagnificusMod.RegisterCard("Forest Spell", "Waldzauber", "The forest spell obtained from Leshy can provide the most primitive defense.", "Der von Leshy erhaltene Waldzauber bietet die ursprünglichste Form der Verteidigung.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The forest spell obtained from Leshy can provide the most primitive defense.", "Der von Leshy erhaltene Waldzauber bietet die ursprünglichste Form der Verteidigung.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MoxShield", "Moxschild", Language.German);
            MagnificusMod.RegisterCard("MoxShield", "Moxschild", "A magic shield inlaid with gemstones always provides a sense of security with its presence.", "Allein die Anwesenheit dieses mit Edelsteinen besetzten Zauberschilds vermittelt stets ein Gefühl der Sicherheit.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A magic shield inlaid with gemstones always provides a sense of security with its presence.", "Allein die Anwesenheit dieses mit Edelsteinen besetzten Zauberschilds vermittelt stets ein Gefühl der Sicherheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nebula Storm", "Nebelsturm", Language.German);
            MagnificusMod.RegisterCard("Nebula Storm", "Nebelsturm", "This cruel storm can directly take away an enemy.", "Dieser erbarmungslose Sturm kann einen Feind auf der Stelle hinwegfegen.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This cruel storm can directly take away an enemy.", "Dieser erbarmungslose Sturm kann einen Feind auf der Stelle hinwegfegen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul Contract", "Seelenvertrag", Language.German);
            MagnificusMod.RegisterCard("Soul Contract", "Seelenvertrag", "Perhaps you need more card assistance, and a soul contract is a great choice.", "Vielleicht brauchst du Unterstützung durch weitere Karten. Ein Seelenvertrag wäre eine gute Wahl.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps you need more card assistance, and a soul contract is a great choice.", "Vielleicht brauchst du Unterstützung durch weitere Karten. Ein Seelenvertrag wäre eine gute Wahl.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wailing Wall", "Klagemauer", Language.German);
            MagnificusMod.RegisterCard("Wailing Wall", "Klagemauer", "Such perseverance even moves the thorny walls to weep.", "Solche Beharrlichkeit rührt selbst die Dornenmauern zu Tränen.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such perseverance even moves the thorny walls to weep.", "Solche Beharrlichkeit rührt selbst die Dornenmauern zu Tränen.", Language.German);
            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coffee Time", "Kaffeezeit", Language.German);
            MagnificusMod.RegisterAbility("Coffee Time", "Kaffeezeit");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] receives the first damage, it gains 2 strength.", "Wenn [creature] zum ersten Mal Schaden erleidet, erhält die Kreatur 2 Kraft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death of Arrogance", "Tod des Hochmuts", Language.German);
            MagnificusMod.RegisterAbility("Death of Arrogance", "Tod des Hochmuts");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, adjacent cards gain 2 power.", "Wenn [creature] stirbt, erhalten benachbarte Karten 2 Kraft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death of Greed", "Tod der Gier", Language.German);
            MagnificusMod.RegisterAbility("Death of Greed", "Tod der Gier");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, adjacent cards gain 3 health.", "Wenn [creature] stirbt, erhalten benachbarte Karten 3 Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "God Made", "Gottes Schöpfung", Language.German);
            MagnificusMod.RegisterAbility("God Made", "Gottes Schöpfung");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Homunculus is created on each empty adjacent space. The Homunculus has : 1 power, 1 health, Familiar.", "Wenn [creature] ausgespielt wird, entsteht auf jedem leeren benachbarten Feld ein Homunkulus. Der Homunkulus hat: 1 Kraft, 1 Gesundheit, Vertrauter.", Language.German);
            MagnificusMod.RegisterAbility("Fir Caller", "Tannenrufer");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, the empty slot on the cardholder's side is filled with Great Firs. Great Fir has: 0 Power, 3 Health, Mighty Leap.", "Wenn [creature] stirbt, werden die leeren Felder auf der Seite des Besitzers mit Großen Tannen gefüllt. Die Große Tanne hat: 0 Kraft, 3 Gesundheit, Mächtiger Satz.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lingering Taste", "Anhaltender Geschmack", Language.German);
            MagnificusMod.RegisterAbility("Lingering Taste", "Anhaltender Geschmack");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, adjacent cards gain 1 health.", "Wenn [creature] stirbt, erhalten benachbarte Karten 1 Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Love of Cheese", "Käseliebe", Language.German);
            MagnificusMod.RegisterAbility("Love of Cheese", "Käseliebe");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, draw a cheese card, cheese has: 0 power, 2 health,Lingering Taste.", "Wenn [creature] ausgespielt wird, ziehst du eine Zauberkäse-Karte. Zauberkäse hat: 0 Kraft, 2 Gesundheit, Anhaltender Geschmack.", Language.German);
