            // Pack
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee's P03 Expansion Pack #1", "Kaycees P03-Erweiterungspaket Nr. 1", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The first expansion pack from the developers of 'P03 in Kaycees Mod' adds [count] new cards across all four regions of Botopia.", "Das erste Erweiterungspaket der Entwickler von „P03 in Kaycees Mod“ fügt [count] neue Karten in allen vier Regionen von Botopia hinzu.", Language.German);
