            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The second official expansion pack, with [count] firey new cards that command an explosive reaction!", "Das zweite offizielle Erweiterungspaket liefert [count] feurige neue Karten, die für explosive Reaktionen sorgen!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inscryption: Rogue Bots of Botopia", "Inscryption: Die abtrünnigen Bots von Botopia", Language.German);
