            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee's P03 Encounter Expansion #1", "Kaycees P03-Begegnungserweiterung Nr. 1", Language.German);
