            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The card was added to your collection.", "Die Karte wurde deiner Sammlung hinzugefügt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "buh", "Hä", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose a card type.", "Wähle einen Kartentyp.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You need at least 20 cards in your deck!", "Du brauchst mindestens 20 Karten in deinem Stapel!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...", "…", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good offering.", "Gute Gabe.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have this.", "Nimm das.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have a choice of merging two cards here..", "Du kannst hier zwei Karten miteinander verschmelzen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bounty", "Kopfgeld", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every 3 succesful battles, you gain a bounty star. With bounty stars, random bounty hunters will start to spawn in battles.", "Nach jeweils 3 erfolgreichen Kämpfen erhältst du einen Kopfgeldstern. Mit Kopfgeldsternen tauchen zufällige Kopfgeldjäger in Kämpfen auf.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boon", "Segen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have only one boon slot.", "Du hast nur einen Segensplatz.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elite", "Elite", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every regular card battle is replaced with an elite battle.", "Jeder gewöhnliche Kartenkampf wird durch einen Elitekampf ersetzt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't merge.", "Nicht verschmelzen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Merge Field Mice", "Feldmäuse verschmelzen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Merge Sentry Drone", "Wachdrohne verschmelzen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Merge Blue Mage", "Blauen Magier verschmelzen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Merge Gravedigger", "Totengräber verschmelzen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have a choice of merging two cards here..", "Du kannst hier zwei Karten miteinander verschmelzen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select the {} deck?", "Den Stapel {} auswählen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select the Deck of Beasts?", "Den Bestienstapel auswählen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select the Deck of the Dead?", "Den Stapel der Toten auswählen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select the Deck of Technology?", "Den Technologiestapel auswählen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select the Deck of Magick?", "Den Magiestapel auswählen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Take the deck.", "Den Stapel nehmen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leave it.", "Liegen lassen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You need at least 20 cards in your deck!", "Du brauchst mindestens 20 Karten in deinem Stapel!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No offering in your deck?", "Keine Opfergabe in deinem Stapel?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fine. Take this instead.", "Na gut. Nimm stattdessen das hier.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What? You still crave more?", "Was? Du willst immer noch mehr?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fine. Take this.", "Na gut. Nimm das hier.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reincarnation", "Wiedergeburt", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Voltage", "Spannung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Construct", "Konstrukt", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fossil", "Fossil", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BountyHunter", "Kopfgeldjäger", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nuzlocke", "Nuzlocke", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boon of Luck", "Segen des Glücks", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start each battle with a clover.", "Beginne jeden Kampf mit einem Klee.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With this boon equipped, Start each battle with a clover.", "Mit diesem ausgerüsteten Segen beginnst du jeden Kampf mit einem Klee.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boon of Flesh", "Segen des Fleisches", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox may be sacrificed.", "Mox-Karten können geopfert werden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With this boon equipped, Mox may be sacrificed.", "Mit diesem ausgerüsteten Segen können Mox-Karten geopfert werden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boon of Voltage", "Segen der Spannung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When you sacrifice a beast card, you increase your max energy and gain an energy cell.", "Wenn du eine Bestienkarte opferst, erhöhst du deine maximale Energie und erhältst eine Energiezelle.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With this boon equipped, When you sacrifice a beast card, you increase your max energy and gain an energy cell.", "Mit diesem ausgerüsteten Segen erhöhst du beim Opfern einer Bestienkarte deine maximale Energie und erhältst eine Energiezelle.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boon of Reincarnation", "Segen der Wiedergeburt", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a Skeleton is sacrificed, draw a squirrel.", "Wenn ein Skelett geopfert wird, ziehe ein Eichhörnchen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With this boon equipped, When a Skeleton is sacrificed, draw a squirrel.", "Mit diesem ausgerüsteten Segen ziehst du ein Eichhörnchen, wenn ein Skelett geopfert wird.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boon of Necromancy", "Segen der Nekromantie", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a Skeleton dies, a random mox is placed in it's place.", "Wenn ein Skelett stirbt, wird an seiner Stelle ein zufälliges Mox platziert.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With this boon equipped, When a Skeleton dies, a random mox is placed in it's place.", "Mit diesem ausgerüsteten Segen wird beim Tod eines Skeletts ein zufälliges Mox an seiner Stelle platziert.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boon of Scrap", "Segen des Schrotts", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever you reach full energy, you gain a bone.", "Immer wenn du deine maximale Energie erreichst, erhältst du einen Knochen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With this boon equipped, Whenever you reach full energy, you gain a bone.", "Mit diesem ausgerüsteten Segen erhältst du jedes Mal einen Knochen, wenn du deine maximale Energie erreichst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boon of Construct", "Segen des Konstrukts", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Any tech card that costs more than 2 energy will drop a random mox on death.", "Jede Technologiekarte, die mehr als 2 Energie kostet, lässt beim Sterben ein zufälliges Mox fallen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With this boon equipped, Any tech card that costs more than 2 energy will drop a random mox on death.", "Mit diesem ausgerüsteten Segen lässt jede Technologiekarte, die mehr als 2 Energie kostet, beim Sterben ein zufälliges Mox fallen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boon of The Saving Grace", "Segen der rettenden Gnade", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever you would recieve fatal damage, the scales are only tipped down to 4.\nONCE PER BATTLE", "Würdest du tödlichen Schaden erleiden, wird die Waage auf 4 Punkte gegen dich gesetzt.\nEINMAL PRO KAMPF", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With this boon equipped, Whenever you would recieve fatal damage, the scales are only tipped down to 4.\nONCE PER BATTLE", "Mit diesem ausgerüsteten Segen wird die Waage auf 4 Punkte gegen dich gesetzt, wenn du tödlichen Schaden erleiden würdest.\nEINMAL PRO KAMPF", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start each battle with a black goat on the board.", "Beginne jeden Kampf mit einer Schwarzen Ziege auf dem Brett.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With this boon equipped, Start each battle with a black goat on the board.", "Mit diesem ausgerüsteten Segen beginnst du jeden Kampf mit einer Schwarzen Ziege auf dem Brett.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start each battle with +3 bones.", "Beginne jeden Kampf mit +3 Knochen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With this boon equipped, Start each battle with +3 bones.", "Mit diesem ausgerüsteten Segen beginnst du jeden Kampf mit +3 Knochen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Draw 2 cards each turn instead of 1, but it will only function if you have less than 20 cards in your deck while battling.", "Ziehe in jedem Zug 2 Karten statt 1, aber nur, wenn dein Stapel im Kampf weniger als 20 Karten enthält.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With this boon equipped, Draw 2 cards each turn instead of 1, but it will only function if you have less than 20 cards in your deck while battling.", "Mit diesem ausgerüsteten Segen ziehst du in jedem Zug 2 Karten statt 1, aber nur, wenn dein Stapel im Kampf weniger als 20 Karten enthält.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start each battle with 2 firs in your hand.", "Beginne jeden Kampf mit 2 Großen Tannen auf der Hand.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With this boon equipped, Start each battle with 2 firs in your hand.", "Mit diesem ausgerüsteten Segen beginnst du jeden Kampf mit 2 Großen Tannen auf der Hand.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boon of Fossils", "Segen der Fossilien", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Terrain cards yield 3 bones on death instead of 1.", "Geländekarten geben beim Sterben 3 statt 1 Knochen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With this boon equipped, Terrain cards yield 3 bones on death instead of 1.", "Mit diesem ausgerüsteten Segen geben Geländekarten beim Sterben 3 statt 1 Knochen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boon of Marrow", "Segen des Knochenmarks", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrificing undead cards yields 2 bones instead of 1.", "Das Opfern untoter Karten gibt 2 statt 1 Knochen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With this boon equipped, Sacrificing undead cards yields 2 bones instead of 1.", "Mit diesem ausgerüsteten Segen gibt das Opfern untoter Karten 2 statt 1 Knochen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boon of Bloodstone", "Segen des Blutsteins", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You may sacrifice terrain cards.", "Du kannst Geländekarten opfern.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With this boon equipped, You may sacrifice terrain cards.", "Mit diesem ausgerüsteten Segen kannst du Geländekarten opfern.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boon of Ouroboros", "Segen des Ouroboros", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You get a different effect depending on the region:\nBeast Dungeon:+2 Starting bones each battle.\nDeath Dungeon:+1 Starting Energy each battle\nTech Dungeon:Start the game with two random mox in your hand.\nMagick Dungeon:Start the game with 2 Squirrels in your hand.", "Je nach Gebiet erhältst du einen anderen Effekt:\nBestien-Dungeon: +2 Knochen zu Beginn jedes Kampfes.\nTodes-Dungeon: +1 Energie zu Beginn jedes Kampfes.\nTechnologie-Dungeon: Beginne jeden Kampf mit zwei zusätzlichen zufälligen Mox auf der Hand.\nMagie-Dungeon: Beginne jeden Kampf mit 2 zusätzlichen Eichhörnchen auf der Hand.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With this boon equipped, You get a different effect depending on the region:\nBeast Dungeon:+2 Starting bones each battle.\nDeath Dungeon:+1 Starting Energy each battle\nTech Dungeon:Start the game with two random mox in your hand.\nMagick Dungeon:Start the game with 2 Squirrels in your hand.", "Mit diesem ausgerüsteten Segen erhältst du je nach Gebiet einen anderen Effekt:\nBestien-Dungeon: +2 Knochen zu Beginn jedes Kampfes.\nTodes-Dungeon: +1 Energie zu Beginn jedes Kampfes.\nTechnologie-Dungeon: Beginne jeden Kampf mit zwei zusätzlichen zufälligen Mox auf der Hand.\nMagie-Dungeon: Beginne jeden Kampf mit 2 zusätzlichen Eichhörnchen auf der Hand.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ay yo yaw cant stand right here", "Hey, du kannst hier nicht stehen!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fir", "Große Tanne", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tombstone", "Grabstein", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conduit Tower", "Leiterturm", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Bot", "Kaputter Bot", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bridge Railing", "Brückengeländer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Boulder", "Smaragdfelsbrocken", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Boulder", "Rubinfelsbrocken", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sapphire Boulder", "Saphirfelsbrocken", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bounty Hunter", "Kopfgeldjäger", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Waddup, to all rappers shut up with your shutting up.", "Yo, an alle Rapper: Hört auf, still zu sein!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My injuries.. They are severe.", "Meine Verletzungen ... Sie sind schwer.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am forced to retire.. for now.", "Ich muss mich zurückziehen ... fürs Erste.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Argh!! What have you done to me?", "Argh!! Was hast du mir angetan?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everything hurts... But.. I'll be back..", "Alles tut weh ... Aber ... ich komme wieder ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well.. you stopped me..", "Nun ... du hast mich aufgehalten ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I WILL get you.. challenger..", "Ich WERDE dich kriegen ... Herausforderer ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've been scrapped!", "Ich wurde verschrottet!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You beat me fair and square...", "Du hast mich fair und ehrlich besiegt ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So I will retreat.. well played.. Expect a rematch soon though..", "Also ziehe ich mich zurück ... gut gespielt ... Aber rechne bald mit einem Rückkampf ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So, we meet again..", "Wir treffen uns also wieder ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh.. Its You..", "Oh ... Du bist es ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aha! Found you!", "Aha! Ich habe dich gefunden!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've come to get my revenge!", "Ich bin gekommen, um mich zu rächen!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Surprise!", "Überraschung!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hey.", "Hey.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well, Hello there.", "Na, hallo.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greeetings!", "Sei gegrüüßt!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just what do YOU think you're doing? Wandering around and destroying our dungeons.", "Was glaubst DU eigentlich, was du tust? Du streifst umher und zerstörst unsere Dungeons.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A little mouse wanders into my sight..", "Eine kleine Maus kommt mir vor die Augen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At last, I have found you..", "Endlich habe ich dich gefunden ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beasts", "Bestien", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Technology", "Technologie", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magick", "Magie", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead", "Tot", Language.German);

            // Bounty
            Dictionary<string, string> bountyName = new Dictionary<string, string>
            {
                {"Barry", "Barry"},
                {"Bolt", "Bolt"},
                {"Gear", "Rad"},
                {"Zap", "Zap"},
                {"Rust", "Rost"},
                {"Clain", "Clain"},
                {"Clank", "Klong"},
                {"Tank", "Tank"},
                {"Gun", "Wumm"},
                {"Shoot", "Baller"},
                {"Maksim", "Maksim"},
                {"Wilkin", "Wilkin"},
                {"Kaycee", "Kaycee"},
                {"Hobbes", "Hobbes"},
                {"Grind", "Mahl"},
                {"Blast", "Knall"},
                {"Crash", "Krach"},
                {"Moon", "Mond"},
                {"Zip", "Zip"},
                {"Jerry", "Jerry"},
                {"Plasma", "Plasma"},
                {"Jimmy", "Jimmy"},
                {"Silence", "Stille"},
                {"Never", "Niemals"},
                {"Hunt", "Jagd"},
                {"Hunter", "Jäger"},
                {"Doom", "Verderben"},
                {"Const", "Konst"},
                {"Boom", "Bumm"},
                {"West", "West"}
            };
            Dictionary<string, string> bountySuffix = new Dictionary<string, string>
            {
                {"son", "son"},
                {"stein", "stein"},
                {"dottir", "dottir"},
                {"vic", "vic"},
                {"berg", "berg"},
                {"sky", "sky"},
                {"ski", "ski"},
                {"sin", "sin"},
                {"sim", "sim"},
                {"fellow", "fellow"},
                {"ed", "ed"},
                {" II", " II"},
                {" III", " III"}
            };
            Dictionary<string, string> bountyPrefix = new Dictionary<string, string>
            {
                {"Mac", "Mac"},
                {"Mc", "Mc"},
                {"Von ", "von "},
                {"Van ", "van "},
                {"Sir ", "Sir "},
                {"Madame ", "Frau "}
            };
            foreach (var n in bountyName)
            {
                foreach (var s in bountySuffix)
                {
                    var name = n.Key + s.Key;
                    var namechinese = n.Value + s.Value;
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, name, namechinese, Language.German);
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But this ain't the last of " + name + "!", "Aber das war noch nicht das Ende von " + namechinese + "!", Language.German);
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, name + ". Seeking revenge..", namechinese + ". Auf der Suche nach Rache ...", Language.German);
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The one who destroyed " + name + "... You won't get away with it again.", "Du hast " + namechinese + " zerstört ... Diesmal kommst du nicht davon.", Language.German);
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Didn't expect to see " + name + " again, did ya?", "Du hast wohl nicht erwartet, " + namechinese + " wiederzusehen, was?", Language.German);
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unfortunately, " + name + " is back.", "Leider ist " + namechinese + " zurück.", Language.German);
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They call me.. " + name + ".. You can't defeat ME!", "Man nennt mich ... " + namechinese + " ... MICH kannst du nicht besiegen!", Language.German);
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's see you stop " + name + ".", "Mal sehen, ob du " + namechinese + " aufhalten kannst.", Language.German);
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just remember that " + name + " can not be defeated.", "Denk daran, dass " + namechinese + " unbesiegbar ist.", Language.German);
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, name + " will be your executioner for the evening.", namechinese + " wird heute Abend dein Henker sein.", Language.German);
                    foreach (var p in bountyPrefix)
                    {
                        name = p.Key + name;
                        namechinese = p.Value + namechinese;
                        SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, name, namechinese, Language.German);
                        SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But this ain't the last of " + name + "!", "Aber das war noch nicht das Ende von " + namechinese + "!", Language.German);
                        SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, name + ". Seeking revenge..", namechinese + ". Auf der Suche nach Rache ...", Language.German);
                        SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The one who destroyed " + name + "... You won't get away with it again.", "Du hast " + namechinese + " zerstört ... Diesmal kommst du nicht davon.", Language.German);
                        SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Didn't expect to see " + name + " again, did ya?", "Du hast wohl nicht erwartet, " + namechinese + " wiederzusehen, was?", Language.German);
                        SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unfortunately, " + name + " is back.", "Leider ist " + namechinese + " zurück.", Language.German);
                        SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They call me.. " + name + ".. You can't defeat ME!", "Man nennt mich ... " + namechinese + " ... MICH kannst du nicht besiegen!", Language.German);
                        SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's see you stop " + name + ".", "Mal sehen, ob du " + namechinese + " aufhalten kannst.", Language.German);
                        SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just remember that " + name + " can not be defeated.", "Denk daran, dass " + namechinese + " unbesiegbar ist.", Language.German);
                        SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, name + " will be your executioner for the evening.", namechinese + " wird heute Abend dein Henker sein.", Language.German);
                    }
                }
            }
        }
    }
    public class WhistleWindAbnormalSigilsMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for WhistleWindAbnormalSigils Mod");
            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aggravating", "Aufstacheln", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While this card is on the board, all opposing creatures gain 1 Power.", "Solange diese Karte auf dem Brett ist, erhalten alle gegnerischen Kreaturen 1 Kraft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My beasts are incensed by your creature's presence.", "Meine Bestien werden durch die Anwesenheit deiner Kreatur aufgebracht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alchemist", "Alchemist", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Energy to discard your current hand and draw cards equal to the amount you discarded.", "Bezahle 2 Energie, um deine aktuelle Hand abzuwerfen und genauso viele Karten zu ziehen, wie du abgeworfen hast.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The unending faith of countless promises.", "Der endlose Glaube unzähliger Versprechen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] replaces your hand with a new one!", "[creature] ersetzt deine Hand durch eine neue!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Assimilator", "Assimilierer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card kills an opposing card, it gains 1 Power and 1 Health.", "Wenn diese Karte eine gegnerische Karte tötet, erhält sie 1 Kraft und 1 Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "From the many, one.", "Aus vielen wird eins.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] makes its victim a part of itself.", "[creature] macht ihr Opfer zu einem Teil ihrer selbst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Barreler", "Walzer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, this card moves in the sigil's direction to the end of the board, moving any cards in the way.", "Am Ende des Zugs ihres Besitzers bewegt sich diese Karte in Siegelrichtung bis zum Ende des Bretts und schiebt alle Karten im Weg mit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Make room.", "Macht Platz.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] moves to the end of the board, tossing anything in its way.", "[creature] bewegt sich bis zum Ende des Bretts und schleudert alles aus dem Weg.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Binding Strike", "Fesselnder Schlag", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] strikes an opposing creature, inflict Bind equal to twice this card's Power.", "Wenn [creature] eine gegnerische Kreatur trifft, fügt sie ihr Bindung in Höhe ihrer doppelten Kraft zu.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your beast falls behind the pack.", "Deine Bestie bleibt hinter dem Rudel zurück.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bitter Enemies", "Erbitterte Feinde", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card gains 1 Power for each other card on the board that also bears this sigil.", "Diese Karte erhält 1 Kraft für jede andere Karte auf dem Brett, die ebenfalls dieses Siegel trägt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A bitter grudge laid bare.", "Ein erbitterter Groll wird sichtbar.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloodfiend", "Blutteufel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card deals damage, it gains 1 Health.", "Wenn diese Karte Schaden verursacht, erhält sie 1 Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Accursed fiend.", "Verfluchter Teufel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] sucks out fresh life!", "[creature] saugt frisches Leben aus!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloodletter", "Aderlass", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a [creature] is struck with a nonfatal attack, absorb 1 Health from the striker.", "Wird [creature] von einem nicht tödlichen Angriff getroffen, absorbiert sie 1 Gesundheit vom Angreifer.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The blood runs warm with sweet vitality.", "Das Blut fließt warm und voller süßer Lebenskraft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] absorbs nutrients!", "[creature] nimmt Nährstoffe auf!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broodmother", "Brutmutter", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, create a Spiderling in your hand. [define:wstl_spiderling]", "Wenn [creature] getroffen wird, erzeuge eine Jungspinne auf deiner Hand. [define:wstl_spiderling]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A small spider takes refuge in your hand.", "Eine kleine Spinne sucht Zuflucht auf deiner Hand.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] drops a spiderling!", "[creature] lässt eine Jungspinne fallen!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conductor", "Dirigent", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The effect of this sigil will change over the next 3 turns while this card is on the board.", "Solange diese Karte auf dem Brett ist, verändert sich die Wirkung dieses Siegels in den nächsten 3 Zügen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "From break and ruin, the most beautiful performance begins.", "Aus Trümmern und Zerstörung erwächst die schönste Darbietung.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] plays a quiet symphony.", "[creature] spielt eine stille Symphonie.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Copycat", "Nachahmer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will transform into a copy of the first creature that opposes it.", "[creature] verwandelt sich in eine Kopie der ersten Kreatur, die ihr gegenübersteht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A near perfect impersonation.", "Eine nahezu perfekte Nachahmung.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] tries to mimick the opposing creature.", "[creature] versucht, die gegenüberliegende Kreatur nachzuahmen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Corrector", "Korrektor", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is drawn, randomly change its stats according to its total play cost.", "Wenn [creature] gezogen wird, ändern sich ihre Werte zufällig entsprechend ihren gesamten Ausspielkosten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How balanced.", "Wie ausgewogen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] stats are forcefully 'corrected'.", "Die Werte von [creature] werden zwangsweise „korrigiert“.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Courageous", "Mutig", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures adjacent to this card lose up to 2 Health. For each point of Heath lost, the affected creature gains 1 Power. This effect cannot kill cards.", "Kreaturen neben dieser Karte verlieren bis zu 2 Gesundheit. Für jeden verlorenen Gesundheitspunkt erhält die betroffene Kreatur 1 Kraft. Dieser Effekt kann keine Karten töten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Life is only given to those who don't fear death.", "Leben wird nur denen geschenkt, die den Tod nicht fürchten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cursed", "Verflucht", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, the killer transforms into a copy of this card.", "Wenn [creature] stirbt, verwandelt sich ihr Töter in eine Kopie dieser Karte.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The curse continues unabated.", "Der Fluch hält unvermindert an.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] passes the curse on.", "[creature] gibt den Fluch weiter.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cycler", "Kreisläufer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, this card moves in the sigil's direction, looping around the owner's side of the board.", "Am Ende des Zugs ihres Besitzers bewegt sich diese Karte in Siegelrichtung und läuft auf der Seite ihres Besitzers über den Rand hinaus im Kreis.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A never-ending cycle.", "Ein endloser Kreislauf.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] moves to a new space, going around its side of the board.", "[creature] bewegt sich auf ein neues Feld und läuft über den Rand ihrer Brettseite hinaus.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "False Throne", "Falscher Thron", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once per turn, pay 1 Health to give Neutered to a chosen creature, then create a free, unaltered copy of it in your hand.", "Bezahle einmal pro Zug 1 Gesundheit, um einer gewählten Kreatur Kastriert zu verleihen, und erzeuge dann eine kostenlose, unveränderte Kopie von ihr auf deiner Hand.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A simple little magic trick.", "Ein einfacher kleiner Zaubertrick.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gives a false present to the chosen creature.", "[creature] macht der gewählten Kreatur ein falsches Geschenk.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flag Bearer", "Fahnenträger", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While this card is on the board, adjacent creatures gain 2 Health.", "Solange diese Karte auf dem Brett ist, erhalten benachbarte Kreaturen 2 Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Morale runs high.", "Die Moral ist hoch.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruler of Frost", "Herrscherin des Frosts", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once per turn, pay 2 Bones to choose a space on the board. If the space is empty, create a Block of Ice. Otherwise, if this card can kill the occupying card, transform it into a Frozen Heart.", "Bezahle einmal pro Zug 2 Knochen, um ein Feld auf dem Brett zu wählen. Ist es leer, erzeuge einen Eisblock. Andernfalls verwandle die Karte darauf in ein Gefrorenes Herz, falls diese Karte sie töten kann.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With a wave of her hand, the Snow Queen blocked the path.", "Mit einer Handbewegung versperrte die Schneekönigin den Weg.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] freezes the path.", "[creature] friert den Weg ein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frozen Heart", "Gefrorenes Herz", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, the killer gains 2 Health.", "Wenn [creature] stirbt, erhält ihr Töter 2 Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spring arrives with blossoming roses.", "Der Frühling kommt mit blühenden Rosen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] releases warm life.", "[creature] setzt warmes Leben frei.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gardener", "Gärtner", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When an allied card is killed, create a Sapling in their place. [define:wstl_parasiteTreeSapling]", "Wenn eine verbündete Karte getötet wird, erzeuge an ihrer Stelle einen Setzling. [define:wstl_parasiteTreeSapling]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They proliferate and become whole. Can you feel it?", "Sie vermehren und vervollständigen sich. Spürst du es?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A sapling grows out of the dead card's corpse.", "Ein Setzling wächst aus dem Leichnam der toten Karte.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gift Giver", "Geschenkgeber", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, create a random card in your hand.", "Wenn [creature] ausgespielt wird, erzeuge eine zufällige Karte auf deiner Hand.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A gift for you.", "Ein Geschenk für dich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] has a gift for you!", "[creature] hat ein Geschenk für dich!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greedy Healing", "Gierige Heilung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its owner's turn, this card gains 2 Health. If 2 turns pass without this card taking damage, it will die.", "Am Ende des Zugs ihres Besitzers erhält diese Karte 2 Gesundheit. Vergehen 2 Züge, ohne dass sie Schaden nimmt, stirbt sie.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your beast has Health in excess.", "Deine Bestie hat Gesundheit im Überfluss.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gives itself more Health!", "[creature] verschafft sich mehr Gesundheit!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grinder", "Zermalmer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card gains the stats of the creatures sacrificed to play it.", "Diese Karte erhält die Werte der Kreaturen, die geopfert wurden, um sie auszuspielen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now everything will be just fine.", "Jetzt wird alles gut.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Group Healer", "Gruppenheiler", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of its owner's turn, this card will heal all allies that have taken damage by 1 Health.", "Zu Beginn des Zugs ihres Besitzers heilt diese Karte alle verletzten Verbündeten um 1 Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You only delay the inevitable.", "Du verzögerst nur das Unvermeidliche.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] heals all its friends.", "[creature] heilt alle ihre Freunde.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Healer", "Heiler", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of your turn, you may choose one of your other cards to heal by 2 Health.", "Am Ende deines Zugs kannst du eine deiner anderen Karten wählen und sie um 2 Gesundheit heilen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Never underestimate the importance of a healer.", "Unterschätze niemals die Bedeutung eines Heilers.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] heals the chosen creature!", "[creature] heilt die gewählte Kreatur!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "High-Strung", "Angespannt", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the current turn, this card gains Haste equal to twice the opposing card's Power.", "Am Ende des aktuellen Zugs erhält diese Karte Eile in Höhe der doppelten Kraft der gegenüberliegenden Karte.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Idol", "Idol", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While this card is on the board, all opposing creatures lose 1 Power.", "Solange diese Karte auf dem Brett ist, verlieren alle gegnerischen Kreaturen 1 Kraft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My beasts defer to you.", "Meine Bestien ordnen sich dir unter.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Left-Veering Strike", "Linksabweichender Schlag", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike the opposing space to the left of the space across from it.", "[creature] trifft das gegnerische Feld links von dem Feld direkt gegenüber.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Right-Veering Strike", "Rechtsabweichender Schlag", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike the opposing space to the right of the space across from it.", "[creature] trifft das gegnerische Feld rechts von dem Feld direkt gegenüber.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lonely", "Einsam", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose a card on the board to gain 1 Pebble unless a card with Pebble already exists, then return this card to your hand. If a card with Pebble dies, all ally cards receive 1 additional damage until a new card is chosen.", "Wähle eine Karte auf dem Brett, die 1 Kiesel erhält, sofern nicht bereits eine Karte mit Kiesel existiert, und nimm die Karte mit diesem Siegel dann auf deine Hand zurück. Stirbt eine Karte mit Kiesel, erleiden alle verbündeten Karten 1 zusätzlichen Schaden, bis eine neue Karte gewählt wird.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A friend to stay.", "Ein Freund, der bleibt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Martyr", "Märtyrer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, all allied creatures gain 2 Health and lose any negative status effects.", "Wenn [creature] stirbt, erhalten alle verbündeten Kreaturen 2 Gesundheit und verlieren alle negativen Statuseffekte.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A selfless death to cleanse your beasts of evil.", "Ein selbstloser Tod, um deine Bestien vom Bösen zu reinigen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]'s death cleanses your other creatures!", "Der Tod von [creature] reinigt deine anderen Kreaturen!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nettle Clothes", "Nesselkleidung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card is played, fill all empty spaces on the owner's side of the board with random Brothers. This card gains the first sigil of each allied Brother.", "Wenn diese Karte ausgespielt wird, fülle alle leeren Felder auf der Seite ihres Besitzers mit zufälligen Brüdern. Diese Karte erhält das erste Siegel jedes verbündeten Bruders.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "These clothes will surely restore our happy days.", "Diese Kleidung wird unsere glücklichen Tage gewiss zurückbringen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] brings out its family!", "[creature] holt ihre Familie hervor!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Neutered", "Kastriert", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] has its Power reduced to 0. At the start of the owner's turn, remove this sigil.", "Die Kraft von [creature] wird auf 0 reduziert. Entferne dieses Siegel zu Beginn des Zugs ihres Besitzers.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Neutered Latch", "Kastrationsanheftung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once per turn, pay [sigilcost:2 Bones] to choose a creature to gain the Neutered sigil, then increase this sigil's activation cost by 1 Bone.", "Bezahle einmal pro Zug [sigilcost:2 Knochen], um eine Kreatur zu wählen, die das Siegel Kastriert erhält, und erhöhe danach die Aktivierungskosten dieses Siegels um 1 Knochen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once per turn, pay 1 bone to choose a creature to gain the Neutered sigil, then increase this sigil's activation cost by 1 Bone.", "Bezahle einmal pro Zug 1 Knochen, um eine Kreatur zu wählen, die das Siegel Kastriert erhält, und erhöhe danach die Aktivierungskosten dieses Siegels um 1 Knochen.", Language.German);
            for (int count = 0; count <= 100; count++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once per turn, pay " + count.ToString() + " bones to choose a creature to gain the Neutered sigil, then increase this sigil's activation cost by 1 Bone.", "Bezahle einmal pro Zug " + count.ToString() + " " + "Knochen" + ", um eine Kreatur zu wählen, die das Siegel Kastriert erhält. Erhöhe dann die Aktivierungskosten dieses Siegels um 1 Knochen.", Language.German);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The will to fight has been lost.", "Der Kampfeswille ist verloren.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] prevents the chosen creature from attacking.", "[creature] hindert die gewählte Kreatur am Angreifen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nimble-Footed", "Flotten Fußes", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owner's turn, this card gains 2 Haste.", "Zu Beginn des Zugs ihres Besitzers erhält diese Karte 2 Eile.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Opportunistic", "Opportunistisch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] deals 1 additional damage to opposing cards that cannot attack this card during their own turn.", "[creature] fügt gegnerischen Karten 1 zusätzlichen Schaden zu, wenn diese sie während ihres eigenen Zugs nicht angreifen können.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A cheap hit.", "Ein billiger Treffer.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Persecutor", "Verfolger", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, create a Nail in the adjacent left space and a Hammer in the adjacent right space if they are empty.", "Wenn eine Karte mit diesem Siegel ausgespielt wird, erzeuge auf dem benachbarten linken Feld einen Nagel, falls es leer ist, und auf dem benachbarten rechten Feld einen Hammer, falls es leer ist.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you guilty of having a closed heart?", "Bist du schuldig, weil dein Herz verschlossen ist?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] reveals its hidden tools!", "[creature] enthüllt ihre verborgenen Werkzeuge!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Persistent", "Fortbestehen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Attacks by this card cannot be avoided or redirected by sigils like Loose Tail or Waterborne.", "Angriffe dieser Karte können nicht durch Siegel wie Lockerer Schwanz oder Wasserwesen vermieden oder umgeleitet werden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prey cannot hide so easily.", "Beute kann sich nicht so leicht verstecken.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] chases its prey down.", "[creature] jagt ihre Beute.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Damage dealt by this card cannot be negated or reduced by sigils such as Armoured or Thick Skin.", "Schaden dieser Karte kann nicht durch Siegel wie Gepanzert oder Dicke Haut aufgehoben oder verringert werden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your beast runs mine through.", "Deine Bestie durchbohrt meine.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures adjacent to this card take 1 less damage when struck.", "Kreaturen neben dieser Karte erleiden bei Treffern 1 Schaden weniger.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your beast shields its ally against the blow.", "Deine Bestie schützt ihren Verbündeten vor dem Schlag.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] shields its friend!", "[creature] schützt ihren Freund!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Punisher", "Bestrafer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, the striker is killed.", "Wenn [creature] getroffen wird, wird der Angreifer getötet.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Retaliation is switft and brutal.", "Die Vergeltung ist schnell und brutal.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] swiftly retaliates!", "[creature] schlägt rasch zurück!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Queen Nest", "Königinnennest", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever another card is killed, create a Worker Bee in your hand. [define:wstl_queenBeeWorker]", "Immer wenn eine andere Karte getötet wird, erzeuge eine Arbeiterbiene auf deiner Hand. [define:wstl_queenBeeWorker]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "For the hive.", "Für den Bienenstock.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Another worker is born to serve [creature].", "Eine weitere Arbeiterin wird geboren, um [creature] zu dienen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reflector", "Reflektor", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card is struck, the striker is dealt damage equal to the striker's Power.", "Wenn diese Karte getroffen wird, erleidet der Angreifer Schaden in Höhe seiner eigenen Kraft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What goes around comes around.", "Was man aussät, erntet man.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] returns the damage.", "[creature] gibt den Schaden zurück.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Refresh Decks", "Stapel erneuern", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Refreshes and reshuffles both draw piles.", "Erneuert und mischt beide Ziehstapel neu.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of its owner's turn, this card heals adjacent cards by 1 Health.", "Zu Beginn des Zugs ihres Besitzers heilt diese Karte benachbarte Karten um 1 Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wounds heal, but the scars remain.", "Wunden heilen, doch die Narben bleiben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] heals adjacent creatures.", "[creature] heilt benachbarte Kreaturen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Return Card to Hand", "Karte auf die Hand zurücknehmen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Returns the selected card to your hand with all changes and statuses retained. Change the selected card's cost to 0-2 Bones based on how recently it was played.", "Nimmt die gewählte Karte auf deine Hand zurück und behält dabei alle Änderungen und Zustände. Ihre Kosten werden je nach Zeitpunkt ihres Ausspielens auf 0 bis 2 Knochen gesetzt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Return to Nihil", "Rückkehr ins Nichts", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, deal damage equal to this card's Power to all other cards on the board.", "Am Ende des Zugs ihres Besitzers fügt diese Karte allen anderen Karten auf dem Brett Schaden in Höhe ihrer Kraft zu.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One step closer to oblivion.", "Ein Schritt näher am Vergessen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The void calls.", "Die Leere ruft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rightful Heir", "Rechtmäßige Erbin", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once per turn, pay [sigilcost:1 Bone] to transform a chosen creature into a Pumpkin, then increase this sigil's activation cost by 1. [define:wstl_ozmaPumpkin]", "Bezahle einmal pro Zug [sigilcost:1 Knochen], um eine gewählte Kreatur in einen Kürbiskopf zu verwandeln, und erhöhe danach die Aktivierungskosten dieses Siegels um 1. [define:wstl_ozmaPumpkin]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once per turn, pay 1 bone to transform a chosen creature into a Pumpkin, then increase this sigil's activation cost by 1. [define:wstl_ozmaPumpkin]", "Bezahle einmal pro Zug 1 Knochen, um eine gewählte Kreatur in einen Kürbiskopf zu verwandeln, und erhöhe danach die Aktivierungskosten dieses Siegels um 1. [define:wstl_ozmaPumpkin]", Language.German);
            for (int count = 0; count <= 100; count++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once per turn, pay " + count.ToString() + " bones to transform a chosen creature into a Pumpkin, then increase this sigil's activation cost by 1. [define:wstl_ozmaPumpkin]", "Bezahle einmal pro Zug " + count.ToString() + " " + "Knochen" + ", um eine gewählte Kreatur in einen Kürbiskopf zu verwandeln. Erhöhe dann die Aktivierungskosten dieses Siegels um 1. [define:wstl_ozmaPumpkin]", Language.German);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All she has left now are her children.", "Alles, was ihr jetzt noch bleibt, sind ihre Kinder.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] turns the creature into a pumpkin.", "[creature] verwandelt die Kreatur in einen Kürbis.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Roots", "Wurzeln", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card is played, create Thorny Vines on adjacent empty spaces. [define:wstl_snowWhitesVine]", "Wenn diese Karte ausgespielt wird, erzeuge Dornenranken auf benachbarten leeren Feldern. [define:wstl_snowWhitesVine]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Resentment bursts forth like a weed.", "Groll sprießt hervor wie Unkraut.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sharp thorns shoot out around [creature]!", "Scharfe Dornen schießen um [creature] hervor!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scorching", "Versengen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The creature opposing this card takes 1 damage at the end of its owner's turn.", "Die Kreatur gegenüber dieser Karte erleidet am Ende des Zugs ihres eigenen Besitzers 1 Schaden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A slow and painful death.", "Ein langsamer und schmerzhafter Tod.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The creature opposing [creature] is burned!", "Die Kreatur gegenüber von [creature] wird verbrannt!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scrambler", "Verwürfler", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, give its stats to the sacrificing card then randomise the resulting stats.", "Wenn [creature] geopfert wird, übertrage ihre Werte auf die Karte, für die sie geopfert wurde, und ändere die resultierenden Werte zufällig.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, give its stats to the sacrificing card then randomise the resulting stats. Works for Spells.", "Wenn [creature] geopfert wird, übertrage ihre Werte auf die Karte, für die sie geopfert wurde, und ändere die resultierenden Werte zufällig. Funktioniert auch mit Zaubern.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you love your city?", "Liebst du deine Stadt?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Serpent's Nest", "Schlangennest", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, the striker gains 1 Worms.", "Wenn [creature] getroffen wird, erhält der Angreifer 1 Punkt Würmer.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It can enter your body through any aperture.", "Es kann durch jede Öffnung in deinen Körper gelangen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Made of Slime", "Aus Schleim", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, give adjacent cards this sigil, and deal 1 damage to this card if it is not a Slime. This card transforms into a Slime on death.", "Am Ende des Zugs ihres Besitzers verleiht diese Karte benachbarten Karten dieses Siegel und erleidet 1 Schaden, wenn sie kein Schleim ist. Beim Sterben verwandelt sie sich in Schleim.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its army grows everyday.", "Seine Armee wächst jeden Tag.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] melts into slime!", "[creature] schmilzt zu Schleim!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sporogenic", "Sporogen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures adjacent to this card gain 1 Spores at the end of its owner's turn. This sigil activates before other sigils.", "Kreaturen neben dieser Karte erhalten am Ende des Zugs des Besitzers dieser Karte 1 Spore. Dieses Siegel wird vor anderen Siegeln aktiviert.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They will love this curse like a blessing.", "Sie werden diesen Fluch wie einen Segen lieben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] scatters spores on the adjacent cards!", "[creature] verteilt Sporen auf benachbarten Karten!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Team Leader", "Teamleiter", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While this card is on the board, all allied creatures gain 1 Power.", "Solange diese Karte auf dem Brett ist, erhalten alle verbündeten Kreaturen 1 Kraft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your beast emboldens its allies.", "Deine Bestie ermutigt ihre Verbündeten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Train", "Der Zug", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, kill all creatures on the board. Creatures killed this way do not drop bones.", "Wenn [creature] ausgespielt wird, töte alle Kreaturen auf dem Brett. Auf diese Weise getötete Kreaturen lassen keine Knochen fallen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The train boards those that don't step away from the tracks.", "Der Zug nimmt jene mit, die nicht von den Gleisen treten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The train blows its mighty horn.", "Der Zug lässt sein mächtiges Horn ertönen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thick Skin", "Dicke Haut", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever [creature] takes damage, reduce that damage by 1.", "Immer wenn [creature] Schaden erleidet, verringere diesen Schaden um 1.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your creature's hide absorbs the blow.", "Die Haut deiner Kreatur fängt den Schlag ab.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] absorbs the blow.", "[creature] fängt den Schlag ab.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Volatile", "Explosiv", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card dies, adjacent and opposing cards are dealt 10 damage.", "Wenn diese Karte stirbt, erleiden benachbarte und gegenüberliegende Karten 10 Schaden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An explosive finish.", "Ein explosives Ende.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] detonates! Adjacent creatures are killed in the blast.", "[creature] explodiert! Benachbarte Kreaturen werden durch die Explosion getötet.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Witness", "Zeuge", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Bones to increase the selected creature's Health by 2 and their taken damage by 1. This effect stacks up to 3 times.", "Bezahle 2 Knochen, um die Gesundheit der gewählten Kreatur um 2 und den von ihr erlittenen Schaden um 1 zu erhöhen. Dieser Effekt ist bis zu 3-mal stapelbar.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The truth will set you free.", "Die Wahrheit wird dich befreien.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The chosen beholds [creature] and is reborn.", "Der Auserwählte erblickt [creature] und wird wiedergeboren.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woodcutter", "Holzfäller", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature moves into the space opposite this card, they take damage equal to this card's Power.", "Wenn eine Kreatur auf das Feld gegenüber dieser Karte zieht, erleidet sie Schaden in Höhe der Kraft dieser Karte.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No matter how many trees fall, the forest remains dense.", "Ganz gleich, wie viele Bäume fallen, der Wald bleibt dicht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] takes a free swing.", "[creature] holt zu einem freien Schlag aus.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its owner's turn, this card moves in the sigil's direction, looping around the owner's side of the board. Allied creatures towards this card in the sigil's direction as far as possible.", "Am Ende des Zugs ihres Besitzers bewegt sich diese Karte in Siegelrichtung und läuft auf ihrer Brettseite im Kreis. Andere verbündete Kreaturen bewegen sich in dieser Richtung so weit wie möglich auf sie zu.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's go, together.", "Gehen wir zusammen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] leads your creatures forward.", "[creature] führt deine Kreaturen vorwärts.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil is immune to the effects of Touch of Death, Stinky, Punisher, Cursed, and Idol.", "Eine Karte mit diesem Siegel ist gegen Berührung des Todes, Gestank, Bestrafer, Verflucht und Idol immun.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Adjacent creatures gain Power equal to half this card's base Power, rounded down. This effect changes next turn.", "Benachbarte Kreaturen erhalten Kraft in Höhe der Hälfte der Grundkraft dieser Karte, abgerundet. Dieser Effekt ändert sich im nächsten Zug.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Allied creatures on the board gain Power equal to half this card's base Power, rounded down. This effect changes next turn.", "Verbündete Kreaturen auf dem Brett erhalten Kraft in Höhe der Hälfte der Grundkraft dieser Karte, abgerundet. Dieser Effekt ändert sich im nächsten Zug.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All other creatures on the board gain Power equal to this card's Power.", "Alle anderen Kreaturen auf dem Brett erhalten Kraft in Höhe der Kraft dieser Karte.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There are no cards you can choose.", "Es gibt keine Karten, die du wählen kannst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can't target the air.", "Du kannst nicht die Luft anvisieren.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You must choose one of your other cards.", "Du musst eine deiner anderen Karten wählen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's already latched...", "Es wurde bereits angeheftet ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You must choose one of your other cards.", "Du musst eine deiner anderen Karten wählen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Some things in this world are too unique to replicate.", "Manche Dinge auf dieser Welt sind zu einzigartig, um sie zu kopieren.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The lie falls apart, revealing your pitiful true self.", "Die Lüge zerfällt und enthüllt dein erbärmliches wahres Selbst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your creature's consitution is too weak.", "Die Konstitution deiner Kreatur ist zu schwach.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cowards don't get the boon of the brave.", "Feiglinge erhalten nicht den Segen der Tapferen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Love yourself.", "Liebe dich selbst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your beast's moxie withers away.", "Der Mut deiner Bestie schwindet.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The curse abates.", "Der Fluch lässt nach.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With a single kiss, the Snow Queen froze their hearts.", "Mit einem einzigen Kuss fror die Schneekönigin ihre Herzen ein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The snow melts away. Perhaps spring is coming.", "Der Schnee schmilzt. Vielleicht kommt der Frühling.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why do they always leave?", "Warum gehen sie immer fort?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "She saw her dear brothers in the distance.", "Sie sah ihre lieben Brüder in der Ferne.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Her family that needed the nettle clothing to be free of the curse.", "Ihre Familie brauchte die Nesselkleidung, um vom Fluch befreit zu werden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "She fell to the ground, vomiting ooze like the rest of [c:bR]the City[c:].", "Sie fiel zu Boden und erbrach Schleim wie der Rest [c:bR]der Stadt[c:].", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The lake ripples gently. As if a number of swans just took flight.", "Der See kräuselt sich sanft. Als wären gerade einige Schwäne aufgeflogen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The punishment for greed is getting everything you wanted.", "Die Strafe für Gier ist, alles zu bekommen, was man sich wünscht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A new nest is born.", "Ein neues Nest entsteht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Status Effect Overflow", "Überlauf der Statuseffekte", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card has more than 5 status effects, display the overflow here.", "Hat eine Karte mehr als 5 Statuseffekte, werden die übrigen hier angezeigt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No one to heal.", "Niemand zu heilen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No allies to receive a blessing. [c:bR]An enemy[c:] will suffice instead.", "Keine Verbündeten können einen Segen erhalten. [c:bR]Ein Gegner[c:] tut es stattdessen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No enemies either. It seems no blessings will be given this turn.", "Auch keine Gegner. Anscheinend wird in diesem Zug kein Segen vergeben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The enemy is immune to the cold.", "Dieser Gegner ist gegen Kälte immun.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its heart is too strong to ensare.", "Sein Herz ist zu stark, um es zu fesseln.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This creature burns with passion. It cannot freeze.", "Diese Kreatur brennt vor Leidenschaft. Sie kann nicht einfrieren.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frost cannot penetrate this one. Choose another.", "Frost kann dieses Ziel nicht durchdringen. Wähle ein anderes.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Woodcutter stuffs the melted heart into his chest.", "Der Holzfäller steckt das geschmolzene Herz in seine Brust.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "These tools remain hidden for now.", "Diese Werkzeuge bleiben vorerst verborgen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not enough space for the vines to grow.", "Nicht genug Platz für die Ranken.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There's no one to hear your message.", "Niemand ist da, um deine Botschaft zu hören.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You must choose one of your other cards to proselytise.", "Du musst eine deiner anderen Karten zum Bekehren wählen.", Language.German);

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Abnormal Sigils is disabled in the configuration. This will likely break things.", "Abnormal Sigils ist in der Konfiguration deaktiviert. Das wird wahrscheinlich zu Fehlern führen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Abnormal Sigils loaded!", "Abnormal Sigils geladen!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Little Witch's Friend", "Freund der Kleinen Hexe", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Little Witch's Big Friend", "Großer Freund der Kleinen Hexe", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slime", "Schleim", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nail", "Nagel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jack", "Jack", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pumpkin", "Kürbiskopf", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sapling", "Setzling", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Worker Bee", "Arbeiterbiene", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Block of Ice", "Eisblock", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frozen Heart", "Gefrorenes Herz", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thorny Vines", "Dornenranken", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spider Brood", "Spinnenbrut", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spiderling", "Jungspinne", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "First Brother", "Erster Bruder", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Second Brother", "Zweiter Bruder", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Third Brother", "Dritter Bruder", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fourth Brother", "Vierter Bruder", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fifth Brother", "Fünfter Bruder", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sixth Brother", "Sechster Bruder", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spore Mold Creature", "Sporenschimmelwesen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nihil", "Nichts", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented by this sigil will be equal to the number of empty spaces on the board.", "Der Wert dieses Siegels entspricht der Anzahl der leeren Felder auf dem Brett.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sigil Power", "Siegelkraft", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the power level of this card's strongest sigil.", "Der Wert dieses Siegels entspricht der Kraftstufe des stärksten Siegels dieser Karte.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loving Slimes", "Liebende Schleime", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented by this sigil will be equal to the number of Slimes that the owner has on their side of the table.", "Der Wert dieses Siegels entspricht der Anzahl der Schleime auf der Brettseite seines Besitzers.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Passing Time", "Vergehende Zeit", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of turns that have passed since this card was placed on the board.", "Der Wert dieses Siegels entspricht der Anzahl der Züge, die vergangen sind, seit diese Karte auf dem Brett platziert wurde.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bind", "Bindung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card attacks after ally cards with less Bind. At 4 Bind, attack after opposing cards as well. Remove all Bind from this card when it attacks or on next upkeep.", "Diese Karte greift nach verbündeten Karten mit weniger Bindung an. Bei 4 Bindung greift sie auch nach gegnerischen Karten an. Entferne alle Bindung von dieser Karte, wenn sie angreift oder bei der nächsten Zugvorbereitung.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card attacks before ally cards with less Haste. At 4 Haste, attack before opposing cards as well. Remove all Haste from this card when it attacks or on next upkeep.", "Diese Karte greift vor verbündeten Karten mit weniger Eile an. Bei 4 Eile greift sie auch vor gegnerischen Karten an. Entferne alle Eile von dieser Karte, wenn sie angreift oder bei der nächsten Zugvorbereitung.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pebble", "Kiesel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card regains 1 Health at the end of the owner's turn. When this card is struck, reduce the received damage by 1.", "Diese Karte erhält am Ende des Zugs ihres Besitzers 1 Gesundheit zurück. Wird sie getroffen, verringere den erlittenen Schaden um 1.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flagellated", "Gegeißelt", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card is struck, take damage equal to this status effect.", "Wenn diese Karte getroffen wird, erleidet sie Schaden in Höhe dieses Statuseffekts.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spores", "Sporen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of its owner's turn, this card takes damage equal to its Spores. Upon dying, create a Spore Mold Creature with stats equal to its Spores.", "Zu Beginn des Zugs ihres Besitzers erleidet diese Karte Schaden in Höhe ihrer Sporen. Wenn sie stirbt, erzeuge ein Sporenschimmelwesen mit Werten in Höhe ihrer Sporen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Worms", "Würmer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owner's turn, this card gains 1 Worms. At 5+ Worms, attack allied creatures instead with a chance to give 1 Worms to struck cards.", "Zu Beginn des Zugs ihres Besitzers erhält diese Karte 1 Punkt Würmer. Ab 5 Würmern greift sie stattdessen verbündete Kreaturen an und kann getroffenen Karten 1 Punkt Würmer geben.", Language.German);

        }
    }
    public class WhistleWindLobotomyMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for WhistleWind_Lobotomy_Mod Mod");

            //other
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "APPENDIX XII, SUBSECTION II - STATUS EFFECTS {0}", "ANHANG XII, UNTERABSCHNITT II - STATUSEFFEKTE {0}", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There are no cards you can choose.", "Es gibt keine Karten, die du wählen kannst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can't target the air.", "Du kannst nicht die Luft anvisieren.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You must choose one of your other cards.", "Du musst eine deiner anderen Karten wählen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's already latched...", "Es wurde bereits angeheftet ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LatchParent", "Anheftungsbasis", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The creature rises from the well and joins your caravan. Ignoring the cries from the well, you hastily continue on.", "Die Kreatur steigt aus dem Brunnen und schließt sich deiner Karawane an. Du ignorierst die Schreie aus dem Brunnen und ziehst hastig weiter.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You may choose [c:bR]1[c:] to join you. The others will remain submerged and forgotten.", "Du kannst [c:bR]1[c:] wählen, der sich dir anschließt. Die anderen bleiben versunken und vergessen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Adoration", "Verehrung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owner's turn, if Melting Love is at 1 Health, absorb the Health of adjacent Slime cards until Melting Love is at max Health.", "Zu Beginn des Zugs ihres Besitzers absorbiert Schmelzende Liebe bei 1 Gesundheit die Gesundheit benachbarter Schleim-Karten, bis sie ihre maximale Gesundheit erreicht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Down", "Unten", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Ye who are full of blessings, rejoice. For I am with ye.[c:]", "[c:bR]Ihr, die ihr voller Segen seid, freut euch. Denn ich bin bei euch.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Thou cannot stop my ascension.[c:]", "[c:bR]Du kannst meinen Aufstieg nicht aufhalten.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]The time has come again. I will be thy guide.[c:]", "[c:bR]Die Zeit ist wieder gekommen. Ich werde dein Führer sein.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Rise, my servants. Rise and serve me.[c:]", "[c:bR]Erhebt euch, meine Diener. Erhebt euch und dient mir.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Thou shalt have no other gods before me.[c:]", "[c:bR]Du sollst keine anderen Götter neben mir haben.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The hands of the Clock move towards salvation.", "Die Zeiger der Uhr bewegen sich auf die Erlösung zu.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]When the day comes, find me.[c:]", "[c:bR]Wenn der Tag kommt, finde mich.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]I will save your life from destruction and raise you from the end of the world.[c:]", "[c:bR]Ich werde dein Leben vor der Vernichtung retten und dich am Ende der Welt erheben.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bless", "Segnen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever Plague Doctor successfully heals another card using the Healer sigil, it changes its appearance.", "Immer wenn der Pestarzt eine andere Karte erfolgreich mit dem Siegel Heiler heilt, verändert er sein Aussehen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blind Rage", "Blinde Wut", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Servant of Wrath will target a random space on the board when attacking, prioritising occupied spaces.", "Die Dienerin des Zorns wählt beim Angriff ein zufälliges Feld auf dem Brett und bevorzugt dabei belegte Felder.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CENSORED", "[ZENSIERT]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenver CENSORED kills a card, create a CENSORED in your hand with the killed card's Power, tribes, and sigils.", "Immer wenn [ZENSIERT] eine Karte tötet, erzeuge einen [ZENSIERT] auf deiner Hand mit der Kraft, den Familien und den Siegeln der getöteten Karte.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Concord", "Einklang", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When Yang is adjacent to Yin, activate a special sequence.", "Wenn Yang neben Yin liegt, wird eine besondere Sequenz ausgelöst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cowardly", "Feige", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If there is an non-Structure ally card on the board, Scaredy Cat transforms into a stronger forme. Otherwise transform into a weaker forme.", "Befindet sich eine andere verbündete Karte ohne die Eigenschaft Struktur auf dem Brett, verwandelt sich die Ängstliche Katze in eine stärkere Form. Andernfalls nimmt sie eine schwächere Form an.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crimson Scar", "Scharlachrote Narbe", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big and Will Be Bad Wolf and Red Hooded Mercenary will gain 1 Power when their counterpart is played on the board. While they're on the board, target them exclusively.", "Der Große und bald böse Wolf und die Rotkäppchen-Söldnerin erhalten 1 Kraft, wenn das jeweilige Gegenstück auf dem Brett ausgespielt wird. Solange beide auf dem Brett sind, zielen sie ausschließlich aufeinander.", Language.German);


            //ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Monster in the Black Forest", "Monster im Schwarzwald", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "'Once upon a time, three birds lived happily in the lush forest...'", "„Es waren einmal drei Vögel, die glücklich in einem üppigen Wald lebten ...“", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The three birds, now one, wandered vainly looking for the monster.", "Die drei Vögel, nun eins, wanderten umher und suchten vergeblich nach dem Monster.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Apostle", "Apostel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "'Thou wilt abandon flesh and be born again.'", "„Du wirst dein Fleisch ablegen und wiedergeboren werden.“", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big Eyes", "Große Augen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While this card is on the board, all creatures on the board are unaffected by Power-changing effects.", "Solange diese Karte auf dem Brett ist, sind alle Kreaturen auf dem Brett gegen kraftverändernde Effekte immun.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While this card is on the board, all creatures on the board are unaffected by Power-changing effects. Upon reaching 80/60/40 Health, permanently disable this effect then switch phase.", "Solange diese Karte auf dem Brett ist, sind alle Kreaturen auf dem Brett gegen kraftverändernde Effekte immun. Bei 80/60/40 Gesundheit wird dieser Effekt dauerhaft deaktiviert und die Phase gewechselt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Confession and Pentinence", "Beichte und Buße", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Keep faith with unwavering resolve.", "Bewahre den Glauben mit unerschütterlicher Entschlossenheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bG]Keep faith with unwavering resolve.[c:]", "[c:bG]Bewahre den Glauben mit unerschütterlicher Entschlossenheit.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dazzling", "Strahlend", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The turn after this card is played, inflict up to 3 other cards on the board with Enchanted.", "Im Zug nach dem Ausspielen dieser Karte belege bis zu 3 andere Karten auf dem Brett mit Verzaubert.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Like moths to a flame.", "Wie Motten zum Licht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Long Arms", "Lange Arme", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card is immune to status ailments.", "Diese Karte ist gegen negative Statuseffekte immun.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card is immune to status ailments. Upon reaching 80/60/40 Health, permanently disable this effect then switch phase.", "Diese Karte ist gegen negative Statuseffekte immun. Bei 80/60/40 Gesundheit wird dieser Effekt dauerhaft deaktiviert und die Phase gewechselt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Misdeeds Not Allowed", "Missetaten verboten", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever this card takes damage, gain 1 Power until the end of the owner's turn.", "Immer wenn diese Karte Schaden erleidet, erhält sie bis zum Ende des Zugs ihres Besitzers 1 Kraft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Small Beak", "Kleiner Schnabel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the turn, target a random lane on the board.  At the start of the next turn, kill all cards in the targeted lane, excluding this card.", "Wähle zu Beginn des Zugs eine zufällige Bahn auf dem Brett. Töte zu Beginn des nächsten Zugs alle Karten auf dieser Bahn außer dieser Karte.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the turn, target a random lane on the board.  At the start of the next turn, kill all cards in the targeted lane, excluding this card. Upon reaching 80/60/40 Health, permanently disable this effect then switch phase.", "Wähle zu Beginn des Zugs eine zufällige Bahn auf dem Brett. Töte zu Beginn des nächsten Zugs alle Karten auf dieser Bahn außer dieser Karte. Bei 80/60/40 Gesundheit wird dieser Effekt dauerhaft deaktiviert und die Phase gewechselt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Time Machine", "Zeitmaschine", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "End the current battle or phase then remove this card from the player's deck. The player must choose an additional card from a selection of 3 to remove from their deck. Selection is based on card power.", "Beende den aktuellen Kampf oder die aktuelle Phase und entferne dann diese Karte aus dem Stapel des Spielers. Der Spieler muss eine weitere Karte aus einer Auswahl von 3 wählen und aus seinem Stapel entfernen. Die Auswahl richtet sich nach der Kartenstärke.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Close your eyes and count to ten.", "Schließe die Augen und zähle bis zehn.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "True Saviour", "Wahrer Retter", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "'My story is nowhere, unknown to all.'", "„Meine Geschichte ist nirgendwo, niemandem bekannt.“", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]I am death and life. Darkness and light.[c:]", "[c:bR]Ich bin Tod und Leben. Dunkelheit und Licht.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unjust Scale", "Ungerechte Waage", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, inflict 1 Sin on all other cards. At the start of owner's turn, kill all other cards with 3+ Sin.", "Am Ende des Zugs ihres Besitzers belegt diese Karte alle anderen Karten mit 1 Sünde. Zu Beginn des Zugs ihres Besitzers tötet sie alle anderen Karten mit mindestens 3 Sünden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quick Draw", "Schnellziehen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The early bird gets the worm.", "Der frühe Vogel fängt den Wurm.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will transform into an alternate forme after 1 turn on the board.", "Eine Karte mit diesem Siegel verwandelt sich nach 1 Zug auf dem Brett in eine andere Form.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Marksman", "Schütze", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your beast strikes with precision.", "Deine Bestie trifft präzise.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Adding rulebook entries for special abilities.", "Regelbucheinträge für besondere Fähigkeiten werden hinzugefügt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All mod cards are disabled, adding Standard Training-Dummy Rabbit as a fallback to prevent issues.", "Alle Mod-Karten sind deaktiviert; das Standard-Trainingspuppenkaninchen wird zur Sicherheit als Ersatz hinzugefügt.", Language.German);


            //cards
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mirabelle", "Mirabelle", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater Apocalypse Bird", "Großer Apokalypsevogel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Poussey", "Poussey", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stemcell-642", "Stammzelle-642", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Noah", "Noah", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yumi", "Yumi", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summer", "Summer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Currince", "Currince", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Igoree", "Igoree", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Genie", "Genie", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mao", "Mao", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Evangeline", "Evangeline", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ttungsil", "Ttungsil", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mabel", "Mabel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Adult Who Tells Lies", "Der lügende Erwachsene", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All-Around Helper", "Alleskönner-Helfer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A murderous cleaning machine. Far nicer than a certain other...well, nevermind.", "Eine mörderische Reinigungsmaschine. Viel netter als eine gewisse andere ... ach, vergiss es.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alriune", "Alriune", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A doll yearning to be a human. A human yearning to be a doll.", "Eine Puppe, die sich danach sehnt, Mensch zu sein. Ein Mensch, der sich danach sehnt, eine Puppe zu sein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Angela", "Angela", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A trustworthy AI assistant. You will trust her with your life.", "Eine vertrauenswürdige KI-Assistentin. Du wirst ihr dein Leben anvertrauen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aspect of Big Bird", "Aspekt des Großen Vogels", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aspect of Small Bird", "Aspekt des Kleinen Vogels", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aspect of Long Bird", "Aspekt des Langen Vogels", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eyeball Chick", "Augenküken", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Keeper of the Black Forest", "Hüter des Schwarzwalds", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Runaway Bird", "Flüchtiger Vogel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Apocalypse Bird", "Apokalypsevogel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guardian Apostle", "Wächterapostel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heretic", "Ketzer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moleman Apostle", "Maulwurfsmann-Apostel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scythe Apostle", "Sensenapostel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spear Apostle", "Speerapostel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Staff Apostle", "Stabapostel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Army in Black", "Armee in Schwarz", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Army in Pink", "Armee in Rosa", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A friendly pink soldier. It will protect you wherever you go.", "Ein freundlicher rosa Soldat. Er wird dich beschützen, wohin du auch gehst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Backward Clock", "Rückwärtsuhr", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A clock to rewind your wasted time. Will you pay the toll?", "Eine Uhr, um deine verschwendete Zeit zurückzudrehen. Wirst du den Preis zahlen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beauty and the Beast", "Die Schöne und das Biest", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A pitiable creature. Death would be a mercy for it.", "Eine bemitleidenswerte Kreatur. Der Tod wäre eine Gnade für sie.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Behaviour Adjustment", "Verhaltensanpassung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A device made to 'fix' errant beasts. Its idea of 'fixing' might not be yours, however.", "Ein Gerät, das fehlgeleitete Bestien „korrigieren“ soll. Seine Vorstellung von „Korrektur“ entspricht allerdings vielleicht nicht deiner.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big Bird", "Großer Vogel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its eyes light up the darkness like stars.", "Seine Augen erhellen die Dunkelheit wie Sterne.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Binah", "Binah", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though not as powerful as she once was, she will still make a great ally.", "Obwohl sie nicht mehr so mächtig ist wie einst, ist sie immer noch eine großartige Verbündete.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloodbath", "Blutbad", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A tub of blood. The hands of people you once loved wait inside.", "Eine Wanne voller Blut. Die Hände der Menschen, die du einst liebtest, warten darin.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue Star", "Blauer Stern", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this is over, let's meet again as stars.", "Wenn das vorbei ist, treffen wir uns als Sterne wieder.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Burrowing Heaven", "Der grabende Himmel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't look away. Contain it in your sight.", "Sieh nicht weg. Behalte es im Blick.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crumpled Can of WellCheers", "Zerknitterte WellCheers-Dose", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rusted Can of WellCheers", "Verrostete WellCheers-Dose", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleton Shrimp", "Skelettgarnele", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Opened Can of WellCheers", "Geöffnete WellCheers-Dose", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A vending machine dispensing ocean soda.", "Ein Verkaufsautomat, der Meereslimonade ausgibt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CENSORED", "[ZENSIERT]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's best you never learn what it looks like.", "Am besten erfährst du nie, wie es aussieht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chesed", "Chesed", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing like a fresh cup of coffee to start your day.", "Nichts geht über eine frische Tasse Kaffee zum Start in den Tag.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Child of the Galaxy", "Kind der Galaxie", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A small child longing for an eternal friend. Will you be his?", "Ein kleines Kind, das sich nach einem ewigen Freund sehnt. Wirst du sein Freund sein?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crumbling Armour", "Bröckelnde Rüstung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A suit of armour that rewards the brave and punishes the cowardly.", "Eine Rüstung, die Tapfere belohnt und Feiglinge bestraft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Il Pianto della Luna", "Il Pianto della Luna", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In reality, man despairs at [c:bR]the moon[c:].", "In Wirklichkeit verzweifelt der Mensch am [c:bR]Mond[c:].", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Der Freischütz", "Der Freischütz", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A friendly hunter to some, a cruel gunsman to others. His bullets always hit their mark.", "Für manche ein freundlicher Jäger, für andere ein grausamer Schütze. Seine Kugeln treffen immer ihr Ziel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't Touch Me", "Fass mich nicht an", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't touch it.", "Fass es nicht an.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dimensional Refraction Variant", "Variante der Dimensionsbrechung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "4th Dimensional Refraction Variant", "Variante der 4. Dimensionsbrechung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A strange phenomenon. Or rather, the creature is the phenomena in and of itself.", "Ein seltsames Phänomen. Oder vielmehr ist die Kreatur selbst das Phänomen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Dreaming Current", "Die träumende Strömung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A sickly child. Everyday it was fed candy that let it see the ocean.", "Ein kränkliches Kind. Jeden Tag bekam es Süßigkeiten, mit denen es den Ozean sehen konnte.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Elder Dreaming Current", "Die Ältestenform der träumenden Strömung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dream of a Black Swan", "Traum eines schwarzen Schwans", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sister of six brothers. Tirelessly she worked to protect them, all for naught.", "Die Schwester von sechs Brüdern. Unermüdlich arbeitete sie daran, sie zu beschützen, doch alles war vergebens.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Express Train to Hell", "Schnellzug zur Hölle", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When the time comes, the train will sound its mighty horn.", "Wenn die Zeit kommt, lässt der Zug sein mächtiges Horn ertönen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fairy Festival", "Feenfestival", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everything will be peaceful while you're under the fairies' care.", "Alles wird friedlich sein, solange die Feen dich versorgen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flesh Idol", "Fleischidol", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prayer inevitably ends with the worshipper's despair.", "Das Gebet endet unweigerlich mit der Verzweiflung des Anbeters.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Forsaken Murderer", "Verlassener Mörder", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Experimented on then forgotten. What was anger has become abhorrence.", "Für Experimente benutzt und dann vergessen. Aus Wut wurde Abscheu.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fragment of the Universe", "Fragment des Universums", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You see a song in front of you. It's approaching, becoming more colourful by the second.", "Du siehst ein Lied vor dir. Es kommt näher und wird mit jeder Sekunde bunter.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Funeral of the Dead Butterflies", "Begräbnis der toten Schmetterlinge", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The coffin is a tribute to the fallen. A memorial to those who can't return home.", "Der Sarg ist eine Ehrung der Gefallenen. Ein Denkmal für jene, die nicht heimkehren können.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gebura", "Gebura", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Head of the Disciplinary Team. A fierce warrior and ally.", "Leiterin des Disziplinarteams. Eine wilde Kriegerin und Verbündete.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant Tree Sap", "Riesenbaumsaft", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sap from a tree at the end of the world. It is a potent healing agent.", "Saft von einem Baum am Ende der Welt. Ein starkes Heilmittel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "2nd Funeral of the Dead Butterflies", "2. Begräbnis der toten Schmetterlinge", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grave of Cherry Blossoms", "Grab der Kirschblüten", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A blooming cherry tree. The more blood it has, the more beautiful it becomes.", "Ein blühender Kirschbaum. Je mehr Blut er hat, desto schöner wird er.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Happy Teddy Bear", "Glücklicher Teddybär", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A discarded stuffed bear. Its memories began with a warm hug.", "Ein weggeworfener Teddybär. Seine Erinnerungen begannen mit einer warmen Umarmung.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Heart of Aspiration", "Das Herz des Strebens", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A heart without an owner. It emboldens those nearby.", "Ein Herz ohne Besitzer. Es ermutigt jene in seiner Nähe.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hod", "Hod", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though death is guaranteed, it never hurts to be prepared, right?", "Auch wenn der Tod sicher ist, schadet es nie, vorbereitet zu sein, oder?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hokma", "Hokma", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All things will happen in time. Just have faith.", "Alles wird zu seiner Zeit geschehen. Hab nur Vertrauen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Honoured Monk", "Ehrwürdiger Mönch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A monk seeking enlightenment through good deeds. But surely there's a quicker way to nirvana...", "Ein Mönch, der durch gute Taten Erleuchtung sucht. Doch es gibt sicher einen kürzeren Weg zum Nirwana ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One Sin and Hundreds of Good Deeds", "Eine Sünde und Hunderte guter Taten", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Jester of Nihil", "Der Narr des Nichts", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Judgement Bird", "Urteilsvogel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A long bird that judges sinners with swift efficiency. It alone is above consequences.", "Ein langer Vogel, der Sünder schnell und effizient richtet. Er allein steht über den Konsequenzen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Laetitia", "Laetitia", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A little witch carrying a heart-shaped gift.", "Eine kleine Hexe mit einem herzförmigen Geschenk.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Luminous Bracelet", "Leuchtendes Armband", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A bracelet that will heal its bearer. It does not forgive the greedy.", "Ein Armband, das seinen Träger heilt. Es verzeiht den Gierigen nicht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Servant of Wrath", "Die Dienerin des Zorns", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blind protector of another world.", "Blinde Beschützerin einer anderen Welt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The King of Greed", "Der König der Gier", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A girl encased in hardened amber. Happiness trapped by greed.", "Ein Mädchen, eingeschlossen in gehärtetem Bernstein. Glück, gefangen in der Gier.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Queen of Hatred", "Die Königin des Hasses", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magical Girl", "Magisches Mädchen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A hero of love and justice. She will aid you on your journey.", "Eine Heldin der Liebe und Gerechtigkeit. Sie wird dir auf deiner Reise helfen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Knight of Despair", "Die Ritterin der Verzweiflung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A loyal knight fighting to protect those close to her.", "Eine treue Ritterin, die kämpft, um jene zu beschützen, die ihr nahestehen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Malkuth", "Malkuth", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The head of the Control Team, here to assist you any way she can.", "Die Leiterin des Kontrollteams, bereit, dir nach Kräften zu helfen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Meat Lantern", "Fleischlaterne", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A beautiful flower attached to a mysterious creature.", "Eine schöne Blume, die an einer geheimnisvollen Kreatur befestigt ist.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Melting Love", "Schmelzende Liebe", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't let your beasts get too close now.", "Lass deine Bestien jetzt nicht zu nahe kommen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "1.76 MHz", "1.76 MHz", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is a record, a record of a day we must never forget.", "Dies ist eine Aufzeichnung, eine Aufzeichnung eines Tages, den wir nie vergessen dürfen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Mirror of Adjustment", "Der Spiegel der Anpassung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mirror that reflects nothing on its surface.", "Ein Spiegel, dessen Oberfläche nichts widerspiegelt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Mountain of Smiling Bodies", "Der Berg der lächelnden Körper", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mass grave, melted and congealed into one eternally hungry beast.", "Ein Massengrab, geschmolzen und zu einer einzigen, ewig hungrigen Bestie erstarrt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nameless Fetus", "Namenloser Fötus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A neverending supply of blood. Just don't wake it up.", "Ein unerschöpflicher Blutvorrat. Weck es nur nicht auf.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Netzach", "Netzach", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Despite his lack of motivation, he'll do his best to succeed.", "Trotz seiner fehlenden Motivation wird er sein Bestes geben, um Erfolg zu haben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nosferatu", "Nosferatu", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A creature of the night, noble and regal. Will you help sate its thirst?", "Eine Kreatur der Nacht, edel und königlich. Wirst du helfen, ihren Durst zu stillen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Notes from a Crazed Researcher", "Notizen eines wahnsinnigen Forschers", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An insane garble of guilty confessions and incoherent gibberish.", "Ein wahnsinniges Durcheinander aus Schuldbekenntnissen und zusammenhanglosem Kauderwelsch.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing There", "Nichts da", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An Egg", "Ein Ei", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yumi", "Yumi", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't remember this challenger...", "Ich erinnere mich nicht an diesen Herausforderer ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Old Faith and Promise", "Alter Glaube und altes Versprechen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mysterious marble. Use it without desire or expectation and you may be rewarded.", "Eine geheimnisvolle Murmel. Benutze sie ohne Wunsch oder Erwartung, und vielleicht wirst du belohnt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Old Lady", "Alte Dame", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An aged storyteller. She can tell you any tale, even those that can't exist.", "Eine alte Geschichtenerzählerin. Sie kann dir jede Geschichte erzählen, selbst solche, die nicht existieren können.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A floating skull. Its hollow sockets see through you.", "Ein schwebender Schädel. Seine leeren Augenhöhlen durchschauen dich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ozma", "Ozma", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The former ruler of a far away land, now reduced to this.", "Die ehemalige Herrscherin eines fernen Landes, nun darauf reduziert.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasite Tree", "Parasitenbaum", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A beautiful tree. It wants only to help you and your beasts.", "Ein wunderschöner Baum. Er will nur dir und deinen Bestien helfen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pinocchio", "Pinocchio", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A wooden doll that mimics the beasts it encounters. Can you see through its lie?", "Eine Holzpuppe, die den Bestien nacheifert, denen sie begegnet. Kannst du ihre Lüge durchschauen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plague Doctor", "Pestarzt", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A worker of miracles. He humbly requests to join you.", "Ein Wundertäter. Er bittet bescheiden darum, sich dir anzuschließen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Porccubus", "Porccubus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A prick from one of its quills creates a deadly euphoria.", "Der Stich eines seiner Stacheln erzeugt eine tödliche Euphorie.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ppodae", "Ppodae", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An innocent little puppy.", "Ein unschuldiger kleiner Welpe.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Price of Silence", "Preis der Stille", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The unflinching hand of time cuts down man and beast alike.", "Die unnachgiebige Hand der Zeit streckt Menschen und Bestien gleichermaßen nieder.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Punishing Bird", "Strafvogel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A small bird on a mission to punish evildoers.", "Ein kleiner Vogel, der ausgesandt wurde, um Übeltäter zu bestrafen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Queen Bee", "Bienenkönigin", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A monstrous amalgam of a hive and a bee.", "Eine monströse Verschmelzung aus Bienenstock und Biene.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Little Red Riding Hooded Mercenary", "Rotkäppchen-Söldnerin", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A skilled mercenary with a bloody vendetta. Perhaps you can help her sate it.", "Eine geschickte Söldnerin mit einer blutigen Fehde. Vielleicht kannst du ihr helfen, sie zu stillen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Red Shoes", "Rote Schuhe", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How pretty. Maybe they'll fit.", "Wie hübsch. Vielleicht passen sie ja.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rudolta of the Sleigh", "Rudolta vom Schlitten", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A grotesque effigy of a reindeer. With its infinite hate, it bequeaths gifts onto you.", "Ein groteskes Abbild eines Rentiers. Mit seinem endlosen Hass überreicht es dir Geschenke.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scaredy Cat", "Ängstliche Katze", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Schadenfreude", "Schadenfreude", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A strange machine. You can feel someone's persistent gaze through the keyhole.", "Eine seltsame Maschine. Durch das Schlüsselloch spürst du den anhaltenden Blick von jemandem.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scorched Girl", "Verkohltes Mädchen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though there's nothing left to burn, the fire won't go out.", "Obwohl nichts mehr zu verbrennen bleibt, geht das Feuer nicht aus.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shelter From the 27th of March", "Zuflucht vom 27. März", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It makes itself the safest place in the world by altering the reality around it.", "Indem es die Realität um sich herum verändert, macht es sich zum sichersten Ort der Welt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Silent Girl", "Stilles Mädchen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A girl hiding a hammer and nail behind her back.", "Ein Mädchen, das einen Hammer und einen Nagel hinter dem Rücken versteckt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chairs", "Stühle", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Silent Orchestra", "Das stille Orchester", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soon, the song none can hear but all can listen to will begin.", "Bald beginnt das Lied, das niemand hören kann, dem aber alle lauschen können.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Singing Machine", "Singende Maschine", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A wind-up music machine. The song it plays is to die for.", "Eine aufziehbare Musikmaschine. Ihr Lied ist zum Sterben schön.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skin Prophecy", "Hautprophezeiung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A holy book. Its believers wrapped it in skin to preserve its sanctity.", "Ein heiliges Buch. Seine Gläubigen hüllten es in Haut, um seine Heiligkeit zu bewahren.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Snow Queen", "Die Schneekönigin", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A queen from far away. Those who enter her palace never leave.", "Eine Königin aus der Ferne. Wer ihren Palast betritt, verlässt ihn nie wieder.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snow White's Apple", "Schneewittchens Apfel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A poisoned apple brought to life, on a fruitless search for its own happily ever after.", "Ein vergifteter Apfel, der zum Leben erwacht ist und vergeblich nach seinem eigenen glücklichen Ende sucht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snow White's Rotted Apple", "Schneewittchens verfaulter Apfel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spider Bud", "Spinnenknospe", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A grotesque mother of spiders. Its children are small but grow quickly.", "Eine groteske Spinnenmutter. Ihre Jungen sind klein, wachsen aber schnell.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Firebird", "Der Feuervogel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A bird that longs for the thrill of being hunted.", "Ein Vogel, der sich nach dem Nervenkitzel sehnt, gejagt zu werden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Little Prince", "Der kleine Prinz", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A giant mushroom chunk. A mist of spores surrounds it.", "Ein riesiges Stück Pilz. Ein Sporennebel umgibt es.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Naked Nest", "Das nackte Nest", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They can enter your body through any aperture.", "Sie können durch jede Öffnung in deinen Körper gelangen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Naked Worm", "Nackter Wurm", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It can enter your body through any aperture.", "Es kann durch jede Öffnung in deinen Körper gelangen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Theresia", "Theresia", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An old music box. It plays a familiar melody.", "Eine alte Spieluhr. Sie spielt eine vertraute Melodie.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Road Home", "Der Weg nach Hause", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A young girl on a quest to return home with her friends.", "Ein junges Mädchen, das sich mit seinen Freunden auf den Heimweg macht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tiphereth", "Tiphereth", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One of a pair of twins. Don't underestimate her capabilities.", "Eine von zwei Zwillingen. Unterschätze ihre Fähigkeiten nicht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Today's Shy Look", "Heutiger schüchterner Blick", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An indecisive creature. Her expression is different whenever you draw her.", "Eine unentschlossene Kreatur. Ihr Gesichtsausdruck ändert sich jedes Mal, wenn du ihre Karte ziehst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tomorrow's Shy Look", "Morgiger schüchterner Blick", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Today's Happy Look", "Heutiger glücklicher Blick", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tomorrow's Happy Look", "Morgiger glücklicher Blick", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tomorrow's Angry Look", "Morgiger wütender Blick", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Today's Angry Look", "Heutiger wütender Blick", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Standard Training-Dummy Rabbit", "Standard-Trainingspuppenkaninchen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A beast in the shape of a training dummy. The safest of these abnormal creatures.", "Eine Bestie in Form einer Trainingspuppe. Die harmloseste dieser abnormalen Kreaturen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Single Recall", "Einmaliger Rückruf", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Total Recall", "Vollständiger Rückruf", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reshuffle Decks", "Stapel neu mischen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Void Dream", "Traum der Leere", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A sleeping goat. Or is it a sheep?", "Eine schlafende Ziege. Oder ist es ein Schaf?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Lady Facing the Wall", "Die Frau vor der Wand", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A deep sorrow, grown to obsession. Perhaps it's best to leave her be.", "Ein tiefer Kummer, der zur Besessenheit wurde. Vielleicht lässt man sie besser in Ruhe.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Elder Lady Facing the Wall", "Ältestenform: Die Frau vor der Wand", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warm-Hearted Woodsman", "Warmherziger Holzfäller", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A tin woodsman on the search for a heart. Perhaps you can give him yours.", "Ein Holzfäller aus Blech auf der Suche nach einem Herzen. Vielleicht kannst du ihm deines geben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We Can Change Anything", "Wir können alles verändern", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whatever you're dissatisfied with, this machine will fix it. You just have to step inside.", "Was immer dich unzufrieden macht, diese Maschine behebt es. Du musst nur hineingehen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WhiteNight", "Weiße Nacht", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The time has come.", "Die Zeit ist gekommen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big and Will Be Bad Wolf", "Großer und bald böser Wolf", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's the fate of all wolves to be the villains of fairy tales.", "Das Schicksal aller Wölfe ist es, die Bösewichte der Märchen zu sein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scarecrow Searching for Wisdom", "Weisheit suchende Vogelscheuche", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A hollow-headed scarecrow. Blood soaks its straw limbs.", "Eine Vogelscheuche mit hohlem Kopf. Blut tränkt ihre Strohglieder.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Portrait of Another World", "Porträt einer anderen Welt", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This portrait captures a moment, one we're destined to lose.", "Dieses Porträt hält einen Moment fest, den wir verlieren werden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yang", "Yang", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A white pendant that heals those nearby.", "Ein weißer Anhänger, der diejenigen in seiner Nähe heilt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yesod", "Yesod", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The head of the Information Department. Incompetence will not be tolerated.", "Der Leiter der Informationsabteilung. Inkompetenz wird nicht geduldet.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yin", "Yin", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A black pendant in search of its missing half.", "Ein schwarzer Anhänger auf der Suche nach seiner verlorenen Hälfte.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You Must Be Happy", "Du musst glücklich sein", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Those that undergo the procedure find themselves rested and healthy again.", "Wer sich dem Verfahren unterzieht, ist danach ausgeruht und wieder gesund.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're Bald...", "Du bist kahl ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've always wondered what it's like to be bald.", "Ich habe mich immer gefragt, wie es ist, kahl zu sein.", Language.German);


            //talkingcards
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The human heart is black, and must be cleaned.", "Das menschliche Herz ist schwarz und muss gereinigt werden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A hand rises from the scarlet pool.", "Eine Hand erhebt sich aus dem scharlachroten Becken.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Another pale hand emerges.", "Eine weitere blasse Hand taucht auf.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A third hand reaches out, as if asking for help.", "Eine dritte Hand streckt sich hervor, als bitte sie um Hilfe.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What have you done to my beast?", "Was hast du meiner Bestie angetan?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At long last, she has found him.", "Endlich hat sie ihn gefunden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That familiar red cloth...", "Dieser vertraute rote Stoff ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Desire unfulfilled, the koi continues for Eden.", "Mit unerfülltem Wunsch zieht der Koi weiter nach Eden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Having failed to protect again, the knight fell once more to despair.", "Nachdem sie erneut beim Beschützen versagt hatte, fiel die Ritterin wieder in Verzweiflung.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The balance must be maintained. Good cannot exist without evil.", "Das Gleichgewicht muss gewahrt bleiben. Ohne Böses kann es kein Gutes geben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They give themselves lovingly.", "Sie geben sich liebevoll hin.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With each body added, its appetite grows.", "Mit jedem hinzugefügten Körper wächst sein Appetit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't worry, bodies are in no short supply.", "Keine Sorge, an Körpern mangelt es nicht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As you cut into the beast's flesh, it lets out a piercing cry.", "Als du in das Fleisch der Bestie schneidest, stößt sie einen schrillen Schrei aus.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What is that thing?", "Was ist das für ein Ding?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems to be trying to mimic you. 'Trying' is the key word.", "Es scheint zu versuchen, dich nachzuahmen. „Versuchen“ ist das entscheidende Wort.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What is it doing?", "Was macht es?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The hands of the Clock move towards salvation.", "Die Zeiger der Uhr bewegen sich auf die Erlösung zu.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A formidable attack. Shame it has left her too tired to defend herself.", "Ein beeindruckender Angriff. Schade, dass sie nun zu erschöpft ist, um sich zu verteidigen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The monster returns to full strength.", "Das Monster erlangt seine volle Stärke zurück.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Abandoned and betrayed, she rages against her own failure.", "Verlassen und verraten, wütet sie über ihr eigenes Versagen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Some days you don't feel like smiling.", "An manchen Tagen ist einem nicht nach Lächeln zumute.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There was no place for frowns in the City.", "Für finstere Mienen war in der Stadt kein Platz.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unable to decide what face to wear, she became shy again.", "Da sie nicht entscheiden konnte, welches Gesicht sie zeigen sollte, wurde sie wieder schüchtern.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now you become the sky, and I the land.", "Jetzt wirst du zum Himmel und ich zum Land.", Language.German);

            //Angela_talk
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A decrepit old man.", "Ein gebrechlicher alter Mann.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I believe that pack animal", "Ich glaube, dieses Lasttier", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "will aid us with its death.", "wird uns durch seinen Tod helfen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you wonder if he ever bathes?", "Fragst du dich, ob er jemals badet?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You should know what to do by now.", "Du solltest inzwischen wissen, was zu tun ist.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He appears to have a simple mind.", "Er scheint einfach gestrickt zu sein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We can easily manipulate him.", "Wir können ihn leicht manipulieren.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fish are a lot like people, aren't they?", "Fische sind Menschen ziemlich ähnlich, findest du nicht?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I recommend holding your breath.", "Ich empfehle, die Luft anzuhalten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everyone has a different side to them.", "Jeder hat verschiedene Seiten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't you think, manager?", "Findest du nicht, Manager?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't die manager.", "Stirb nicht, Manager.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Watch out for traps.", "Achte auf Fallen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Does the cold bother you?", "Stört dich die Kälte?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We appear to have reached the end.", "Wir scheinen das Ende erreicht zu haben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I expect you to conquer this challenge", "Ich erwarte, dass du diese Herausforderung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "quite easily, manager.", "ganz leicht meisterst, Manager.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A final trial for you, manager.", "Eine letzte Prüfung für dich, Manager.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It has been quite the journey, yes?", "Was für eine Reise, nicht wahr?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...do not expect a comment from me.", "... erwarte keinen Kommentar von mir.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do not be deceived.", "Lass dich nicht täuschen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He is not an abnormality.", "Er ist keine Abnormalität.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An unloyal crew...", "Eine untreue Mannschaft ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He reminds me of you", "Er erinnert mich an dich", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "in a way.", "auf eine gewisse Weise.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This threat may be beyond you.", "Diese Bedrohung könnte deine Kräfte übersteigen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We kept them separated for", "Wir haben sie getrennt gehalten", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this reason, manager.", "aus diesem Grund, Manager.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hello manager.", "Hallo, Manager.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shall we get going?", "Sollen wir loslegen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am here to assist you.", "Ich bin hier, um dir zu helfen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gotten yourself in trouble?", "Hast du Ärger bekommen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can rely on me.", "Du kannst dich auf mich verlassen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thank you.", "Danke.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Try not to make a mess.", "Versuch, kein Chaos anzurichten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's hurry this up, yes?", "Beeilen wir uns, ja?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing I can't overcome.", "Nichts, was ich nicht überwinden könnte.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I see.", "Ich verstehe.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reminds me of the facility.", "Erinnert mich an die Anlage.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No point in hesitating.", "Zögern bringt nichts.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrifices must be made.", "Opfer müssen gebracht werden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing you should be uncomfortable with.", "Nichts, was dir unangenehm sein sollte.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A golden opportunity.", "Eine goldene Gelegenheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I expect you to know the best choice.", "Ich erwarte, dass du die beste Wahl triffst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I leave it to your discretion.", "Ich überlasse es deinem Ermessen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We must all overcome ordeals in life.", "Wir alle müssen im Leben Prüfungen überwinden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You taught me that.", "Das hast du mich gelehrt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You wouldn't fail so easily, right?", "Du würdest nicht so leicht scheitern, oder?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No point in dilly-dallying now.", "Es hat keinen Sinn, noch länger zu trödeln.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yet another obstacle in my way...", "Wieder ein Hindernis auf meinem Weg ...", Language.German);

            //ApocalypseBird_talk
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let me tell you a story. The story of the [c:bR]Black Forest[c:].", "Lass mich dir eine Geschichte erzählen. Die Geschichte des [c:bR]Schwarzwalds[c:].", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The three birds, [c:bR]now one[c:] looked around for [c:bR]the Beast[c:]. But there was nothing.", "Die drei Vögel, [c:bR]nun eins[c:], sahen sich nach [c:bR]der Bestie[c:] um. Doch da war nichts.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No creatures. No beast. No sun or moon or stars. Only a single bird, alone in an empty forest.", "Keine Kreaturen. Keine Bestie. Keine Sonne, kein Mond und keine Sterne. Nur ein einzelner Vogel, allein in einem leeren Wald.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once upon a time, [c:bR]three birds[c:] lived happily in the lush Forest with their fellow animals.", "Es waren einmal [c:bR]drei Vögel[c:], die glücklich mit den anderen Tieren im üppigen Wald lebten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One day a stranger arrived at the Forest. He proclaimed that the Forest would soon be ensared in a bitter conflict.", "Eines Tages kam ein Fremder in den Wald. Er verkündete, dass der Wald bald in einen erbitterten Konflikt geraten würde.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One that would only end when everything was devoured by a [c:bR]terrible Beast[c:].", "Einen Konflikt, der erst enden würde, wenn alles von einer [c:bR]schrecklichen Bestie[c:] verschlungen wäre.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The birds, frightened by this doomsay, sought to prevent conflict from ever breaking out.", "Von dieser düsteren Prophezeiung erschrocken, wollten die Vögel jeden Konflikt verhindern.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fights began to break out. More and more creatures left the Forest, no matter how hard the birds worked.", "Kämpfe brachen aus. Immer mehr Kreaturen verließen den Wald, so sehr sich die Vögel auch bemühten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They decided to combine their powers. This way, they could better protect their home.", "Sie beschlossen, ihre Kräfte zu vereinen. So konnten sie ihre Heimat besser beschützen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This way they could better return the peace.", "So konnten sie den Frieden besser wiederherstellen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Darkness fell upon the forest. Mayhem ran amok as creatures screamed in terror at the towering bird.", "Dunkelheit fiel über den Wald. Chaos brach aus, als die Kreaturen beim Anblick des riesigen Vogels vor Angst schrien.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Someone yelled out [c:bB]'It's the Beast! A big, scary monster lives in the Black Forest!'[c:]", "Jemand rief: [c:bB]„Es ist die Bestie! Ein großes, furchterregendes Monster lebt im Schwarzwald!“[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bG]Big Bird[c:] with his many eyes kept constant watch over the entire Forest.", "[c:bG]Großer Vogel[c:] hielt mit seinen vielen Augen ständig den ganzen Wald im Blick.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bSG]Long Bird[c:] weighed the sins of all creatures in the forest with his scales.", "[c:bSG]Langer Vogel[c:] wog mit seiner Waage die Sünden aller Kreaturen im Wald.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Small Bird[c:] punished wrongdoers with his beak.", "[c:bR]Kleiner Vogel[c:] bestrafte Übeltäter mit seinem Schnabel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You walk down into a large clearing, the black trees crowding around you.", "Du steigst in eine große Lichtung hinab, während sich schwarze Bäume um dich drängen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An otherworldly roar brings you to attention. The very earth quails in fear as something approaches you.", "Ein außerweltliches Brüllen lässt dich aufhorchen. Die Erde selbst erzittert vor Angst, während sich etwas nähert.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lumbering yet impossibly fast, you find yourself face-to-face with...", "Trotz seiner schwerfälligen Bewegungen ist es unfassbar schnell, und du stehst plötzlich Auge in Auge mit ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An otherworldly roar shakes you to your core. The forest floor quakes as something approaches you.", "Ein außerweltliches Brüllen erschüttert dich bis ins Mark. Der Waldboden bebt, während sich etwas nähert.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]The Beast[c:].", "[c:bR]Die Bestie[c:].", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The far-sighted eyes have been blinded.", "Die weitsichtigen Augen wurden geblendet.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The head that looked to the cosmos has been lowered.", "Der Kopf, der zum Kosmos blickte, hat sich gesenkt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mouth that devours everything has been shut.", "Der Mund, der alles verschlingt, hat sich geschlossen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]The monster[c:] is not so easily tamed.", "[c:bR]Das Monster[c:] lässt sich nicht so leicht zähmen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your efforts prove futile.", "Deine Bemühungen erweisen sich als vergeblich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Beast is [c:bR]immune to mortal damage[c:].", "Die Bestie ist [c:bR]gegen tödlichen Schaden immun[c:].", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yet even it has its weaknesses.", "Doch selbst sie hat ihre Schwächen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gather your courage, and march onward.", "Fass Mut und marschiere weiter.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bSG]Into the twilight.[c:]", "[c:bSG]In die Dämmerung.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mouth that devours everything opens.", "Der Mund, der alles verschlingt, öffnet sich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Small Bird's beak whispered endlessly.", "Der Schnabel des Kleinen Vogels flüsterte unaufhörlich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The beast's maw snaps shut on empty air.", "Das Maul der Bestie schnappt nach leerer Luft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Big Bird's eyes imprisoned light...", "Die Augen des Großen Vogels hielten das Licht gefangen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...and they burned like stars.", "... und sie brannten wie Sterne.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...but there was nothing to behold.", "... doch es gab nichts zu betrachten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Long Bird's arms concealed time...", "Die Arme des Langen Vogels verbargen die Zeit ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...yet sins continued day after day.", "... doch die Sünden gingen Tag für Tag weiter.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Beast senses your hunger, and grows more daring.", "Die Bestie spürt deinen Hunger und wird kühner.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Beast begins to grow desperate.", "Die Bestie beginnt zu verzweifeln.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your power angers the Beast.", "Deine Kraft erzürnt die Bestie.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Beast grows more aggressive.", "Die Bestie wird aggressiver.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Beast's strength grows beyond imagination...", "Die Stärke der Bestie wächst über jede Vorstellung hinaus ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Beast's hide hardens under your creatures' claws.", "Die Haut der Bestie verhärtet sich unter den Klauen deiner Kreaturen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Beast and its ilk move quickly and frequently. Use these to reposition your creatures.", "Die Bestie und ihresgleichen bewegen sich schnell und häufig. Nutze diese Möglichkeiten, um deine Kreaturen neu zu positionieren.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Returned creatures will have their cost changed based on how recently you played them.", "Die Kosten zurückgenommener Kreaturen ändern sich je nachdem, wie lange ihr Ausspielen zurückliegt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Newly played creatures will cost [c:bR]2 Bones[c:] to play again.", "Kürzlich ausgespielte Kreaturen kosten beim erneuten Ausspielen [c:bR]2 Knochen[c:].", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I will reduce their recall cost over time, until they become [c:bR]free[c:] to replay.", "Ich werde ihre Rückrufkosten mit der Zeit senken, bis du sie [c:bR]kostenlos[c:] erneut ausspielen kannst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Use these to reposition your creatures, for a cost.", "Nutze diese Möglichkeiten, um deine Kreaturen gegen einen Preis neu zu positionieren.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why don't we continue a little longer?", "Warum machen wir nicht noch ein wenig weiter?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The beast is immune to mortal damage.", "Die Bestie ist gegen tödlichen Schaden immun.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Excess injury will instead yield you up to [c:bR]2[c:] bones.", "Überschüssiger Schaden bringt dir stattdessen bis zu [c:bR]2[c:] Knochen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't worry about running dry, the ground you walk on is full of them.", "Keine Sorge, dass sie ausgehen: Der Boden, auf dem du stehst, ist voll davon.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ground is full of bones.", "Der Boden ist voller Knochen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Backed into a corner, the Beast releases one final burst of strength.", "In die Enge getrieben, entfesselt die Bestie einen letzten Kraftschub.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When the Beast attacks a space marked in [c:bR]red[c:], it will deal twice the normal damage.", "Wenn die Bestie ein [c:bR]rot[c:] markiertes Feld angreift, verursacht sie den doppelten normalen Schaden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When the Beast attacks a space marked in [c:bSG]white[c:], it will deal half the normal damage, but regain vitality.", "Wenn die Bestie ein [c:bSG]weiß[c:] markiertes Feld angreift, verursacht sie die Hälfte des normalen Schadens, gewinnt aber Lebenskraft zurück.", Language.German);

            //BackwardClock
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Close your eyes and count to ten.", "Schließe die Augen und zähle bis zehn.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When you open them, you will be standing at the exact moment you wish to be in.", "Wenn du sie öffnest, wirst du genau in dem Moment stehen, den du dir wünschst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]One of your creatures[c:] must stay behind to operate [c:bR]the Clock[c:].", "[c:bR]Eine deiner Kreaturen[c:] muss zurückbleiben, um [c:bR]die Uhr[c:] zu bedienen.", Language.German);

            //Binah_talk
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deal with those beasts quickly.", "Kümmere dich schnell um diese Bestien.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A small obstacle.", "Ein kleines Hindernis.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let us begin.", "Fangen wir an.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't lose your appetite now.", "Verlier jetzt nicht den Appetit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I grow tired of fish.", "Ich habe langsam genug von Fisch.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You must enjoy the stench.", "Du musst diesen Gestank genießen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Another two-faced deceiver.", "Noch ein doppelzüngiger Betrüger.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No one helps you without a price.", "Niemand hilft dir ohne Gegenleistung.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Be wary of where your foot falls.", "Achte darauf, wohin du trittst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems we have reached the conclusion.", "Es scheint, wir sind am Ende angekommen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are we doing this again?", "Tun wir das schon wieder?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have fought stronger foes.", "Ich habe schon gegen stärkere Gegner gekämpft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What is this?", "Was ist das?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A captain of a sunken vessel.", "Der Kapitän eines gesunkenen Schiffes.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "His crew has no loyalty.", "Seine Mannschaft ist nicht loyal.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have wandered into a dangerous place.", "Du bist an einen gefährlichen Ort geraten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you think yourself immortal?", "Hältst du dich für unsterblich?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quite the marvelous beast, isn't it?", "Was für eine wunderbare Bestie, nicht wahr?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have entered its lair once more.", "Du bist erneut in ihren Unterschlupf gekommen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You must have a death wish.", "Du musst lebensmüde sein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I do enjoy this place.", "Ich mag diesen Ort wirklich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well look who it is.", "Na, wen haben wir denn da?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose.", "Wähle.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Be calm.", "Bleib ruhig.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Miss me?", "Hast du mich vermisst?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Countless stars light the sky today.", "Unzählige Sterne erhellen heute den Himmel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your outlook is what decides things.", "Deine Sichtweise entscheidet über den Ausgang.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am curious to see", "Ich bin gespannt,", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "what memories you yielded.", "welche Erinnerungen du preisgegeben hast.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Excellent.", "Ausgezeichnet.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have done well.", "Du hast gut gehandelt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This power is incomplete.", "Diese Kraft ist unvollständig.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "More bodies to clean.", "Noch mehr Körper zum Aufräumen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The closer to death, the freer you are.", "Je näher du dem Tod bist, desto freier bist du.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Did you think you could avoid it?", "Dachtest du, du könntest es vermeiden?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is nearing the end.", "Das Ende naht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your breath is fading.", "Dein Atem schwindet.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No one will blame you.", "Niemand wird dir die Schuld geben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inching closer to wholeness.", "Schritt für Schritt der Vollständigkeit näher.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you up to the task?", "Bist du der Aufgabe gewachsen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tis an ordeal to overcome.", "Das ist eine Prüfung, die es zu überwinden gilt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is no obstacle you can't overcome.", "Es gibt kein Hindernis, das du nicht überwinden kannst.", Language.German);

            //Chesed_talk
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So many animals~", "So viele Tiere~", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So much dust.", "So viel Staub.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do we have to fight?", "Müssen wir kämpfen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's an impressive hook there~.", "Was für ein beeindruckender Haken~", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you feeling hungry?", "Hast du Hunger?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm used to the stench of decay by now.", "Ich bin den Gestank der Verwesung inzwischen gewohnt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What an odd fellow.", "Was für ein seltsamer Kerl.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What tricks are up their sleeve?", "Welche Tricks haben sie im Ärmel?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing like a cup of coffee", "Nichts geht über eine Tasse Kaffee,", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "to keep you warm~", "um dich warm zu halten~", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We've come so far...", "Wir sind schon so weit gekommen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "just a little more now.", "nur noch ein kleines Stück.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you prepared manager?", "Bist du bereit, Manager?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We can't hesitate now.", "Wir dürfen jetzt nicht zögern.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A pirate? How fun~", "Ein Pirat? Wie amüsant~", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Watch your head now.", "Pass auf deinen Kopf auf.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one...", "Dieser hier ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope you're prepared.", "Ich hoffe, du bist bereit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I worry you have a death wish.", "Ich fürchte, du bist lebensmüde.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are we really doing this?", "Tun wir das wirklich?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hey~ manager.", "Hey~ Manager.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Off on a nice stroll?", "Auf zu einem schönen Spaziergang?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Who will it be this time~?", "Wer wird es diesmal sein~?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm sure we can do this well.", "Ich bin sicher, dass wir das gut schaffen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's try our best, yeah?", "Geben wir unser Bestes, ja?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't overwork yourself~", "Überarbeite dich nicht~", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hey, thanks~", "Hey, danke~", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That was smooth~", "Das lief glatt~", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guess I gotta work harder", "Ich muss wohl härter arbeiten", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "in their stead, huh?", "an ihrer Stelle, was?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How about a nice cup of coffee?", "Wie wäre es mit einer schönen Tasse Kaffee?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah!", "Ah!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm.", "Hm.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tch.", "Tss.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't want anyone to die here.", "Ich möchte nicht, dass hier jemand stirbt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If there's a meaning to this fight...", "Wenn dieser Kampf einen Sinn hat ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No choice but to stand our ground.", "Uns bleibt nichts anderes übrig, als standzuhalten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All this effort wasted on fighting.", "All diese Mühe, die im Kampf verschwendet wird.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I guess this is as far as I can go...", "Ich schätze, weiter komme ich nicht ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah...", "Ah ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heh...", "Heh ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "See you in Hell.", "Wir sehen uns in der Hölle.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm...", "Hmm ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This again?", "Schon wieder?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We can lose everything", "Wir können alles verlieren,", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "if we hesitate.", "wenn wir zögern.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'd hate for us to suffer even more.", "Ich möchte nicht, dass wir noch mehr leiden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This looks promising~", "Das sieht vielversprechend aus~", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, this again~", "Oh, schon wieder~", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I wouldn't mind a nice of cup of coffee now.", "Eine schöne Tasse Kaffee könnte ich jetzt gut gebrauchen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Who will it be~?", "Wer wird es sein~?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sometimes, you have to get bold", "Manchmal muss man mutig sein,", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "in order to protect something.", "um etwas zu beschützen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing we haven't seen before.", "Nichts, was wir nicht schon gesehen hätten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm sure this will go well.", "Ich bin sicher, dass das gut läuft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's do our best and finish the job~", "Geben wir unser Bestes und bringen die Arbeit zu Ende~", Language.German);

            //Gebura_talk
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Who's this geezer?", "Wer ist dieser alte Kerl?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This guy...", "Dieser Kerl ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What a pain.", "Was für eine Plage.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's make quick work of him.", "Machen wir kurzen Prozess mit ihm.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This stench takes me back.", "Dieser Gestank weckt Erinnerungen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Watch that hook there.", "Pass auf diesen Haken auf.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Keep on your toes now.", "Bleib wachsam.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "These traps are annoying.", "Diese Fallen sind nervig.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clear a path and strike cleanly.", "Räume den Weg frei und schlage sauber zu.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing left but to continue forward.", "Es bleibt nichts anderes, als weiterzugehen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We've got this.", "Wir schaffen das.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One more enemy left.", "Nur noch ein Gegner übrig.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not the strangest thing I've seen.", "Nicht das Seltsamste, was ich gesehen habe.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Be quick and avoid those cannons.", "Sei schnell und weich den Kanonen aus.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "His goons are tougher than they look.", "Seine Schergen sind härter, als sie aussehen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why have you come here?", "Warum bist du hierhergekommen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You trying to die?", "Willst du sterben?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let me handle this.", "Lass mich das übernehmen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "These stupid birds...", "Diese dummen Vögel ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't chicken out now.", "Kneif jetzt nicht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Manager.", "Manager.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hey manager.", "Hey, Manager.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not as strong as I used to be.", "Ich bin nicht mehr so stark wie früher.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Still not used to it.", "Ich bin es immer noch nicht gewohnt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't let your strength get to your head.", "Lass dir deine Stärke nicht zu Kopf steigen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Always keep a cool head.", "Bewahre immer einen kühlen Kopf.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm starting to get accustomed", "Ich beginne mich", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "to this new body.", "an diesen neuen Körper zu gewöhnen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I won't waste this strength.", "Ich werde diese Kraft nicht verschwenden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thanks.", "Danke.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kch.", "Tsch.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bastard.", "Mistkerl.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That all?", "War's das?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I wasn't so feeble before...", "Früher war ich nicht so schwach ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's beat these guys into submission.", "Prügeln wir diese Kerle zur Unterwerfung.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's do this.", "Los geht's.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We mustn't falter just yet.", "Wir dürfen jetzt noch nicht nachgeben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We'll talk after everything's over.", "Wir reden, wenn alles vorbei ist.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't let it be in vain, yeah?", "Lass es nicht umsonst gewesen sein, ja?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't like this...", "Das gefällt mir nicht ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wayward wrath will only ruin yourself.", "Ungezügelter Zorn wird nur dich selbst ruinieren.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You know this isn't just a silly game, right?", "Du weißt, dass das nicht nur ein albernes Spiel ist, oder?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mind where you point your blade.", "Achte darauf, wohin du deine Klinge richtest.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not a chance.", "Keine Chance.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This looks like a good opportunity.", "Das sieht nach einer guten Gelegenheit aus.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guess I'll cop a nap.", "Ich werde wohl ein Nickerchen machen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Another opportunity, huh?", "Noch eine Gelegenheit, was?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't take it for granted.", "Nimm es nicht als selbstverständlich hin.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A test of some sort?", "Eine Art Prüfung?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let me have a go.", "Lass mich mal.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's work together", "Arbeiten wir zusammen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "and give it our best shot.", "und geben unser Bestes.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I defer to your judgement.", "Ich vertraue auf dein Urteil.", Language.German);

            //Hod_talk
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Watch out for that pickaxe.", "Pass auf die Spitzhacke auf.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We've prepared for this.", "Wir haben uns darauf vorbereitet.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll follow your lead.", "Ich folge deiner Führung.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Urk, the smell...", "Igitt, dieser Geruch ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's get out of here quickly...", "Lass uns schnell hier weg ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't knock over those buckets.", "Stoß diese Eimer nicht um.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A betrayal...", "Ein Verrat ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll trust you, manager.", "Ich vertraue dir, Manager.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So many pelts...", "So viele Felle ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The moon's so large...", "Der Mond ist so groß ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We can do this.", "Wir schaffen das.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We're a lot stronger than before.", "Wir sind viel stärker als früher.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A pirate...skeleton?", "Ein Piraten...skelett?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Those cannons hurt a lot...", "Diese Kanonen tun richtig weh ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That monster...", "Dieses Monster ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What do we do?", "Was tun wir?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Keep calm...keep calm...", "Ruhig bleiben ... ruhig bleiben ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remember our training.", "Denk an unser Training.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh! Um...", "Oh! Ähm ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hello manager.", "Hallo, Manager.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I won't be a hindrance!", "Ich werde nicht zur Last fallen!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Who do you choose?", "Wen wählst du?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm not that skilled...", "Ich bin nicht so geschickt ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "but I'll do my best!", "aber ich gebe mein Bestes!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll try not to be a hindrance.", "Ich versuche, nicht zur Last zu fallen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If we prepare, we can overcome this.", "Wenn wir uns vorbereiten, können wir das überwinden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm here to do my best.", "Ich bin hier, um mein Bestes zu geben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I still have a lot to improve on...", "Ich muss noch vieles verbessern ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I gotta get on everyone else's level.", "Ich muss das Niveau der anderen erreichen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With this I can better help everyone.", "Damit kann ich allen besser helfen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope this helps.", "Ich hoffe, das hilft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah!", "Ah!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ow!", "Aua!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I-I can take it...", "I-ich halte das aus ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can't let them down...", "Ich darf sie nicht enttäuschen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I’m nervous, but...", "Ich bin nervös, aber ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I won't let you down...!", "Ich werde dich nicht enttäuschen ...!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I won't let you down!", "Ich werde dich nicht enttäuschen!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope nothing bad happens.", "Ich hoffe, dass nichts Schlimmes passiert.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alright, here I come!", "Na gut, ich komme!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everything will work out...", "Alles wird gut ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maybe...", "Vielleicht ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If we brace ourselves, we can win this.", "Wenn wir uns wappnen, können wir gewinnen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can do this.", "Ich schaffe das.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I was nothing but trouble...", "Ich habe nur Ärger gemacht ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My body feels numb...", "Mein Körper fühlt sich taub an ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I should've done a better job.", "Ich hätte es besser machen sollen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't like this...", "Das gefällt mir nicht ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maybe someone else can go?", "Vielleicht kann jemand anderes gehen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can't...not again...", "Ich kann nicht ... nicht schon wieder ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You need me, right?", "Du brauchst mich, oder?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's think about this...", "Denken wir darüber nach ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If it will make me more helpful...", "Wenn mich das nützlicher macht ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Will this give me my courage?", "Wird mir das Mut geben?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A trial?", "Eine Prüfung?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope I can help.", "Ich hoffe, ich kann helfen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope I'm prepared.", "Ich hoffe, ich bin vorbereitet.", Language.German);

            //Hokma_talk
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is no different from anything else.", "Das ist nicht anders als alles andere.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We've done this before.", "Das haben wir schon einmal gemacht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We must move onward.", "Wir müssen weitergehen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We can endlessly question", "Wir können uns endlos fragen,", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "why we must endure this endeavour.", "warum wir dieses Unterfangen ertragen müssen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Take all possibilities", "Zieh alle Möglichkeiten", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "into consideration.", "in Betracht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's work quickly now.", "Arbeiten wir jetzt schnell.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "His madness can be used to our advantage.", "Wir können seinen Wahnsinn zu unserem Vorteil nutzen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bend the rules to your favour.", "Beuge die Regeln zu deinem Vorteil.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't let the snow blind you.", "Lass dich nicht vom Schnee blenden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We are all bound by something greater.", "Wir alle sind an etwas Größeres gebunden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He is no exception.", "Er ist keine Ausnahme.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If we focus, victory is assured.", "Wenn wir uns konzentrieren, ist der Sieg sicher.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everything will happen as it should.", "Alles wird so geschehen, wie es soll.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...I admit I am caught off-guard.", "... ich gebe zu, ich bin überrascht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In the end, this is all a pointless errand.", "Am Ende ist das alles ein sinnloser Auftrag.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cannons are slow.", "Die Kanonen sind langsam.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We can easily avoid them.", "Wir können ihnen leicht ausweichen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every Goliath has its David.", "Jeder Goliath hat seinen David.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have faith in yourself, and in us.", "Glaub an dich und an uns.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greetings manager.", "Sei gegrüßt, Manager.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is work to be done.", "Es gibt Arbeit zu erledigen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What matters more than strength...", "Was wichtiger ist als Stärke ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "is faith in our victory.", "ist der Glaube an unseren Sieg.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stay true to your belief.", "Bleib deiner Überzeugung treu.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have come to the point", "Du hast den Punkt", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "of no return.", "ohne Wiederkehr erreicht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It begins once more.", "Es beginnt von Neuem.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This will help greatly.", "Das wird sehr helfen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let us begin the day.", "Beginnen wir den Tag.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Overconfidence is the greatest enemy.", "Übermut ist der größte Feind.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's hurry to finish this work.", "Beeilen wir uns, diese Arbeit zu erledigen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A pointless errand.", "Ein sinnloser Auftrag.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An opportunity presents itself.", "Eine Gelegenheit bietet sich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Be prudent about this.", "Sei vorsichtig dabei.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have faith in your decision.", "Ich vertraue deiner Entscheidung.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boundless pride and ambition", "Grenzenloser Stolz und Ehrgeiz", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "will bring about a bitter end...", "werden zu einem bitteren Ende führen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do not be hasty.", "Handle nicht übereilt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is no halting now.", "Jetzt gibt es kein Halten mehr.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An endless series of trials.", "Eine endlose Reihe von Prüfungen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have faith in yourself and us.", "Glaub an dich und an uns.", Language.German);

            //JesterOfNihil
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Watch them carefully.", "Beobachte sie genau.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They're calling - no, praying for something.", "Sie rufen – nein, sie beten um etwas.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There was no way to know if they had gathered to become [c:gray]the Jester[c:],", "Es war nicht zu erkennen, ob sie sich versammelt hatten, um [c:gray]der Narr[c:] zu werden,", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "or if [c:gray]the Jester[c:] had come to resemble them.", "oder ob [c:gray]der Narr[c:] ihnen ähnlich geworden war.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:gray]The Jester[c:] retraced the steps of a path everyone would've taken.", "[c:gray]Der Narr[c:] ging den Weg nach, den jeder genommen hätte.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No matter what it did, the Jester always found itself at the end of that road.", "Egal, was er tat, der Narr fand sich immer am Ende dieses Weges wieder.", Language.German);

            //LyingAdult
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Long ago, there was a city made of shining emerald.", "Vor langer Zeit gab es eine Stadt aus leuchtendem Smaragd.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruled by the princess [c:bR]Ozma[c:], it was home to many otherworldly splendors.", "Die von Prinzessin [c:bR]Ozma[c:] regierte Stadt beherbergte viele Wunder aus anderen Welten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One day, an adult named [c:g1]Oz[c:] arrived to the Emerald City.", "Eines Tages kam eine Erwachsene namens [c:g1]Oz[c:] in die Smaragdstadt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looking upon the brilliant city, she came up with a brilliant plan.", "Beim Anblick der strahlenden Stadt kam ihr ein glänzender Plan.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soon, [c:g1]Oz[c:] came to be known as a wizard by the people.", "Bald wurde [c:g1]Oz[c:] den Menschen als Zauberin bekannt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing is as deceptive as evident truth.", "Nichts ist trügerischer als eine offensichtliche Wahrheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unable to ever go back home, they began an endless journey.", "Da sie nie wieder nach Hause zurückkehren konnten, begannen sie eine endlose Reise.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]I’ll make your wishes come true. What do you wish for?[c:]", "[c:g1]Ich werde deine Wünsche erfüllen. Was wünschst du dir?[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Poor [c:bR]Ozma[c:] didn’t know that lying adults don’t approach others without reason.", "Die arme [c:bR]Ozma[c:] wusste nicht, dass lügende Erwachsene sich anderen nicht grundlos nähern.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]Last of all, road that is lost. I will send you home.[c:]", "[c:g1]Zuletzt, verlorener Weg. Ich werde dich nach Hause schicken.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]What are you fighting for so fiercely when you have nowhere to go back to?[c:]", "[c:g1]Wofür kämpfst du so verbissen, wenn du keinen Ort hast, an den du zurückkehren kannst?[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]Poor stuffing of straw. I'll give you the wisdom to ponder over anything.[c:]", "[c:g1]Arme Strohpuppe. Ich gebe dir die Weisheit, über alles nachzudenken.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]Do you think jabbering away with your oh-so smart mouth is all that matters?[c:]", "[c:g1]Glaubst du, mit deinem ach so klugen Mund daherzuplappern ist alles, was zählt?[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]Cowardly kitten, I'll give you the courage to stand up to anything and everything.[c:]", "[c:g1]Ängstliches Kätzchen, ich gebe dir den Mut, dich allem und jedem zu stellen.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]What are you even going to do when you lack the bravery to face anything head-on?[c:]", "[c:g1]Was willst du tun, wenn dir der Mut fehlt, irgendetwas direkt anzugehen?[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]Tin-cold woodsman. I'll give you the heart to forgive and love anyone.[c:]", "[c:g1]Blechkalter Holzfäller. Ich gebe dir das Herz, jedem zu vergeben und jeden zu lieben.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]Who do you possibly expect to understand with that ice-cold heart of yours?[c:]", "[c:g1]Wen glaubst du mit deinem eiskalten Herzen überhaupt verstehen zu können?[c:]", Language.German);

            //Malkuth_talk
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heads up manager!", "Pass auf, Manager!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We've got this!", "Wir schaffen das!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's stay sharp, now!", "Bleiben wir wachsam!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The familiar smell of death.", "Der vertraute Geruch des Todes.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Winning's just a matter of time!", "Der Sieg ist nur eine Frage der Zeit!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Watch out for those bait buckets!", "Pass auf die Köderkübel auf!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Be on the look-out!", "Halt die Augen offen!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Watch out for traps!", "Pass auf die Fallen auf!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We need to be smart about this.", "Wir müssen dabei klug vorgehen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This guy looks tough.", "Dieser Kerl sieht hart aus.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Take a deep breath, and focus.", "Atme tief durch und konzentriere dich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We've made this far.", "Wir sind so weit gekommen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We can't lose now!", "Wir dürfen jetzt nicht verlieren!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are those cannons?", "Sind das Kanonen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We've dealt with worse.", "Wir haben schon Schlimmeres überstanden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No need to worry too much!", "Du musst dir nicht zu viele Sorgen machen!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Treat it as another abnormality", "Betrachte es als eine weitere Abnormalität", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "and act accordingly!", "und handle entsprechend!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This thing is huge...", "Dieses Ding ist riesig ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Uh, don't worry!", "Äh, keine Sorge!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We can do it!", "Wir schaffen das!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We just need to outlast it...", "Wir müssen nur länger durchhalten als es ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Manage your resources carefully!", "Verwalte deine Ressourcen sorgfältig!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nice to meet you, manager!", "Schön, dich kennenzulernen, Manager!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hello again!", "Hallo noch mal!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm prepared to help!", "Ich bin bereit zu helfen!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I promise to succeed!", "Ich verspreche, Erfolg zu haben!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greetings Manager!", "Sei gegrüßt, Manager!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trust me and follow my lead!", "Vertrau mir und folge meiner Führung!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's do this!", "Los geht's!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm fully prepared now!", "Ich bin jetzt vollständig vorbereitet!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Winning is just a matter of time!", "Der Sieg ist nur eine Frage der Zeit!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll do my best within my ability!", "Ich werde im Rahmen meiner Fähigkeiten mein Bestes geben!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thank you manager!", "Danke, Manager!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't panic.", "Keine Panik.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stay calm.", "Bleib ruhig.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll fight harder, don't worry!", "Ich werde härter kämpfen, keine Sorge!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've got a good feeling about this!", "Ich habe ein gutes Gefühl dabei!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's stay sharp, shall we?", "Bleiben wir wachsam, ja?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Focus on the path forward!", "Konzentriere dich auf den Weg nach vorn!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not like this...", "Nicht so ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...Don't give up.", "... gib nicht auf.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I talked big and failed, again.", "Ich habe große Töne gespuckt und wieder versagt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stay calm, everyone.", "Bleibt ruhig, alle zusammen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have faith in your decision.", "Ich vertraue deiner Entscheidung.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why don't we take a deep breath?", "Wie wäre es, wenn wir tief durchatmen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Things are going smoothly!", "Alles läuft glatt!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's make the most of this!", "Machen wir das Beste daraus!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I trust your judgement!", "Ich vertraue deinem Urteil!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have faith in me!", "Hab Vertrauen in mich!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You've got this manager!", "Du schaffst das, Manager!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing we haven't solved before!", "Nichts, was wir nicht schon gelöst hätten!", Language.German);

            //MapNodes
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You enter a clearing surrounded by dark, twisting trees.", "Du betrittst eine Lichtung, umgeben von dunklen, verdrehten Bäumen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Their branches claw at the leering moon as you approach the well at the clearing's centre.", "Ihre Äste kratzen nach dem grinsenden Mond, während du dich dem Brunnen in der Mitte der Lichtung näherst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unearthly voices arise from the its inky depths, pleading, screaming, wishing and wanting.", "Überirdische Stimmen steigen aus seiner tintenschwarzen Tiefe auf, flehend, schreiend, wünschend und verlangend.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There are things in the well, waiting to be drawn up. Powerful, mysterious,", "Im Brunnen warten Dinge darauf, heraufgezogen zu werden. Mächtig, geheimnisvoll,", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]abnormal[c:].", "[c:bR]abnormal[c:].", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As you journey through the wilderness, you come across a small group of humans.", "Auf deiner Reise durch die Wildnis begegnest du einer kleinen Gruppe Menschen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They're dressed oddly for this climate, and even odder, [c:bR]they seem to recognise you[c:].", "Sie sind für dieses Klima seltsam gekleidet und, noch seltsamer, [c:bR]sie scheinen dich zu erkennen[c:].", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They are on an expedition of some kind, in search of [c:bR]strange[c:] beasts.", "Sie sind auf einer Art Expedition auf der Suche nach [c:bR]seltsamen[c:] Bestien.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Their appear quite knowledgeable. Perhaps you can convince them to aid you on your journey.", "Sie scheinen sehr sachkundig zu sein. Vielleicht kannst du sie überreden, dir auf deiner Reise zu helfen.", Language.German);

            //Netzach_talk
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That banging's annoying...", "Dieses Gehämmer nervt ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Again?", "Schon wieder?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not a fan of that pickaxe.", "Ich bin kein Fan dieser Spitzhacke.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So many buckets of fish...", "So viele Eimer voller Fisch ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The smell's making me sick.", "Der Geruch macht mich krank.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Can't we take the long way around?", "Können wir nicht einen Umweg nehmen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everyone here's crazy...", "Hier sind alle verrückt ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At least those traps are obvious.", "Wenigstens sind die Fallen offensichtlich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just want to lie down in the snow", "Ich will mich nur in den Schnee legen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "and go to sleep.", "und schlafen gehen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the final boss?", "Ist das der letzte Boss?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Since we've come this far, may as well.", "Wenn wir schon so weit gekommen sind, können wir genauso gut weitermachen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's finish this.", "Bringen wir es zu Ende.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...am I hallucinating?", "... halluziniere ich?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I guess I've seen weirder things.", "Ich habe wohl schon Seltsameres gesehen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Those cannons are pretty slow, huh?", "Diese Kanonen sind ziemlich langsam, was?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What is that thing?", "Was ist das für ein Ding?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't need this stress...", "Diesen Stress brauche ich nicht ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why are we back here?", "Warum sind wir wieder hier?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pick someone else?", "Jemand anderen wählen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Know what I need most? Retreat and sleep.", "Weißt du, was ich am meisten brauche? Rückzug und Schlaf.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sigh...", "Seufz ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm too tired for this.", "Ich bin zu müde dafür.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This battlefield atmosphere...", "Diese Schlachtfeldatmosphäre ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not a fan of it.", "Gefällt mir nicht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That should be enough, right?", "Das sollte reichen, oder?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Waste of effort.", "Verschwendete Mühe.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll try not to disappoint.", "Ich versuche, nicht zu enttäuschen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thanks, I guess.", "Danke, nehme ich an.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I just wanna nap in the back...", "Ich will hinten nur ein Nickerchen machen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How did I end up doing things like this?", "Wie bin ich nur dazu gekommen, so etwas zu tun?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's do this...", "Los geht's ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's get this over with.", "Bringen wir es hinter uns.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guess I can sleep now.", "Ich kann jetzt wohl schlafen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sorry I couldn't help.", "Tut mir leid, dass ich nicht helfen konnte.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why is the end always futile?", "Warum ist das Ende immer vergeblich?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...I just wanna end this quickly.", "... ich will das nur schnell beenden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Can I opt out?", "Kann ich aussteigen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Is leaving an option?", "Ist Weggehen eine Möglichkeit?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose whoever.", "Wähle, wen du willst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At your discretion, manager.", "Ganz wie du meinst, Manager.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why with all the tests?", "Warum all diese Prüfungen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ugh...", "Uff ...", Language.German);

            //Tiphereth_talk
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's deal with this guy quickly.", "Kümmern wir uns schnell um diesen Kerl.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Should've stayed out of the way.", "Ich hätte mich raushalten sollen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You still haven't beat him?", "Hast du ihn immer noch nicht besiegt?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It smells like the Backstreets here.", "Hier riecht es wie in den Hinterstraßen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At least his actions are predictable.", "Wenigstens sind seine Handlungen vorhersehbar.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quickly now.", "Schnell jetzt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guess we're next on the chopping block.", "Wir sind wohl die Nächsten auf dem Hackklotz.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Those knives look sharp. Careful.", "Diese Messer sehen scharf aus. Vorsicht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hold onto those pelts now.", "Halt diese Felle gut fest.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We've got this manager.", "Wir schaffen das, Manager.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't forget, you have us to help.", "Vergiss nicht, dass wir dir helfen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One more foe to beat.", "Noch ein Gegner zu besiegen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seriously?", "Im Ernst?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Never was that into pirates.", "Ich war nie besonders von Piraten begeistert.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This guy can't aim at all.", "Dieser Kerl kann überhaupt nicht zielen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's massive...", "Es ist riesig ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope you know", "Ich hoffe, du weißt,", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "what you're doing.", "was du tust.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Keep your head on tight, manager.", "Pass gut auf deinen Kopf auf, Manager.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This'll be tough.", "Das wird hart.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We'll make it out for sure.", "Wir kommen da bestimmt heraus.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hurry and pick one of us.", "Beeil dich und wähle einen von uns.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't keep up waiting.", "Lass uns nicht warten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Buckle up manager.", "Schnall dich an, Manager.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have faith.", "Hab Vertrauen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're not fighting alone.", "Du kämpfst nicht allein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can't plan forever.", "Du kannst nicht ewig planen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now's the time for action.", "Jetzt ist es Zeit zu handeln.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You know what to do, right?", "Du weißt, was zu tun ist, oder?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We can't let everyone die here.", "Wir können nicht alle hier sterben lassen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Think I can't do this myself?", "Glaubst du, ich schaffe das nicht allein?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not bad.", "Nicht schlecht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This better be useful.", "Das sollte besser nützlich sein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I was too slow...", "Ich war zu langsam ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Push forward!", "Vorwärts!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't get cocky.", "Werd nicht übermütig.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can still fight!", "Ich kann noch kämpfen!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...Sorry", "... tut mir leid", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why'd you bring us here?", "Warum hast du uns hergebracht?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No.", "Nein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't you dare.", "Wag es nicht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A respite?", "Eine Verschnaufpause?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Decide for yourself.", "Entscheide selbst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Make good use of this.", "Mach guten Gebrauch davon.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose someone that needs it.", "Wähle jemanden, der es braucht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A trial?", "Eine Prüfung?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We've gone through worse.", "Wir haben Schlimmeres überstanden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can handle it.", "Ich kann das bewältigen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll win this for sure.", "Ich werde das ganz sicher gewinnen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You'll do fine, like always.", "Du wirst das gut machen, wie immer.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here we go.", "Los geht's.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What a strange place...", "Was für ein seltsamer Ort ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Time to work.", "Zeit zu arbeiten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's do our best.", "Geben wir unser Bestes.", Language.German);

            //WhiteNight
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]The time has come. A new world will come.[c:]", "[c:bR]Die Zeit ist gekommen. Eine neue Welt wird entstehen.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]I am death and life. Darkness and light.[c:]", "[c:bR]Ich bin Tod und Leben. Dunkelheit und Licht.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Have I not chosen you, the Twelve? Yet one of you is a devil.[c:]", "[c:bR]Habe ich nicht euch, die Zwölf, erwählt? Und doch ist einer von euch ein Teufel.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]None of you can leave my side until I permit you.[c:]", "[c:bR]Keiner von euch darf meine Seite ohne meine Erlaubnis verlassen.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Be at ease. No calamity shall be able to trouble you.[c:]", "[c:bR]Seid unbesorgt. Kein Unglück wird euch behelligen.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]I shall not leave thee until I have completed my mission.[c:]", "[c:bR]Ich werde dich nicht verlassen, bis ich meine Aufgabe erfüllt habe.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]What did you do?[c:]", "[c:bR]Was habt ihr getan?[c:]", Language.German);

            //Yesod_talk
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't let his age lull you into", "Lass dich von seinem Alter nicht", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a false sense of security.", "in falscher Sicherheit wiegen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That pickaxe is sharp. Stay vigilant.", "Diese Spitzhacke ist scharf. Bleib wachsam.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's not waste any time.", "Verschwenden wir keine Zeit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't let the smell dull your mind.", "Lass den Geruch deinen Verstand nicht trüben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "His hook always seems to hit its mark.", "Sein Haken scheint immer sein Ziel zu treffen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm sure you know how to deal with it.", "Ich bin sicher, du weißt, wie du damit umgehen musst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This isn't particularly pleasant...", "Das ist nicht besonders angenehm ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Come up with a plan, then execute it.", "Mach einen Plan und setze ihn dann um.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't let the cold cloud your senses, manager.", "Lass die Kälte deine Sinne nicht trüben, Manager.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hasty actions will bring more harm than good.", "Übereilte Handlungen richten mehr Schaden als Nutzen an.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We must make sound judgements", "Wir müssen gute Entscheidungen treffen,", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "before rushing forward.", "bevor wir vorwärtsstürmen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Use what we've learned until now.", "Nutzen wir, was wir bisher gelernt haben,", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "to take him down.", "um ihn zu besiegen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Consider this your final test.", "Betrachte dies als deine letzte Prüfung.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A skeleton? That's new.", "Ein Skelett? Das ist neu.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "His crew seems persuadable.", "Seine Mannschaft scheint sich überreden zu lassen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Can't say I'm impressed.", "Ich kann nicht behaupten, beeindruckt zu sein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't be intimidated.", "Lass dich nicht einschüchtern.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Manage your creatures wisely,", "Setze deine Kreaturen klug ein,", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "and maintain constant fire.", "und halte das Dauerfeuer aufrecht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We know its tricks now.", "Wir kennen seine Tricks jetzt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We are at an advantage.", "Wir sind im Vorteil.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't lose your cool now.", "Verlier jetzt nicht die Ruhe.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Recklessly charging is not an effecient combat method.", "Unüberlegtes Drauflosstürmen ist keine wirksame Kampfmethode.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We must prioritise concluding this fight quickly.", "Wir müssen es zur Priorität machen, diesen Kampf schnell zu beenden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I take it you're prepared for any outcome.", "Ich nehme an, du bist auf jeden Ausgang vorbereitet.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In a situation such as this,", "In einer solchen Situation", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "we must be calm and make sound judgements.", "müssen wir ruhig bleiben und besonnene Entscheidungen treffen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I will fulfill my responsibility.", "Ich werde meiner Verantwortung gerecht werden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I accept this with grace.", "Ich nehme das mit Würde an.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kh.", "Kh.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay no mind to me.", "Kümmere dich nicht um mich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Focus on the goal.", "Konzentriere dich auf das Ziel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If there's no opportunity to strike,", "Wenn sich keine Gelegenheit zum Angriff bietet,", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "we'll simply make one.", "schaffen wir uns eben eine.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's end this quickly.", "Bringen wir es schnell zu Ende.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Very well.", "Sehr gut.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's not push ourselves too carelessly.", "Überanstrengen wir uns nicht leichtsinnig.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't want to waste any time.", "Ich will keine Zeit verschwenden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is no need to pity me.", "Du brauchst kein Mitleid mit mir zu haben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I couldn't see the path ahead.", "Ich konnte den Weg vor mir nicht erkennen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What did I do wrong?", "Was habe ich falsch gemacht?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's entirely my fault.", "Es ist ganz allein meine Schuld.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This isn't particularly delightful.", "Das ist nicht gerade erfreulich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This death must not be in vain.", "Dieser Tod darf nicht umsonst sein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I suppose I should just accept this.", "Ich nehme an, ich muss es einfach akzeptieren.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frankly,", "Ehrlich gesagt", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I dislike how numb I've become to death.", "missfällt es mir, wie gleichgültig mir der Tod geworden ist.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I trust you will choose correctly.", "Ich vertraue darauf, dass du richtig wählen wirst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Be logical about this.", "Geh logisch an die Sache heran.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems to be a test of some kind.", "Es scheint eine Art Prüfung zu sein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A single mistake could cause disaster.", "Ein einziger Fehler könnte eine Katastrophe auslösen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We must always proceed with discretion.", "Wir müssen stets umsichtig vorgehen.", Language.German);

            //部分印记、说明补充
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Single Recall is created in your hand. A Single Recall can return a card on your side of the board to your hand.", "Ein Einmaliger Rückruf wird auf deiner Hand erzeugt. Damit kannst du eine Karte auf deiner Seite des Bretts auf deine Hand zurückholen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This will let you return a played card to your hand. Returned cards will cost [c:bR]Bones[c:] to replay.", "Damit holst du eine ausgespielte Karte auf deine Hand zurück. Zurückgeholte Karten kosten beim erneuten Ausspielen [c:bR]Knochen[c:].", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Total Recall is created in your hand. A Total Recall will return all cards on your side of the board to your hand.", "Ein Vollständiger Rückruf wird auf deiner Hand erzeugt. Er holt alle Karten auf deiner Seite des Bretts auf deine Hand zurück.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This will return all your cards to your hand. Returned cards will cost [c:bR]Bones[c:] to replay.", "Damit holst du alle deine Karten auf deine Hand zurück. Zurückgeholte Karten kosten beim erneuten Ausspielen [c:bR]Knochen[c:].", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Justitia", "Justitia", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Non-Terrain cards targeted by Judgement Bird are killed regardless of Health. Judgement Bird is not affected by abilities like Sharp and Punisher.", "Karten, die kein Gelände sind und vom Urteilsvogel anvisiert werden, sterben unabhängig von ihrer Gesundheit. Fähigkeiten wie Spitze Stacheln und Bestrafer wirken nicht auf den Urteilsvogel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In the Name of Love and Hate", "Im Namen von Liebe und Hass", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When 2 more ally cards have died than opposing cards or vice versa, Magical Girl will transform then move to the side of the board that lost more cards.", "Wenn 2 verbündete Karten mehr als gegnerische Karten gestorben sind oder umgekehrt, verwandelt sich das Magische Mädchen und bewegt sich auf die Brettseite, die mehr Karten verloren hat.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magical Girls", "Magische Mädchen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain a special card when all 4 Magical Girls or their evolutions are on the same side of the board.", "Erhalte eine besondere Karte, wenn alle 4 Magischen Mädchen oder ihre Weiterentwicklungen auf derselben Brettseite sind.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mimicry", "Mimikry", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing There reveals itself on death.", "Nichts da offenbart sich beim Tod.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pink", "Rosa", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Army in Pink will transform when 3 ally cards die.", "Die Armee in Rosa verwandelt sich, wenn 3 verbündete Karten sterben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sap", "Saft", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever Giant Tree Sap is sacrificed, there is an increasing chance the sacrificing card will explode.", "Jedes Mal, wenn Riesenbaumsaft geopfert wird, steigt die Wahrscheinlichkeit, dass die opfernde Karte explodiert.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Smile", "Lächeln", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mountain of Smiling Bodies grows into a stronger forme whenever killing a card. Upon dying, revert to a previous forme if possible.", "Der Berg der lächelnden Körper nimmt jedes Mal, wenn er eine Karte tötet, eine stärkere Form an. Beim Tod kehrt er nach Möglichkeit zu einer vorherigen Form zurück.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sound of a Star", "Der Klang eines Sterns", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If there are no cards on the opposing side that can be attacked, Blue Star strikes all slots directly.", "Gibt es auf der gegnerischen Seite keine angreifbaren Karten, greift der Blaue Stern alle Felder direkt an.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Sword Sharpened with Tears", "Das mit Tränen geschärfte Schwert", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Knight of Despair and Servant of Wrath will transform when an adjacent card dies.", "Die Ritterin der Verzweiflung und die Dienerin des Zorns verwandeln sich, wenn eine benachbarte Karte stirbt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Syrinx", "Syrinx", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nameless Fetus transforms when sacrificed six times.", "Der Namenlose Fötus verwandelt sich, nachdem er sechsmal geopfert wurde.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Homing Instinct", "Der Heimkehrinstinkt", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When The Road Home is played, create a Scaredy Cat in your hand. [define:wstl_scaredyCat]", "Wenn der Weg nach Hause ausgespielt wird, erzeuge eine Ängstliche Katze auf deiner Hand. [define:wstl_scaredyCat]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Three Birds", "Drei Vögel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain a special card when Punishing Bird, Judgement Bird, and Big Bird are on the same side of the board.", "Erhalte eine besondere Karte, wenn Strafvogel, Urteilsvogel und Großer Vogel auf derselben Brettseite sind.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Today's Expression", "Der heutige Gesichtsausdruck", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Today's Shy Look changes forme when drawn.", "Der Heutige schüchterne Blick ändert seine Form, wenn er gezogen wird.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wrist Cutter", "Handgelenkschneider", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloodbath transforms whenever a card is sacrificed.", "Das Blutbad verwandelt sich jedes Mal, wenn eine Karte geopfert wird.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yellow Brick Road", "Die gelbe Ziegelstraße", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain a special card when Ozma, The Road Home, Warm-Hearted Woodsman, and Scarecrow Searching for Wisdom are all on the same side of the board.", "Erhalte eine besondere Karte, wenn Ozma, der Weg nach Hause, der Warmherzige Holzfäller und die Weisheit suchende Vogelscheuche auf derselben Brettseite sind.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clouded Monk", "Verschleierter Mönch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enchanted", "Verzaubert", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card will target cards with the Dazzling sigil, dealing no damage to them and dying after attacking. At the start of the owner's next turn, lose 1 stack of this effect.", "Diese Karte greift Karten mit dem Siegel Strahlend an, verursacht bei ihnen keinen Schaden und stirbt nach dem Angriff. Zu Beginn des nächsten Zuges ihres Besitzers verliert sie 1 Stapel dieses Effekts.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sin", "Sünde", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card deals damage to another creature, transfer 1 Sin to that card.", "Wenn diese Karte einer anderen Kreatur Schaden zufügt, überträgt sie 1 Sünde auf diese Karte.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WhistleWind Lobotomy Mod", "WhistleWinds Lobotomy-Mod", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Through the Twilight", "Durch die Dämmerung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Survive the apocalypse and defeat the Beast.", "Überlebe die Apokalypse und besiege die Bestie.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Impuritas Civitatis", "Impuritas Civitatis", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Meet Angela at a Sephirot choice node.", "Triff Angela an einem Sephirot-Auswahlknoten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gather the guardians of the Black Forest.", "Versammle die Wächter des Schwarzen Waldes.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Full House", "Full House", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bring all of the magical girls together.", "Bring alle Magischen Mädchen zusammen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reunite a group of long-lost friends.", "Führe eine Gruppe lange getrennter Freunde wieder zusammen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blessing", "Segen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You witnessed His coming.", "Du hast Seine Ankunft miterlebt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good cannot exist without evil.", "Ohne das Böse kann das Gute nicht existieren.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A strange gurgling sound comes from your beast's stomach.", "Aus dem Magen deiner Bestie ertönt ein seltsames Gurgeln.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Sephirah agrees, and the others continue their separate way.", "Der Sephirah stimmt zu, und die anderen setzen ihre Wege getrennt fort.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Before they go, they promise to see you again.", "Vor ihrem Aufbruch versprechen sie, dich wiederzusehen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You may ask [c:bR]1[c:] to join you. The others will continue on their own.", "Du kannst [c:bR]1[c:] von ihnen bitten, sich dir anzuschließen. Die anderen gehen allein weiter.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Something prevents its function. You cannot escape this one.", "Etwas verhindert seine Funktion. Diesmal kannst du nicht entkommen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have I backed you into a corner? Or am I simply boring you?", "Habe ich dich in die Enge getrieben? Oder langweile ich dich bloß?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I suppose it doesn't matter. I will honour your request.", "Ich nehme an, das spielt keine Rolle. Ich werde deiner Bitte nachkommen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You cannot escape so easily.", "So leicht kannst du nicht entkommen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Divine power infuses the beasts in your caravan, empowering them.", "Göttliche Macht durchströmt die Bestien deiner Karawane und stärkt sie.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Do not deny me.[c:]", "[c:bR]Verweigere dich mir nicht.[c:]", Language.German);

            //packandchallenges
            for (int count = 0; count <= 100; count++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A set of " + count.ToString() + " cards based on the abnormalities from Lobotomy Corporation and Library of Ruina.", "Ein Satz von " + count.ToString() + " " + (count == 1 ? "Karte" : "Karten") + ", basierend auf den Abnormalitäten aus Lobotomy Corporation und Library of Ruina.", Language.German);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A set of [summary] exclusively featuring abnormalities and related phenomena.", "Ein Satz von [summary], der ausschließlich Abnormalitäten und damit verbundene Phänomene enthält.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Abnormal Bosses", "Abnormale Bosse", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vanilla bosses will play Abnormalities during their battles.", "Bosse aus dem Grundspiel spielen in ihren Kämpfen Abnormalitäten aus.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Abnormal Encounters", "Abnormale Begegnungen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All regular battles will only use abnormality cards.", "In allen gewöhnlichen Kämpfen werden nur Abnormalitätskarten verwendet.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start with a Beast", "Mit einer Bestie beginnen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start your run with Apocalypse Bird in your deck.", "Beginne deinen Durchlauf mit dem Apokalypsevogel in deinem Stapel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Better Rare Chances", "Höhere Chance auf seltene Karten", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rare cards are more likely to appear at abnormal choice nodes.", "Seltene Karten erscheinen mit höherer Wahrscheinlichkeit an Abnormalitäts-Auswahlknoten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Final Apocalypse", "Letzte Apokalypse", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leshy is replaced as the final boss of the run with the Beast.", "Die Bestie ersetzt Leshy als letzten Boss des Durchlaufs.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Final Coming", "Letzte Ankunft", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Saviour boss will be stronger and guaranteed to appear.", "Der Boss Retter ist stärker und erscheint garantiert.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Final Laugh", "Letztes Lachen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leshy is replaced as the final boss of the run with the Fool.", "Der Narr ersetzt Leshy als letzten Boss des Durchlaufs.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Final Trick", "Letzter Trick", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Adult boss will be stronger and guaranteed to appear.", "Der Boss Erwachsene ist stärker und erscheint garantiert.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start with a Fool", "Mit einem Narren beginnen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start your run with Jester of Nihil in your deck.", "Beginne deinen Durchlauf mit dem Narren des Nichts in deinem Stapel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start with a Liar", "Mit einem Lügner beginnen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start your run with Adult Who Tells Lies in your deck.", "Beginne deinen Durchlauf mit dem lügenden Erwachsenen in deinem Stapel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Miracle Worker", "Wundertäter", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leshy will play Plague Doctor against you. Beware the Clock.", "Leshy spielt den Pestarzt gegen dich aus. Hüte dich vor der Uhr.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Too fast. Too soon.[c:]", "[c:bR]Zu schnell. Zu früh.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your journey has brought here, to a dark, oppressive forest.", "Deine Reise hat dich hierher geführt, in einen dunklen, bedrückenden Wald.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sky above you is an inky void, empty of even a single star.", "Der Himmel über dir ist eine tintenschwarze Leere, ohne auch nur einen Stern.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A horrible roar rattles your bones, and a fearful chill overcomes you.", "Ein schreckliches Brüllen erschüttert deine Knochen und ein eisiger Schrecken erfasst dich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Somewhere beyond the dark trees, there's a monster.", "Irgendwo hinter den dunklen Bäumen lauert ein Monster.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]A monster in the Black Forest.[c:]", "[c:bR]Ein Monster im Schwarzen Wald.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your journey has brought here, to an unknown yet familiar forest.", "Deine Reise hat dich hierher geführt, in einen unbekannten und doch vertrauten Wald.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Somewhere beyond the dark trees, you know, there's a monster.", "Du weißt, dass irgendwo hinter den dunklen Bäumen ein Monster lauert.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dag nab it! My reindeer!", "Verdammt noch mal! Mein Rentier!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cute Lil Guy", "Niedlicher kleiner Kerl", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will enter a downed state instead of dying. Downed creatures are invulnerable under special conditions.", "[creature] geht zu Boden, statt zu sterben. Am Boden liegende Kreaturen sind unter bestimmten Bedingungen unverwundbar.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kill WhiteNight and all Apostles on the board then deal 33 direct damage.", "Töte Weiße Nacht und alle Apostel auf dem Brett und füge dann 33 direkten Schaden zu.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of combat, this card will mark random spaces with coloured targets, then attack those spaces on its next turn. Red: this card's damage is doubled; White: this card's damage is halved and it heals equal to its Power; Yellow: no special effect.", "Am Ende des Kampfes markiert diese Karte zufällige Felder mit farbigen Zielen und greift diese in ihrem nächsten Zug an. Rot: Ihr Schaden wird verdoppelt; Weiß: Ihr Schaden wird halbiert und sie heilt Gesundheit in Höhe ihrer Kraft; Gelb: kein besonderer Effekt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every 3 turns, change the active egg effect. On the final phase, this sigil changes behaviour. Opponent cards may move at the end of the turn. This card cannot go below 90/60/30 Health.", "Alle 3 Züge wechselt der aktive Ei-Effekt. In der letzten Phase ändert dieses Siegel sein Verhalten. Gegnerische Karten können sich am Ende des Zuges bewegen. Die Gesundheit dieser Karte kann nicht unter 90/60/30 sinken.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, deal direct damage to the owner proportional to how much damage this card received during the turn.", "Am Ende des Zuges ihres Besitzers fügt diese Karte ihm direkten Schaden zu, der proportional zu dem in diesem Zug erlittenen Schaden ist.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eat 'em!", "Friss sie!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Single Recall Bottle", "Flasche mit Einmaligem Rückruf", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Total Recall Bottle", "Flasche mit Vollständigem Rückruf", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Twilight falls...", "Die Dämmerung bricht herein...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The beginning at the end.", "Der Anfang am Ende.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The end at the beginning.", "Das Ende am Anfang.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everything is equal. Everything is as it should be.", "Alles ist gleich. Alles ist, wie es sein sollte.", Language.German);

        }
    }
    public class TVFsBossesMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for TVFsBosses Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though there was no one in sight, some offerings were laid out before you.", "Obwohl niemand zu sehen war, lagen einige Opfergaben vor dir bereit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There was no [c:bR]Woodcarver[c:] nearby.", "Die [c:bR]Holzschnitzerin[c:] war nirgends in der Nähe.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Still, her totem pieces remained.", "Ihre Totemteile waren jedoch noch da.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The old [c:bR]Woodcarver[c:] was nowhere to be found.", "Die alte [c:bR]Holzschnitzerin[c:] war nirgends zu finden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Her carvings remained by the log she once sat upon.", "Ihre Schnitzereien lagen noch neben dem Baumstamm, auf dem sie einst gesessen hatte.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The [c:bR]Woodcarver[c:] emerged from the thicket.", "Die [c:bR]Holzschnitzerin[c:] trat aus dem Dickicht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Her face looked somehow more stern than usual.", "Ihr Gesicht wirkte irgendwie strenger als sonst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An ancient woman approached.", "Eine uralte Frau näherte sich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "She looked intensely displeased with you.", "Sie schien höchst unzufrieden mit dir zu sein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nearby branches rustled as The [c:bR]Woodcarver[c:] revealed herself.", "Die Zweige in der Nähe raschelten, als sich die [c:bR]Holzschnitzerin[c:] zeigte.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "She had no offerings this time.", "Diesmal hatte sie keine Opfergaben dabei.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Leave.[c:]", "[c:bR]Geh.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Turn back.", "Kehr um.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You are not prepared.", "Du bist nicht bereit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woodcarver Boss", "Boss Holzschnitzerin", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Prospector is replaced as the boss of the Woodlands.", "Die Holzschnitzerin ersetzt den Goldgräber als Boss des Waldgebiets.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You found yourself among a grove of thick and pungent mushrooms.", "Du befandest dich in einem Hain dichter, stechend riechender Pilze.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The operating table lay abandoned.", "Der Operationstisch lag verlassen da.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The [c:bR]Mycologists[c:] stepped out from behind an enormous mushroom.", "Die [c:bR]Pilzkundler[c:] traten hinter einem riesigen Pilz hervor.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One of them looked anxious, but the other bore a very serious expression.", "Einer von ihnen wirkte besorgt, der andere hatte einen sehr ernsten Ausdruck.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You squinted to see a figure through the thick cloud of spores.", "Du kniffst die Augen zusammen und erspähtest eine Gestalt durch die dichte Sporenwolke.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The [c:bR]Mycologists[c:]' shared body was posed in a threatening stance.", "Der gemeinsame Körper der [c:bR]Pilzkundler[c:] nahm eine bedrohliche Haltung ein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The [c:bR]Mycologists[c:] appeared more crazed with each breath they took.", "Die [c:bR]Pilzkundler[c:] wirkten mit jedem Atemzug wahnsinniger.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It was clear they wanted to experiment on more than just your creatures.", "Es war klar, dass sie nicht nur an deinen Kreaturen experimentieren wollten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[size:3]It will suffice.[size:]", "[size:3]Das wird genügen.[size:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[size:3]For our experiments, yes.[size:]", "[size:3]Für unsere Experimente, ja.[size:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[size:3]Do not worry. I have a backup plan.[size:]", "[size:3]Keine Sorge. Ich habe einen Ersatzplan.[size:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[size:3]Satisfactory results.[size:]", "[size:3]Zufriedenstellende Ergebnisse.[size:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "B- But there is only one challenger?", "A-Aber es gibt nur einen Herausforderer?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We... We need your body?", "Wir... Wir brauchen deinen Körper?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Y- You will... not submit your body for our experiments?", "D-Du wirst... deinen Körper nicht für unsere Experimente zur Verfügung stellen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mycologists Boss", "Boss Pilzkundler", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Angler is replaced as the boss of the Wetlands.", "Die Pilzkundler ersetzen den Angler als Boss des Sumpfgebiets.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Experiment", "Experiment", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GOOD.", "GUT.", Language.German);

        }
    }
    public class ZephtSunMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for ZephtSun Mod");
            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DebugSun", "Sonnen-Debug", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sun: ", "Sonne: ", Language.German);
            for (int count = 0; count <= 100; count++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sun: " + count.ToString(), "Sonne: " + count.ToString(), Language.German);
            }

            // Challenge
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Night time", "Nachtzeit", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will no longer get passive sun falling from the sky.", "Du erhältst keine passiv vom Himmel fallende Sonne mehr.", Language.German);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SunBoost", "Sonnenzuwachs", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is placed on the board, the owner will gain sun.", "Wird [creature] auf das Brett gelegt, erhält der Besitzer Sonne.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wise use of emergency supplies.", "Notvorräte klug eingesetzt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SunKill", "Sonnentod", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] defeats another card, the other card will drop sun.", "Besiegt [creature] eine andere Karte, lässt diese Sonne fallen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Recycle your enemies back into nutrients", "Verwandle deine Feinde wieder in Nährstoffe", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SunMaker 1", "Sonnenproduktion 1", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will produce 1 sun, if it belongs to the player.", "Am Ende des Zuges ihres Besitzers erzeugt [creature] 1 Sonne, falls sie dem Spieler gehört.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every little bit counts", "Jede Kleinigkeit zählt", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SunMaker 2", "Sonnenproduktion 2", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will produce 2 sun, if it belongs to the player.", "Am Ende des Zuges ihres Besitzers erzeugt [creature] 2 Sonne, falls sie dem Spieler gehört.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If only the moon was this useful", "Wenn doch der Mond nur so nützlich wäre", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SunMaker 3", "Sonnenproduktion 3", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will produce 3 sun, if it belongs to the player.", "Am Ende des Zuges ihres Besitzers erzeugt [creature] 3 Sonne, falls sie dem Spieler gehört.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The power of the sun, in the palm of your hand", "Die Macht der Sonne in deiner Handfläche", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SunMaker", "Sonnenproduktion", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will produce X sun, if it belongs to the player. Some cards produce more sun than others.", "Am Ende des Zuges ihres Besitzers erzeugt [creature] X Sonne, falls sie dem Spieler gehört. Manche Karten erzeugen mehr Sonne als andere.", Language.German);

            // ShowThenClear
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You dont have enough sun for that one", "Du hast dafür nicht genug Sonne", Language.German);

        }
    }
    public class PlantsVSZombiesMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for PlantsVSZombies Mod");
            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Peashooter", "Erbsenschütze", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Repeater", "Doppelerbsenschütze", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leaflitter", "Laubstreu", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A plant commonly used to fend off the undead", "Eine Pflanze, die häufig zur Abwehr von Untoten eingesetzt wird", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Threepeater", "Dreifacherbsenschütze", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A more powerful version of the iconic peashooter", "Eine stärkere Version des berühmten Erbsenschützen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "they say 3 heads are better than one", "Man sagt, 3 Köpfe seien besser als einer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cactus", "Kaktus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Try not to prick yourself on it", "Pass auf, dass du dich nicht daran stichst", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Splinters", "Splitter", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Homing Thistle", "Zieldistel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one tracks down its target with ease", "Diese Pflanze spürt ihr Ziel mühelos auf", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cattail", "Katzenrohr", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nyah~", "Miau~", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chomper", "Schnapper", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No bark and all bite", "Kein Bellen, nur Beißen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Starfruit", "Sternfrucht", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Surprisingly not a ball of fire", "Überraschenderweise kein Feuerball", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloomerang", "Blümerang", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't be deceived, it won't just return if you throw it away", "Lass dich nicht täuschen: Wenn du sie wegwirfst, kommt sie nicht einfach zurück", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "bonk choy", "Box-Choi", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A feisty one for sure", "Ein echtes Energiebündel, das steht fest", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Citron", "Zitrone", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you can afford to play it, it's zest is bound to aid you", "Wenn du sie dir leisten kannst, wird dir ihr spritziges Wesen gewiss helfen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Red Stinger", "Roter Stachel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Position it strategically if you want to use its full potential", "Platziere ihn strategisch, um sein volles Potenzial zu nutzen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spikerock", "Stachelfels", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spikeweed", "Stachelkraut", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Will you lay the spikeweed as a trap for those who dare approach it?", "Legst du das Stachelkraut als Falle für alle aus, die sich ihm nähern?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anybody who attempts to trample it will meet a sharp fate.", "Wer sie zu zertrampeln versucht, erlebt ein stacheliges Schicksal.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Artichoke", "Artischocke", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This drone has seen some warfare", "Diese Drohne hat schon Krieg erlebt", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beeshooter", "Bienenschütze", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "According to all known laws of aviation, there is no way a bee should be able to fly", "Nach allen bekannten Gesetzen der Luftfahrt dürfte eine Biene nicht fliegen können", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Puffshroom", "Kleiner Pustepilz", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It might not be very powerful, but it can get you out of a pinch", "Er ist vielleicht nicht sehr stark, kann dir aber aus einer Klemme helfen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seashroom", "Seepilz", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just a little mushroom, sitting on the water", "Nur ein kleiner Pilz, der auf dem Wasser sitzt", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scaredyshroom", "Angstpilz", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Some may consider this one a coward for its tactics", "Manche halten ihn wegen seiner Taktik für einen Feigling", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fume", "Dunst", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fumeshroom", "Dunstpilz", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its fumes can hit many foes", "Sein Dunst kann viele Feinde treffen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sporeshroom", "Sporenpilz", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Put divide and conquer into practice", "Setze Teile und herrsche in die Praxis um", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sunflower", "Sonnenblume", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "These can power entire infantries", "Sie können ganze Armeen mit Energie versorgen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Twin Sunflower", "Doppelsonnenblume", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Truly a great powerplant", "Ein wahrhaft kraftvolles Kraftwerk", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SunShroom", "Sonnenpilz", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "allow the sunshroom some time to reach its full potential", "Gib dem Sonnenpilz Zeit, sein volles Potenzial zu entfalten", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ToadStool", "Krötenpilz", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A frogish fungus, how curious", "Ein froschartiger Pilz, wie seltsam", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sun bean", "Sonnenbohne", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "will you invest in the sun bean?", "Investierst du in die Sonnenbohne?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wallnut", "Wallnuss", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What an iconic line of defence", "Was für eine legendäre Verteidigungslinie", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tallnut", "Hochwallnuss", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Near nothing can get past this one", "An ihr kommt fast nichts vorbei", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Endurian", "Durianpanzer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's outer shell wont be so enjoyable to get through", "Durch seine äußere Schale zu kommen, wird kein Vergnügen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Garlic", "Knoblauch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Control the upcoming onslaughts with the Garlic's stench.", "Kontrolliere die bevorstehenden Angriffe mit dem Gestank des Knoblauchs.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Infi-nut", "Unendnuss", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defeating this one isn't so simple", "So einfach lässt sie sich nicht besiegen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Potato Mine", "Kartoffelmine", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A small but potentially dangerous spud", "Eine kleine, aber möglicherweise gefährliche Knolle", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cherry Bomb", "Kirschbombe", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It may be sweet but you shouldnt underestimate it", "Sie mag süß sein, aber unterschätze sie nicht", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jalapeno", "Jalapeño", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I would not want to eat that", "Das würde ich nicht essen wollen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DoomShroom", "Untergangspilz", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A force to be reckoned with", "Eine Macht, mit der man rechnen muss", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Torchwood", "Fackelholz", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It can boost it's allies' power", "Er kann die Kraft seiner Verbündeten verstärken", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MagnetShroom", "Magnetpilz", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weakens the enemy to aid its allies", "Schwächt den Feind, um seinen Verbündeten zu helfen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hypnoshroom", "Hypnopilz", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One mans foe is another mans friend", "Der Feind des einen ist der Freund des anderen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gold Leaf", "Goldblatt", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Foil your opponents' plans by turning over a new leaf", "Vereitle die Pläne deiner Gegner und wende dabei das Blatt", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pumpkin", "Kürbiskopf", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fortify all of your cards with this one simple trick", "Stärke alle deine Karten mit diesem einfachen Trick", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Escape Root", "Fluchtwurzel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Allows other cards the freedom of escaping to safety", "Ermöglicht anderen Karten, sich in Sicherheit zu bringen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coffee bean", "Kaffeebohne", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It can energise plants and unlock further potential", "Sie kann Pflanzen Energie geben und weiteres Potenzial freisetzen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sprout", "Spross", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But a simple sprout, what will it grow into? nobody knows, Limitless potential", "Nur ein einfacher Spross. Was wird daraus wachsen? Niemand weiß es. Das Potenzial ist grenzenlos", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A common browncoat, hungry for brains", "Ein gewöhnlicher Zombie im braunen Mantel, hungrig nach Gehirnen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conehead", "Verkehrshutkopf", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A browncoat that equipped itself with road work equipment", "Ein Zombie im braunen Mantel, der sich mit Straßenbauausrüstung ausgestattet hat", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Buckethead", "Eimerkopf", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "To think headgear could provide so much protection", "Wer hätte gedacht, dass eine Kopfbedeckung so viel Schutz bietet?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flag Zombie", "Fahnenzombie", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A true leader, calling in allies for combat", "Ein wahrer Anführer, der Verbündete zum Kampf ruft", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snorkel", "Schnorchler", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dives in the deep and emerges for a munch", "Taucht in die Tiefe und kommt zum Knabbern wieder hoch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Screen Door", "Fliegengittertür", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I much prefer doors of sturdy wood", "Ich bevorzuge Türen aus robustem Holz", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jack in a box", "Springteufel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one brings tension with such a simple melody", "Eine so einfache Melodie sorgt hier für Spannung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crater", "Krater", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just a hole", "Nur ein Loch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cycle of the forest", "Der Kreislauf des Waldes", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shroom Chunksr", "Pilzbrocken", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chunks of shrooms", "Pilzstücke", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shards of shells", "Schalensplitter", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zombie Arm", "Zombiearm", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A zombie must have dropped this", "Das muss wohl ein Zombie verloren haben", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stray Cat", "Streunende Katze", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How bizarre.. i don't recognise that one", "Wie seltsam... Den erkenne ich nicht", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stray Cat Requiem", "Requiem der streunenden Katze", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Debugger", "Debugger", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Debuggest", "Super-Debugger", Language.German);

            // Starter
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plants vs Zombies", "Plants vs. Zombies", Language.German);
            for (int count = 0; count <= 100; count++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Adds plants vs zombies cards to the mix, with a custom sun currency too. Contains " + count.ToString() + " new cards.", "Fügt Plants-vs.-Zombies-Karten und eine eigene Sonnenressource hinzu. Enthält " + count.ToString() + " " + (count == 1 ? "neue Karte" : "neue Karten") + ".", Language.German);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The original seeds", "Die ursprünglichen Samen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The midnight crew", "Die Mitternachtsmannschaft", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Zen Garden", "Der Zen-Garten", Language.German);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Add Stats", "Werte hinzufügen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, its health, attack, and other sigils will be added to every other non terrain card on your side of the board. Then this card will perish. Cards bearing this sigil cannot be used in sigil transfers or campfires.", "Wenn [creature] ausgespielt wird, werden ihre Gesundheit, ihr Angriff und ihre anderen Siegel zu jeder anderen Karte auf deiner Brettseite hinzugefügt, die kein Gelände ist. Danach kommt diese Karte um. Karten mit diesem Siegel können weder für Siegelübertragungen noch am Lagerfeuer verwendet werden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The power of teamwork", "Die Kraft der Zusammenarbeit", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Add Stats Opponent", "Werte beim Gegner hinzufügen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, its health, attack, and other sigils will be added to every card on the opposing side of the board. Then this card will perish. Cards bearing this sigil cannot be used in sigil transfers or campfires.", "Wenn [creature] ausgespielt wird, werden ihre Gesundheit, ihr Angriff und ihre anderen Siegel zu jeder Karte auf der gegnerischen Brettseite hinzugefügt. Danach kommt diese Karte um. Karten mit diesem Siegel können weder für Siegelübertragungen noch am Lagerfeuer verwendet werden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blight your foes", "Verderbe deine Feinde", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Armor breaker", "Rüstungsbrecher", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it removes all defense sigils from all of the opposing cards.", "Wenn [creature] ausgespielt wird, entfernt sie alle Verteidigungssiegel von allen gegnerischen Karten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Removing defense is a great offense", "Verteidigung zu brechen ist ein guter Angriff", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DoomBringer", "Verderbenbringer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will explode and deal 7 damage to all of the opponent's cards, along with 1 damage to all of the owners cards.", "Am Ende des Zuges ihres Besitzers explodiert [creature] und fügt allen gegnerischen Karten 7 Schaden sowie allen Karten ihres Besitzers 1 Schaden zu.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only destruction lays in its wake", "Nur Zerstörung bleibt zurück", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fade Away", "Langsames Vergehen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will take 1 damage.", "Am Ende des Zuges ihres Besitzers erleidet [creature] 1 Schaden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing can last forever", "Nichts währt ewig", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hard Headed", "Dickkopf", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is attacked, the damage taken will be reduced by 2. Then this sigil will be removed.", "Wenn [creature] angegriffen wird, wird der erlittene Schaden um 2 verringert. Danach wird dieses Siegel entfernt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Headwear is surprisingly good at negating wounds", "Kopfbedeckungen schützen erstaunlich gut vor Verletzungen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hypnotist", "Hypnotiseur", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] gets defeated, its killer will move to take its place.", "Wird [creature] besiegt, bewegt sich die Karte, die sie getötet hat, auf ihren Platz.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "To think that betrayal can happen so easily", "Wie leicht es doch zum Verrat kommen kann", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pierce", "Durchbohren", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Before attacking, [creature] attacks the given card in the opposing queue, it also nullifies the Armored sigil.", "Vor ihrem Angriff greift [creature] die entsprechende Karte in der gegnerischen Warteschlange an und setzt außerdem das Siegel Gepanzert außer Kraft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hiding in the back doesn't protect you here", "Sich hinten zu verstecken schützt dich hier nicht", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spicy", "Scharf", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will explode and deal 4 damage to the opposing card and to the card on the opposing backline. Cards bearing this sigil cannot be used in sigil transfers or campfires.", "Am Ende des Zuges ihres Besitzers explodiert [creature] und fügt der gegenüberliegenden Karte und der Karte dahinter in der gegnerischen Warteschlange 4 Schaden zu. Karten mit diesem Siegel können weder für Siegelübertragungen noch am Lagerfeuer verwendet werden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've never been too fond of spice", "Ich mochte scharfes Essen noch nie besonders", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spore Spreader", "Sporenverbreitung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] defeats another card, a copy of itself will be returned to your hand.", "Besiegt [creature] eine andere Karte, wird eine Kopie von ihr auf deine Hand zurückgelegt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "just how much will these spores spread?", "Wie weit werden sich diese Sporen wohl ausbreiten?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spudow", "Kartoffelknall", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] gets defeated, it deals 4 damage to the opposing card.", "Wird [creature] besiegt, fügt sie der gegenüberliegenden Karte 4 Schaden zu.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Always watch your step in a potato field", "Achte in einem Kartoffelfeld immer auf deine Schritte", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sweet", "Süß", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will explode and deal 3 damage to the cards in the 3 enemy slots around it, then deal 1 damage to the cards in your adjacent slots. Cards bearing this sigil cannot be used in sigil transfers or campfires.", "Am Ende des Zuges ihres Besitzers explodiert [creature] und fügt den Karten auf den 3 feindlichen Feldern um sie herum 3 Schaden und anschließend den Karten auf deinen benachbarten Feldern 1 Schaden zu. Karten mit diesem Siegel können weder für Siegelübertragungen noch am Lagerfeuer verwendet werden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maybe there's a bit more tartness than anticipated", "Vielleicht ist es etwas saurer als erwartet", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scaredy", "Ängstlich", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] loses 1 attack but gains 1 health when against an opposing card whose attack is greater than 0, unless the opposing card retreats too.", "[creature] verliert 1 Angriff, erhält aber 1 Gesundheit, wenn ihr eine Karte mit mehr als 0 Angriff gegenübersteht, außer diese Karte trägt ebenfalls das Siegel Ängstlich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They call it a tactical retreat", "Sie nennen es einen taktischen Rückzug", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zombie Caller", "Zombie-Rufer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, A zombie gets played on each empty adjacent space, though it may have headgear. [define:zep_pvz_zombie]", "Wenn [creature] ausgespielt wird, wird auf jedem leeren benachbarten Feld ein Zombie ausgespielt, der eine Kopfbedeckung tragen kann. [define:zep_pvz_zombie]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A huge wave of zombies is approaching", "Eine riesige Welle Zombies nähert sich", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shrooms", "Pilze", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of mushrooms that the owner has on their side of the table.", "Der durch dieses Siegel dargestellte Wert entspricht der Anzahl der Pilze auf der Brettseite seines Besitzers.", Language.German);

        }
    }
    public class SmallTweakHydraMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for SmallTweak_Hydra Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this Sigil hatches when drawn if 5 unique numbers are in the Health of creatures in your deck, and in their Power, and if there is a creature of 5 unique tribes in your deck. [This Excludes all cards bearing this sigil]", "Eine Karte mit diesem Siegel schlüpft beim Ziehen, wenn die Kreaturen in deinem Stapel 5 verschiedene Gesundheitswerte und 5 verschiedene Angriffswerte aufweisen und sich Kreaturen aus 5 verschiedenen Familien in deinem Stapel befinden. [Alle Karten mit diesem Siegel sind ausgenommen]", Language.German);


        }
    }
    public class MoreItemsMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for MoreItems Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All Brittle", "Alle brüchig", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All Sharp", "Spitze Stacheln für alle", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All cards on the board gain Brittle", "Alle Karten auf dem Brett erhalten Brüchig", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All cards on the board gain Sharp", "Alle Karten auf dem Brett erhalten Spitze Stacheln", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All Split Strike", "Gegabelter Angriff für alle", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All cards on the board gain Split Strike", "Alle Karten auf dem Brett erhalten Gegabelter Angriff", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shuffle Sigils", "Siegel mischen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All sigils on the board are removed and added to a random card", "Alle Siegel auf dem Brett werden entfernt und einer zufälligen Karte hinzugefügt", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No Waterbourne", "Kein Abtauchen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All my cards on the board with Submerge are revealed and the sigil removed", "Alle gegnerischen Karten auf dem Brett mit Abtauchen werden aufgedeckt und verlieren dieses Siegel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hot Meat", "Heißes Fleisch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Using this item at the campfire will save your card from being destroyed for a single turn.", "Am Lagerfeuer eingesetzt, schützt dieser Gegenstand deine Karte während dieses Lagerfeuerbesuchs vor der Zerstörung.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Places Bait Buckets on all empty spaces. The smell is overwhelming.", "Platziert Ködereimer auf allen freien Feldern. Der Geruch ist überwältigend.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mrs. Bomb's Remote", "Frau Bombes Fernbedienung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Places Explode Bots on all empty spaces. Pretty annoying honestly.", "Platziert Sprengbots auf allen freien Feldern. Ziemlich nervig, um ehrlich zu sein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mrs. Bomb's Remote. Click that thing and Explode Bots will drop in every open space.", "Frau Bombes Fernbedienung. Ein Klick darauf und Sprengbots fallen auf jedes freie Feld.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Returns the last friendly card that perished card to your hand", "Bringt die zuletzt umgekommene verbündete Karte auf deine Hand zurück", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mycologist Saw", "Säge der Pilzkundler", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Combine 2 cards on your side of the board to become one.", "Vereint 2 Karten auf deiner Seite des Bretts zu einer einzigen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A temporary abomination if I ever 'saw' one.", "Eine vorübergehende Abscheulichkeit, wie ich sie noch nie gesägt habe.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Survivor", "Überlebender", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose a card on the board to have a chance to either be destroyed or buffed.", "Wähle eine deiner Karten auf dem Brett: Sie wird mit einer gewissen Wahrscheinlichkeit zerstört oder verstärkt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Teeth Jar", "Zahnglas", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Adds 10 teeth to your currency bowl. Does not get added to your scales.", "Fügt deiner Währungsschale 10 Zähne hinzu. Sie werden nicht auf deine Waage gelegt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Card Pack", "Kartenpackung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Adds 5 random cards to your hand.", "Fügt deiner Hand 5 zufällige Karten hinzu.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So that's why my pack mules are coming back short.", "Deshalb kommen meine Packesel also mit zu wenig Ladung zurück.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Meat Cake", "Fleischtorte", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Relights a candle if you have lost a battle. Does not work during boss battles.", "Zündet eine Kerze erneut an, wenn du einen Kampf verloren hast. Funktioniert nicht während Bosskämpfen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In case you change your mind", "Falls du es dir anders überlegst", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trap", "Falle", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Adds a rabbit and pelts to your hand.", "Fügt deiner Hand Felle hinzu.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pick Axe", "Spitzhacke", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All my cards on the board are replaced with a gold nugget", "Alle gegnerischen Karten auf dem Brett werden durch Goldnuggets ersetzt", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Still sharp since the day i crafted it", "Noch genauso scharf wie an dem Tag, an dem ich sie hergestellt habe", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Camera", "Bestienkamera", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Take a picture of a card on the board and add it to your deck", "Fotografiere eine Karte auf dem Brett und füge deiner Hand eine Kopie davon hinzu", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My spare camera, use it wisely.", "Meine Ersatzkamera. Setze sie weise ein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mystical power of that item scared the survivors away.", "Die mystische Kraft dieses Gegenstands hat die Überlebenden vertrieben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "May you continue their legacy", "Mögest du ihr Vermächtnis fortführen", Language.German);

        }
    }
    public class DinoMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Dino Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Akainacephalus", "Akainacephalus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A brutish beast. The first attacks to it's shell it will completely disregard.", "Eine brutale Bestie. Die ersten Angriffe auf ihren Panzer ignoriert sie vollständig.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amalgasaur", "Amalgasaur", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Ever-Changing amalgasaur. It can never decide on its true stats.", "Der sich ständig wandelnde Amalgasaur. Er kann sich nie für seine wahren Werte entscheiden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amber", "Bernstein", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An ancient amber..", "Ein uraltes Stück Bernstein...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ancient Geck", "Uralter Geck", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wow.. CLap.CLap.Calp!", "Wow... Klatsch. Klatsch. Klatsch!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Asteroid", "Asteroid", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A full board clear, but be careful. It crashes after 1 use.", "Räumt das Brett vollständig ab, aber Vorsicht: Nach 1 Einsatz stürzt es ab.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Vial", "Zerbrochenes Fläschchen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oops. You bwoke it.", "Hoppla. Du hast es kaputt gemacht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brontosaurus", "Brontosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The lanky Brontosaurus. It's neck streches so high up, it can catch airborne creatures in mid-air.", "Der schlaksige Brontosaurus. Sein Hals reicht so hoch, dass er flugfähige Kreaturen in der Luft fangen kann.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Asteroid Crashsite", "Asteroideneinschlagstelle", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DJ Bronto", "DJ Bronto", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fossil", "Fossil", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A dinosaur fossil long forgotten. It's slowly falling apart.", "Ein längst vergessenes Dinosaurierfossil. Es zerfällt langsam.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frozen T-Rex", "Eingefrorener T. rex", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's frozen. You may regret releasing it.", "Er ist eingefroren. Du könntest es bereuen, ihn zu befreien.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ghost Dinosaur", "Geisterdinosaurier", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A ghost, stuck in the mortal realm, forever wadnering.", "Ein Geist, gefangen in der Welt der Sterblichen, der ewig umherwandert.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Indominus", "Indominus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Long Bronto", "Langer Bronto", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Megalodon", "Megalodon", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even the great white shivers when confronted by this horror..", "Selbst der Weiße Hai zittert angesichts dieses Schreckens...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mononykus", "Mononykus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What a weird looking creature..", "Was für eine seltsam aussehende Kreatur...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lepidoptera", "Schmetterling", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A feeble moth. Maybe you can find a way to power it up?", "Eine schwache Motte. Vielleicht findest du einen Weg, sie stärker zu machen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bronto Neck", "Brontohals", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Insect Neck", "Insektenhals", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feathered Neck", "Gefiederter Hals", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Furry Neck", "Pelziger Hals", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scaly Neck", "Schuppiger Hals", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Neck", "Hals", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Notosaurus", "Notosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Notosaurus, a giant swimming beast.", "Der Notosaurus, eine riesige schwimmende Bestie.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasaurolophus", "Parasaurolophus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Parasaurolophus. This beast calls its allies to help defend itself.", "Der Parasaurolophus. Diese Bestie ruft ihre Verbündeten zu Hilfe, um sich zu verteidigen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pterodactyl", "Pterodaktylus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Pterodactyl, a fearsome flying beast. It swoops down on its prey with maximum efficiency.", "Der Pterodaktylus, eine furchterregende fliegende Bestie. Er stürzt sich äußerst effizient auf seine Beute.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raptor Hatchling", "Raptor-Jungtier", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A weak dinosaur hatchling. Make sure to protect it.", "Ein schwaches Dinosaurier-Jungtier. Beschütze es gut.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rox", "Rox", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What a curious creature..", "Was für eine merkwürdige Kreatur...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undead Raptor", "Untoter Raptor", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Undead Velociraptor. It manages to stay alive, but only for a while.", "Der untote Velociraptor. Er schafft es, am Leben zu bleiben, aber nur eine Weile.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spiked Raptor", "Stachelraptor", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spinosaurus", "Spinosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Spinosaurus. This beast is agile in water, and on land.", "Der Spinosaurus. Diese Bestie ist im Wasser ebenso wendig wie an Land.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mysterious Egg", "Geheimnisvolles Ei", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't actually know whats in it..", "Ich weiß wirklich nicht, was darin ist...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tessie", "Tessie", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A creature originating from a frozen wasteland..", "Eine Kreatur aus einer gefrorenen Einöde...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "T-rex", "T. rex", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Triceratops", "Triceratops", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mighty Triceratops. It turns from defense, to offense after 1 hit.", "Der mächtige Triceratops. Nach 1 Treffer wechselt er von der Verteidigung zum Angriff.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Velociraptor", "Velociraptor", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Velociraptor, a flighty, agile beast.", "Der Velociraptor, eine schreckhafte und wendige Bestie.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strange Vial", "Seltsames Fläschchen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A demonic fluid in a vile. Under the right conditions it can evolve into a horryfying beast.", "Eine dämonische Flüssigkeit in einem Fläschchen. Unter den richtigen Bedingungen kann sie sich zu einer schrecklichen Bestie entwickeln.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Call Allies", "Verbündete rufen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, it will summon allies adjacent of where the card is placed.", "Wenn eine Karte mit diesem Siegel ausgespielt wird, beschwört sie Verbündete auf den leeren benachbarten Feldern.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dino-Mod Card Pack", "Kartenpaket der Dino-Mod", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Adds silly dinos and prehistoric beasts to the game!", "Fügt dem Spiel alberne Dinos und prähistorische Bestien hinzu!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unknown Hatchling", "Unbekanntes Jungtier", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, a card bearing this sigil has a chance to hatch into a random Dinosaur.", "Am Ende des Zuges hat eine Karte mit diesem Siegel eine Chance, als zufälliger Dinosaurier zu schlüpfen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crumbling", "Zerfall", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, a card bearing this sigil will create 1 bone, but will lose 1 health.", "Am Ende des Zuges erzeugt eine Karte mit diesem Siegel 1 Knochen, verliert aber 1 Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Roar of Terror", "Schreckensgebrüll", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The creature opposing the bearer of this sigil will have its damage set to 1.", "Der Schaden der Kreatur gegenüber dem Träger dieses Siegels wird auf 1 gesetzt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stretching", "Strecken", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, a card bearing this sigil will move, and stretch it's neck.", "Am Ende des Zuges ihres Besitzers bewegt sich eine Karte mit diesem Siegel in die angezeigte Richtung und streckt ihren Hals.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Experimental Vial", "Experimentelles Fläschchen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil dies, it will transform into a monster.", "Wenn eine Karte mit diesem Siegel stirbt, verwandelt sie sich in ein Monster.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DinoMod", "Dino-Mod", Language.German);
        }
    }
