    public class TooManySigilsMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for TooManySigils Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ants Minus", "Ameisen minus eins", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This cards power is equal to the amount of Ant's on field, minus this one.", "Die Kraft dieser Karte entspricht der Anzahl der Ameisen auf dem Feld, diese Karte ausgenommen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card is damaged, It takes half the Damage it would normally.", "Wenn diese Karte Schaden erleidet, erhält sie nur halb so viel wie gewöhnlich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bell Presser", "Glockenläuter", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This cards power is equal to the amount of times the bell has been rung.", "Die Kraft dieser Karte entspricht der Anzahl der Glockenschläge.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Borrowed Time", "Geborgte Zeit", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card perishes its Icecube is summoned if done in time, or else if over the EvolveTurns a corrupt version will be summoned.", "Kommt diese Karte rechtzeitig um, wird ihre im Eis eingeschlossene Kreatur beschworen. Ist die Anzahl der Züge bis zur Entwicklung überschritten, wird stattdessen eine verdorbene Version beschworen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coins Within", "Münzen im Innern", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card is struck it provides 1 foil to its owner, as long as it lives anyway.", "Wird diese Karte getroffen, erhält ihr Besitzer 1 Folienkarte, sofern sie überlebt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Covalesce", "Genesung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil is alive during your endstep, This card gains 1 health.", "Ist eine Karte mit diesem Siegel am Ende deines Zuges am Leben, erhält sie 1 Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Pack", "Totenpaket", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it provides 1 Item to its owner.", "Kommt eine Karte mit diesem Siegel um, erhält ihr Besitzer 1 Gegenstand.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fish Out Of Water", "Fisch auf dem Trockenen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, this card switches from having Airborne to Waterborne and so on. If neither are present will start with Waterborne.", "Am Ende des Zuges wechselt diese Karte zwischen Flugfähig und Wasserwesen. Hat sie keines der beiden Siegel, beginnt sie mit Wasserwesen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain One Battery", "Eine Batterie erhalten", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner gains one Max Energy.", "Wenn eine Karte mit diesem Siegel ausgespielt wird, erhält ihr Besitzer einen Punkt maximale Energie.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain Two Batteries", "Zwei Batterien erhalten", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner gains two Max Energy.", "Wenn eine Karte mit diesem Siegel ausgespielt wird, erhält ihr Besitzer zwei Punkte maximale Energie.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain Three Batteries", "Drei Batterien erhalten", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner gains three Max Energy.", "Wenn eine Karte mit diesem Siegel ausgespielt wird, erhält ihr Besitzer drei Punkte maximale Energie.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain Four Batteries", "Vier Batterien erhalten", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner gains four Max Energy.", "Wenn eine Karte mit diesem Siegel ausgespielt wird, erhält ihr Besitzer vier Punkte maximale Energie.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain Five Batteries", "Fünf Batterien erhalten", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner gains five Max Energy.", "Wenn eine Karte mit diesem Siegel ausgespielt wird, erhält ihr Besitzer fünf Punkte maximale Energie.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain Six Batteries", "Sechs Batterien erhalten", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner gains six Max Energy.", "Wenn eine Karte mit diesem Siegel ausgespielt wird, erhält ihr Besitzer sechs Punkte maximale Energie.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heart Locked", "Herzsperre", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is damaged, It only takes 1 Damage.", "Wenn eine Karte mit diesem Siegel Schaden erleidet, erhält sie nur 1 Schaden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is damaged, a card is added to your hand.", "Wenn eine Karte mit diesem Siegel Schaden erleidet, wird deiner Hand eine Karte hinzugefügt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil is on the field during your endstep, a card is launched to one of your empty spaces.", "Befindet sich eine Karte mit diesem Siegel am Ende deines Zuges auf dem Feld, wird eine Karte auf eines deiner leeren Felder befördert.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lose One Battery", "Eine Batterie verlieren", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner loses one Max Energy.", "Wenn eine Karte mit diesem Siegel ausgespielt wird, verliert ihr Besitzer einen Punkt maximale Energie.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lose Two Batteries", "Zwei Batterien verlieren", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner loses two Max Energy.", "Wenn eine Karte mit diesem Siegel ausgespielt wird, verliert ihr Besitzer zwei Punkte maximale Energie.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lose Three Batteries", "Drei Batterien verlieren", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner loses three Max Energy.", "Wenn eine Karte mit diesem Siegel ausgespielt wird, verliert ihr Besitzer drei Punkte maximale Energie.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lose Four Batteries", "Vier Batterien verlieren", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner loses four Max Energy.", "Wenn eine Karte mit diesem Siegel ausgespielt wird, verliert ihr Besitzer vier Punkte maximale Energie.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lose Five Batteries", "Fünf Batterien verlieren", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner loses five Max Energy.", "Wenn eine Karte mit diesem Siegel ausgespielt wird, verliert ihr Besitzer fünf Punkte maximale Energie.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lose Six Batteries", "Sechs Batterien verlieren", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner loses six Max Energy.", "Wenn eine Karte mit diesem Siegel ausgespielt wird, verliert ihr Besitzer sechs Punkte maximale Energie.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One Fourth Chance Instakill", "Sofortiger Tod mit einem Viertel Chance", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card would be attacked, there is a 25% chance that the striker perishes.", "Wenn diese Karte angegriffen würde, kommt der Angreifer mit einer Wahrscheinlichkeit von 25 % um.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rotting", "Verrottend", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil is alive during your endstep, this card loses 1 power and 1 health.", "Ist eine Karte mit diesem Siegel am Ende deines Zuges am Leben, verliert sie 1 Kraft und 1 Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil is on field during your endstep, this card moves in the direction inscribed in the sigil, and a card is played in its previous space.", "Befindet sich eine Karte mit diesem Siegel am Ende deines Zuges auf dem Feld, bewegt sie sich in die angezeigte Richtung und eine Karte wird auf ihrem vorherigen Feld ausgespielt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is damaged, It takes 1 less Damage.", "Wenn eine Karte mit diesem Siegel Schaden erleidet, erhält sie 1 Schaden weniger.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Treasure Tracker", "Schatzsucher", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At The end of the Owners turn, this card will provide the owner with 1 foil.", "Am Ende des Zuges ihres Besitzers gibt diese Karte ihm 1 Folienkarte.", Language.German);

        }
    }
    public class PizzaTowerCardsMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for PizzaTowerCards Mod");
