            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pizza Tower Themed Cards", "Karten im Pizza-Tower-Stil", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flying Anchovi", "Fliegende Sardelle", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A flying fish, how ridiculous.", "Ein fliegender Fisch, wie lächerlich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bad Rat", "Böse Ratte", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A bad rat. No, not that kind.", "Eine böse Ratte. Nein, nicht so eine.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bandit Chicken", "Banditenhuhn", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Speedy and goes well with sauce.", "Schnell und passt gut zu Soße.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pizza Box Goblin", "Pizzakarton-Goblin", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Expert with demolitions, not so much with clothing.", "Experte für Sprengungen, weniger für Kleidung.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brick", "Ziegel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A chef's best friend and an impressive wall.", "Der beste Freund eines Kochs und eine beeindruckende Mauer.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Can of Whoop Ass", "Dose Prügel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cardboard Tank", "Papp-Panzer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mobile and fragile machine of war.", "Eine mobile und zerbrechliche Kriegsmaschine.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cheese Slime", "Käseschleim", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harmless.", "Harmlos.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fake Peppino", "Falscher Peppino", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A half baked clone of a paranoid chef.", "Ein halbgarer Klon eines paranoiden Kochs.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fork Knight", "Gabelritter", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cowardly, but can still catch someone off guard if placed right.", "Feige, kann aber bei richtiger Platzierung trotzdem jemanden überraschen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gabaghoul", "Gabaghoul", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A deadly spirit, haunting from beyond the grave.", "Ein tödlicher Geist, der aus dem Jenseits heimsucht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gerome", "Gerome", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tower janitor, unlocker of secrets, not here though", "Hausmeister des Turms und Öffner von Geheimnissen. Nur nicht hier.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ghost John", "Geister-John", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The spirit of a fallen John, seeking revenge.", "Der Geist eines gefallenen John, der Rache sucht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ghost King", "Geisterkönig", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruler of the Pizzascape.", "Herrscher von Pizzascape.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ghost Knight", "Geisterritter", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defender of the Pizzascare.", "Verteidiger von Pizzascare.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gustavo", "Gustavo", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A helpful chef, always there for his friends", "Ein hilfsbereiter Koch, der immer für seine Freunde da ist", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kentucky Kenny", "Kentucky-Kenny", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tosses hot wings, too hot.", "Wirft scharfe Hähnchenflügel. Zu scharf.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mini John", "Mini-John", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "May be small, but still packs a punch.", "Er mag klein sein, aber seine Schläge haben es in sich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cheese Monster", "Käsemonster", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Stretcher.", "Der Strecker.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mushroom Monster", "Pilzmonster", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't Make a Sound.", "Kein Mucks.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pineapple Monster", "Ananasmonster", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sausage Monster", "Wurstmonster", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tomato Monster", "Tomatenmonster", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mr. Stick", "Mr. Stick", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An inventor and a salesman, two traits that spell greed", "Erfinder und Verkäufer: zwei Eigenschaften, die für Gier stehen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Noise", "The Noise", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An insufferable nuisance, though he does have tricks up his sleeve", "Ein unerträglicher Störenfried, der allerdings ein paar Asse im Ärmel hat", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Noise Bomb", "The-Noise-Bombe", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dangerous, but can be useful.", "Gefährlich, aber möglicherweise nützlich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Noisette", "Noisette", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The girlfriend of The Noise, also runs a cafe", "The Noises Freundin, die außerdem ein Café betreibt", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Noisey", "Noisey", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Can't attack, but can be used as a wall.", "Kann nicht angreifen, aber als Mauer dienen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Olive Trooper", "Olivenkrieger", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An invasive, alien species.", "Eine invasive außerirdische Spezies.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pencer", "Pencer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tries to act noble, but is really just a coward.", "Er versucht, edel zu wirken, ist aber in Wirklichkeit ein Feigling.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pepperoni Goblin", "Peperoni-Goblin", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An annoyance.", "Eine Nervensäge.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pepperoni Goblin Bat", "Peperoni-Goblin-Fledermaus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An annoyance, but now it flys.", "Eine Nervensäge, die jetzt auch noch fliegt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pepperman", "Paprikamann", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An artist and a narcissist, but strong", "Ein Künstler und Narzisst, aber stark", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Peppibot", "Peppibot", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A robotic replication of a paranoid chef.", "Eine robotische Nachbildung eines paranoiden Kochs.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Peppino", "Peppino", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Paranoid and ready to pound anything into the ground", "Paranoid und bereit, alles in Grund und Boden zu stampfen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Peppino Clone", "Peppino-Klon", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An imperfect clone of a paranoid chef.", "Ein unvollkommener Klon eines paranoiden Kochs.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pillar John", "Säulen-John", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Structural integrity is important, and this one is more than happy to supply", "Strukturelle Stabilität ist wichtig, und er stellt sie nur zu gern bereit", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pineacool", "Ananacool", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's one cool customer.", "Ein echt cooler Kunde.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pizza Face", "Pizzagesicht", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ruler of the Pizza Tower, powerful and fast", "Der Herrscher des Pizza Tower, mächtig und schnell", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ruler of the Pizza Tower, powerful and holding a secret if it can evolve", "Der Herrscher des Pizza Tower, mächtig und mit einem Geheimnis, falls er sich entwickeln kann", Language.German);
