            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "hooved tribe", "Huftierstamm", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "reptile tribe", "Reptilienfamilie", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "insect tribe", "Insektenstamm", Language.German);

        }
    }
    public class AgasMagnificusExpansionMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for AgasMagnificusExpansion Mod");

            // Pack
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aga's Magnificus Expansion", "Agas Magnificus-Erweiterung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An unofficial expansion to the Magnificus Mod featuring [count] unique and colourful mages", "Eine inoffizielle Erweiterung für den Magnificus-Mod mit [count] einzigartigen und farbenfrohen Magiern", Language.German);

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ascension Mage", "Aufstiegsmagier", Language.German);
            MagnificusMod.RegisterCard("Ascension Mage", "Aufstiegsmagier", "Utilising the power of time they grant knowledge and experience from far beyond", "Mit der Macht der Zeit vermitteln sie Wissen und Erfahrung aus weiter Ferne");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Utilising the power of time they grant knowledge and experience from far beyond", "Mit der Macht der Zeit vermitteln sie Wissen und Erfahrung aus weiter Ferne", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ash Mage", "Aschenmagier", Language.German);
            MagnificusMod.RegisterCard("Ash Mage", "Aschenmagier", "Ashes he sheds from his own body, scorching any and all who oppose him", "Asche, die er von seinem eigenen Körper abstreift, versengt jeden, der sich ihm entgegenstellt");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ashes he sheds from his own body, scorching any and all who oppose him", "Asche, die er von seinem eigenen Körper abstreift, versengt jeden, der sich ihm entgegenstellt", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Egg", "Zerbrochenes Ei", Language.German);
            MagnificusMod.RegisterCard("Broken Egg", "Zerbrochenes Ei", "Only the greatest of trainers might find this treasure", "Nur die größten Trainer können diesen Schatz finden");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only the greatest of trainers might find this treasure", "Nur die größten Trainer können diesen Schatz finden", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chosen One", "Auserwählter", Language.German);
            MagnificusMod.RegisterCard("Chosen One", "Auserwählter", "My selected favourite. He still clings to his elders though...", "Mein auserwählter Liebling. Allerdings hängt er immer noch an seinen Älteren...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My selected favourite. He still clings to his elders though...", "Mein auserwählter Liebling. Allerdings hängt er immer noch an seinen Älteren...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cleanliness Mage", "Sauberkeitsmagier", Language.German);
            MagnificusMod.RegisterCard("Cleanliness Mage", "Sauberkeitsmagier", "The proudest of all my pupils. None come close to his bath superpowers", "Der stolzeste meiner Schüler. Niemand kommt an seine Bade-Superkräfte heran");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The proudest of all my pupils. None come close to his bath superpowers", "Der stolzeste meiner Schüler. Niemand kommt an seine Bade-Superkräfte heran", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cleric", "Kleriker", Language.German);
            MagnificusMod.RegisterCard("Cleric", "Kleriker", "With the virtue of his divine Magicks, he bears the pain of all and rids them of their wounds", "Dank seiner göttlichen Magie trägt er den Schmerz aller und heilt ihre Wunden");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With the virtue of his divine Magicks, he bears the pain of all and rids them of their wounds", "Dank seiner göttlichen Magie trägt er den Schmerz aller und heilt ihre Wunden", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clock Mage", "Uhrenmagier", Language.German);
            MagnificusMod.RegisterCard("Clock Mage", "Uhrenmagier", "A wizard with a mastery over time itself. When he nears his demise, he reverts to the past, and comes back to life", "Ein Zauberer, der die Zeit selbst beherrscht. Wenn sein Ende naht, kehrt er in die Vergangenheit zurück und erwacht zu neuem Leben");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A wizard with a mastery over time itself. When he nears his demise, he reverts to the past, and comes back to life", "Ein Zauberer, der die Zeit selbst beherrscht. Wenn sein Ende naht, kehrt er in die Vergangenheit zurück und erwacht zu neuem Leben", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creature Collector", "Kreaturensammler", Language.German);
            MagnificusMod.RegisterCard("Creature Collector", "Kreaturensammler", "He had searched far and wide for his little companion, you see", "Er hatte überall nach seinem kleinen Gefährten gesucht, musst du wissen");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He had searched far and wide for his little companion, you see", "Er hatte überall nach seinem kleinen Gefährten gesucht, musst du wissen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Division Mage", "Teilungsmagier", Language.German);
            MagnificusMod.RegisterCard("Division Mage", "Teilungsmagier", "So the card says at least... I assumed those freaks were long dealth with", "Das behauptet zumindest die Karte... Ich dachte, diese Irren wären längst erledigt");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So the card says at least... I assumed those freaks were long dealth with", "Das behauptet zumindest die Karte... Ich dachte, diese Irren wären längst erledigt", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Egg", "Ei", Language.German);
            MagnificusMod.RegisterCard("Egg", "Ei", "Only the greatest of trainers might find this treasure", "Nur die größten Trainer können diesen Schatz finden");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only the greatest of trainers might find this treasure", "Nur die größten Trainer können diesen Schatz finden", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Druid", "Druide", Language.German);
            MagnificusMod.RegisterCard("Druid", "Druide", "Nature's primal devotee, feeding on sapped mana to cure his allies", "Ein ursprünglicher Anhänger der Natur, der sich von entzogenem Mana nährt, um seine Verbündeten zu heilen");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nature's primal devotee, feeding on sapped mana to cure his allies", "Ein ursprünglicher Anhänger der Natur, der sich von entzogenem Mana nährt, um seine Verbündeten zu heilen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enchanter", "Verzauberer", Language.German);
            MagnificusMod.RegisterCard("Enchanter", "Verzauberer", "He spews cosmic magicks upon his demise, enchanting everything nearby", "Bei seinem Tod versprüht er kosmische Magie und verzaubert alles in der Nähe");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He spews cosmic magicks upon his demise, enchanting everything nearby", "Bei seinem Tod versprüht er kosmische Magie und verzaubert alles in der Nähe", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "EveryMage", "Allmagier", Language.German);
            MagnificusMod.RegisterCard("EveryMage", "Allmagier", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "mage", "Magier", Language.German);
            MagnificusMod.RegisterCard("mage", "Magier", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Evoker", "Hervorrufer", Language.German);
            MagnificusMod.RegisterCard("Evoker", "Hervorrufer", "The ominous crettin of disgusting teachings. It's summonable snakes are of the deadliest caliber", "Dieser unheilvolle Kretin mit seinen widerwärtigen Lehren kann äußerst tödliche Schlangen beschwören");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ominous crettin of disgusting teachings. It's summonable snakes are of the deadliest caliber", "Dieser unheilvolle Kretin mit seinen widerwärtigen Lehren kann äußerst tödliche Schlangen beschwören", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Serpent Summon", "Schlangenbeschwörung", Language.German);
            MagnificusMod.RegisterCard("Serpent Summon", "Schlangenbeschwörung", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Firebender", "Pyromane", Language.German);
            MagnificusMod.RegisterCard("Firebender", "Pyromane", "Chipper in the heat of battle, he is always on the hunt for the next victim of his fireballs", "Selbst im Kampf gut gelaunt, sucht er stets das nächste Opfer seiner Feuerbälle");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chipper in the heat of battle, he is always on the hunt for the next victim of his fireballs", "Selbst im Kampf gut gelaunt, sucht er stets das nächste Opfer seiner Feuerbälle", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Foresight Mage", "Weitsichtmagier", Language.German);
            MagnificusMod.RegisterCard("Foresight Mage", "Weitsichtmagier", "As he gazes upon your future, attacks that may come his way he forever predicts", "Während er in deine Zukunft blickt, sagt er ständig voraus, welche Angriffe ihn treffen könnten");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As he gazes upon your future, attacks that may come his way he forever predicts", "Während er in deine Zukunft blickt, sagt er ständig voraus, welche Angriffe ihn treffen könnten", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Foresight Mage", "Weitsichtmagier", Language.German);
            MagnificusMod.RegisterCard("Foresight Mage", "Weitsichtmagier", "Gazing into the future, he may see any body who dares make an approach", "Beim Blick in die Zukunft kann er jeden sehen, der sich ihm zu nähern wagt");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gazing into the future, he may see any body who dares make an approach", "Beim Blick in die Zukunft kann er jeden sehen, der sich ihm zu nähern wagt", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Glacier", "Gletscher", Language.German);
            MagnificusMod.RegisterCard("Glacier", "Gletscher", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gashadokuro", "Gashadokuro", Language.German);
            MagnificusMod.RegisterCard("Gashadokuro", "Gashadokuro", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Sentinel", "Edelsteinwächter", Language.German);
            MagnificusMod.RegisterCard("Gem Sentinel", "Edelsteinwächter", "the elite warrior unit enchanted with the aura of my moxen", "Die Elitekrieger, verzaubert von der Aura meiner Mox");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the elite warrior unit enchanted with the aura of my moxen", "Die Elitekrieger, verzaubert von der Aura meiner Mox", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grand Astrologer", "Großer Astrologe", Language.German);
            MagnificusMod.RegisterCard("Grand Astrologer", "Großer Astrologe", "The battlefield is forever his playground, and space is his weapon. All is bare before him.", "Das Schlachtfeld ist für immer sein Spielplatz und der Raum seine Waffe. Nichts bleibt vor ihm verborgen.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The battlefield is forever his playground, and space is his weapon. All is bare before him.", "Das Schlachtfeld ist für immer sein Spielplatz und der Raum seine Waffe. Nichts bleibt vor ihm verborgen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gravity Mage", "Schwerkraftmagier", Language.German);
            MagnificusMod.RegisterCard("Gravity Mage", "Schwerkraftmagier", "A master of the forces of gravity. Any and all mox bend to his unwavering will", "Ein Meister der Gravitationskräfte. Jeder Mox beugt sich seinem unbeugsamen Willen");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A master of the forces of gravity. Any and all mox bend to his unwavering will", "Ein Meister der Gravitationskräfte. Jeder Mox beugt sich seinem unbeugsamen Willen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Illusion Mage", "Illusionsmagier", Language.German);
            MagnificusMod.RegisterCard("Illusion Mage", "Illusionsmagier", "Dawning his tricks and disguises, there is none scarier. At first glance", "Mit seinen Tricks und Verkleidungen ist niemand furchteinflößender. Auf den ersten Blick.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dawning his tricks and disguises, there is none scarier. At first glance", "Mit seinen Tricks und Verkleidungen ist niemand furchteinflößender. Auf den ersten Blick.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Infestation Mage", "Befallsmagier", Language.German);
            MagnificusMod.RegisterCard("Infestation Mage", "Befallsmagier", "I suppose a usurping challenger such as yourself could endulge in a dosage of skinwalking", "Ich nehme an, ein machthungriger Herausforderer wie du könnte sich ein wenig Gestaltwandlerei gönnen");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I suppose a usurping challenger such as yourself could endulge in a dosage of skinwalking", "Ich nehme an, ein machthungriger Herausforderer wie du könnte sich ein wenig Gestaltwandlerei gönnen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Insulting Mirror", "Beleidigender Spiegel", Language.German);
            MagnificusMod.RegisterCard("Insulting Mirror", "Beleidigender Spiegel", "The Magick Menace Flies About All Spitting Taunts And Hurling Cheeky Comments, Your Anger, It Channels Into A Strength Of It's Own", "Die magische Bedrohung fliegt umher, schleudert Spott und freche Bemerkungen und wandelt deinen Zorn in eigene Stärke um");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Magick Menace Flies About All Spitting Taunts And Hurling Cheeky Comments, Your Anger, It Channels Into A Strength Of It's Own", "Die magische Bedrohung fliegt umher, schleudert Spott und freche Bemerkungen und wandelt deinen Zorn in eigene Stärke um", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Iron Maiden", "Eiserne Jungfrau", Language.German);
            MagnificusMod.RegisterCard("Iron Maiden", "Eiserne Jungfrau", "My finest of paladins working the finest of hours. No soul goes through his grand wall", "Mein bester Paladin im besten Einsatz. Keine Seele durchdringt seine große Mauer");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My finest of paladins working the finest of hours. No soul goes through his grand wall", "Mein bester Paladin im besten Einsatz. Keine Seele durchdringt seine große Mauer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kickmoxer", "Moxboxer", Language.German);
            MagnificusMod.RegisterCard("Kickmoxer", "Moxboxer", "He dedicated his life to the art of combat, and may adapt to whomever he faces", "Er widmete sein Leben der Kampfkunst und kann sich jedem Gegner anpassen");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He dedicated his life to the art of combat, and may adapt to whomever he faces", "Er widmete sein Leben der Kampfkunst und kann sich jedem Gegner anpassen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mass Grave", "Massengrab", Language.German);
            MagnificusMod.RegisterCard("Mass Grave", "Massengrab", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Agairan", "Meister Agairan", Language.German);
            MagnificusMod.RegisterCard("Master Agairan", "Meister Agairan", "The Crimson Chimera. The teacher of alchemy instills the deadliest of toxins", "Die purpurrote Chimäre. Der Lehrer der Alchemie vermittelt die tödlichsten Gifte");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Crimson Chimera. The teacher of alchemy instills the deadliest of toxins", "Die purpurrote Chimäre. Der Lehrer der Alchemie vermittelt die tödlichsten Gifte", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Bluetwo", "Meister Doppelblau", Language.German);
            MagnificusMod.RegisterCard("Master Bluetwo", "Meister Doppelblau", "The steel knight of sapphire. Even after death her psychic presence commands our foes", "Die Stahlritterin des Saphirs. Selbst nach ihrem Tod beherrscht ihre psychische Präsenz unsere Feinde");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The steel knight of sapphire. Even after death her psychic presence commands our foes", "Die Stahlritterin des Saphirs. Selbst nach ihrem Tod beherrscht ihre psychische Präsenz unsere Feinde", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Doublin", "Meister Doublin", Language.German);
            MagnificusMod.RegisterCard("Master Doublin", "Meister Doublin", "The Bone Lord's messiah. The teacher of prayer has learned apt essence stealing.", "Der Messias des Knochenfürsten. Der Lehrer des Gebets hat das geschickte Stehlen von Essenz erlernt.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bone Lord's messiah. The teacher of prayer has learned apt essence stealing.", "Der Messias des Knochenfürsten. Der Lehrer des Gebets hat das geschickte Stehlen von Essenz erlernt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Megawizard", "Megazauberer", Language.German);
            MagnificusMod.RegisterCard("Megawizard", "Megazauberer", "Hulking he is in his menace, meanacing he is in his dim. Such raw power would never last an eternity", "Gewaltig in seiner Bedrohung, bedrohlich selbst in seinem trüben Geist. Solche rohe Kraft hält nicht ewig");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hulking he is in his menace, meanacing he is in his dim. Such raw power would never last an eternity", "Gewaltig in seiner Bedrohung, bedrohlich selbst in seinem trüben Geist. Solche rohe Kraft hält nicht ewig", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Meteorologist", "Meteorologe", Language.German);
            MagnificusMod.RegisterCard("Meteorologist", "Meteorologe", "They carefully observe the universe, casting storms of meteors upon whom they see fit. Maybe they're cruel? Maybe not? Only they know", "Sie beobachten das Universum aufmerksam und schleudern Meteorstürme auf jene, die sie auswählen. Grausam? Vielleicht, vielleicht auch nicht. Nur sie wissen es");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They carefully observe the universe, casting storms of meteors upon whom they see fit. Maybe they're cruel? Maybe not? Only they know", "Sie beobachten das Universum aufmerksam und schleudern Meteorstürme auf jene, die sie auswählen. Grausam? Vielleicht, vielleicht auch nicht. Nur sie wissen es", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Miniwizard", "Minizauberer", Language.German);
            MagnificusMod.RegisterCard("Miniwizard", "Minizauberer", "A mage accursed by it's miniscule size. Worry not though, to such ends he found a solution.", "Ein Magier, der durch seine winzige Größe verflucht ist. Keine Sorge, er hat eine Lösung gefunden.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mage accursed by it's miniscule size. Worry not though, to such ends he found a solution.", "Ein Magier, der durch seine winzige Größe verflucht ist. Keine Sorge, er hat eine Lösung gefunden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phantom Thief", "Phantomdieb", Language.German);
            MagnificusMod.RegisterCard("Phantom Thief", "Phantomdieb", "A billowing cloud of crime, darting in and out, and stealing his foes", "Eine wallende Verbrechenswolke, die auftaucht und verschwindet und dabei ihre Feinde stiehlt");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A billowing cloud of crime, darting in and out, and stealing his foes", "Eine wallende Verbrechenswolke, die auftaucht und verschwindet und dabei ihre Feinde stiehlt", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Preformence Mage", "Präludiumsmagier", Language.German);
            MagnificusMod.RegisterCard("Preformence Mage", "Präludiumsmagier", "Who knows to what ends his mystery rabbit has been through", "Wer weiß, was sein geheimnisvolles Kaninchen alles durchgemacht hat");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Who knows to what ends his mystery rabbit has been through", "Wer weiß, was sein geheimnisvolles Kaninchen alles durchgemacht hat", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Queen's Familiar", "Vertrauter der Königin", Language.German);
            MagnificusMod.RegisterCard("Queen's Familiar", "Vertrauter der Königin", "A majestic chimera of beautiful beasts. It keeps it's armies close inside", "Eine majestätische Chimäre aus schönen Bestien. Sie hält ihre Armeen nah bei sich, in ihrem Inneren");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A majestic chimera of beautiful beasts. It keeps it's armies close inside", "Eine majestätische Chimäre aus schönen Bestien. Sie hält ihre Armeen nah bei sich, in ihrem Inneren", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RisingHunger", "Wachsender Hunger", Language.German);
            MagnificusMod.RegisterCard("RisingHunger", "Wachsender Hunger", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Roach Familiar", "Kakerlakenvertrauter", Language.German);
            MagnificusMod.RegisterCard("Roach Familiar", "Kakerlakenvertrauter", "A spiritually manufacrued cockroach. It's will allows it ressurection abilities! that ultimately fail.", "Eine geistig erschaffene Kakerlake. Ihr Wille verleiht ihr die Fähigkeit zur Wiederauferstehung! Die letztlich versagt.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A spiritually manufacrued cockroach. It's will allows it ressurection abilities! that ultimately fail.", "Eine geistig erschaffene Kakerlake. Ihr Wille verleiht ihr die Fähigkeit zur Wiederauferstehung! Die letztlich versagt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shadow Wizard", "Schattenzauberer", Language.German);
            MagnificusMod.RegisterCard("Shadow Wizard", "Schattenzauberer", "A mobster of the underseen. He calls the shadows to gang on it's foes", "Ein Gangster aus dem Verborgenen. Er ruft die Schatten, um seine Feinde gemeinsam anzugreifen");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mobster of the underseen. He calls the shadows to gang on it's foes", "Ein Gangster aus dem Verborgenen. Er ruft die Schatten, um seine Feinde gemeinsam anzugreifen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shinobi", "Shinobi", Language.German);
            MagnificusMod.RegisterCard("Shinobi", "Shinobi", "Warrior of the dark, They strike from the unawares, where nobody lays claim or sight", "Krieger der Dunkelheit: Sie schlagen überraschend zu, wo niemand Anspruch erhebt und niemand hinsieht");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warrior of the dark, They strike from the unawares, where nobody lays claim or sight", "Krieger der Dunkelheit: Sie schlagen überraschend zu, wo niemand Anspruch erhebt und niemand hinsieht", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shower Mage", "Duschmagier", Language.German);
            MagnificusMod.RegisterCard("Shower Mage", "Duschmagier", "The outcast of my school and rightfully so! His levels of stentch could only be described with magic...", "Der Ausgestoßene meiner Schule, und das zu Recht! Sein Gestank lässt sich nur mit Magie beschreiben...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The outcast of my school and rightfully so! His levels of stentch could only be described with magic...", "Der Ausgestoßene meiner Schule, und das zu Recht! Sein Gestank lässt sich nur mit Magie beschreiben...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sludge Mage", "Schlammmagier", Language.German);
            MagnificusMod.RegisterCard("Sludge Mage", "Schlammmagier", "An entity of unknown origins, powered off the ill spreading plague to all", "Eine Entität unbekannter Herkunft, von Krankheit angetrieben und überall Seuchen verbreitend");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An entity of unknown origins, powered off the ill spreading plague to all", "Eine Entität unbekannter Herkunft, von Krankheit angetrieben und überall Seuchen verbreitend", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sui-Sage", "Sui-Weiser", Language.German);
            MagnificusMod.RegisterCard("Sui-Sage", "Sui-Weiser", "The leader of a pack, soon to be packed away", "Der Anführer eines Rudels, der bald selbst eingepackt wird");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The leader of a pack, soon to be packed away", "Der Anführer eines Rudels, der bald selbst eingepackt wird", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summoner", "Beschwörer", Language.German);
            MagnificusMod.RegisterCard("Summoner", "Beschwörer", "A mad man of the arts of life, he creates it out of thin air. And with frightning sensibilities", "Ein Wahnsinniger der Lebenskunst, der Leben aus dem Nichts erschafft und dabei erschreckendes Feingefühl zeigt");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mad man of the arts of life, he creates it out of thin air. And with frightning sensibilities", "Ein Wahnsinniger der Lebenskunst, der Leben aus dem Nichts erschafft und dabei erschreckendes Feingefühl zeigt", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Symmetrical Mage", "Symmetriemagier", Language.German);
            MagnificusMod.RegisterCard("Symmetrical Mage", "Symmetriemagier", "Everyone has two sides to them, you see. Especially once they mess with my temper", "Jeder hat zwei Seiten, weißt du. Besonders wenn er mich reizt");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everyone has two sides to them, you see. Especially once they mess with my temper", "Jeder hat zwei Seiten, weißt du. Besonders wenn er mich reizt", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Teleportation Mage", "Teleportationsmagier", Language.German);
            MagnificusMod.RegisterCard("Teleportation Mage", "Teleportationsmagier", "A herald of endless portals, jolting around the battlefield in infinitum and negating incoming strikes", "Ein Herold endloser Portale, der unentwegt über das Schlachtfeld springt und eingehende Angriffe vereitelt");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A herald of endless portals, jolting around the battlefield in infinitum and negating incoming strikes", "Ein Herold endloser Portale, der unentwegt über das Schlachtfeld springt und eingehende Angriffe vereitelt", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Torrent Mage", "Strommagier", Language.German);
            MagnificusMod.RegisterCard("Torrent Mage", "Strommagier", "An apprentice of the ocean utilising it to drown the lands and the terrain above", "Ein Lehrling des Ozeans, der mit dessen Hilfe das Land und das Gelände darüber überflutet");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An apprentice of the ocean utilising it to drown the lands and the terrain above", "Ein Lehrling des Ozeans, der mit dessen Hilfe das Land und das Gelände darüber überflutet", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Untamed Dragon", "Ungezähmter Drache", Language.German);
            MagnificusMod.RegisterCard("Untamed Dragon", "Ungezähmter Drache", "Legends whisper this beast, was once a companion to the mox master Goranj", "Legenden flüstern, dass diese Bestie einst ein Gefährte des Moxmeisters Grange war");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Legends whisper this beast, was once a companion to the mox master Goranj", "Legenden flüstern, dass diese Bestie einst ein Gefährte des Moxmeisters Grange war", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warlock", "Hexenmeister", Language.German);
            MagnificusMod.RegisterCard("Warlock", "Hexenmeister", "A blackened wizard pursuiting the studies of the blood magicks. Such bleeding he turns into a horrible weapon", "Ein geschwärzter Zauberer, der Blutmagie studiert. Das Blutvergießen macht er zu einer schrecklichen Waffe");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A blackened wizard pursuiting the studies of the blood magicks. Such bleeding he turns into a horrible weapon", "Ein geschwärzter Zauberer, der Blutmagie studiert. Das Blutvergießen macht er zu einer schrecklichen Waffe", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wicked Witch", "Boshafte Hexe", Language.German);
            MagnificusMod.RegisterCard("Wicked Witch", "Boshafte Hexe", "A flying jesting witch, laughing your sorrows and posioning your armies", "Eine fliegende, scherzende Hexe, die über deinen Kummer lacht und deine Armeen vergiftet");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A flying jesting witch, laughing your sorrows and posioning your armies", "Eine fliegende, scherzende Hexe, die über deinen Kummer lacht und deine Armeen vergiftet", Language.German);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acid Aura", "Säureaura", Language.German);
            MagnificusMod.RegisterAbility("Acid Aura", "Säureaura");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] deals 1 damage to the creature opposing it every turn", "[creature] fügt der gegenüberliegenden Kreatur in jedem Zug 1 Schaden zu.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakening", "Erwachen", Language.German);
            MagnificusMod.RegisterAbility("Awakening", "Erwachen");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it's owner chooses an ally creature to evolve into a higher form.", "Wenn [creature] ausgespielt wird, wählt ihr Besitzer eine verbündete Kreatur, die sich zu einer höheren Form entwickelt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Backfire Strike", "Rückschlagangriff", Language.German);
            MagnificusMod.RegisterAbility("Backfire Strike", "Rückschlagangriff");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] damages creatures that oppose those it attacks.", "[creature] fügt auch der Karte auf ihrer eigenen Seite Schaden zu, die dem jeweiligen Angriffsziel gegenübersteht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Guzzler", "Blutschlucker", Language.German);
            MagnificusMod.RegisterAbility("Blood Guzzler", "Blutschlucker");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] deals damage, it gains 1 health for each damage dealt.", "Wenn [creature] Schaden verursacht, erhält sie pro verursachtem Schadenspunkt 1 Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brute Parasite", "Brutaler Parasit", Language.German);
            MagnificusMod.RegisterAbility("Brute Parasite", "Brutaler Parasit");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, an Egg is created on the opposing space.", "Wenn [creature] ausgespielt wird, entsteht auf dem gegenüberliegenden Feld ein Ei.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deluge", "Sintflut", Language.German);
            MagnificusMod.RegisterAbility("Deluge", "Sintflut");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, opponent creatures with 0 power drown and get given the Waterborne sigil.", "Wenn [creature] ausgespielt wird, tauchen gegnerische Kreaturen mit 0 Kraft unter und erhalten das Siegel Wasserwesen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Division", "Teilung", Language.German);
            MagnificusMod.RegisterAbility("Division", "Teilung");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After attacking, [creature] splits into 2 identical clones, each bearing half of it's original stats.", "Nach dem Angriff teilt sich [creature] in 2 identische Klone, die jeweils die Hälfte ihrer ursprünglichen Werte besitzen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sentry", "Wache", Language.German);
            MagnificusMod.RegisterAbility("Sentry", "Wache");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature moves into the space opposing [creature], they are dealt 1 damage.", "Wenn eine Kreatur auf das Feld gegenüber von [creature] zieht, erleidet sie 1 Schaden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah, let one never underestimate the speed of a Foresight Mage.", "Ah, unterschätze niemals die Geschwindigkeit eines Weitsichtmagiers.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Healing Aura", "Heilaura", Language.German);
            MagnificusMod.RegisterAbility("Healing Aura", "Heilaura");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] heals nearby allied creatures. The healing is proportionate to it's power.", "[creature] heilt verbündete Kreaturen in der Nähe. Die Heilung ist proportional zu ihrer Kraft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heart Stealer", "Herzensdieb", Language.German);
            MagnificusMod.RegisterAbility("Heart Stealer", "Herzensdieb");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "when [creature] kills a creature, it gets added to your hand.", "Wenn [creature] eine Kreatur tötet, wird die Karte des Opfers deiner Hand hinzugefügt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignis Incant", "Feuerbeschwörung", Language.German);
            MagnificusMod.RegisterAbility("Ignis Incant", "Feuerbeschwörung");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 blood for [creature] to deal 2 damage to a chosen opposing slot.", "Bezahle 1 Blut, damit [creature] einem gewählten gegnerischen Feld 2 Schaden zufügt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Intimidate", "Einschüchtern", Language.German);
            MagnificusMod.RegisterAbility("Intimidate", "Einschüchtern");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is placed on the board, the creature opposing it will flee to their right.", "Wenn [creature] auf das Brett gelegt wird, flieht die gegenüberliegende Kreatur nach rechts.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lonesome", "Einsamkeit", Language.German);
            MagnificusMod.RegisterAbility("Lonesome", "Einsamkeit");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains +1 power for each adjacent empty space.", "[creature] erhält für jedes leere benachbarte Feld +1 Kraft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magic Burst", "Magieausbruch", Language.German);
            MagnificusMod.RegisterAbility("Magic Burst", "Magieausbruch");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After perishing, creatures adjascent to [creature] have their powers increased by 1.", "Nachdem [creature] gestorben ist, erhalten benachbarte Kreaturen 1 Kraft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Psystrike", "Psychoschlag", Language.German);
            MagnificusMod.RegisterAbility("Psystrike", "Psychoschlag");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After [creature] perishes, it manipulates the creature opposing it to strike both of it's adjascent allies.", "Nach ihrem Tod manipuliert [creature] die gegenüberliegende Kreatur, sodass diese ihre beiden benachbarten Verbündeten angreift.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Serpent Master", "Schlangenmeister", Language.German);
            MagnificusMod.RegisterAbility("Serpent Master", "Schlangenmeister");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of every turn, [creature] spawns a Summon Serpent on a space of it's owner's choosing. A Summon Serpent is defined as: 1 power, 1 health.", "Zu Beginn jedes Zuges erzeugt [creature] eine Schlangenbeschwörung auf einem Feld nach Wahl ihres Besitzers. Eine Schlangenbeschwörung besitzt 1 Kraft und 1 Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shadow Strike", "Schattenschlag", Language.German);
            MagnificusMod.RegisterAbility("Shadow Strike", "Schattenschlag");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] calls upon the shadows of creatures adjascent to it's target to strike it as well.", "[creature] ruft die Schatten der Kreaturen neben ihrem Ziel herbei, damit auch sie es angreifen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tidal Lock", "Gezeitensperre", Language.German);
            MagnificusMod.RegisterAbility("Tidal Lock", "Gezeitensperre");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the beginning of it's owner's turn, [creature] will pull small creatures, like squirrels, into it's orbit.", "Zu Beginn des Zuges ihres Besitzers zieht [creature] kleine Kreaturen wie Eichhörnchen in ihre Umlaufbahn.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wizard's Heart", "Zaubererherz", Language.German);
            MagnificusMod.RegisterAbility("Wizard's Heart", "Zaubererherz");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a Mox card corresponding to the current gems you control takes it's place.", "Wenn [creature] stirbt, nimmt eine Mox-Karte, die deinen derzeit kontrollierten Edelsteinen entspricht, ihren Platz ein.", Language.German);

        }
    }
    public class MagModExpansionMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for MagModExpansion Mod");

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beaver's Defense", "Biberverteidigung", Language.German);
            MagnificusMod.RegisterCard("Beaver's Defense", "Biberverteidigung", "Curating defensive dams upon use, not bad for a dire situation.", "Errichtet beim Einsatz defensive Dämme, nicht schlecht in einer brenzligen Lage.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Curating defensive dams upon use, not bad for a dire situation.", "Errichtet beim Einsatz defensive Dämme, nicht schlecht in einer brenzligen Lage.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bomb Sage", "Bombenweiser", Language.German);
            MagnificusMod.RegisterCard("Bomb Sage", "Bombenweiser", "When attacked, this sage is known for blowing up.. Literally and metaphorically.", "Wird dieser Weise angegriffen, ist er dafür bekannt, zu explodieren... im wörtlichen wie im übertragenen Sinn.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When attacked, this sage is known for blowing up.. Literally and metaphorically.", "Wird dieser Weise angegriffen, ist er dafür bekannt, zu explodieren... im wörtlichen wie im übertragenen Sinn.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boxing Champ", "Boxchampion", Language.German);
            MagnificusMod.RegisterCard("Boxing Champ", "Boxchampion", "Rejecting the use of wands, this champion prefers to settle things with his fists.", "Dieser Champion lehnt Zauberstäbe ab und regelt die Dinge lieber mit seinen Fäusten.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rejecting the use of wands, this champion prefers to settle things with his fists.", "Dieser Champion lehnt Zauberstäbe ab und regelt die Dinge lieber mit seinen Fäusten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brontosaurus", "Brontosaurus", Language.German);
            MagnificusMod.RegisterCard("Brontosaurus", "Brontosaurus", "I LOVE DINO MOD!!!!!", "ICH LIEBE DIE DINO-MOD!!!!!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "ICH LIEBE DIE DINO-MOD!!!!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cheese Wizard", "Käsezauberer", Language.German);
            MagnificusMod.RegisterCard("Cheese Wizard", "Käsezauberer", "As trained Chef-Magi, Cheese Wizards use their intellect and Mysticality to accomplish their goals.", "Als ausgebildete Kochmagier nutzen Käsezauberer ihren Verstand und ihre mystischen Fähigkeiten, um ihre Ziele zu erreichen.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As trained Chef-Magi, Cheese Wizards use their intellect and Mysticality to accomplish their goals.", "Als ausgebildete Kochmagier nutzen Käsezauberer ihren Verstand und ihre mystischen Fähigkeiten, um ihre Ziele zu erreichen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cheezling", "Käsling", Language.German);
            MagnificusMod.RegisterCard("Cheezling", "Käsling", "With cheese like this, who needs friends?", "Wer braucht Freunde bei so einem Käse?");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With cheese like this, who needs friends?", "Wer braucht Freunde bei so einem Käse?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Telepathy", "Telepathie", Language.German);
            MagnificusMod.RegisterCard("Telepathy", "Telepathie", "A pupil can gather all the resources they need through sheer will alone.", "Ein Schüler kann alle benötigten Ressourcen allein durch Willenskraft sammeln.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A pupil can gather all the resources they need through sheer will alone.", "Ein Schüler kann alle benötigten Ressourcen allein durch Willenskraft sammeln.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Direct Hit", "Direkttreffer", Language.German);
            MagnificusMod.RegisterCard("Direct Hit", "Direkttreffer", "Upon being casted, your opponent will instantly take three damage.", "Beim Wirken erleidet dein Gegner sofort drei Schaden.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Upon being casted, your opponent will instantly take three damage.", "Beim Wirken erleidet dein Gegner sofort drei Schaden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mysterious Egg", "Geheimnisvolles Ei", Language.German);
            MagnificusMod.RegisterCard("Mysterious Egg", "Geheimnisvolles Ei", "Who knows what could hatch from this egg...", "Wer weiß, was aus diesem Ei schlüpfen könnte...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Who knows what could hatch from this egg...", "Wer weiß, was aus diesem Ei schlüpfen könnte...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Faceless", "Gesichtsloser", Language.German);
            MagnificusMod.RegisterCard("Faceless", "Gesichtsloser", "A hollow shell of a mage, desperately looking for something to call its own.", "Die leere Hülle eines Magiers, die verzweifelt nach etwas sucht, das ihr gehört.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A hollow shell of a mage, desperately looking for something to call its own.", "Die leere Hülle eines Magiers, die verzweifelt nach etwas sucht, das ihr gehört.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Faker", "Fälscher", Language.German);
            MagnificusMod.RegisterCard("Faker", "Fälscher", "Lie. Cheat. Deny. The lengths the Faker will go to in order to escape unharmed...", "Lügen. Betrügen. Leugnen. Was der Fälscher nicht alles tut, um unversehrt zu entkommen...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lie. Cheat. Deny. The lengths the Faker will go to in order to escape unharmed...", "Lügen. Betrügen. Leugnen. Was der Fälscher nicht alles tut, um unversehrt zu entkommen...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Figletar", "Figletar", Language.German);
            MagnificusMod.RegisterCard("Figletar", "Figletar", "A wiz who brought an evil king to a terrible fate, this one knows a thing or two in the ring.", "Ein Zauberer, der einem bösen König ein schreckliches Schicksal bereitete. Im Ring kennt er sich aus.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A wiz who brought an evil king to a terrible fate, this one knows a thing or two in the ring.", "Ein Zauberer, der einem bösen König ein schreckliches Schicksal bereitete. Im Ring kennt er sich aus.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Firestarter", "Brandstifter", Language.German);
            MagnificusMod.RegisterCard("Firestarter", "Brandstifter", "Careful when casting this one, pupils have reported that the dueling grounds can get a little toasty.", "Vorsicht beim Wirken: Schüler berichten, dass es auf dem Duellplatz etwas heiß werden kann.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Careful when casting this one, pupils have reported that the dueling grounds can get a little toasty.", "Vorsicht beim Wirken: Schüler berichten, dass es auf dem Duellplatz etwas heiß werden kann.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fridge Mage", "Kühlschrankmagier", Language.German);
            MagnificusMod.RegisterCard("Fridge Mage", "Kühlschrankmagier", "Its cold atmosphere will chill foes, weakening their offensive power.", "Seine kalte Atmosphäre kühlt Feinde ab und schwächt ihre Angriffskraft.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its cold atmosphere will chill foes, weakening their offensive power.", "Seine kalte Atmosphäre kühlt Feinde ab und schwächt ihre Angriffskraft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gembro", "Edelsteinbrudi", Language.German);
            MagnificusMod.RegisterCard("Gembro", "Edelsteinbrudi", "The ability to tank any hit once, this pupil has high gusto.", "Dieser Schüler kann einmal jeden Treffer einstecken und steckt voller Tatendrang.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ability to tank any hit once, this pupil has high gusto.", "Dieser Schüler kann einmal jeden Treffer einstecken und steckt voller Tatendrang.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Tick", "Edelsteinzecke", Language.German);
            MagnificusMod.RegisterCard("Gem Tick", "Edelsteinzecke", "An elusive tick, which grants power to others via its mox body.", "Eine schwer fassbare Zecke, die anderen durch ihren Mox-Körper Kraft verleiht.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An elusive tick, which grants power to others via its mox body.", "Eine schwer fassbare Zecke, die anderen durch ihren Mox-Körper Kraft verleiht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ghost Dinosaur", "Geisterdinosaurier", Language.German);
            MagnificusMod.RegisterCard("Ghost Dinosaur", "Geisterdinosaurier", "I LOVE DINO MOD!!!!!", "ICH LIEBE DIE DINO-MOD!!!!!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "ICH LIEBE DIE DINO-MOD!!!!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Third Eye", "Drittes Auge", Language.German);
            MagnificusMod.RegisterCard("Third Eye", "Drittes Auge", "Harnessing the power of a third eye, the spell allows its caster to gain any card that it has.", "Mit der Kraft des dritten Auges kann der Anwender dieses Zaubers eine Karte aus seinem verbleibenden Stapel wählen und auf seine Hand nehmen.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harnessing the power of a third eye, the spell allows its caster to gain any card that it has.", "Mit der Kraft des dritten Auges kann der Anwender dieses Zaubers eine Karte aus seinem verbleibenden Stapel wählen und auf seine Hand nehmen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baseball Mage", "Baseballmagier", Language.German);
            MagnificusMod.RegisterCard("Baseball Mage", "Baseballmagier", "This mage's wand doubles as a baseball bat as well. It's suprisingly durable.", "Der Zauberstab dieses Magiers dient auch als Baseballschläger. Er ist überraschend langlebig.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This mage's wand doubles as a baseball bat as well. It's suprisingly durable.", "Der Zauberstab dieses Magiers dient auch als Baseballschläger. Er ist überraschend langlebig.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ice Golem", "Eisgolem", Language.German);
            MagnificusMod.RegisterCard("Ice Golem", "Eisgolem", "Hailing from an icy mountaintop, melting never seemed to phase this brute.", "Diese Bestie stammt von einem eisigen Berggipfel und scheint sich am Schmelzen nie zu stören.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hailing from an icy mountaintop, melting never seemed to phase this brute.", "Diese Bestie stammt von einem eisigen Berggipfel und scheint sich am Schmelzen nie zu stören.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looting Bandit", "Plündernder Bandit", Language.German);
            MagnificusMod.RegisterCard("Looting Bandit", "Plündernder Bandit", "A distant follower of the Master Orlu's Valkyries, training to become just like them.", "Ein entfernter Anhänger der Walküren von Meisterin Orau, der trainiert, um wie sie zu werden.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A distant follower of the Master Orlu's Valkyries, training to become just like them.", "Ein entfernter Anhänger der Walküren von Meisterin Orau, der trainiert, um wie sie zu werden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mana Mage", "Manamagier", Language.German);
            MagnificusMod.RegisterCard("Mana Mage", "Manamagier", "Brings together the energy that emits from Mana to deliver powerful strikes.", "Bündelt die Energie, die vom Mana ausgeht, um mächtige Schläge auszuteilen.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brings together the energy that emits from Mana to deliver powerful strikes.", "Bündelt die Energie, die vom Mana ausgeht, um mächtige Schläge auszuteilen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pondering Pupil", "Grübelnder Schüler", Language.German);
            MagnificusMod.RegisterCard("Pondering Pupil", "Grübelnder Schüler", "It draws from your gem pile using the powers of its mind alone.", "Er zieht allein mit seiner Geisteskraft aus deinem Edelsteinstapel.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It draws from your gem pile using the powers of its mind alone.", "Er zieht allein mit seiner Geisteskraft aus deinem Edelsteinstapel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mirror Mage", "Spiegelmagier", Language.German);
            MagnificusMod.RegisterCard("Mirror Mage", "Spiegelmagier", "Mirror, mirror, on the wall, who's the best Scrybe of them all?", "Spieglein, Spieglein an der Wand, wer ist der beste Wahrschreiber im ganzen Land?");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mirror, mirror, on the wall, who's the best Scrybe of them all?", "Spieglein, Spieglein an der Wand, wer ist der beste Wahrschreiber im ganzen Land?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whack-A-Mage", "Hau-den-Magier", Language.German);
            MagnificusMod.RegisterCard("Whack-A-Mage", "Hau-den-Magier", "Always popping up to cause mischief whenever he can.", "Taucht bei jeder Gelegenheit auf, um Unfug zu treiben.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Always popping up to cause mischief whenever he can.", "Taucht bei jeder Gelegenheit auf, um Unfug zu treiben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mononykus", "Mononykus", Language.German);
            MagnificusMod.RegisterCard("Mononykus", "Mononykus", "I LOVE DINO MOD!!!!!", "ICH LIEBE DIE DINO-MOD!!!!!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "ICH LIEBE DIE DINO-MOD!!!!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PLUTO", "PLUTO", Language.German);
            MagnificusMod.RegisterCard("PLUTO", "PLUTO", "Hmph. So this is where that one went.", "Hmpf. Dort ist er also gelandet.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmph. So this is where that one went.", "Hmpf. Dort ist er also gelandet.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protect", "Beschützen", Language.German);
            MagnificusMod.RegisterCard("Protect", "Beschützen", "In a tough spot? This spell will give one of your cards full immunity to the next attack it recieves.", "In einer schwierigen Lage? Dieser Zauber macht eine deiner Karten gegen ihren nächsten erlittenen Angriff vollständig immun.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In a tough spot? This spell will give one of your cards full immunity to the next attack it recieves.", "In einer schwierigen Lage? Dieser Zauber macht eine deiner Karten gegen ihren nächsten erlittenen Angriff vollständig immun.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pterodactyl", "Pterodaktylus", Language.German);
            MagnificusMod.RegisterCard("Pterodactyl", "Pterodaktylus", "I LOVE DINO MOD!!!!!", "ICH LIEBE DIE DINO-MOD!!!!!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "ICH LIEBE DIE DINO-MOD!!!!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rabbid Sage", "Tollwütiger Hasenweiser", Language.German);
            MagnificusMod.RegisterCard("Rabbid Sage", "Tollwütiger Hasenweiser", "A raving magician with a field of electricity at his disposal.", "Ein rasender Magier mit einem elektrischen Feld zu seiner Verfügung.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A raving magician with a field of electricity at his disposal.", "Ein rasender Magier mit einem elektrischen Feld zu seiner Verfügung.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelemox", "Skelettmox", Language.German);
            MagnificusMod.RegisterCard("Skelemox", "Skelettmox", "A poor skeleton being controlled by a Green Mox, I almost feel bad for it.", "Ein armes Skelett, das von einem Grünen Mox gesteuert wird. Es tut mir fast leid.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A poor skeleton being controlled by a Green Mox, I almost feel bad for it.", "Ein armes Skelett, das von einem Grünen Mox gesteuert wird. Es tut mir fast leid.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slime Wiz", "Schleimzauberer", Language.German);
            MagnificusMod.RegisterCard("Slime Wiz", "Schleimzauberer", "It'll use the slime against the enemies, to drop their attack whence struck.", "Er setzt Schleim gegen Feinde ein, um ihren Angriff zu senken, wenn er getroffen wird.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It'll use the slime against the enemies, to drop their attack whence struck.", "Er setzt Schleim gegen Feinde ein, um ihren Angriff zu senken, wenn er getroffen wird.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Smug Witch", "Eitle Hexe", Language.German);
            MagnificusMod.RegisterCard("Smug Witch", "Eitle Hexe", "The smuggest pupil in all the land. Legends say his Smug Throw is unrivaled.", "Der eitelste Schüler im ganzen Land. Sein Eitelkeitswurf soll der Legende nach unerreicht sein.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The smuggest pupil in all the land. Legends say his Smug Throw is unrivaled.", "Der eitelste Schüler im ganzen Land. Sein Eitelkeitswurf soll der Legende nach unerreicht sein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summon Spear", "Beschwörungsspeer", Language.German);
            MagnificusMod.RegisterCard("Summon Spear", "Beschwörungsspeer", "Roots up a spear from the ground, acting as a sturdy counter.", "Holt einen Speer aus dem Boden hervor, der als robuste Abwehr dient.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Roots up a spear from the ground, acting as a sturdy counter.", "Holt einen Speer aus dem Boden hervor, der als robuste Abwehr dient.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spike Mage", "Stachelmagier", Language.German);
            MagnificusMod.RegisterCard("Spike Mage", "Stachelmagier", "This mage learned from the best of my Pike Mage's Scarecrows.", "Dieser Magier lernte von den besten Vogelscheuchen meines Speermagiers.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This mage learned from the best of my Pike Mage's Scarecrows.", "Dieser Magier lernte von den besten Vogelscheuchen meines Speermagiers.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "T-Rex", "T. rex", Language.German);
            MagnificusMod.RegisterCard("T-Rex", "T. rex", "I LOVE DINO MOD!!!!!", "ICH LIEBE DIE DINO-MOD!!!!!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "ICH LIEBE DIE DINO-MOD!!!!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Virtual King", "Virtueller König", Language.German);
            MagnificusMod.RegisterCard("Virtual King", "Virtueller König", "Self-proclaimed ruler of the virtual lands who won't abide to measly “card game rules”.", "Selbst ernannter Herrscher der virtuellen Lande, der sich nicht an läppische „Kartenspielregeln“ hält.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Self-proclaimed ruler of the virtual lands who won't abide to measly “card game rules”.", "Selbst ernannter Herrscher der virtuellen Lande, der sich nicht an läppische „Kartenspielregeln“ hält.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moron Core", "Trottelkern", Language.German);
            MagnificusMod.RegisterCard("Moron Core", "Trottelkern", "An odd core hailing from an abandoned factory, hates the word \"moron\".", "Ein seltsamer Kern aus einer verlassenen Fabrik, der das Wort „Trottel“ hasst.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An odd core hailing from an abandoned factory, hates the word \"moron\".", "Ein seltsamer Kern aus einer verlassenen Fabrik, der das Wort „Trottel“ hasst.", Language.German);

            // Pack
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Smughtro's MagMod Expansion", "Smughtros MagMod-Erweiterung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Adds 19 common cards, 7 rare cards, 7 spells, and 6 token cards to Magnificus Mod.", "Fügt dem Magnificus-Mod 19 gewöhnliche Karten, 7 seltene Karten, 7 Zauber und 6 Markenkarten hinzu.", Language.German);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death Assist", "Todeshilfe", Language.German);
            MagnificusMod.RegisterAbility("Death Assist", "Todeshilfe");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it will deal 3 damage to the opponent.", "Wenn eine Karte mit diesem Siegel stirbt, fügt sie dem Gegner 3 Schaden zu.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emmental Elemental", "Emmentalelementar", Language.German);
            MagnificusMod.RegisterAbility("Emmental Elemental", "Emmentalelementar");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, summon a Cheezling.", "Wenn eine Karte mit diesem Siegel ausgespielt wird, beschwöre einen Käsling.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "First Strike", "Erstschlag", Language.German);
            MagnificusMod.RegisterAbility("First Strike", "Erstschlag");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, it will instantly attack the opposing lane. If there are no opposing cards, no damage will be dealt.", "Wenn eine Karte mit diesem Siegel ausgespielt wird, greift sie sofort die gegenüberliegende Bahn an. Gibt es keine gegnerischen Karten, wird kein Schaden verursacht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unknown Hatching", "Unbekannter Schlupf", Language.German);
            MagnificusMod.RegisterAbility("Unknown Hatching", "Unbekannter Schlupf");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of your turn, a card bearing this sigil will hatch into a random dinosaur.", "Zu Beginn des Zuges ihres Besitzers schlüpft eine Karte mit diesem Siegel als zufälliger Dinosaurier.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Healthy Death", "Gesunder Tod", Language.German);
            MagnificusMod.RegisterAbility("Healthy Death", "Gesunder Tod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, the cards to the left and right of the sigil bearer heal 1 health.", "Wenn eine Karte mit diesem Siegel stirbt, heilen die Karten links und rechts von ihr jeweils 1 Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mana Mess", "Manachaos", Language.German);
            MagnificusMod.RegisterAbility("Mana Mess", "Manachaos");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw a random non-rare Mana costing card.", "Wenn eine Karte mit diesem Siegel ausgespielt wird, ziehe eine zufällige, nicht seltene Karte mit Manakosten.", Language.German);

        }
    }
    public class FloweysMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for FloweysMod Mod");


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flowey", "Flowey", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A fanatical leader hell-bent on bringing about the apocalypse by reviving the great Cthulhu through behind-the-scenes scheming.", "Ein fanatischer Anführer, der mit geheimen Machenschaften den großen Cthulhu wiederbeleben und die Apokalypse herbeiführen will.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You Idiot", "Du Idiot", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You really are an Idiot if you think you can defeat me!", "Du bist wirklich ein Idiot, wenn du glaubst, mich besiegen zu können!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Omega Flowey", "Omega-Flowey", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You really are an idiot.", "Du bist wirklich ein Idiot.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Patience", "Geduld", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "patient.", "Geduldig.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bravery", "Tapferkeit", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brave.", "Mutig.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Integrity", "Integrität", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "integrant.", "Aufrichtig.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perseverence", "Beharrlichkeit", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Persevering.", "Beharrlich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kindness", "Güte", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kind.", "Freundlich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Justice", "Gerechtigkeit", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Justice.", "Gerechtigkeit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Howdy- Uh i meant Are you ready to Die?", "Hallo! Äh, ich meine: Bist du bereit zu sterben?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Howdy! it's me Flowey, Flowey the Flower!", "Hallo! Ich bin's, Flowey, Flowey die Blume!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You know whats going on here, dont you?", "Du weißt, was hier vor sich geht, nicht wahr?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You just wanted to see me suffer[c:0]!", "Du wolltest mich nur leiden sehen[c:0]!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do You know that ive been watching you?", "Weißt du, dass ich dich die ganze Zeit beobachtet habe?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well i took over Inscryption now!", "Tja, jetzt habe ich Inscryption übernommen!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "and i know what Secrets are hiding beneath Inscryption...", "Und ich weiß, welche Geheimnisse sich unter Inscryption verbergen...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now nothing stands in my Way to take over the World now!", "Jetzt steht meiner Weltherrschaft nichts mehr im Weg!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What do you think this Fight was about?", "Was glaubst du, worum es in diesem Kampf ging?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I just used it as a cover to snoop through Inscryptions Files!", "Ich habe ihn nur als Deckung benutzt, um in Inscryptions Dateien herumzuschnüffeln!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And your PC of course!", "Und natürlich deinen PC!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And you may have noticed, BUT iam now connected to the Internet!", "Du hast es vielleicht bemerkt, ABER ich bin jetzt mit dem Internet verbunden!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So now its time to begin Uploading Inscryption!", "Jetzt wird es Zeit, Inscryption hochzuladen!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You REALLY are an Idiot!", "Du bist WIRKLICH ein Idiot!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't even need the Power of Human Souls if i just use the OLD_DATA!", "Ich brauche nicht einmal die Kraft menschlicher Seelen, wenn ich ALTE_DATEN benutze!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Do you know what you are achieving by this? Nothing", "[c:bR]Weißt du, was du damit erreichst? Nichts.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]You cant get rid of me! No matter what you do, i will always be there!", "[c:bR]Du wirst mich nicht los! Was du auch tust, ich werde immer da sein!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Th- The Souls?", "[c:bR]D-Die Seelen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]wh- where are my Powers?", "[c:bR]W-Wo sind meine Kräfte?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]WHAT HAVE YOU DONE?!", "[c:bR]WAS HAST DU GETAN?!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Floweys Defence dropped to [c:bR]0!", "Floweys Verteidigung ist auf [c:bR]0 gesunken!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]NOOOOOO", "[c:bR]NEEEEEEIN", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What just happened...", "Was ist gerade passiert...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmph seemms you have won this time...", "Hmpf, anscheinend hast du dieses Mal gewonnen...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]NOBODY IS GOING TO HELP YOU!", "[c:bR]NIEMAND WIRD DIR HELFEN!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "STOP CALLING FOR [c:bR]HELP!", "HÖR AUF, NACH [c:bR]HILFE ZU RUFEN!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Did you really think id let you kill me so easily?", "[c:bR]Glaubtest du wirklich, ich würde dich mich so leicht töten lassen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]what the-", "[c:bR]Was zum...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Flowey thought they could just use me...", "[c:bR]Flowey dachte, er könnte mich einfach benutzen...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]He didnt even know what I am!", "[c:bR]Er wusste nicht einmal, was ich bin!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]But now IAM in control...", "[c:bR]Aber jetzt habe ICH die Kontrolle...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]How pathetic of him to not set his HP to Infinite... I won't make that mistake", "[c:bR]Wie erbärmlich, dass er seine LP nicht einmal auf unendlich gesetzt hat... Diesen Fehler mache ich nicht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Try all you want you can't kill me!", "[c:bR]Versuch es, so oft du willst, du kannst mich nicht töten!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Now lets see what this does...", "[c:bR]Mal sehen, was das hier bewirkt...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]WHY CANT I UNDO THIS???", "[c:bR]WARUM KANN ICH DAS NICHT RÜCKGÄNGIG MACHEN???", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SEEING YOU DIE OVER AND OVER AGIAN IS REALLY [c:bR]FUN!", "DIR IMMER WIEDER BEIM STERBEN ZUZUSEHEN, MACHT ECHT [c:bR]SPASS!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOT EVEN A SINGLE POINT OF DAMAGE!", "NICHT EIN EINZIGER SCHADENSPUNKT!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SOMEONE LIKE [c:bR]YOUCANT BEAT ME!", "JEMAND WIE [c:bR]DU KANN MICH NICHT BESIEGEN!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Starvation wont interrupt this fight!", "[c:bR]Die Hungersnot wird diesen Kampf nicht unterbrechen!", Language.German);


        }
    }
    public class UndertaleMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for UndertaleMod Mod");

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Card Pack:U", "Kartenpaket: Undertale", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aaron", "Aaron", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, Aaron the bold, aaron the beautiful. can you manage to take your eyes off his muscles?", "Ach ja, Aaron der Kühne, Aaron der Schöne. Kannst du deine Augen von seinen Muskeln abwenden?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alphys", "Alphys", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dr. Alphys is responsible for the creation of some of the more 'unnerving' individuals you've seen here... or should I say... MULTI-viduals.", "Dr. Alphys ist für einige der „beunruhigenderen“ Individuen verantwortlich, die du hier gesehen hast... oder sollte ich sagen... MULTIviduen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loveable, yet pestulant. The duality of this creature is unparalleled.", "Liebenswert und doch reizbar. Die Zwiespältigkeit dieser Kreatur ist beispiellos.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Asgore", "Asgore", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The king of monsters... he truly is an intimidating force of brute strength, but also... compassion?", "Der König der Monster... eine wahrhaft einschüchternde rohe Kraft, aber auch... Mitgefühl?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "asriel dreemurr", "Asriel Dreemurr", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the most powerful being in the underground... hopefully you find some use for him.", "Das mächtigste Wesen im Untergrund... Hoffentlich findest du Verwendung für ihn.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Astigmatism", "Astigmatismus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The frustrating astigmatism... it can't make up its mind.", "Der frustrierende Astigmatismus... Er kann sich nicht entscheiden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gaster Blaster", "Gaster-Blaster", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Block of Ice", "Eisblock", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A peculiarly large ice cube... Who knows what could be inside.", "Ein ungewöhnlich großer Eiswürfel... Wer weiß, was darin steckt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chara", "Chara", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dogamy", "Dogamy", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dogamy and his wife, Dogaressa, love to tag-team the battlefield. Just don't let one of them perish...", "Dogamy und seine Frau Dogaressa kämpfen gern gemeinsam. Lass nur keinen von ihnen sterben...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dogaressa", "Dogaressa", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Doggo", "Doggo", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah, the blind doggo... He leaps towards any sound of movement.", "Ach, der blinde Doggo... Er springt auf jedes Bewegungsgeräusch zu.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "doodlebog", "Doodlebog", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dummy", "Attrappe", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the bland dummy... not as charismatic as its 'mad' counterpart", "Die langweilige Attrappe... nicht so charismatisch wie ihr „wütendes“ Gegenstück.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amalgamate", "Amalgam", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Endogeny", "Endogeny", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "null", "null", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Final Froggit", "Letzter Froggit", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, the ultimate boss of froggits... Still as easily fooled as its lesser evolved kin.", "Ach ja, der ultimative Froggit-Boss... Noch immer genauso leicht zu täuschen wie seine weniger entwickelten Verwandten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frisk", "Frisk", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Froggit", "Froggit", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, as shy as they come... the froggit wishes not to engage in conflict. how unfortunate.", "Ach ja, schüchterner geht es kaum... Der Froggit will sich nicht auf einen Konflikt einlassen. Wie bedauerlich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "W.D.Gaster", "W. D. Gaster", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "glyde", "Glyde", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such a narcisist, it can only attack if a card is in front of it to watch.", "So ein Narzisst, dass er nur angreifen kann, wenn eine Karte vor ihm zusieht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater Dog", "Großer Hund", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "truly and nobly adequate, it is the highest form of evolution a canine can become.", "Wahrhaft und edel angemessen: Dies ist die höchste Entwicklungsform, die ein hundeartiges Wesen erreichen kann.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gyftrot", "Gyftrot", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Be kind to this creature, it has gone through enough.", "Sei freundlich zu dieser Kreatur, sie hat genug durchgemacht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ice Wolf", "Eiswolf", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, this buff creature spawns a block of ice upon death.", "Ach ja, diese muskulöse Kreatur erzeugt beim Tod einen Eisblock.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Icecap", "Icecap", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jerry", "Jerry", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just ditch him already.", "Lass ihn doch einfach zurück.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Knight Knight", "Knight Knight", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ah, the forboding knight knight... a sentinel of sleep. She is relentless in her conquest..", "Ach, die unheilvolle Knight Knight... eine Wächterin des Schlafes. Bei ihrer Eroberung ist sie unerbittlich...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lemon Bread", "Zitronenbrot", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lesser Dog", "Jung: Hund", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mediocre canine at best... at least in its current form.", "Allenfalls ein mittelmäßiges hundeartiges Wesen... zumindest in seiner jetzigen Form.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loox", "Loox", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cunning Loox EyeWalker... you would be wise not to pick on him.", "Der gerissene Loox EyeWalker... Du solltest ihn besser nicht ärgern.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mad Dummy", "Wütende Attrappe", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dummy?", "Attrappe?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looks can be deceiving...", "Der Schein kann trügen...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Madjick", "Madjick", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "quite the magician...", "Was für ein Zauberer...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Memoryhead", "Memoryhead", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mettaton", "Mettaton", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A hyper-intelligent, systematic, complex data analyzer... reminds me of an old 'friend'.", "Ein hochintelligenter, systematischer und komplexer Datenanalysator... Er erinnert mich an einen alten „Freund“.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mettaton Ex", "Mettaton EX", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Migosp", "Migosp", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the irritable Migosp... its attack increases in a crowd.", "Der reizbare Migosp... Sein Angriff steigt in einer Menge.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Migospel", "Migospel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moldbygg", "Moldbygg", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moldsmal", "Moldsmal", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one's giving me imposter vibes.", "Der hier wirkt auf mich wie ein Hochstapler.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moldessa", "Moldessa", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ah, the gelatinous moldsmal. you probably never wondered what it's made of.", "Ach, der gallertartige Moldsmal. Du hast dich vermutlich nie gefragt, woraus er besteht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Muffet", "Muffet", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, the spider queen. her rapid play game is remarkable.", "Ach ja, die Spinnenkönigin. Ihr schnelles Spiel ist bemerkenswert.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Napstablook", "Napstablook", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The most melancholy of ghosts... it cares not of battle, but still fights to impress.", "Der melancholischste aller Geister... Der Kampf kümmert ihn nicht, doch er kämpft trotzdem, um zu beeindrucken.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "onionsan", "Onionsan", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not much strategy with one... It becomes a random tentcle card one the second turn.", "Viel Strategie steckt nicht dahinter... Im zweiten Zug wird er zu einer zufälligen Tentakelkarte.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A boney brute, papyrus is. He will generate bones like nobody's business.", "Papyrus ist ein knochiger Kraftprotz. Er erzeugt Knochen wie kein Zweiter.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parsnik", "Parsnik", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pyrope", "Pyrope", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Pyrope wants nothing more than to crank up the heat, let's see how fatal that can be.", "Pyrope will nichts lieber, als die Hitze aufzudrehen. Mal sehen, wie tödlich das werden kann.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reaper Bird", "Sensenmannvogel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Royal Guards", "Königsgarde", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "two star-crossed lovers... will they ever focus on what's important?", "Zwei unglückliche Liebende... Werden sie sich je auf das Wesentliche konzentrieren?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "if you pick this card, i feel like i'm going to have a bad time.", "Wenn du diese Karte wählst, habe ich das Gefühl, dass ich eine schlechte Zeit haben werde.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shyren", "Shyren", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The musically inclined shyren... strike her bells to watch her sing.", "Die musikalische Shyren... Schlage ihre Glocken an und höre sie singen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snowdrake", "Snowdrake", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The laughable Snowdrake... striving to prove his father wrong. Will you let him succeed?", "Der lächerliche Snowdrake... Er will seinem Vater beweisen, dass er unrecht hat. Lässt du ihn Erfolg haben?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So Cold", "So kalt", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "so sorry", "so leid", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "he's very sorry", "es tut ihm sehr leid", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Temmie", "Temmie", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Temmie the immortal cat... at least i think she's a feline. Nothing to lose, everything to gain.", "Temmie, die unsterbliche Katze... Zumindest halte ich sie für eine Katze. Nichts zu verlieren, alles zu gewinnen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toriel", "Toriel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The keeper of the ruins... She will protect your side of the board to the best of her ability.", "Die Hüterin der Ruinen... Sie wird deine Seite des Bretts nach besten Kräften beschützen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tsunderplane", "Tsunderplane", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "She can't decide between wanting your attention and wanting you to back off... i suggest the latter.", "Sie kann sich nicht entscheiden, ob du sie beachten oder verschwinden sollst... Ich empfehle Letzteres.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undyne", "Undyne", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How could I forget Undyne? She is a true warrior, with an almighty aim on her spear.", "Wie könnte ich Undyne vergessen? Sie ist eine wahre Kriegerin mit herausragender Treffsicherheit beim Speerwurf.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vegetoid", "Vegetoid", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "eat your greens. (not monitored by the fda)", "Iss dein Grünzeug. (Nicht von der FDA überwacht)", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vulkin", "Vulkin", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A very passionate creature, this one. It's not his intention to harm, but that doesn't stop him.", "Eine sehr leidenschaftliche Kreatur. Er will niemandem wehtun, aber das hält ihn nicht davon ab.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whimsalot", "Whimsalot", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the noble whimsalot... pray that it deems your conquest riteous.", "Der edle Whimsalot... Bete, dass er deinen Feldzug für rechtschaffen hält.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whimsun", "Whimsun", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the insignificant whimsun... it flees the battle after a single attack.", "Der unbedeutende Whimsun... Er verlässt den Kampf, nachdem er einmal angegriffen hat.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woshua", "Woshua", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This creature has no lust for blood. His will lies with helping others. But it will fight if provoked.", "Diese Kreatur ist nicht blutdürstig. Sie will anderen helfen, kämpft aber, wenn man sie provoziert.", Language.German);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Antisocial", "Antisozial", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will gain an attack buff if you have at least 1 other card on your side of the board.", "Eine Karte mit diesem Siegel erhält einen Angriffsbonus, wenn du mindestens 1 weitere Karte auf deiner Seite des Bretts hast.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cleanser", "Reiniger", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will heal every card on its owner's side of the board, except the sigil bearer, for 1 health, at the start of every turn.", "Zu Beginn der Kampfphase ihres Besitzers heilt eine Karte mit diesem Siegel alle anderen Karten auf seiner Brettseite um 1 Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Determination", "Entschlossenheit", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will move to any open slot its owner chooses, it will also gain EXP and LV after a kill. But is that really what you want?", "Eine Karte mit diesem Siegel bewegt sich auf ein freies Feld nach Wahl ihres Besitzers und erhält nach einem Todesstoß EP und Level. Aber ist es wirklich das, was du willst?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Incendiary", "Brandstifter", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil damages a card, that card gains the \"ablaze\" sigil. While a card is ablaze, it will lose one health per turn.", "Greift eine Karte mit diesem Siegel eine Karte an, erhält das Ziel das Siegel Entflammt. Eine entflammte Karte verliert zu Beginn der Kampfphase ihres Besitzers eine Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ablaze", "Entflammt", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will take 1 damage at the start of its owner's turn.", "Zu Beginn der Kampfphase ihres Besitzers erleidet eine Karte mit diesem Siegel 1 Schaden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Indecisive", "Unentschlossen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is struck, it has a 50/50 chance to either gain a stat buff, or perish; creating a copy of this card in your hand.", "Wird eine Karte mit diesem Siegel getroffen, hat sie eine 50/50-Chance, entweder eine Werteverstärkung zu erhalten oder zu sterben; nur beim Tod entsteht eine Kopie auf deiner Hand.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everyone knows Jerry. Makes Turns 2 seconds longer. Cards gain a stat buff when Jerry is killed or sacrificed.", "Jeder kennt Jerry. Er verlängert Züge um 2 Sekunden. Wird Jerry getötet oder geopfert, erhalten die Karten auf der Spielerseite eine Werteverstärkung.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mercy", "Gnade", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A 'Determined' card will be granted this sigil when the card opposing it has low health, prompting the player to make a moral decision.", "Eine Karte mit Entschlossenheit erhält dieses Siegel, wenn die gegenüberliegende Karte wenig Gesundheit hat, und stellt den Spieler vor eine moralische Entscheidung.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Insight", "Einsicht", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you wanna have a bad time?", "Willst du eine schlechte Zeit haben?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Doodler", "Kritzler", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is struck, it will sometimes summon doodlebogs on adjacent spaces.", "Wird eine Karte mit diesem Siegel getroffen, beschwört sie gelegentlich Doodlebogs auf benachbarten Feldern.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Timid", "Schüchtern", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When an opponent card moves into the opposing space of a card bearing this sigil, the sigil bearer will try to move one space over.", "Wenn eine gegnerische Karte auf das Feld gegenüber einer Karte mit diesem Siegel zieht, versucht diese, sich um ein Feld zu bewegen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You ditched Jerry.", "Du hast Jerry zurückgelassen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wow, you guys SUCK at this.", "Wow, ihr seid darin echt MIES.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The wi-fi here sucks.", "Das WLAN hier ist mies.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SHHHH! Im THINKING, guys!!", "PSSST! Ich DENKE nach, Leute!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Get your own, twerp.", "Besorg dir selbst eins, Zwerg.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why are we doing this? What a fail.", "Warum machen wir das? Was für ein Reinfall.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guys. its COLD. Does ANYONE care?", "Leute, es ist KALT. Interessiert das IRGENDWEN?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ka-SIGH", "Seufz...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DUH! Who DOESNT know?", "NA KLAR! Wer weiß das NICHT?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well... can YOU give me a ride home?", "Also... kannst DU mich nach Hause fahren?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awkwarrrd.", "Peeeinlich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So, like, what are you even doing?", "Also, was machst du da eigentlich?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Huh? Did they ditch me...? SOME friends!", "Hä? Haben sie mich zurückgelassen...? Das sind vielleicht Freunde!", Language.German);



        }
    }
    public class RevenantMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for RevenantMod Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DanseMacabre", "Totentanz", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Bones to reverse this sigil effect. At the end of the owner's turn, all creatures on the board gain 1 health.", "Bezahle 2 Knochen, um den Effekt dieses Siegels umzukehren. Am Ende des Zuges seines Besitzers erhalten alle Kreaturen auf dem Brett 1 Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LifeDraw", "Lebenszug", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Blood to draw a card from your main deck.", "Bezahle 1 Blut, um eine Karte aus deinem Hauptstapel zu ziehen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soulgate", "Seelentor", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Bone to gain 1 Energy, lose as much Max Energy at the end of the owner's turn.", "Bezahle 1 Knochen, um 1 Energie zu erhalten. Am Ende des Zuges des Besitzers verlierst du ebenso viel maximale Energie.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Evocation", "Beschwörung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 3 Energy to return the oldest non-Brittle allied creature from the graveyard to your hand.", "Bezahle 3 Energie, um die älteste verbündete Kreatur ohne Brüchig vom Friedhof auf deine Hand zurückzuholen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dormant", "Ruhend", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay Bones equal to the Power of [creature] to disable this sigil for 1 turn. [creature] cannot attack normally.", "Bezahle so viele Knochen, wie [creature] Kraft hat, um dieses Siegel für 1 Zug zu deaktivieren. [creature] kann nicht normal angreifen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Transmute", "Umwandlung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Bones to transform [creature] to its alternate form.", "Bezahle 2 Knochen, um [creature] in ihre alternative Form zu verwandeln.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protector", "Beschützer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures adjacent to [creature] gain 1 max health.", "Kreaturen neben [creature] erhalten 1 maximale Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CalamityEffusion", "Unheilserguss", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, all creatures on the board lose 1 health.", "Am Ende des Zuges ihres Besitzers verlieren alle Kreaturen auf dem Brett 1 Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ComfortAura", "Trost-Aura", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, creatures adjacent to [creature] heal 1 health.", "Am Ende des Zuges ihres Besitzers heilen Kreaturen neben [creature] 1 Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CorpseParty", "Leichenfest", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-brittle creature on the owner's side perishes by combat, a Zombie enters your hand. A Zombie is defined as: 1 Power, 1 Health.", "Wenn eine Kreatur auf der Seite des Besitzers ohne Brüchig im Kampf stirbt, gelangt ein Zombie auf deine Hand. Ein Zombie hat 1 Kraft und 1 Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DeathKnock", "Totenklopfen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes by combat, it strikes back then perishes.", "Wenn [creature] im Kampf stirbt, schlägt sie zurück und kommt anschließend um.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DeathMetal", "Death Metal", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, adjacent creatures and opposing creatures to the left, right, and center of it take 1 damage. It gains 1 Power for each affected creature.", "Wenn [creature] ausgespielt wird, erleiden benachbarte Kreaturen sowie gegnerische Kreaturen links, rechts und gegenüber 1 Schaden. Für jede betroffene Kreatur erhält sie 1 Kraft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defiler", "Schänder", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, draw a card then choose one to discard from your hand.", "Wenn [creature] stirbt, ziehe eine Karte und wähle anschließend eine Karte aus deiner Hand zum Abwerfen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Encroachment", "Vordringen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] creates a copy of it in your hand after 2 turns on the board.", "Nachdem [creature] 2 Züge auf dem Brett war, erzeugt sie eine Kopie von sich auf deiner Hand.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeletonize", "Skelettierung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a Skeleton with its old sigils enters your hand. A Skeleton is defined as: 1 Power, 1 Health, Brittle.", "Wenn [creature] stirbt, gelangt ein Skelett mit ihren bisherigen Siegeln auf deine Hand. Ein Skelett hat 1 Kraft, 1 Gesundheit und Brüchig.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exorcise", "Exorzismus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, Bones equal to the Bone cost of the opposing creature are granted to the player.", "Wenn [creature] ausgespielt wird, erhält der Spieler so viele Knochen, wie die gegenüberliegende Kreatur an Knochen kostet.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ExplodingCorpse", "Explodierende Leiche", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes by combat, all empty spaces on the board are filled with a Guts card.", "Wenn [creature] im Kampf stirbt, werden alle leeren Felder auf dem Brett mit einer Eingeweide-Karte gefüllt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GrudgeCollector", "Grollsammler", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains 1 power for every 2 times opponent creatures deal direct damage to its owner.", "[creature] erhält 1 Kraft für jeweils 2 direkte Schadensereignisse, die gegnerische Kreaturen ihrem Besitzer zufügen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chime Power", "Schellenkraft", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented by this sigil will be equal to the number of Bell cards on the board.", "Der durch dieses Siegel dargestellte Wert entspricht der Anzahl der Glockenkarten auf dem Brett.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Digger Power", "Knochengräberkraft", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented by this sigil will be equal to the number of Bone and Digger related sigils on the board.", "Der durch dieses Siegel dargestellte Wert entspricht der Anzahl der knochen- und gräberbezogenen Siegel auf dem Brett.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignition", "Zündung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains 1 power at the cost of 1 health after each turn on the board.", "Nach jedem Zug auf dem Brett erhält [creature] 1 Kraft auf Kosten von 1 Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Digger Latch", "Knochengräberanheftung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will generate 1 Bone. When it perishes, its owner chooses a creature to gain the Bone Digger sigil.", "Am Ende des Zuges ihres Besitzers erzeugt [creature] 1 Knochen. Wenn sie stirbt, wählt ihr Besitzer eine Kreatur, die das Siegel Knochengräber erhält.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Primed Digger Latch", "Verstärkte Knochengräberanheftung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will generate 1 Bone. When it perishes, its owner chooses a creature to gain this sigil.", "Am Ende des Zuges ihres Besitzers erzeugt [creature] 1 Knochen. Wenn sie stirbt, wählt ihr Besitzer eine Kreatur, die dieses Siegel erhält.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rejuvenation", "Verjüngung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Fledgling sigil.", "Wenn [creature] stirbt, wählt ihr Besitzer eine Kreatur, die das Siegel Entwicklung erhält.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skull Storm", "Totensturm", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, this sigil is replaced with another sigil at random. When it perishes, its owner chooses a creature to gain this sigil.", "Am Ende des Zuges ihres Besitzers wird dieses Siegel durch ein zufälliges anderes Siegel ersetzt. Wenn die tragende Karte stirbt, wählt ihr Besitzer eine Kreatur, die dieses Siegel erhält.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignite", "Entfachen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Ignition sigil.", "Wenn [creature] stirbt, wählt ihr Besitzer eine Kreatur, die das Siegel Zündung erhält.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MacabreBonePulse", "Makabrer Knochenpuls", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it perishes immediately, dropping Bones equal to double the amount of creatures on the owner's side.", "Wenn [creature] ausgespielt wird, stirbt sie sofort und hinterlässt doppelt so viele Knochen, wie Kreaturen auf der Seite ihres Besitzers sind.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maternal", "Mütterlich", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures adjacent to [creature] are inscrybed by Waterborne.", "Kreaturen neben [creature] erhalten das Siegel Wasserwesen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Necrosis", "Nekrose", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] loses 1 power and 1 max health after each turn on the board.", "Nach jedem Zug auf dem Brett verliert [creature] 1 Kraft und 1 maximale Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Limbo", "Vorhölle", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it returns to the top of your deck.", "Wenn [creature] stirbt, kehrt sie oben auf deinen Stapel zurück.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RelentlessRevenant", "Unerbittlicher Wiedergänger", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owner's turn, creatures adjacent to [creature] transform into a Revenant. A Revenant is defined as: 3 Power, 1 Health, Brittle.", "Zu Beginn des Zuges ihres Besitzers verwandeln sich Kreaturen neben [creature] in Wiedergänger. Ein Wiedergänger hat 3 Kraft, 1 Gesundheit und Brüchig.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revedue", "Wiedergänger-Rückkehr", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After attacking, [creature] perishes, then shuffle 2 Revenants with its old sigils into your side deck. A Revenant is defined as: 3 Power, 1 Health, Brittle.", "Nach dem Angreifen stirbt [creature]. Mische dann 2 Wiedergänger mit ihren bisherigen Siegeln in deinen Nebenstapel. Ein Wiedergänger hat 3 Kraft, 1 Gesundheit und Brüchig.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bad Omen", "Schlechtes Omen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will deal 1 damage to the owner.", "Am Ende des Zuges ihres Besitzers fügt [creature] ihm 1 Schaden zu.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rancor", "Groll", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it leaves a permanent 1 power buff in the space it occupied.", "Wenn [creature] stirbt, hinterlässt sie auf ihrem Feld einen dauerhaften Bonus von 1 Kraft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SoothingMeadows", "Beruhigende Auen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, all creatures on the board gain 1 health.", "Am Ende des Zuges ihres Besitzers erhalten alle Kreaturen auf dem Brett 1 Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PartingStroke", "Letzter Strich", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-brittle creature on the owner's side perishes by combat, its owner chooses a creature to lose all of its sigils.", "Wenn eine Kreatur ohne Brüchig auf der Seite des Besitzers im Kampf stirbt, wählt ihr Besitzer eine Kreatur, die alle Siegel verliert.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SplittingCorpse", "Sich teilende Leiche", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes by combat, create a Dysmorphia on each empty adjacent space.", "Wenn [creature] im Kampf stirbt, erzeuge auf jedem leeren benachbarten Feld eine Dysmorphie.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Torpid", "Träge", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] cannot attack normally.", "[creature] kann nicht normal angreifen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grim Epitaph", "Düsteres Epitaph", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, you may choose a card that has already been put to rest, to bring back to your hand.", "Wenn [creature] ausgespielt wird, kannst du eine bereits zur Ruhe gelegte Karte wählen und auf deine Hand zurückholen.", Language.German);


            //card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bigfoot", "Bigfoot", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a mysterious creature lurking the forests, only few have claimed to see one.", "Eine geheimnisvolle Kreatur, die in den Wäldern lauert. Nur wenige behaupten, sie gesehen zu haben.", Language.German);
            GrimoraMod.RegisterCard("Bigfoot", "Bigfoot");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goblin", "Goblin", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A loyal barbaric beast, a fine addition to your army.", "Eine loyale, wilde Bestie, eine gute Ergänzung für deine Armee.", Language.German);
            GrimoraMod.RegisterCard("Goblin", "Goblin");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vila", "Vila", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Love at first sight, at least that's what it wants you to think.", "Liebe auf den ersten Blick, zumindest sollst du das glauben.", Language.German);
            GrimoraMod.RegisterCard("Vila", "Vila");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yaramayawho", "Yaramayawho", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one can never seem to finish it's meals...", "Es scheint seine Mahlzeiten nie aufessen zu können...", Language.German);
            GrimoraMod.RegisterCard("Yaramayawho", "Yaramayawho");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Test Limbs", "Testgliedmaßen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Those parts used to belong to someone, or now some thing...(Test)", "Diese Teile gehörten einst jemandem, oder nun etwas... (Test)", Language.German);
            GrimoraMod.RegisterCard("Test Limbs", "Testgliedmaßen");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Allip", "Allip", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remnants of the insane! You never know what story lies behind that face, but it's sure to be filled with fervor.", "Die Überreste der Wahnsinnigen! Du weißt nie, welche Geschichte sich hinter diesem Gesicht verbirgt, doch sie ist gewiss voller Inbrunst.", Language.German);
            GrimoraMod.RegisterCard("Allip", "Allip");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amami Rabbit", "Amami-Kaninchen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hiding their young in holes, they wish for their best safety.", "Sie verstecken ihre Jungen in Höhlen, um sie bestmöglich zu schützen.", Language.German);
            GrimoraMod.RegisterCard("Amami Rabbit", "Amami-Kaninchen");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ankhame", "Ankhame", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A relic that is drawn to your blood, perhaps you could give it a swing!", "Ein Relikt, das von deinem Blut angezogen wird. Vielleicht solltest du es mal schwingen!", Language.German);
            GrimoraMod.RegisterCard("Ankhame", "Ankhame");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anneta", "Anneta", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That ink keeps on pouring, is she even there anymore? All that death promises is that you will wake up again.", "Die Tinte strömt weiter. Ist sie überhaupt noch da? Alles, was der Tod verspricht, ist, dass du wieder erwachen wirst.", Language.German);
            GrimoraMod.RegisterCard("Anneta", "Anneta");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anorexia", "Anorexie", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Overflowing you with self loathing, you never know what form it may take on next.", "Es überflutet dich mit Selbsthass, und du weißt nie, welche Gestalt es als Nächstes annehmen wird.", Language.German);
            GrimoraMod.RegisterCard("Anorexia", "Anorexie");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lych Bell", "Lichglocke", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems like they found a new way to use bells.", "Offenbar haben sie eine neue Verwendung für Glocken gefunden.", Language.German);
            GrimoraMod.RegisterCard("Lych Bell", "Lichglocke");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TheBloated", "Der Aufgedunsene", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grotesque boils, ready to burst.", "Groteske Geschwüre, bereit zu platzen.", Language.German);
            GrimoraMod.RegisterCard("TheBloated", "Der Aufgedunsene");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BrainJar", "Hirn im Glas", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One shudders to imagine what inhuman thoughts lie inside that jar...", "Der Gedanke an die unmenschlichen Gedanken in diesem Glas lässt einen erschaudern...", Language.German);
            GrimoraMod.RegisterCard("BrainJar", "Hirn im Glas");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Combustor", "Brandkadaver", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh dear, what a fall from such a stimulatingly high status, now all that's left is a metal carcass, and the last of that watchful substance...", "Ach du meine Güte, was für ein Fall aus einem so anregend hohen Rang! Nun bleiben nur eine Metallhülle und die letzten Reste jener wachsamen Substanz...", Language.German);
            GrimoraMod.RegisterCard("Combustor", "Brandkadaver");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Misplayed Stoat", "Verspieltes Hermelin", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A decaying Stoat whose oh-so perfect strategies failed him tremendously.", "Ein verwesendes Hermelin, dessen ach so perfekte Strategien es gewaltig im Stich gelassen haben.", Language.German);
            GrimoraMod.RegisterCard("Misplayed Stoat", "Verspieltes Hermelin");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dysmorphia", "Dysmorphie", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dysmorphia Left.", "Dysmorphie links.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dysmorphia Right.", "Dysmorphie rechts.", Language.German);
            GrimoraMod.RegisterCard("Dysmorphia", "Dysmorphie");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exorcist", "Exorzist", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He still thinks banishing the dammed will do him good, does he know where he is?", "Er glaubt noch immer, dass es ihm nützt, die Verdammten zu verbannen. Weiß er überhaupt, wo er ist?", Language.German);
            GrimoraMod.RegisterCard("Exorcist", "Exorzist");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flembones", "Eiterknochen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wait until he plays with his webcam.", "Warte, bis er mit seiner Webcam spielt.", Language.German);
            GrimoraMod.RegisterCard("Flembones", "Eiterknochen");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stein & Frank", "Stein und Frank", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even hell was not hot enough to split them.", "Selbst die Hölle war nicht heiß genug, um sie zu trennen.", Language.German);
            GrimoraMod.RegisterCard("Stein & Frank", "Stein und Frank");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FulmineSkull", "Donnerschädel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you listen closely, you can still hear the cackling of flame on bone... as well as their voice.", "Wenn du genau hinhörst, kannst du noch das Knistern der Flammen auf den Knochen hören... und ihre Stimme.", Language.German);
            GrimoraMod.RegisterCard("FulmineSkull", "Donnerschädel");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FulurOssa", "Donnerknochen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It never truly left the electric chair.", "Er hat den elektrischen Stuhl nie wirklich verlassen.", Language.German);
            GrimoraMod.RegisterCard("FulurOssa", "Donnerknochen");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PrometheusFlame", "Prometheusflamme", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one is quite unique, the lingering spoils of a thief to benefit humanity! Fancy liver by chance?", "Dieses Stück ist einzigartig: die verbliebene Beute eines Diebes zum Wohl der Menschheit! Lust auf Leber?", Language.German);
            GrimoraMod.RegisterCard("PrometheusFlame", "Prometheusflamme");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guts", "Eingeweide", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Annoying guts.", "Nervige Eingeweide.", Language.German);
            GrimoraMod.RegisterCard("Guts", "Eingeweide");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harbinger", "Vorbote", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A powerful fiend that extols a heavy price for its servitude.", "Ein mächtiger Teufel, der für seine Dienste einen hohen Preis verlangt.", Language.German);
            GrimoraMod.RegisterCard("Harbinger", "Vorbote");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hastur", "Hastur", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He came from beyond the stars, gifting pieces of his reflection to kings and fools alike. Will you accept this piece?", "Er kam von jenseits der Sterne und schenkte Königen und Narren gleichermaßen Stücke seines Spiegelbilds. Nimmst du dieses Stück an?", Language.German);
            GrimoraMod.RegisterCard("Hastur", "Hastur");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Common Imp", "Gewöhnlicher Wicht", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A tiny creature known for causing trouble and mayhem wherever it goes, with its mischievous grin and playful nature!", "Eine winzige Kreatur, die überall Unheil und Chaos anrichtet, mit einem schelmischen Grinsen und verspieltem Wesen!", Language.German);
            GrimoraMod.RegisterCard("Common Imp", "Gewöhnlicher Wicht");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orochimitama", "Orochimitama", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh... He is not supposed to be here...", "Oh... Er sollte nicht hier sein...", Language.German);
            GrimoraMod.RegisterCard("Orochimitama", "Orochimitama");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inochi", "Lebenshauch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A soothing presence to heal your creatures, a calm before the storm.", "Eine beruhigende Präsenz, die deine Kreaturen heilt, die Ruhe vor dem Sturm.", Language.German);
            GrimoraMod.RegisterCard("Inochi", "Lebenshauch");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trail of Torment.", "Pfad der Qual.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Possessed Limbs", "Besessene Gliedmaßen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once attached to a living person, they now belong to something else entirely.", "Einst an einem lebenden Menschen befestigt, gehören sie nun zu etwas völlig anderem.", Language.German);
            GrimoraMod.RegisterCard("Possessed Limbs", "Besessene Gliedmaßen");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mole Digger", "Maulwurf-Totengräber", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The stalwart Mole... Digger? Whatever this is...", "Der standhafte Maulwurf... Totengräber? Was auch immer das ist...", Language.German);
            GrimoraMod.RegisterCard("Mole Digger", "Maulwurf-Totengräber");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nekros", "Nekros", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nekros possesses the board, challenger. Death is his playground.", "Nekros beherrscht das Brett, Herausforderer. Der Tod ist sein Spielplatz.", Language.German);
            GrimoraMod.RegisterCard("Nekros", "Nekros");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NekrosPrime", "Nekros Prime", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will find no greater power... than the simple thought of your own name... inscrybed upon a grave.", "Du wirst keine größere Macht finden... als den bloßen Gedanken an deinen eigenen Namen... auf einem Grabstein eingraviert.", Language.German);
            GrimoraMod.RegisterCard("NekrosPrime", "Nekros Prime");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nuckelavee", "Nuckelavee", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Administrator of its sea, you better hope it's breath doesn't taint your Thralls!", "Der Herr seines Meeres. Hoffe besser, dass sein Atem deine Diener nicht verdirbt!", Language.German);
            GrimoraMod.RegisterCard("Nuckelavee", "Nuckelavee");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OdiousMass", "Abscheuliche Masse", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How unsightly.", "Wie unansehnlich.", Language.German);
            GrimoraMod.RegisterCard("OdiousMass", "Abscheuliche Masse");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orochi", "Orochi", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrifices must be made.", "Opfer müssen gebracht werden.", Language.German);
            GrimoraMod.RegisterCard("Orochi", "Orochi");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Ouro", "Meister Ouro", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "From within the endless torment and suffering, they had somehow learned a way to see inside this poor broken thing... and take away its pain.", "Inmitten endloser Qualen und Leiden fanden sie irgendwie einen Weg, in dieses arme zerbrochene Wesen hineinzusehen... und ihm seinen Schmerz zu nehmen.", Language.German);
            GrimoraMod.RegisterCard("Master Ouro", "Meister Ouro");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An endless cycle of life and death has taken a toll on these discarded remains. The pain was real, but death is never final!", "Ein endloser Kreislauf aus Leben und Tod hat diese zurückgelassenen Überreste gezeichnet. Der Schmerz war echt, doch der Tod ist niemals endgültig!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GanCeann", "GanCeann", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Countless legends tell of the dullahan, but all fail to convey the true extent of its pique.", "Unzählige Legenden erzählen vom Dullahan, doch keine vermittelt das wahre Ausmaß seines Zorns.", Language.German);
            GrimoraMod.RegisterCard("GanCeann", "GanCeann");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dark Prince", "Dunkler Prinz", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The power of fluffy bois shines within you.", "Die Kraft flauschiger Kerlchen leuchtet in dir.", Language.German);
            GrimoraMod.RegisterCard("Dark Prince", "Dunkler Prinz");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stillborn Raven", "Totgeborener Rabe", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feels good to be young again!", "Es fühlt sich gut an, wieder jung zu sein!", Language.German);
            GrimoraMod.RegisterCard("Stillborn Raven", "Totgeborener Rabe");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reanimated", "Wiedererweckter", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BRINGING THE SCYTHE OF DEATH, THE REVENANT... WAIT, WHAT?", "MIT DER SENSE DES TODES KOMMT DER WIEDERGÄNGER... MOMENT, WAS?", Language.German);
            GrimoraMod.RegisterCard("Reanimated", "Wiedererweckter");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RevenantEldritch", "Unheimlicher Wiedergänger", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The source of Calamity, relentless and unerring.", "Die Quelle des Unheils, unerbittlich und unfehlbar.", Language.German);
            GrimoraMod.RegisterCard("RevenantEldritch", "Unheimlicher Wiedergänger");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lazy Bones", "Fauler Knochen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A slothful skeleton with a knack for jokes. I adore him.", "Ein träges Skelett mit einem Händchen für Witze. Ich liebe ihn.", Language.German);
            GrimoraMod.RegisterCard("Lazy Bones", "Fauler Knochen");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelephone", "Skelettfon", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A way to communicate with the dead, for a price.", "Eine Möglichkeit, mit den Toten zu kommunizieren, gegen einen Preis.", Language.German);
            GrimoraMod.RegisterCard("Skelephone", "Skelettfon");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soulgate", "Seelentor", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A chance to enter the soul realm, how delightful? I hope you can afford the price.", "Eine Gelegenheit, das Seelenreich zu betreten, wie erfreulich! Hoffentlich kannst du den Preis bezahlen.", Language.German);
            GrimoraMod.RegisterCard("Soulgate", "Seelentor");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SpadeWarrior", "Pikkrieger", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This fearsome warrior will put you six feet under, in every possible sense.", "Dieser furchterregende Krieger bringt dich unter die Erde, in jeder erdenklichen Hinsicht.", Language.German);
            GrimoraMod.RegisterCard("SpadeWarrior", "Pikkrieger");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "UndeadCivilian", "Untoter Bürger", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lost in eternal darkness, this poor soul desperately seeks a way out. Perhaps you can light his way?", "In ewiger Dunkelheit verloren, sucht diese arme Seele verzweifelt einen Ausweg. Kannst du ihr den Weg erleuchten?", Language.German);
            GrimoraMod.RegisterCard("UndeadCivilian", "Untoter Bürger");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "UndeadVillage", "Untotendorf", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Abandoned and forlorn, this village seeks new residents to fill its decrepit homes.", "Verlassen und trostlos sucht dieses Dorf neue Bewohner für seine verfallenen Häuser.", Language.German);
            GrimoraMod.RegisterCard("UndeadVillage", "Untotendorf");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In every town, in every city, someone must work to bury the dead. In time, they too will be buried.", "In jedem Dorf, in jeder Stadt muss jemand die Toten begraben. Mit der Zeit werden auch sie begraben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dr.Bones", "Dr. Knochen", Language.German);
            GrimoraMod.RegisterCard("Dr.Bones", "Dr. Knochen");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whatever doesn't kill you simply makes you, saner.", "Was dich nicht umbringt, macht dich nur geistig gesünder.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wendigo", "Wendigo", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Returned from the deep wilds, reminds me of a friend.", "Aus der tiefen Wildnis zurückgekehrt, erinnert er mich an einen Freund.", Language.German);
            GrimoraMod.RegisterCard("Wendigo", "Wendigo");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mister Win", "Herr Sieg", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card that wins. It always wins. That's why it's called Mister Win.", "Eine Karte, die gewinnt. Sie gewinnt immer. Deshalb heißt sie Herr Sieg.", Language.German);
            GrimoraMod.RegisterCard("Mister Win", "Herr Sieg");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not that one, I'm afraid.", "Diese nicht, fürchte ich.", Language.German);

            // Dlg
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You... you murderous monster.", "Du... du mörderisches Monster.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh Dear... The flow of Calamity will pursue you.", "Ach du meine Güte... Der Strom des Unheils wird dich verfolgen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hecatomb the village you once lived.", "Richte im Dorf, in dem du einst lebtest, ein Massaker an.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seak for the shovel that digs forever.", "Suche nach der Schaufel, die ewig gräbt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bring me the lost one with a spark in hand.", "Bring mir den Verlorenen mit einem Funken in der Hand.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Compelled by the beckoning of an ancient entity,", "Vom Ruf einer uralten Entität getrieben,", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a forbidden ritual has been initiated.", "hat ein verbotenes Ritual begonnen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The pain reaches the ancient great serpent of death.", "Der Schmerz erreicht die uralte große Schlange des Todes.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrifices must be made.", "Opfer müssen gebracht werden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh... There are no dead cards yet.", "Oh... Es gibt noch keine toten Karten.", Language.German);

            // Pack
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revenant Mod Card Pack", "Revenant-Mod-Kartenpaket", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card pack consists of mainly cards that return to the player in a variety of ways.", "Dieses Kartenpaket besteht hauptsächlich aus Karten, die auf verschiedene Weise zum Spieler zurückkehren.", Language.German);
        }
    }
    public class SquirrelBombMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for SquirrelBombMod Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pipis", "Pipis", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pipis.", "Pipis.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Help", "Hilfe", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn [creature] will sacrifice itself to heal the adjacent cards by 1.", "Am Ende des Zuges ihres Besitzers opfert sich [creature], um benachbarte Karten um 1 Gesundheit zu heilen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pass-through", "Durchlass", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is about to get attacked by a card with an attack higher than this card's health, this card perishes.", "Wenn [creature] von einer Karte angegriffen werden soll, deren Angriff höher ist als ihre Gesundheit, kommt sie um.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spam Call", "Spam-Anruf", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Empty spaces within a circuit completed by [creature] spawn Spam Mail at the end of the owner's turn.", "Am Ende des Zuges ihres Besitzers entsteht auf leeren Feldern innerhalb eines von [creature] geschlossenen Stromkreises Spam-Mail.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NEO Strike", "NEO-Schlag", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike each opposing space that is occupied by a creature and additionally every side of the board occupied by a creature. It will strike directly if no creatures oppose it.", "[creature] greift jedes besetzte gegnerische Feld an und zusätzlich beide Felder jeder gegnerischen Bretthälfte, in der ein Ziel steht. Gibt es kein gegnerisches Ziel, greift sie die beiden mittleren Felder direkt an.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Call for Help", "Hilferuf", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will call for help.", "Am Ende des Zuges ihres Besitzers ruft [creature] um Hilfe.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Run Forth", "Vorwärtssturm", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Before [creature] attacks, its power will be set to at least 1.", "Bevor [creature] angreift, wird ihre Kraft auf mindestens 1 gesetzt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flying Head", "Fliegender Kopf", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The most important part.", "Der wichtigste Teil.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spam Cart", "Spam-Wagen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Filled with spam mail. Absorbs all kinds of attacks.", "Voller Spam-Mails. Absorbiert Angriffe aller Art.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spam Mail", "Spam-Mail", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Has all kinds of unforgettable deals.", "Enthält allerlei unvergessliche Angebote.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big Shooter", "Großschütze", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shoots big shots.", "Feuert große Schüsse ab.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heart on a Chain", "Herz an der Kette", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beautiful.", "Wunderschön.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spamgel", "Spamgel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The result of pressing F1.", "Das Ergebnis eines Drucks auf F1.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hand Phone", "Handtelefon", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you really need anyone else?", "Brauchst du wirklich noch jemand anderen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE POWER OF NEO!!!", "DIE MACHT VON NEO!!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't you wanna be a big shot?", "Willst du nicht eine große Nummer werden?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Receiver", "Empfänger", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The voice runs out eventually.", "Die Stimme versiegt irgendwann.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grizzlipis", "Grizzligutschein", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grizzlipis.", "Grizzligutschein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear Cart", "Bärenwagen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Filled with bears. Absorbs all kinds of attacks.", "Voller Bären. Absorbiert Angriffe aller Art.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear Mail", "Bärenpost", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mail for bears.", "Post für Bären.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear on a Chain", "Bär an der Kette", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear Hand", "Bärentatze", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Squirrel Bomb", "Eichhörnchenbombe", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Squirrels explode when killed, dealing 10 damage to adjacent cards.", "Eichhörnchen explodieren, wenn sie getötet werden, und fügen benachbarten Karten 10 Schaden zu.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dance Party", "Tanzparty", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your cards move each turn. The cards that can't move die.", "Deine Karten bewegen sich in jedem Zug. Karten, die sich nicht bewegen können, sterben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Again", "Noch einmal", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All opponent cards attack twice.", "Alle gegnerischen Karten greifen zweimal an.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Starving", "Hungernd", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pray.", "Bete.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dogfish", "Dornhai", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each battle starts with a Bait Bucket that has Guardian.", "Jeder Kampf beginnt mit einem Ködereimer mit Beschützer.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Annoying Totems", "Nervige Totems", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start each battle with an Annoying totem for your most used tribe.", "Beginne jeden Kampf mit einem Nervig-Totem für deine meistgenutzte Familie.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Painful Draws", "Schmerzhafte Züge", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Drawing from the main deck deals 1 damage.", "Das Ziehen aus dem Hauptstapel verursacht 1 Schaden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Painful Squirrels", "Schmerzhafte Eichhörnchen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Drawing from the side deck deals 1 damage.", "Das Ziehen aus dem Nebenstapel verursacht 1 Schaden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Runes", "Runen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enemy cards of the dominant tribe get random sigils.", "Gegnerische Karten der vorherrschenden Familie erhalten zufällige Siegel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dentistry", "Zahnmedizin", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Item events and Trinket Bearer cards only give pliers.", "Gegenstandsereignisse und Karten mit Ausgerüstet geben nur Zangen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Archived", "Archiviert", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A random card choice is hidden in every card choice event.", "Bei jeder Kartenauswahl ist eine zufällige Kartenoption verborgen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Foundation", "Fundament", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All cards have 1 less attack. Side deck cards have Leader.", "Alle deine Karten haben 1 Angriff weniger. Karten des Nebenstapels erhalten Anführer.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Final Boss v2", "Letzter Boss v2", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Replaces Leshy as the final boss with a true BIG SHOT.", "Ersetzt Leshy als letzten Boss durch eine echte GROSSE NUMMER.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You must dance! Don't stop dancing!!", "Du musst tanzen! Hör nicht auf zu tanzen!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whoever stops dancing at my party will suffer the consequences.", "Wer auf meiner Party aufhört zu tanzen, wird die Folgen tragen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Is that mechanic annoying?", "Ist diese Mechanik nervig?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perfect. That's the point of it.", "Perfekt. Genau darum geht es.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dance my puppet! Daaaance.", "Tanz, meine Marionette! Taaaanz.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You need to pass, remember?", "Du musst passen, erinnerst du dich?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'M [_spamton_0,STEALING] YOUR KROMER", "ICH [_spamton_0,KLAUE] DEIN KROMER", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HOLY [_spamton_0,CUNGADERO] DO I FEEL GOOD", "HEILIGER [_spamton_0,BIMBAM], FÜHLE ICH MICH GUT", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HERE I AM!!!", "HIER BIN ICH!!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BIG", "RIESEN", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<size=10>BIG!!!</size>", "<size=10>RIESIG!!!</size>", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<size=15>[_spamton_0,BIGGER AND BETTER THAN EVER]</size>", "<size=15>[_spamton_0,GRÖSSER UND BESSER ALS JE ZUVOR]</size>", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AND NOW THAT I'M IN THIS [_spamton_0,GAME OF CARDS]", "UND JETZT, WO ICH IN DIESEM [_spamton_0,KARTENSPIEL] BIN", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I CAN'T BE DEFEATED!!!", "ICH KANN NICHT BESIEGT WERDEN!!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PREPARE TO GET [_spamton_0,ABSOLUTELY OBLITERATED] BY [_spamton_0,THE POWER OF NEO]!!!", "MACH DICH BEREIT, VON [_spamton_0,DER MACHT VON NEO] [_spamton_0,VÖLLIG ZERSTÖRT] ZU WERDEN!!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,THIS] AGAIN???", "SCHON WIEDER [_spamton_0,DAS]???", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PREPARE TO GET [_spamton_0,DESTROYED]!!!", "MACH DICH BEREIT, [_spamton_0,ZERSTÖRT] ZU WERDEN!!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU WON'T STAND A CHANGE, YOU [_spamton_0,LITTLE RING WORM]!!!", "DU HAST KEINE CHANCE, DU [_spamton_0,KLEINER RINGWURM]!!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PREPARE TO [_spamton_0,GET PUNCHED] IN YOUR [_spamton_0,FACE]!!!", "MACH DICH BEREIT, EINEN [_spamton_0,SCHLAG] INS [_spamton_0,GESICHT] ZU KRIEGEN!!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BEHOLED [_spamton_0,ME]!!! BEHOLD [_spamton_0,YOU]!!!", "BETRACHTE [_spamton_0,MICH]!!! BETRACHTE [_spamton_0,DICH]!!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,HYPERLINK BLOCKED]", "[_spamton_0,HYPERLINK BLOCKIERT]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ISN'T THIS BODY JUST [_spamton_0,HEAVEN]LY?", "IST DIESER KÖRPER NICHT EINFACH [_spamton_0,HIMMLISCH]?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "2X THE [_spamton_0,FIRE]POWER", "2X SO VIEL [_spamton_0,FEUERKRAFT]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "3X THE [_spamton_0,WATER]POWER", "3X SO VIEL [_spamton_0,WASSERKRAFT]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AND MOST IMPORTANTLY", "UND VOR ALLEM", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FLYING HEADS!!!", "FLIEGENDE KÖPFE!!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WE'LL TURN THOSE [_spamton_0,SCHMOES] AND [_spamton_0,DAVES]", "WIR MACHEN AUS DIESEN [_spamton_0,TROTTELN] UND [_spamton_0,DEPPEN]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "INTO [_spamton_0,ROSEN GRAVES]", "[_spamton_0,ROSENGRÄBER]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THOSE [_spamton_0,CATHODE SCREENS]", "DIESE [_spamton_0,KATHODENBILDSCHIRME]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "INTO [_spamton_0,CATHODE SCREAMS]", "IN [_spamton_0,KATHODENSCHREIE]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DON'T YOU WANNA BE [_spamton_0,PART] OF MY BEAUTIFUL [_spamton_0,HEART]?!", "WILLST DU NICHT [_spamton_0,TEIL] MEINES WUNDERSCHÖNEN [_spamton_0,HERZENS] SEIN?!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OR... DID YOU NEED A LITTLE [_spamton_0,SPECIL TOUR]?", "ODER... BRAUCHTEST DU EINE KLEINE [_spamton_0,SPEZIALFÜHRUNG]?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,WHAT]?!", "[_spamton_0,WAS]?!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU [_spamton_0,STOLE] MY [_spamton_0,HEART]?", "DU HAST MEIN [_spamton_0,HERZ] [_spamton_0,GESTOHLEN]?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU CAN'T BE [_spamton_0,STEALING] MY [_spamton_0,HEART], IT IS MY [_spamton_0,HEART]!", "DU KANNST NICHT MEIN [_spamton_0,HERZ] [_spamton_0,STEHLEN], ES IST MEIN [_spamton_0,HERZ]!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "STOP [_spamton_0,STEALING] MY HEART YOU [_spamton_0,!@#$]", "HÖR AUF, MEIN HERZ ZU [_spamton_0,STEHLEN], DU [_spamton_0,!@#$]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "O U C [_spamton_0,HYPERLINK BLOCKED]", "A U A [_spamton_0,HYPERLINK BLOCKIERT]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU JUST [_spamton_0,BROKE] MY [_spamton_0,$4.99] HEART", "DU HAST GERADE MEIN [_spamton_0,$4.99]-HERZ [_spamton_0,ZERBROCHEN]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DO YOU KNOW THAT IT [_spamton_0,HURTS] WHEN YOU [_spamton_0,DO] THAT?!", "WEISST DU, DASS ES [_spamton_0,WEHTUT], WENN DU DAS [_spamton_0,TUST]?!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DON'T YOU WANNA HELP YOUR OLD PAL SPAMTON?", "WILLST DU NICHT DEINEM ALTEN KUMPEL SPAMTON HELFEN?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THINK! WHAT ARE MY [_spamton_0,EGGS] GOING TO DO!?", "DENK NACH! WAS SOLLEN MEINE [_spamton_0,EIER] NUR TUN?!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT'S CALLING...", "ES RUFT...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MY [_spamton_0,HEART]...", "MEIN [_spamton_0,HERZ]...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MY [_spamton_0,HANDS]...", "MEINE [_spamton_0,HÄNDE]...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LOOK AT THE [_spamton_0,POWER OF NEO] AND ASK YOURSELF...", "SIEH DIR [_spamton_0,DIE MACHT VON NEO] AN UND FRAG DICH...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DON'T YOU?", "WILLST DU NICHT?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DON'T YOU WANNA BE A [_spamton_0,BIG SHOT]!?", "WILLST DU NICHT EINE [_spamton_0,GROSSE NUMMER] WERDEN?!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MY ESTEEM CUSTOMER I SEE YOU ARE ATTEMPTING TO DEPLETE MY HP!", "VEREHRTER KUNDE, ICH SEHE, DU VERSUCHST, MEINE LP AUFZUBRAUCHEN!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'LL ADMIT YOU'VE GOT SOME [_spamton_0,GUTS]!", "ICH GEBE ZU, DU HAST [_spamton_0,MUMM]!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BUT IN A [_spamton_0,1 FOR 1] BATTLE, NEO NEVER LOSES!!!", "ABER IN EINEM [_spamton_0,1-GEGEN-1]-KAMPF VERLIERT NEO NIE!!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT'S TIME FOR A LITTLE [_spamton_0,BLUELIGHT SPECIL]", "ZEIT FÜR EIN KLEINES [_spamton_0,BLAULICHT-SONDERANGEBOT]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ARE YOU [_spamton_0,SURPRISED] THAT YOU CAN'T JUST [_spamton_0,DESTROY] ME WITH YOUR [_spamton_0,PATHETIC LITTLE] [_spamton_0,CARDS]?", "BIST DU [_spamton_0,ÜBERRASCHT], DASS DU MICH NICHT MIT DEINEN [_spamton_0,ERBÄRMLICHEN KLEINEN] [_spamton_0,KARTEN] [_spamton_0,ZERSTÖREN] KANNST?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DIDN'T YOU KNOW [_spamton_0,NEO] IS FAMOUS FOR ITS HIGH DEFENSE!?", "WUSSTEST DU NICHT, DASS [_spamton_0,NEO] FÜR SEINE HOHE VERTEIDIGUNG BERÜHMT IST?!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOW... ENJ0Y THE FIR3WORKS!!!", "JETZT... G3NIESS DAS FEUERW3RK!!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ENJOY THE FIREWORKS!!!!", "GENIESS DAS FEUERWERK!!!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT?", "WAS?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,WHO] ARE YOU TRYING TO [_spamton_0,CALL]???", "[_spamton_0,WEN] WILLST DU [_spamton_0,ANRUFEN]???", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU HAVE NO [_spamton_0,FRIENDS] IN THIS [_spamton_0,WORLD]!!!", "DU HAST KEINE [_spamton_0,FREUNDE] IN DIESER [_spamton_0,WELT]!!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THEY'RE ALL [_spamton_0,PAPER CARDS]!!!", "DAS SIND DOCH ALLES [_spamton_0,PAPIERKARTEN]!!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHO'RE YOU GONNA CALL, THE [_spamton_0,POLICE]?", "WEN WILLST DU RUFEN, DIE [_spamton_0,POLIZEI]?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU'RE [_spamton_0,PATHETIC]!!", "DU BIST [_spamton_0,ERBÄRMLICH]!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,SCREAMING] FOR [_spamton_0,HELP] [_spamton_0,AT THE BOTTOM OF A DUMPSTER]!!!", "[_spamton_0,SCHREIEN] NACH [_spamton_0,HILFE] [_spamton_0,AM BODEN EINES MÜLLCONTAINERS]!!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THERE'S NO [_spamton_0,HELP] FOR YOU!!!", "FÜR DICH GIBT ES KEINE [_spamton_0,HILFE]!!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOUR [_spamton_0,VOICE] IS GOING TO RUN OUT EVENTUALLY!!", "DEINE [_spamton_0,STIMME] WIRD IRGENDWANN VERSAGEN!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GIVE UP!!!", "GIB AUF!!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU CAN'T WIN!!!", "DU KANNST NICHT GEWINNEN!!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I AM UNSTOPPABLE!!!", "ICH BIN UNAUFHALTSAM!!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOUR [_spamton_0,FREE TRIAL OF] LIFE IS ABOUT TO [_spamton_0,EXPIRE]!!!", "DEINE [_spamton_0,KOSTENLOSE TESTVERSION] DES LEBENS WIRD BALD [_spamton_0,ABLAUFEN]!!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,GOOBERT]?", "[_spamton_0,GLIBBERBERT]?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IS IT THAT [_spamton_0,PATHETIC] LITTLE [_spamton_0,JAR] OF [_spamton_0,GOO]?", "IST DAS DIESES [_spamton_0,ERBÄRMLICHE] KLEINE [_spamton_0,GLAS] VOLLER [_spamton_0,SCHLEIM]?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT [_spamton_0,HELP] WILL IT [_spamton_0,PROVIDE] TO [_spamton_0,YOU]???", "WELCHE [_spamton_0,HILFE] KANN ER [_spamton_0,DIR] [_spamton_0,BIETEN]???", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,MAGNIFICUS]??", "[_spamton_0,MAGNIFICUS]??", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT IS A [_spamton_0,MAGNIFICUS]? IS IT A KIND OF [_spamton_0,BLOWFISH]?", "WAS IST EIN [_spamton_0,MAGNIFICUS]? EINE ART [_spamton_0,KUGELFISCH]?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT'S A [_spamton_0,BLOWFISH] GONNA [_spamton_0,DO TO ME]??", "WAS WILL MIR EIN [_spamton_0,KUGELFISCH] SCHON [_spamton_0,ANTUN]??", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,LESHY]???", "[_spamton_0,LESHY]???", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IS THAT THE [_spamton_0,GUY] WHO I [_spamton_0,HIT] AT THE BEGGINING OF OUR [_spamton_0,FIGHT]???", "IST DAS DER [_spamton_0,TYP], DEN ICH ANFANGS IN UNSEREM [_spamton_0,KAMPF] [_spamton_0,GESCHLAGEN] HABE???", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HA! I'M NOT EVEN SURE THAT HE IS [_spamton_0,ALIVE AND WELL]!!!", "HA! ICH BIN NICHT MAL SICHER, OB ER NOCH [_spamton_0,AM LEBEN UND WOHLAUF] IST!!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_1,ROYAL]?", "[_spamton_1,ROYAL]?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ROYAL [_spamton_0,WHAT]? ROYAL [_spamton_0,WHO]?", "ROYAL [_spamton_0,WAS]? ROYAL [_spamton_0,WER]?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,WHO/WHAT/WHEN/WHY/HOW] IS [_spamton_0,ROYAL]?", "[_spamton_0,WER/WAS/WANN/WARUM/WIE] IST [_spamton_0,ROYAL]?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU'RE SO PATHETIC", "DU BIST SO ERBÄRMLICH", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MUMBLING NONSENSE WORDS THROUGH A [_spamton_0,PLAYING CARD]", "DU MURMELST UNSINN DURCH EINE [_spamton_0,SPIELKARTE]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DO YOU THINK YOU CAN [_spamton_0,AVOID] YOUR [_spamton_0,UNAVOIDABLE, QUICKLY APPROACHING] DEMISE?", "GLAUBST DU, DU KANNST DEINEM [_spamton_0,UNVERMEIDLICHEN UND RASCH NAHENDEN] ENDE [_spamton_0,ENTGEHEN]?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,THERE]", "[_spamton_0,DORT]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT ARE YOU GONNA DO WITHOUT YOUR [_spamton_0,COMMUNICATION DEVICE]???", "WAS WILLST DU OHNE DEIN [_spamton_0,KOMMUNIKATIONSGERÄT] TUN???", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WAIT IS IT JUST [_spamton_0,ME]", "WARTE, BILDE NUR [_spamton_0,ICH] MIR DAS EIN", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OR DOES IT SOUND LIKE A [_spamton_0,SHIP] IS COMING [_spamton_0,OUR] WAY??", "ODER KLINGT ES, ALS KÄME EIN [_spamton_0,SCHIFF] AUF [_spamton_0,UNS] ZU??", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT'S PROBABLY [_spamton_0,NOTHING] [_spamton_0,AT HALF PRICE]", "DAS IST BESTIMMT [_spamton_0,NICHTS] [_spamton_0,ZUM HALBEN PREIS]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT'S PROBABLY JUST A SOUND IN MY [_spamton_0,HEAD], IN MY [_spamton_0,EARS]", "DAS IST BESTIMMT NUR EIN GERÄUSCH IN MEINEM [_spamton_0,KOPF], IN MEINEN [_spamton_0,OHREN]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THERE'S NO WAY A [_spamton_0,SHIP] COULD FIT IN THIS LITTLE [_spamton_0,CABIN FOR SALE]", "EIN [_spamton_0,SCHIFF] PASST UNMÖGLICH IN DIESE KLEINE [_spamton_0,HÜTTE ZU VERKAUFEN]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU WILL NEVER DEFEAT-", "DU WIRST MICH NIE BESIEGEN-", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SAY [_spamton_0,GOODBYE] [_spamton_0,TO YOUR FRIENDS AND FAMILY]", "SAG [_spamton_0,DEINEN FREUNDEN UND DEINER FAMILIE] [_spamton_0,LEB WOHL]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE [_spamton_0,POWER OF NEO] WAS TOO MUCH FOR YOU", "DIE [_spamton_0,MACHT VON NEO] WAR ZU STARK FÜR DICH", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CONFIDENTIAL", "VERTRAULICH", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DEFEATED BY A WEAKLING HUMAN...", "VON EINEM SCHWÄCHLICHEN MENSCHEN BESIEGT...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOOOOOOOOOOOOOOO!!!!!!", "NEEEEEEEEEEEIN!!!!!!", Language.German);


        }
    }
