            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It grew a tail...", "Ihm ist ein Schwanz gewachsen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased rattler", "Verseuchte Klapperschlange", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The disease has given this thing poison", "Die Krankheit hat dieses Ding giftig gemacht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased raven", "Verseuchter Rabe", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It looks like it has gone mad", "Es sieht aus, als wäre er wahnsinnig geworden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased ringworm", "Verseuchter Ringwurm", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased skunk", "Verseuchtes Stinktier", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This damned disease has gotten to even the smallest of critters", "Diese verdammte Krankheit hat selbst die kleinsten Tiere erwischt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased smoke", "Verseuchter Rauch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That thing scares me", "Dieses Ding macht mir Angst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased urayuli", "Verseuchter Urayuli", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's gotten weaker", "Es ist schwächer geworden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased vulture", "Verseuchter Geier", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's grown a second head", "Ihm ist ein zweiter Kopf gewachsen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased water dragon", "Verseuchter Wasserdrache", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's such a pitiful creature now", "Jetzt ist es eine so bemitleidenswerte Kreatur.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased weasel", "Verseuchtes Wiesel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not as worthless now I see", "Nun ist es wohl doch nicht so nutzlos.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased wolf", "Verseuchter Wolf", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even more rabid than it's kin", "Noch tollwütiger als seine Artgenossen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased wolfcub", "Verseuchter Wolfswelpe", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh god its eye!", "Oh Gott, sein Auge!", Language.German);


        }
    }
    public class LethalCabinMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for LethalCabin Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lethal Cabin", "Tödliche Hütte", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Celestial Body: Inscryption.\n Population: Sparse.\n Conditions: Unknown.\n Fauna: [count] species.", "Himmelskörper: Inscryption.\n Bevölkerung: spärlich.\n Bedingungen: unbekannt.\n Fauna: [count] Arten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hygrodere", "Hygrodere", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A eukaryotic organism that can multiply to millions with incredible speed.", "Ein eukaryotischer Organismus, der sich mit unglaublicher Geschwindigkeit millionenfach vermehren kann.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jester", "Narr", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You know as much as I do. I just call it the Jester.", "Du weißt genauso viel wie ich. Ich nenne es einfach den Narren.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kidnapper Fox", "Entführerfuchs", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A large mammal with a horizontal jaw and unique skull shape giving it a great biting strength, and a long, frog-like tongue which can reach even twice the length of its spindly body.", "Großes Säugetier mit waagerechtem Kiefer und einzigartiger Schädelform, die ihm starke Beißkraft verleihen. Seine lange, froschartige Zunge kann doppelt so lang wie sein schlaksiger Körper sein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Landmine", "Landmine", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Manticoil", "Manticoil", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Poses little threat and has a generally passive temperament, although it's capable of transmitting deadly diseases.", "Stellt kaum eine Gefahr dar und ist meist friedlich, kann jedoch tödliche Krankheiten übertragen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Masked", "Maskierter", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mask Hornets", "Maskenhornissen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mysterious creature that takes the form of an escape door in order to lure in potential prey.", "Geheimnisvolle Kreatur, die die Gestalt einer Fluchttür annimmt, um mögliche Beute anzulocken.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nutcracker", "Nussknacker", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "watches with one tireless eye, which only senses movement. It remembers the last creature it noticed, whether they are moving or not.", "Es beobachtet mit einem unermüdlichen Auge, das nur Bewegung wahrnimmt. Es erinnert sich an die letzte bemerkte Kreatur, ob sie sich bewegt oder nicht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Old Bird", "Alter Vogel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An autonomous, offensive weapon of war with a humanoid design. Equipped with a spotlight, rocket legs, an acoustic device and a missile launcher, they are truly a sight to behold.", "Autonome offensive Kriegswaffe mit humanoidem Design. Mit Scheinwerfer, Raketenbeinen, akustischem Gerät und Raketenwerfer ist sie wahrlich ein beeindruckender Anblick.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Roaming Locusts", "Streunende Heuschrecken", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unlike some species which are more prone to jump or fly, roaming locusts are almost never grounded and stay close together even when in smaller numbers.", "Anders als Arten, die eher springen oder fliegen, landen streunende Heuschrecken fast nie und bleiben selbst in kleiner Zahl dicht beieinander.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sentry Turret", "Wachturmgeschütz", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snare Flea", "Fangfloh", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A very large arthropod that possesses the ability to tighten itself around large prey to suffocate.", "Ein sehr großer Gliederfüßer, der sich um große Beute zusammenziehen kann, um sie zu ersticken.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spore Lizard", "Sporenechse", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The bulb on its tail secretes a chemical which attracts and accelerates the growth of a fungus, which it can then shake to release spores as a defense mechanism.", "Die Knolle an seinem Schwanz sondert einen Stoff ab, der einen Pilz anzieht und dessen Wachstum beschleunigt. Durch Schütteln setzt es zur Verteidigung Sporen frei.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thumper", "Stampfer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Highly aggressive, carnivorous species of hunters, typically at the top of their food chain.", "Äußerst aggressive fleischfressende Jäger, die gewöhnlich an der Spitze ihrer Nahrungskette stehen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tulip Snake", "Tulpenechse", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lifting heavy and large objects into the air has often been observed as a part of the tulip snake's mating display. They are capable of carrying rocks, plants and even other creatures at least twice their size in an effort to impress their potential mate.", "Das Anheben großer, schwerer Gegenstände wurde oft als Teil der Balz der Tulpenechse beobachtet. Um mögliche Partner zu beeindrucken, kann sie Steine, Pflanzen und sogar Kreaturen tragen, die mindestens doppelt so groß sind wie sie.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vain Shroud", "Eitler Schleier", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baboon Hawk", "Pavianhabicht", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As lone scouts, baboon hawks are generally timid and won't attack unless provoked. In greater numbers they can become a great danger.", "Als einzelne Späher sind Pavianhabichte meist scheu und greifen nur an, wenn sie provoziert werden. In größerer Zahl können sie sehr gefährlich werden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Barber", "Friseur", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Also known as the Clay Surgeon, Barber is a pack-forming creature that follows a Master Barber's beat to move and attack unsuspecting prey", "Der Friseur, auch Tonchirurg genannt, lebt im Rudel und folgt dem Takt eines Meisterfriseurs, um sich zu bewegen und ahnungslose Beute anzugreifen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bunker Spider", "Bunkerspinne", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This enormous arachnid produces silk and lays it around its chosen nesting area, then waits for it to be tripped on.", "Dieses riesige Spinnentier produziert Seide, verteilt sie um sein gewähltes Nest und wartet, bis jemand darüber stolpert.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Butler", "Butler", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deformed like a deflated balloon, this humanoid smells of rotten meat and, if you listen close, you can hear a faint sound of flies buzzing inside...", "Dieser wie ein schlaffer Ballon verformte Humanoide riecht nach verdorbenem Fleisch. Hört man genau hin, vernimmt man im Innern ein schwaches Fliegensummen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Circuit Bees", "Stromkreisbienen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Also known as red bees, these social insects possess the aBEElity to create a field of electrostatic charge.", "Diese auch Rotbienen genannten sozialen Insekten sind bienenstark darin, ein elektrostatisches Feld zu erzeugen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coil-Head", "Federkopf", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Known to combust into flames when being dissected or even deactivated, and carries dangerously high levels of radioactive particles.", "Es ist dafür bekannt, bei einer Sezierung oder sogar Deaktivierung in Flammen aufzugehen, und enthält gefährlich hohe Mengen radioaktiver Partikel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Company Cruiser", "Firmenkreuzer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jeb", "Jeb", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We trust you'll be a great asset to the Company.", "Wir sind überzeugt, dass du eine große Bereicherung für die Firma sein wirst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Earth Leviathan", "Erdleviathan", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Can burrow as far as 40 meters underground, judging by the incredible excavations it can leave behind.", "Den gewaltigen Grabungen nach zu urteilen, die es hinterlässt, kann es bis zu 40 Meter tief graben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eyeless Dog", "Augenloser Hund", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A large mammal, hunting in very large packs. They are endurance hunters and attempt to make up for their lack of sight with their sense of hearing.", "Große Säugetiere, die in sehr großen Rudeln jagen. Als Ausdauerjäger versuchen sie, ihre fehlende Sicht durch ihren Hörsinn auszugleichen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Forest Keeper", "Waldhüter", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exhibits a curious behavior similar to that of a human child the age of 5 or 6. It will eat anything it find fascinating.", "Es zeigt ein neugieriges Verhalten wie ein menschliches Kind von 5 oder 6 Jahren. Es frisst alles, was es faszinierend findet.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ghost Girl", "Geistermädchen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hoarding Bug", "Hortekäfer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Given its name due to its territorial nature, they will seek out any object they can find and will protect these objects as a part of the nest.", "Ihr Name kommt von ihrem Revierverhalten. Sie suchen nach allen Gegenständen, die sie finden können, und schützen sie als Teil ihres Nestes.", Language.German);




        }
    }
    public class RemoxedBossesMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Remoxed_Bosses Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Crate", "Todeskiste", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil dies, it will deal 1 damage to the Scale in favor for the Player.", "Stirbt eine Karte mit diesem Siegel, neigt sich die Waage um 1 Punkt zugunsten des Spielers.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dropped Gem", "Fallengelassener Edelstein", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dropped Pearl", "Fallengelassene Perle", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enchanted Frog", "Verzauberter Frosch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Crew", "Edelsteincrew", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Trap", "Edelsteinfalle", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil dies, it will kill the opposing card.", "Stirbt eine Karte mit diesem Siegel, tötet sie die gegenüberliegende Karte.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Nugget", "Edelsteinklumpen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Minecart", "Minenwagen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Seaman", "Mox-Seemann", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem powered Trap", "Edelsteinbetriebene Falle", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orange Powder", "Oranges Pulver", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil dies, it will grant the opossing card +1 Attack Power and the Orange Mox Sigil.", "Stirbt eine Karte mit diesem Siegel, erhält die gegenüberliegende Karte +1 Angriff und das Oranges-Mox-Siegel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Overloaded", "Überladen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will move in the inscribed direction and leave behind a Orange Mox.", "Am Ende des Zugs ihres Besitzers bewegt sich eine Karte mit diesem Siegel in die angegebene Richtung und hinterlässt eine Oranges-Mox-Karte auf ihrem alten Feld.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oyster", "Auster", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remoxed Bosses", "Neu gestaltete Mox-Bosse", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Re-adds the Great White to the card pool.", "Fügt den Weißen Hai wieder dem Kartenpool hinzu.", Language.German);

        }
    }
    public class TerrariascryptionMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Terrariascryption Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hivemind", "Schwarmbewusstsein", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil is equal to the number of Crimson tribes on the board.", "Der von diesem Siegel dargestellte Wert entspricht der Anzahl der Kreaturen der Karmin-Familie auf dem Brett.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You dare think that you can skip this fight?", "Du glaubst wirklich, du könntest diesen Kampf überspringen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You dare think that you can skip this fight? Face Moonlord, you coward!", "Du glaubst wirklich, du könntest diesen Kampf überspringen? Stell dich dem Mondherrn, Feigling!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Starvation won't interrupt this fight!", "[c:bR]Die Hungersnot wird diesen Kampf nicht unterbrechen!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cursed Flames", "Verfluchte Flammen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gets harmed by Acids every turn.", "[creature] wird jeden Zug durch Säure verletzt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flame Protected", "Flammengeschützt", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] can not be damaged by cursed flames.", "[creature] kann durch verfluchte Flammen keinen Schaden erleiden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cursed Flamethrower", "Verfluchter Flammenwerfer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] discharges cursed flames to harm the opposing creature over time.", "[creature] setzt verfluchte Flammen frei, die der gegenüberliegenden Kreatur mit der Zeit Schaden zufügen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AngryTrapper", "Wütender Fallensteller", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a Man Eater consumes enough human flesh, it undergoes a cocoon-like metamorphosis into a far deadlier form.", "Hat eine Menschenfresserpflanze genug menschliches Fleisch verschlungen, durchläuft sie eine kokongleiche Verwandlung in eine weit tödlichere Form.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Crawler", "Blutkriecher", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Most spiders operate independently, but ones touched by the Crimson hive coordinate together to consume life.", "Die meisten Spinnen handeln allein, doch die vom Karmin-Schwarm berührten arbeiten zusammen, um Leben zu verschlingen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Mummy", "Blutmumie", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The blood-dripping organic matter in these mummies display far better preservation than the rest of their ilk.", "Das bluttriefende organische Material dieser Mumien ist viel besser erhalten als das ihrer Artgenossen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue Slime", "Blauer Schleim", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A simple, gelatinous creature that swallows anything and everything whole! It takes a long time to digest anything.", "Eine einfache gallertartige Kreatur, die alles im Ganzen verschluckt! Sie braucht sehr lange, um etwas zu verdauen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Corruptor", "Verderber", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Like a cancer, the putrid creatures born from the Corruption mutate and grow into bigger, more deadly forms which discharge acids.", "Wie ein Krebsgeschwür mutieren die fauligen Kreaturen der Verderbnis zu größeren, tödlicheren Formen, die Säure verspritzen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Corrupt Slime", "Verderbter Schleim", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Steeped in the power of Corruption, these slimes can survive being cut apart into smaller pieces, unlike their untainted brethren.", "Von der Macht der Verderbnis durchdrungen, überleben diese Schleime es, in kleine Stücke geschnitten zu werden, anders als ihre unversehrten Verwandten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crimera", "Krimära", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The most common horror to be born from the Crimson, it seeks to consume pure things with unrelenting hunger.", "Das häufigste Grauen aus dem Karmin sucht mit unstillbarem Hunger nach reinen Dingen, um sie zu verschlingen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dasher", "Stürmer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will Dash in the direction inscribed on the sigil, Attacking whoever stands infront of it.", "Am Ende des Zugs ihres Besitzers stürmt [creature] in die auf dem Siegel angegebene Richtung und greift an, was vor ihr steht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deerclops", "Hirschzyklop", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hailing from a distant land, this cyclopic monstrosity lurks in cold places, wreaking havoc on those who disturb it.", "Diese einäugige Monstrosität aus einem fernen Land lauert an kalten Orten und richtet unter denen, die sie stören, Verwüstung an.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Demon", "Dämon", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Demons are the infantry of the underworld. Unlike their lesser brothers, they cast shadow magic rather than hell magic.", "Dämonen bilden die Infanterie der Unterwelt. Anders als ihre kleineren Brüder wirken sie Schattenmagie statt Höllenmagie.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Worm-like monstrosities are the Corruption's most favored creatures, tunneling underneath unsuspecting victims.", "Wurmartige Monstrositäten sind die bevorzugten Kreaturen der Verderbnis und graben Tunnel unter ahnungslosen Opfern.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eater of Souls", "Seelenfresser", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Birthed from the Corruption as a being of pure malice, its sole instincts are to pursue, punish, and kill.", "Als Wesen reiner Bosheit aus der Verderbnis geboren, kennt es nur den Instinkt, zu verfolgen, zu bestrafen und zu töten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eater of Worlds", "Weltenfresser", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conceived from the bottomless malice of the Corruption, this mighty abyssal worm tunnels wildly to devour all in its path.", "Dieser mächtige Abgrundwurm, aus der bodenlosen Bosheit der Verderbnis geboren, gräbt wild umher und verschlingt alles auf seinem Weg.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Empress of Light", "Kaiserin des Lichts", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beneath the Hallow's cleansing blanket lies a vengeful fae goddess bent on scrubbing the land of any and all impurity.", "Unter dem reinigenden Mantel der Heiligung verbirgt sich eine rachsüchtige Feengöttin, die das Land von jeder Unreinheit säubern will.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moon lord", "Mondherr", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eye Of Cthulu", "Auge des Cthulhu", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A piece of Cthulhu ripped from his body centuries ago in a bloody war. It wanders the night seeking its host body... and revenge!", "Ein Teil von Cthulhu, der vor Jahrhunderten in einem blutigen Krieg aus seinem Körper gerissen wurde. Er wandert durch die Nacht auf der Suche nach seinem Wirtskörper ... und nach Rache!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eye Servant", "Augendiener", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Face Monster", "Gesichtsmonster", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It would be unwise to face off with one of these unfeeling, hungry mutations. Their mouths are large enough to devour all things.", "Es wäre unklug, sich mit diesen gefühllosen, hungrigen Mutationen anzulegen. Ihre Mäuler sind groß genug, um alles zu verschlingen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moon Awakening", "Erwachen des Mondes", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Creature behind the Moon has awoken...", "Eine Kreatur hinter dem Mond ist erwacht ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant Tortoise", "Riesenschildkröte", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No one takes the giant tortoises seriously. Not until they come hurtling through the air, a spinning, spiky ball of death.", "Niemand nimmt Riesenschildkröten ernst. Bis sie als rotierende, stachelige Todesbälle durch die Luft geschossen kommen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Herpling", "Herpling", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "These hyper, demented, slug-like fiends serve the crimson horde with an unstoppable appetite for blood and flesh.", "Diese überdrehten, wahnsinnigen, schneckenartigen Unholde dienen der Karminhorde mit unstillbarem Hunger nach Blut und Fleisch.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hooked", "Gehakt", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hook", "Haken", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will summon Hooks on either side of it.", "[creature] beschwört auf beiden Seiten Haken.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "if [creature] is not surrounded by a card bearing the Hooked Sigil it will loose all attack.", "Ist [creature] nicht von einer Karte mit dem Gehakt-Siegel umgeben, verliert sie ihren gesamten Angriff.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aggressive flying insects which swarm the jungle depths. Their venomous barbs discharge over great distances at high velocity.", "Aggressive fliegende Insekten, die in den Tiefen des Dschungels schwärmen. Ihre giftigen Stacheln schießen sie mit hoher Geschwindigkeit über große Entfernungen ab.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ice Slime", "Eisschleim", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slimes that spent too long in arctic temperatures may begin to partially freeze, developing a shifting layer of ice on their surface.", "Schleime, die zu lange arktischer Kälte ausgesetzt sind, können teilweise gefrieren und eine sich verändernde Eisschicht an ihrer Oberfläche entwickeln.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spiked Ice Slime", "Stacheliger Eisschleim", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Ice Slime has large ice shards in its mass from excessive exposure to the cold.Somehow, it is able to launch these at its prey.", "Dieser Eisschleim hat durch zu lange Kälteeinwirkung große Eissplitter in seiner Masse. Irgendwie kann er diese auf seine Beute schleudern.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichor", "Ichor", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gets damaged for the damage * 2.", "[creature] erleidet das Doppelte des Schadens.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichor Protected", "Ichor-geschützt", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creatures]s defense can not be lowered by ichor.", "Die Verteidigung von [creature] kann nicht durch Ichor gesenkt werden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichor Discharging", "Ichorentladung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] discharges Ichor to lower the opposing creatures defenses.", "[creature] stößt Ichor aus, um die Verteidigung gegnerischer Kreaturen zu senken.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichor Sticker", "Ichoraufkleber", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Filled to the brim with powerful ichor, these squid-like abominations spew their corrosive bio-fluid at their prey.", "Diese tintenfischartigen Scheusale sind bis zum Rand mit mächtigem Ichor gefüllt und speien ihre ätzende Körperflüssigkeit auf ihre Beute.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "King Slime", "Schleimkönig", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slimes normally aren't intelligent, but occasionally they merge together to become a powerful force to swallow all things.", "Schleime sind normalerweise nicht intelligent, doch gelegentlich verschmelzen sie zu einer mächtigen Kraft, die alles verschlingen kann.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Engulfer", "Verschlinger", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed on the sigil. Creatures in the way will be engulfed.", "Am Ende des Zugs ihres Besitzers bewegt sich [creature] in die auf dem Siegel angegebene Richtung. Kreaturen auf ihrem Weg werden verschlungen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lavaborne", "Lavageboren", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will hide underneath Lava. Any card willing to attack will be damaged by the Lava", "[creature] verbirgt sich unter Lava. Jede Karte, die sie angreifen will, erleidet Schaden durch die Lava.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leap", "Sprung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Bones to choose an empty slot to move [creature] into and deal 1 damage to the opposing slot.", "Bezahle 2 Knochen, um ein leeres Feld zu wählen, auf das [creature] zieht, und dem gegenüberliegenden Feld 1 Schaden zuzufügen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lunar Spells", "Mondzauber", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will create Spells as it strafes.", "[creature] erzeugt Zauber, wenn sie sich seitwärts bewegt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LunaticCultist", "Lunatischer Kultist", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lightning Orb", "Blitzkugel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ice Mist", "Eisnebel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lord of the Moon", "Herr des Mondes", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chest", "Truhe", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Talking to a chest doesn't cause craziness, but if the chest answers back, it may cause death! It still contains rare treasure, regardless!", "Mit einer Truhe zu sprechen macht nicht verrückt, doch wenn sie antwortet, kann es zum Tod führen! Seltene Schätze enthält sie trotzdem!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Corrupted Mimic", "Verderbter Nachahmer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mimics which fall to Corruption grow larger and more powerful as a result. They can be birthed from ordinary chests by force.", "Nachahmer, die der Verderbnis verfallen, werden größer und mächtiger. Sie können gewaltsam aus gewöhnlichen Truhen hervorgebracht werden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crimson Mimic", "Karmin-Nachahmer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "True Eye", "Wahres Auge", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phase Switcher", "Phasenwechsel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Upon Death, [creature] will reach its next Phase.", "Beim Tod erreicht [creature] ihre nächste Phase.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nebula Pillar", "Nebulasäule", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Solar Pillar", "Sonnensäule", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stardust Pillar", "Sternenstaubsäule", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vortex Pillar", "Säule des Strudels", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pixie", "Pixie", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A larger, more luminous form of fairy. Pixies provide the Hallow with more blessed light and aid in the cleansing of the land.", "Eine größere, leuchtendere Feenform. Pixies versorgen die Heiligung mit mehr gesegnetem Licht und helfen, das Land zu reinigen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plantera", "Plantera", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A dormant, yet powerful floral guardian awoken by the fallout of Cthulhu's destroyed machinations. Its reach spans the entire jungle.", "Eine schlafende, aber mächtige Blütenwächterin, geweckt durch die Folgen von Cthulhus zerstörten Machenschaften. Ihr Einfluss reicht über den ganzen Dschungel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Planteras Hook", "Planteras Haken", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Purple Slime", "Violetter Schleim", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will spit out a randomly chosen Rare Card upon being placed.", "Wenn [creature] platziert wird, spuckt sie eine zufällig gewählte seltene Karte aus.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Red Slime", "Roter Schleim", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Who needs muscles, skin, or even eyeballs? Skeletons get by with just the bones on their back, just as deadly as more fleshy foes.", "Wer braucht Muskeln, Haut oder gar Augäpfel? Skelette kommen allein mit ihren Knochen aus und sind ebenso tödlich wie fleischigere Gegner.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Serpent", "Knochenschlange", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mighty serpentine dragons once ruled hell, but long ago shed their obsidian scales.A skeletal husk is all that remains.", "Mächtige schlangenartige Drachen beherrschten einst die Hölle, doch sie warfen vor langer Zeit ihre Obsidianschuppen ab. Nur eine Skeletthülle blieb zurück.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slimer", "Flügelschleim", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Slimer has become airborne with wings of unknown origin. The wings are easily knocked off with force, depriving it of its flight.", "Der Flügelschleim fliegt mit Flügeln unbekannter Herkunft. Sie lassen sich leicht abschlagen, wodurch er seine Flugfähigkeit verliert.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Man Eater", "Menschenfresser", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A sharp-toothed plant with a taste for human flesh. It has the ability to hide inside the mud and reach over great distances.", "Eine scharfzähnige Pflanze mit Vorliebe für Menschenfleisch. Sie kann sich im Schlamm verbergen und sehr weit reichen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dryad", "Dryade", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sands of time are flowing. And well, you are not aging very gracefully.", "Der Sand der Zeit verrinnt. Und nun ja, du alterst nicht besonders anmutig.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guide", "Führer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They say there is a person who will tell you how to survive in this land... oh wait. That's me.", "Man sagt, hier gebe es jemanden, der dir erklärt, wie du überlebst ... Ach, Moment. Das bin ich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tree but ded.", "Ein Baum, aber tot.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cool Slime", "Cooler Schleim", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Easily the coolest slime around, no question. You can tell from the backwards hat and indecipherable slang.", "Zweifellos der coolste Schleim weit und breit. Das zeigen seine rückwärts getragene Kappe und sein unverständlicher Slang.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clumsy Slime", "Ungeschickter Schleim", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This slime was a little confused when the other slimes started putting on hats and accessories. But it did its best.", "Dieser Schleim war etwas verwirrt, als die anderen Hüte und Accessoires anzogen. Aber er gab sein Bestes.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nerdy Slime", "Nerdiger Schleim", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just a smidge cleverer than other slimes, this slime discovered how to coexist with humans. The secret: accessorizing!", "Dieser Schleim ist nur ein kleines bisschen schlauer als die anderen und hat herausgefunden, wie man mit Menschen zusammenlebt. Das Geheimnis: Accessoires!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Surly Slime", "Mürrischer Schleim", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Irascible and insufferable, this grumpy slime is probably up to no good. Probably. Its the thought that counts really.", "Reizbar und unerträglich, führt dieser mürrische Schleim wahrscheinlich nichts Gutes im Schilde. Wahrscheinlich. Schließlich zählt der Gedanke.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elder Slime", "Ältester Schleim", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Older, though not necessarily wiser, the other slimes look up to the Elder Slime. If it survived this long, it must know something!", "Der älteste Schleim ist zwar älter, aber nicht unbedingt weiser. Die anderen sehen zu ihm auf. Wenn er so lange überlebt hat, muss er etwas wissen!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Diva Slime", "Diva-Schleim", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Born of the combined energies of Shimmer and the Queen Slime, this slime is full of boundless energy and enthusiasm! And so fancy!", "Dieser Schleim entstand aus den vereinten Energien von Schimmer und Schleimkönigin und steckt voller Energie und Begeisterung! Und wie elegant er ist!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mystic Slime", "Mystischer Schleim", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This slime knows that great witches wear impressive hats, but it only found a droopy one. Might explain the backfired polymorph!", "Dieser Schleim weiß, dass große Hexen beeindruckende Hüte tragen, fand aber nur einen schlaffen. Das erklärt vielleicht den misslungenen Verwandlungszauber!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Squire Slime", "Knappen-Schleim", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A hero amongst slimes, it wields the greatest arms and armor known to its kind. It doesn't actually know how to use them, but its a start.", "Ein Held unter den Schleimen, ausgerüstet mit den besten Waffen und Rüstungen seiner Art. Er weiß zwar nicht, wie man sie benutzt, aber es ist ein Anfang.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unicorn", "Einhorn", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "These majestic single-horned equines storm angrily through the hallowed land in search of lowly intrusions needing to be cleansed away.", "Diese majestätischen Einhörner stürmen wütend durch das geheiligte Land und suchen nach niederen Eindringlingen, die beseitigt werden müssen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wall Creator", "Mauererschaffer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will create a Wall on [creature]s Side.", "[creature] erzeugt eine Mauer auf der Seite von [creature].", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wall of Flesh", "Fleischwand", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Serving as the world's core and guardian, the towering demon lord exists to keep powerful ancient spirits sealed away.", "Dieser hoch aufragende Dämonenfürst dient als Kern und Wächter der Welt und hält mächtige uralte Geister versiegelt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Middle Strike", "Mittelschlag", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Right Strike", "Rechtsschlag", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Left Strike", "Linksschlag", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attack only cards in the slot to its right. If a targeted slot is empty, the damage will be redirected to the opponent.", "[creature] greift nur Karten auf dem Feld rechts von ihr in derselben Reihe an. Ist das Zielfeld leer, erhält der Gegner den Schaden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attack only cards in the slot to its left. If a targeted slot is empty, the damage will be redirected to the opponent.", "[creature] greift nur Karten auf dem Feld links von ihr in derselben Reihe an. Ist das Zielfeld leer, erhält der Gegner den Schaden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Terrascryption", "Terrascryption", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card pack contains a bunch of awesome Terraria themed Cards!", "Dieses Kartenpaket enthält jede Menge großartige Karten im Terraria-Stil!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fortunate draw.", "Glücklicher Zug.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Be safe", "Pass auf dich auf", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perfect", "Perfekt", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sands of time are flowing.", "Der Sand der Zeit verrinnt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I Hope you aren't making a Mistake!", "Ich hoffe, du machst keinen Fehler!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You think this works?", "Glaubst du, das funktioniert?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh what a misplay?", "Oh, was für ein Fehlzug!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh!", "Oh!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose Me.", "Wähle mich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't Sacrifice me.", "Opfere mich nicht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you need to....", "Wenn du musst ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stop that.", "Hör damit auf.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Angler...", "Der Angler ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "how disgusting", "Wie widerlich", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just defeat him already", "Besieg ihn endlich", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boss time, eh?", "Zeit für den Boss, was?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What an honor.", "Was für eine Ehre.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is great!", "Das ist großartig!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What an honor", "Was für eine Ehre", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fingers crossed", "Daumen drücken", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nice Deck.", "Schöner Stapel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Iam here to help You!", "Ich bin hier, um dir zu helfen!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lucky.", "Glück gehabt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't die", "Stirb nicht", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "not the worst draw.", "Nicht der schlechteste Zug.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good Choice!", "Gute Wahl!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Iam a Guide afterall.", "Ich bin schließlich ein Führer.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OK...", "Na gut ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its a Good Choice.", "Das ist eine gute Wahl.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Total misplay.", "Ein völliger Fehlzug.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yep.", "Jep.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I Hope this is right!", "Ich hoffe, das ist richtig!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sure I guess?", "Ja, denke ich?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose Who you want.", "Wähle, wen du willst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrifice me if you need to.", "Opfere mich, wenn es nötig ist.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I will still guide you!", "Ich werde dich weiterhin führen!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Prospector. Watch out for his Pickaxe.", "Der Goldgräber. Pass auf seine Spitzhacke auf.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Prospector...", "Der Goldgräber ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kill the Mule for Cards", "Töte das Maultier für Karten", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the mule's key", "das Maultier ist der Schlüssel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you sure about this?", "Bist du dir sicher?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Corruption is waiting for you!", "Die Verderbnis wartet auf dich!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Crimson is waiting for you!", "Das Karmin wartet auf dich!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Brain of Cthulu has awoken!", "Das Hirn des Cthulhu ist erwacht!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Representing a flaming celestial event known as 'solar flares', this tower holds the seal locking away a terrifying tyrant.", "Dieser Turm steht für das flammende Himmelsereignis der Sonneneruptionen und trägt das Siegel, das einen furchterregenden Tyrannen einschließt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Representing a deep celestial void known as 'vortex', this tower holds the seal locking away a terrifying tyrant.", "Dieser Turm steht für die tiefe himmlische Leere namens Wirbel und trägt das Siegel, das einen furchterregenden Tyrannen einschließt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Representing a stormy celestial body known as 'nebula', this tower holds the seal locking away a terrifying tyrant.", "Dieser Turm steht für den stürmischen Himmelskörper namens Nebel und trägt das Siegel, das einen furchterregenden Tyrannen einschließt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Representing a glittering celestial remnant known as 'stardust', this tower holds the seal locking away a terrifying tyrant.", "Dieser Turm steht für den glitzernden himmlischen Überrest namens Sternenstaub und trägt das Siegel, das einen furchterregenden Tyrannen einschließt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And so arrives the Moonlord, harbringer of all Destruction.", "Und so erscheint der Mondherr, Vorbote aller Zerstörung.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You saved us all!", "Du hast uns alle gerettet!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Eater of Worlds has awoken!", "Der Weltenfresser ist erwacht!", Language.German);

        }
    }
    public class BittysRegionsMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for BittysRegions Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TIME TO FORGE METAL!", "ZEIT, METALL ZU SCHMIEDEN!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GO MY KNIGHTS!", "LOS, MEINE RITTER!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah... no materials...", "Ach ... keine Materialien mehr ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>You may claim those are your cards...</color>", "<color=#32CD32>Du kannst behaupten, diese Karten seien deine ...</color>", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>But the spiders inside them are MINE!</color>", "<color=#32CD32>Aber die Spinnen darin gehören MIR!</color>", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>A shame... There's none of my spiders on your side...</color>", "<color=#32CD32>Schade ... Auf deiner Seite ist keine meiner Spinnen ...</color>", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>A spider's bite always strikes when least expected...</color>", "<color=#32CD32>Der Biss einer Spinne trifft immer dann, wenn man ihn am wenigsten erwartet ...</color>", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mad laughter of a wild dog.", "Das wahnsinnige Lachen eines wilden Hundes.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chihuahua", "Chihuahua", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Savage and vicious, all wrapped up in a tiny package.", "Wild und bösartig, alles verpackt in einem winzigen Körper.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woodpecker", "Specht", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The persistent Woodpecker, it strikes endlessly.", "Der ausdauernde Specht schlägt unaufhörlich zu.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ever-rolling squirrel ball, a strange and bizzare phenomenon.", "Die unaufhörlich rollende Eichhörnchenkugel, ein seltsames und merkwürdiges Phänomen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the mighty hawk, champion of the skies.", "Der mächtige Habicht, Champion der Lüfte.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seagull", "Möwe", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Known as rats of the skies... Or was that another bird?", "Man nennt sie Ratten der Lüfte ... Oder war das ein anderer Vogel?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hermit Crab", "Einsiedlerkrebs", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The humble hermit crab. Always seeking a new home.", "Der bescheidene Einsiedlerkrebs sucht immer nach einem neuen Zuhause.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rock Wall", "Steinmauer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A sheer wall of rock.", "Eine steile Felswand.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A world on fire.", "Eine Welt in Flammen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flaming Tree", "Brennender Baum", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coal Pile", "Kohlehaufen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fuel for the flames.", "Brennstoff für die Flammen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shackle", "Fessel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bindings forged in flames.", "In Flammen geschmiedete Fesseln.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Knight", "Ritter", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creations of steel and fire.", "Schöpfungen aus Stahl und Feuer.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Turtle Rock", "Felsenschildkröte", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Covered in rocks, with strength to reflect it.", "Von Felsen bedeckt und entsprechend stark.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flamemingo", "Flammingo", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The majestic Phoenix. Always comes back.", "Der majestätische Phönix. Er kehrt immer zurück.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A flamingo in terrible pain. Not to be mistaken with the majestic Phoenix.", "Ein Flamingo mit schrecklichen Schmerzen. Nicht mit dem majestätischen Phönix verwechseln.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Drake", "Drache", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dwellers of volcanos and other infernal places.", "Bewohner von Vulkanen und anderen höllischen Orten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Salamander", "Salamander", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A slippery little creature.", "Eine kleine, glitschige Kreatur.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flaming Salmon", "Brennender Lachs", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Salmon scarred by searing flames. Native to lava pools.", "Ein von sengenden Flammen gezeichneter Lachs. Er lebt in Lavabecken.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A savage beast of the depths.", "Eine wilde Bestie aus der Tiefe.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fire Ant", "Feuerameise", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hundreds scurry from their anthill.", "Hunderte eilen aus ihrem Ameisenhügel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coal Boy", "Kohlenjunge", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A freakish creation. It bites.", "Eine unheimliche Schöpfung. Sie beißt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brood Mother", "Brutmutter", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mother of many, stored inside her own body.", "Mutter vieler Jungen, die sie in ihrem Körper trägt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Childlike wonder, monsterous body.", "Kindliche Neugier in einem monströsen Körper.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasitic Spider", "Parasitäre Spinne", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Infesting everything it touches.", "Sie befällt alles, was sie berührt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Egg Sack", "Eiersack", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A sac of eggs.", "Ein Sack voller Eier.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Daddy Long Legs", "Weberknecht", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tall and spindly, father of none.", "Groß und dürr, doch niemandes Vater.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pillar?", "Säule?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A pillar?", "Eine Säule?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wolf Spider", "Wolfsspinne", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As deadly as a normal wolf, but more skittish.", "So tödlich wie ein gewöhnlicher Wolf, aber scheuer.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Night Mare", "Nachtmahr", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A fragment of a darkened dream. It harms everything, including allies.", "Ein Bruchstück eines düsteren Traums. Es verletzt alles, auch Verbündete.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A rampaging monster of many legs.", "Ein tobendes Monster mit vielen Beinen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Doom Clock", "Weltuntergangsuhr", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An ancient calendar foretelling the end of the world.", "Ein alter Kalender, der das Ende der Welt vorhersagt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chair", "Stuhl", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A strange metal chair.", "Ein seltsamer Metallstuhl.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elk Mage", "Hirschmagier", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An ambitious Elk, making its way in the world.", "Ein ehrgeiziger Hirsch, der seinen Weg in der Welt sucht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mus-Elk Mage", "Muskelhirschmagier", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Muscle Mage's incarnation. Muscular and beautiful.", "Die Verkörperung des Muskelmagiers. Muskulös und schön.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Glowing Buck", "Leuchtender Hirsch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fully fledged master of luminescence.", "Ein vollendeter Meister der Leuchtkraft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A fading light.", "Ein verblassendes Licht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card pack adds [count] new cards that are found in every region. (There are more cards that are region specific!)", "Dieses Kartenpaket fügt [count] neue Karten hinzu, die in jeder Region vorkommen. (Weitere Karten sind nur in bestimmten Regionen zu finden!)", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The damp air of the underground...", "Die feuchte Luft unter der Erde ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And water dripping down stalagmites...", "Und Wasser, das an Stalagmiten hinabtropft ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You entered... [c:bG]The Infested Caves.[c:]", "Du betrittst ... [c:bG]die befallenen Höhlen.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Webs line the walls...", "Spinnweben säumen die Wände ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The skittering of many legs echo throughout the caverns...", "Das Trippeln unzähliger Beine hallt durch die Höhlen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With trepidation, you enter... [c:bG]The Infested Caves.[c:]", "Ängstlich betrittst du ... [c:bG]die befallenen Höhlen.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cool air of the caverns greeted your face...", "Die kühle Höhlenluft streifte dein Gesicht ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As you crept below...", "Während du dich hinabschlichst ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Into [c:bG]The Infested Caves.[c:]", "In [c:bG]die befallenen Höhlen.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The smell of sulfur...", "Der Geruch von Schwefel ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And falling ash...", "Und fallende Asche ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You reach... [c:bG]The Lava Flow.[c:]", "Du erreichst ... [c:bG]den Lavastrom.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You see the land glowing in the distance...", "In der Ferne siehst du das Land glühen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Molten rock, flowing in rivers...", "Geschmolzenes Gestein fließt in Strömen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have reached... [c:bG]The Lava Flow.[c:]", "Du hast ... [c:bG]den Lavastrom erreicht.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The landscape is dark with ash...", "Die Landschaft ist dunkel vor Asche ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The trees are burning...", "Die Bäume brennen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You tread through... [c:bG]The Lava Flow.[c:]", "Du wanderst durch ... [c:bG]den Lavastrom.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This time you will choose a region specific card.", "Diesmal wählst du eine regionsspezifische Karte.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose wisely.", "Wähle mit Bedacht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You approach a great stone forge.", "Du näherst dich einer großen steinernen Schmiede.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems that you aren't alone.", "Du scheinst nicht allein zu sein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The clanging of metal reverberates around you.", "Metallisches Klirren hallt um dich herum.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sparks spill from the forge.", "Funken sprühen aus der Schmiede.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You run into a nearby cave to escape the smell of sulfur.", "Du rennst in eine nahe Höhle, um dem Schwefelgeruch zu entkommen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "However, this cave is inhabited.", "Diese Höhle ist jedoch bewohnt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am the blacksmith, [c:bG]Martel.[c:]", "Ich bin der Schmied, [c:bG]Martel.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The old man has given me the opportunity to face you properly...", "Der alte Mann hat mir die Gelegenheit gegeben, mich dir richtig zu stellen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am the blacksmith.", "Ich bin der Schmied.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's forge you into a fine creation.", "Lass mich aus dir ein vortreffliches Werk schmieden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And you... are the iron.", "Und du ... bist das Eisen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is time, challenger.", "Es ist Zeit, Herausforderer.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Time for you to see the true meaning of... PERFECTION.", "Es ist Zeit, dir die wahre Bedeutung von ... PERFEKTION zu zeigen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You approach the deepest part of the cave.", "Du näherst dich dem tiefsten Teil der Höhle.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Long legs creep out of the shadows, as many smaller spiders skitter around.", "Lange Beine kriechen aus den Schatten, während viele kleinere Spinnen umherhuschen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A light hearted voice calls out to you.", "Eine unbeschwerte Stimme ruft dich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>Ahuhuhu~</color>", "<color=#32CD32>Ahuhuhu~</color>", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>My, who do we have here?</color>", "<color=#32CD32>Na, wen haben wir denn hier?</color>", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>It's been so long since I've seen a Challenger...</color>", "<color=#32CD32>Ich habe so lange keinen Herausforderer mehr gesehen ...</color>", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>Let's have some fun...</color>", "<color=#32CD32>Hab Freude mit mir ...</color>", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>I am the queen of the spiders,</color>", "<color=#32CD32>Ich bin die Königin der Spinnen,</color>", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>And You're LUNCH!</color>", "<color=#32CD32>Und du bist mein MITTAGESSEN!</color>", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Is this...", "Ist das ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A new map?", "Eine neue Karte?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't know who stands at the end of this path...", "Ich weiß nicht, wer am Ende dieses Weges wartet ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're not meant to see this dialogue.", "Du solltest diesen Dialog nicht sehen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Something has gone wrong.", "Etwas ist schiefgelaufen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Insect Swarm", "Insektenschwarm", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of insects that the owner has on their side of the table.", "Der Wert dieses Siegels entspricht der Anzahl der Insekten auf der Seite seines Besitzers.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Create Terrain", "Gelände erzeugen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a random terrain is created on the opposing space.", "Wenn [creature] ausgespielt wird, entsteht auf dem gegenüberliegenden Feld ein zufälliges Gelände.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Egg Sacks", "Eiersäcke", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, Spiderlings are created on the owner's empty spaces.", "Wenn [creature] stirbt, entstehen Jungspinnen auf den leeren Feldern des Besitzers.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Many Legs", "Vielbeinig", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, a Leg is created in its place and a card bearing this sigil moves to the right.", "Wird [creature] getroffen, entsteht an ihrer Stelle ein Bein und eine Karte mit diesem Siegel bewegt sich nach rechts.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Stock", "Knochenvorrat", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a bone is generated for card on the owner's side of the board.", "Wenn [creature] ausgespielt wird, entsteht für jede Karte auf der Seite des Besitzers ein Knochen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flip Attack", "Angriffstausch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks, swap its Power and Health.", "Wenn [creature] angreift, werden ihre Kraft und Gesundheit vertauscht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inflamed", "Entzündet", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, discard the oldest card in your hand.", "Wird [creature] getroffen, wirf die älteste Karte auf deiner Hand ab.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Recursive", "Rekursiv", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes or is discarded, a copy of it is created in your deck.", "Wenn [creature] stirbt oder abgeworfen wird, entsteht eine Kopie dieser Karte in deinem Stapel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scuttler", "Flitzer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of battle, [creature] will move in the direction inscribed in the sigil.", "Zu Beginn des Kampfes bewegt sich [creature] in die auf dem Siegel angegebene Richtung.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dark Growth", "Dunkles Wachstum", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, adjacent and opposing cards gain 1 power and lose 1 health.", "Wenn [creature] stirbt, erhalten die links und rechts benachbarten Karten derselben Seite und die gegenüberliegende Karte 1 Kraft und verlieren 1 Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn [creature] counts down. If this sigil reaches 0, you lose.", "Am Ende jedes Zugs zählt [creature] herunter. Erreicht dieses Siegel 0, verlierst du.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Muscle Milk", "Muskelmilch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may be played on other cards. When [creature] is played on another card, it gains 1 power and loses 1 health.", "[creature] kann auf andere Karten gespielt werden. Wird [creature] auf eine andere Karte gespielt, erhält die darunterliegende Karte je 1 Kraft und Gesundheit; danach stirbt die aufgespielte Kreatur.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summoning", "Beschwörung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a random card of the same cost tier is summoned to the right.", "Wenn [creature] ausgespielt wird, wird rechts eine zufällige Karte derselben Kostenstufe beschworen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Terrain Dweller", "Geländebewohner", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may be played on terrain cards. When [creature] is played on a terrain card, the terrain gains this creature's stats and sigils.", "[creature] kann auf Geländekarten gespielt werden. Wird [creature] auf eine Geländekarte gespielt, erhält das Gelände die Werte und Siegel dieser Kreatur.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blazing Deck", "Brennender Stapel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owner's turn, [creature] will draw 1 card from your deck with Fleeting.", "Zu Beginn des Zugs ihres Besitzers zieht [creature] 1 Karte mit Flüchtig aus deinem Stapel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bellows", "Blasebalg", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, draw 1 card from your side deck with Fleeting.", "Wird [creature] getroffen, ziehe 1 Karte mit Flüchtig aus deinem Nebenstapel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Squirrel Swarm", "Eichhörnchenschwarm", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil and drop a Squirrel in its old space. Creatures that are in the way will be pushed in the same direction.", "Am Ende des Zugs ihres Besitzers bewegt sich [creature] in die auf dem Siegel angegebene Richtung und hinterlässt ein Eichhörnchen. Kreaturen im Weg werden in dieselbe Richtung geschoben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, deal a single damage point to the opposing card.", "Wenn [creature] ausgespielt wird, füge der gegenüberliegenden Karte 1 Schaden zu.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hand Limit", "Handlimit", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn [creature] is in your hand or on the board, discard your oldest card until you have 4 or less cards in your hand, or the oldest card has this sigil.", "Solange [creature] auf deiner Hand oder auf dem Brett ist, wirf am Ende jedes Zugs deine älteste Karte ab, bis du höchstens 4 Karten auf der Hand hast oder die älteste Karte dieses Siegel trägt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Devour", "Verschlingen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, the opposing card is consumed. If this creature dies, the consumed creature is returned to the hand.", "Wenn [creature] ausgespielt wird, wird die gegenüberliegende Karte verschlungen. Stirbt diese Kreatur, kehrt die verschlungene Kreatur auf die Hand zurück.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Discard Shield", "Abwurfschild", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all cards in your hand have Fleeting removed from them. When a card is drawn, Fleeting is removed from it.", "Wenn [creature] ausgespielt wird, wird Flüchtig von allen Karten auf deiner Hand entfernt. Wird eine Karte gezogen, verliert auch sie Flüchtig.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anthill", "Ameisenhügel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card is discarded while [creature] is on the board, create a Fire Ant in your hand.", "Wird eine Karte abgeworfen, während [creature] auf dem Brett ist, entsteht eine Feuerameise auf deiner Hand.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spider's Host", "Spinnenwirt", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a spiderling crawls out.", "Wenn [creature] stirbt, kriecht eine Jungspinne hervor.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasitic Bite", "Parasitenbiss", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks another creature, that creature's sigils are removed and becomes host to a spiderling.", "Wenn [creature] eine andere Kreatur angreift, verliert diese ihre Siegel und wird zum Wirt einer Jungspinne.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AH HA HA!", "AH HA HA!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT'S ME!", "ICH BIN'S!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LIGHT, LIGHT!", "LICHT, LICHT!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I BURN!", "ICH BRENNE!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I SEE YOU!", "ICH SEHE DICH!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YES!", "JA!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BURN, BURN!", "BRENN, BRENN!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DIE, DIE!", "STIRB, STIRB!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I BURN SO BRIGHTLY!", "ICH BRENNE SO HELL!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "COAL BOY, AWAY!", "KOHLENJUNGE, LOS!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PERFECT!", "PERFEKT!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AHAHAHAH", "AHAHAHA", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AHAHAHAHA", "AHAHAHAHA", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE BLINDING LIGHT!", "DAS BLENDENDE LICHT!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "EVERYONE SHALL KNOW MY PAIN!", "ALLE SOLLEN MEINEN SCHMERZ KENNENLERNEN!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SO COLD...", "SO KALT ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DARKNESS...", "DUNKELHEIT ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FADING...", "ICH VERBLASSE ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RELEASE!", "BEFREIUNG!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PICK ME!", "WÄHL MICH!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I WILL SHINE!", "ICH WERDE STRAHLEN!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE LIGHT BECKONS!", "DAS LICHT RUFT!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ME, ME!", "ICH, ICH!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SO BRIGHT!", "SO HELL!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reminds me of him...", "Erinnert mich an ihn ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NO GOOD FROM DARK!", "DUNKELHEIT BRINGT NICHTS GUTES!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ASHES, LIGHT!", "ASCHE, LICHT!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE LIGHT BECKONS!", "DAS LICHT RUFT!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE FLAMES!", "DIE FLAMMEN!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT HURTS!", "ES TUT WEH!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DARKNESS, DARKNESS!", "DUNKELHEIT, DUNKELHEIT!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'M BURNING!", "ICH BRENNE!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DOOM APPROACHES...", "DER UNTERGANG NAHT ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "REJOICE!", "FREUT EUCH!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ever closer to him...", "Ihm immer näher ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I TRANSCEND!", "ICH TRANSZENDIERE!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LIGHT!", "LICHT!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "STARS, HORSESHOES!", "STERNE, HUFEISEN!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TRIAL BY FIRE!", "FEUERPROBE!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DARKNESS HIDING!", "DUNKELHEIT VERSTECKT SICH!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DID YOU GET IT?", "HAST DU'S VERSTANDEN?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I AM COAL BOY!", "ICH BIN DER KOHLENJUNGE!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOY OF COAL!", "JUNGE AUS KOHLE!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU!", "DU!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PICKAXE MAN!", "MANN MIT DER SPITZHACKE!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HE MINES COAL!", "ER GRÄBT KOHLE!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GOLD SHINES BRIGHTLY!", "GOLD GLÄNZT HELL!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BURN THE DOGS!", "VERBRENNT DIE HUNDE!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOSS TIME!", "BOSSZEIT!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AHAHAHAHAHAHAHAHA!", "AHAHAHAHAHAHAHA!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FISH MAN!", "FISCHMANN!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BUCKETS OF FISH!", "EIMER VOLLER FISCHE!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FIIIISH!", "FIIISCH!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SO DARK AND COLD...", "SO DUNKEL UND KALT ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TWINS?", "ZWILLINGE?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SHINY KNIVES!", "GLÄNZENDE MESSER!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HIM!", "ER!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The moon...", "Der Mond ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "EMBODIMENT OF DARKNESS...", "VERKÖRPERUNG DER DUNKELHEIT ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PHANTOMS, DEMONS!", "PHANTOME, DÄMONEN!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DARK, DARK!", "DUNKEL, DUNKEL!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MOONLIGHT...", "MONDLICHT ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TRI CANDLE LIGHT!", "DREI KERZENLICHTER!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHERE'S THE SUN?", "WO IST DIE SONNE?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HEAVE,", "HO,", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HO!", "RUCK!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GUNPOWDER!", "SCHIESSPULVER!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOOM!", "BUMM!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can't burn water...", "Wasser kann man nicht verbrennen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CREATE SPARKS!", "ERZEUGE FUNKEN!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignite!", "Entzünde!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MASTER!", "MEISTER!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT'S HIM! IT'S HIM!", "ER IST ES! ER IST ES!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have brought me into your hand.", "Du hast mich auf deine Hand genommen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hello again.", "Hallo, schon wieder.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "For glory!", "Für den Ruhm!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "EN GUARDE!", "IN DECKUNG!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reforged...", "Neu geschmiedet ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heat and iron.", "Hitze und Eisen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This will be good.", "Das wird gut.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you must.", "Wenn es sein muss.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only a flesh wound.", "Nur eine Fleischwunde.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ergh.", "Argh.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oof.", "Uff.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I will not fail.", "Ich werde nicht scheitern.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stronger...", "Stärker ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I grow.", "Ich wachse.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A trial...", "Eine Prüfung ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I shouldn't be here.", "Ich sollte nicht hier sein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And yet I am.", "Und doch bin ich hier.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He mines ore for the Master.", "Er baut Erz für den Meister ab.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With the old man's permission of course.", "Natürlich mit der Erlaubnis des alten Mannes.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Prospector.", "Der Goldgräber.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He races against the Diver...", "Er tritt gegen den Taucher an ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Angler.", "Der Angler.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't actually know what they do.", "Ich weiß eigentlich nicht, was sie tun.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Who are they?", "Wer sind sie?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The old man...", "Der alte Mann ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He trades with the master sometimes.", "Er handelt manchmal mit dem Meister.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Master.", "Der Meister.", Language.German);


        }
    }
