    public class LobotomyNostalgiaMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Lobotomy_Nostalgia_Mod Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lobotomy-Nostalgia-Mod", "Lobotomy-Nostalgie-Mod", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card pack was originally created by KingSlime, later revamped and maintained by Nostalgist, containing [count] Abnormality cards from Lobotomy Corporation.", "Dieses Kartenpaket wurde ursprünglich von KingSlime erstellt und später von Nostalgist überarbeitet und gepflegt. Es enthält [count] Abnormalitätskarten aus Lobotomy Corporation.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amber Dawn", "Bernsteinfarbene Morgendämmerung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amber Dawn, searching for the perfect meals", "Die bernsteinfarbene Morgendämmerung sucht nach dem perfekten Mahl.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amber Dusk", "Bernsteinfarbene Abenddämmerung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amber Dusk, loves the taste", "Die bernsteinfarbene Abenddämmerung liebt den Geschmack.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amber Midnight", "Bernsteinfarbene Mitternacht", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "'they fough amongst themselves to feed'", "„Sie kämpften untereinander, um zu fressen.“", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "apocalypse, the horrid amalgamation of the defenders of the forest. a shame how it ended for them", "Der Apokalypsevogel, eine grauenhafte Verschmelzung der Verteidiger des Waldes. Schade, wie es für sie endete.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Aspiration, it loves seeing the battlefield", "Das Streben sieht sich gern das Schlachtfeld an.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The crazed notes, seems the writer lost thier mind", "Die wahnsinnigen Notizen. Ihr Verfasser scheint den Verstand verloren zu haben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crimson Dawn", "Blutrote Morgendämmerung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The crimson Dawn, a walking circus", "Die blutrote Morgendämmerung, ein wandelnder Zirkus.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crimson Dusk", "Blutrote Abenddämmerung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The circus tent is finally here", "Das Zirkuszelt ist endlich da.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crimson Noon", "Blutroter Mittag", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Crimson Noon, even more deformed then its brothers", "Der blutrote Mittag ist noch missgestalteter als seine Brüder.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Dawn", "Smaragdgrüne Morgendämmerung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the emerald Dawn, building towards that they came", "Die smaragdgrüne Morgendämmerung baut auf ihre Herkunft hin.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Dusk", "Smaragdgrüne Abenddämmerung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "constructing a tower from whence they came, so much potential", "Sie bauen einen Turm dorthin, woher sie kamen. So viel Potenzial.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Midnight", "Smaragdgrüne Mitternacht", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "'the tower is touched by the sky, and it will leave nothing on this earth'", "„Der Turm berührt den Himmel und wird nichts auf dieser Erde zurücklassen.“", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Noon", "Smaragdgrüner Mittag", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "emerald noon, expresseing only despair and ire", "Der smaragdgrüne Mittag drückt nur Verzweiflung und Zorn aus.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the flesh idol, worshiped by those who are truly insane", "Das Fleischidol, von wahrhaft Wahnsinnigen verehrt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Great Sap, usefull past the card", "Der große Saft ist auch außerhalb der Karte nützlich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "hod, the training meltdown", "Hod, der Zusammenbruch des Trainings.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Malkuth, The meltdown of annoying me", "Malkuth, der Zusammenbruch, der mich nervt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the mirror of adjustment, some say it leads to another world", "Der Spiegel der Anpassung. Manche sagen, er führt in eine andere Welt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "netzach, the safety meltdown", "Netzach, der Zusammenbruch der Sicherheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slime, heard he trying hard to make this mod good", "Schleim, er soll sich sehr bemühen, diesen Mod gut zu machen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the band, popular amongst teens", "Die Band ist bei Jugendlichen beliebt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orchestra", "Orchester", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the bear, it waits to show its true self", "Der Bär wartet darauf, sein wahres Wesen zu zeigen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the bloody, seems the blood never ends", "Die Blutige: Das Blut scheint niemals zu enden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the box, dont stare into the keyhole for to long", "Die Schachtel. Sieh nicht zu lange durch das Schlüsselloch.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The clockwork, the humming of its motors arent the only annoyance it makes", "Das Uhrwerk: Das Summen seiner Motoren ist nicht das Einzige, was stört.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Current, an experiment that has never seen the real world", "Die Strömung, ein Experiment, das die echte Welt nie gesehen hat.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the cute, its looks can melt even the coldest hearts", "Die Niedliche: Ihr Anblick kann selbst die kältesten Herzen schmelzen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this one is no longer cute", "Diese hier ist nicht mehr niedlich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the dream, a peaceful ram that loves to sleep", "Der Traum, ein friedlicher Widder, der gerne schläft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "guess its dream came true", "Ihr Traum ist wohl wahr geworden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the exposed, taking the direct approach", "Die Entblößte geht direkt vor.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The flower, living and walking on sunshine", "Die Blume lebt und wandelt im Sonnenschein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the fragment, the poor creature experimented on into its form", "Das Fragment, eine arme Kreatur, die durch Experimente diese Gestalt erhielt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Happy, calm yet in a state of excietment", "Die Fröhliche ist ruhig und dennoch aufgeregt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the hatefull, innocent mind for what she hides underneath", "Die Hassvolle: Unter dem, was sie verbirgt, steckt ein unschuldiger Geist.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the helper, it just wants to help you out", "Der Helfer will dir nur helfen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the judge, decider of the good and the bad", "Der Richter entscheidet über Gut und Böse.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the killer, made with intent", "Der Killer wurde mit Absicht geschaffen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the lady, no one knows what she truly looks like", "Die Dame: Niemand weiß, wie sie wirklich aussieht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The little red, hunting the wolf in a game of cat and mouse", "Das kleine Rotkäppchen jagt den Wolf in einem Katz-und-Maus-Spiel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Mad, its given up on playing nice", "Die Wahnsinnige gibt sich nicht länger freundlich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Many, Containing all the fun of 5 in 1", "Die Vielen bieten den Spaß von 5 in 1.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the masiyah, the prophet that speaks past death", "Der Messias, der Prophet, der über den Tod hinaus spricht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The melting, master of the servants", "Die Schmelzende, Herrin der Diener.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Moral, It Tries but fails to keep balance", "Die Moralische versucht vergeblich, das Gleichgewicht zu halten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yin and Yang", "Yin und Yang", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the nameless, abondend and always hungering", "Die Namenlose, verlassen und stets hungrig.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Neurtal, the only one i can deal with", "Die Neutrale, die Einzige, mit der ich umgehen kann.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Today's Neutral Look", "Der heutige neutrale Blick", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the old, no one is here to keep her company", "Die Alte, niemand leistet ihr Gesellschaft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the phoenix, its ashes keep it forever alive", "Der Phönix, dessen Asche ihn ewig leben lässt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Plague, its only the beginning", "Die Seuche, das ist erst der Anfang.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the poisoned, this apple keeps everyone away", "Die Vergiftete: Dieser Apfel hält alle fern.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the reindeer, dragging christmas fun all over the world", "Das Rentier zieht den Weihnachtsspaß durch die ganze Welt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Sad, its destined to never see the light", "Die Traurige ist dazu bestimmt, nie das Licht zu sehen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Today's Sad Look", "Der heutige traurige Blick", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the sniper, one shot is all it needs", "Der Scharfschütze braucht nur einen Schuss.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the star, the center of both attention and fashion", "Der Star, Mittelpunkt von Aufmerksamkeit und Mode.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the swan, its song sound similar to those of the band", "Der Gesang des Schwans klingt ähnlich wie der der Band.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The train, best not walk in its way", "Der Zug: Geh ihm besser nicht in den Weg.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the tree, spreading its roots to help its allies", "Der Baum breitet seine Wurzeln aus, um Verbündeten zu helfen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the true hatred, seems she let out what she had inside", "Der wahre Hass scheint herausgelassen zu haben, was in ihr steckte.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the wolf, seems cute on first glance", "Der Wolf wirkt auf den ersten Blick niedlich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the woodsman, sweeping the forest with its axe", "Der Holzfäller fegt mit seiner Axt durch den Wald.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Army, they never seem to end", "Die Armee scheint endlos zu sein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've never seen this one here", "Das habe ich hier noch nie gesehen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The CherryTree, Contains the bodies of thousands", "Der Kirschbaum enthält die Körper Tausender.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Fruit, its ripe for the picking.", "Die Frucht ist reif zum Pflücken.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Galaxy, a blessing, and a curse.", "Die Galaxie, ein Segen und ein Fluch.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The greedfull, carefull not to touch it.", "Die Gierige: Pass auf, dass du sie nicht berührst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Hive, The true ruler of the hive", "Der Bienenstock, sein wahrer Herrscher.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Innocent, Ignorant in everything besides pain", "Die Unschuldige kennt nichts außer Schmerz.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Mountain, it smiles upon you ", "Der Berg lächelt dich an.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Nest, its presence is unsettling  ", "Das Nest: Seine Anwesenheit ist beunruhigend.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Nothing...", "Das Nichts ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Silent, Performing the best orchestra around.", "Die Stille, die das beste Orchester weit und breit dirigiert.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Silent", "Die Stille", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Swarm, he dresses for the occasion", "Der Schwarm hat sich für den Anlass gekleidet.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Trap, So Cute yet so deadly", "Die Falle, so niedlich und doch so tödlich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tiphereth, the command meltdown", "Tiphereth, der Zusammenbruch der Leitung.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Violet Dawn", "Violette Morgendämmerung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "violet dawn, radiating the field", "Die violette Morgendämmerung bestrahlt das Feld.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "violet Midnight", "Violette Mitternacht", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "we tried to accept it,we wanted to understand them", "Wir versuchten, es zu akzeptieren; wir wollten sie verstehen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Violet noon", "Violetter Mittag", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "violet noon, enscrybing the words of their gods", "Der violette Mittag ritzt die Worte ihrer Götter ein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So that explains the chills", "Das erklärt das Frösteln.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the white night, the true end of the world", "Die weiße Nacht, das wahre Ende der Welt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yesod, the concealing meltdown", "Yesod, der Zusammenbruch der Verheimlichung.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Claw", "Die Klaue", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps you can survive this white midnight.", "Vielleicht überlebst du diese weiße Mitternacht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You definitely won't press the button, right?", "Du wirst den Knopf doch nicht drücken, oder?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If it's not voluntary, does anyone really need to be 'fixed'?", "Wenn es nicht freiwillig ist, muss dann überhaupt jemand „repariert“ werden?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No one wants to know what truly protects them.", "Niemand will wissen, was sie wirklich beschützt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is currently unclear why such a painting would exist.", "Warum ein solches Gemälde existiert, ist derzeit unklar.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gloomy Seahorse", "Düsteres Seepferdchen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Play the fatal movement.", "Spiele den tödlichen Satz.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why does the mysterious ray appear within the facility?", "Warum erscheint der rätselhafte Rochen in der Einrichtung?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stingray", "Stachelrochen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What sorrow.", "Was für eine Trauer.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Intangible creation.", "Eine ungreifbare Schöpfung.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A scarecrow soaked in fresh blood.", "Eine mit frischem Blut getränkte Vogelscheuche.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you yearn for blessings?", "Sehnst du dich nach Segen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps, she can protect no one.", "Vielleicht kann sie niemanden beschützen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mechanical creations, restoring peace and health", "Mechanische Schöpfungen, die Frieden und Gesundheit wiederherstellen.", Language.German);

        }
    }
    public class NevernamedsBestiaryMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Nevernameds_Bestiary Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ace Lord", "Assfürst", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aderyn Y corph", "Aderyn Y corph", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The corpse bird. It's appearance portends the end.", "Der Leichenvogel. Sein Erscheinen kündigt das Ende an.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Adipocere", "Leichenwachs", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Poor little corpse wax, it can be molded into any shape you can think of.", "Armes kleines Leichenwachs, es lässt sich in jede erdenkliche Form bringen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It lurks below the water, until the time is ripe to rend the land for prey.", "Es lauert unter Wasser, bis die Zeit gekommen ist, das Land auf der Suche nach Beute aufzureißen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ahuizotl", "Ahuizotl", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Albatross", "Albatros", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The noble albatross. It's vast wingspan creates an impressive downdraft.", "Der edle Albatros. Seine gewaltige Flügelspannweite erzeugt einen beeindruckenden Abwind.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Albatross Chick", "Albatrosküken", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The young of the immense albatross, it seems almost lost inside of it's own down.", "Das Junge des riesigen Albatros scheint fast in seinem eigenen Flaum zu verschwinden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gar Roe", "Knochenhechtrogen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toxic gar roe, will kill anything that swallows it.", "Giftiger Knochenhechtrogen tötet alles, was ihn verschluckt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alligator Gar", "Alligatorhecht", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ferocious Alligator Gar. It squirts out it's toxic eggs when frightened.", "Der wilde Alligatorhecht spritzt seine giftigen Eier aus, wenn er erschrickt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amorphous Shame", "Formlose Scham", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...such a shame...", "... was für eine Schande ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anaconda", "Anaconda", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't... don't say it. I have heard it all before, and it is not funny.", "Sag ... sag es nicht. Ich habe das alles schon gehört, und es ist nicht lustig.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anansi", "Anansi", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anansi, the many legged trickster. He attacks multiple times per turn, in flagrant disregard for the rules.", "Anansi, der vielbeinige Schwindler. Er greift mehrmals pro Zug an und missachtet dabei offen die Regeln.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anchimayen", "Anchimayen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anemone", "Seeanemone", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The soft, unassuming anemone- it seems to have remarkable potential for propagation, but no means as of yet...", "Die weiche, unscheinbare Seeanemone scheint großes Vermehrungspotenzial zu besitzen, hat aber noch keine Möglichkeit dazu ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Angel Shark", "Engelhai", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Despite the name, it is far from divine.", "Trotz seines Namens ist er alles andere als göttlich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That irritating canine...", "Dieser lästige Hund ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anteater", "Ameisenbär", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The slothly anteater only attacks with vigour when presented with a meal.", "Der träge Ameisenbär greift nur dann mit Schwung an, wenn ihm eine Mahlzeit winkt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Antingaw", "Antingaw", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A peculiar mollusk. It gathers sustenance from burrowing into barren rock...", "Ein sonderbares Weichtier. Es gräbt sich in kahles Gestein und gewinnt so Nahrung ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So small... so fragile...", "So klein ... so zerbrechlich ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The larvae of the antlion. It's skill for trapping knows no match... in the insect world.", "Die Larve des Ameisenlöwen. Ihre Fähigkeit, Fallen zu stellen, ist unerreicht ... in der Insektenwelt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ararach", "Ararach", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The infinilegged crawler, the Ararach never settles on a definitive strategy of attack for long...", "Ararach, der Kriecher mit unzähligen Beinen, bleibt nie lange bei einer Angriffsstrategie ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The archerfish is quick to retaliate to any confrontation with a precise jet of water.", "Der Schützenfisch reagiert auf jede Konfrontation mit einem präzisen Wasserstrahl.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Areion", "Areion", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The eternally running Areion. It loyally moves wherever it's owner demands it in the blink of an eye.", "Areion läuft ewig. Treu bewegt es sich im Nu dorthin, wo sein Besitzer es verlangt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Artful Magister", "Listiger Magister", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aspidochelone", "Aspidochelone", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That ruthless spiny turtle... it shares it's spines with it's comrades..", "Diese rücksichtslose, stachelige Schildkröte ... Sie teilt ihre Stacheln mit ihren Gefährten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Automamox", "Automamox", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Axehandle Hound", "Axtstielhund", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The peculiar axehandle hound. It uses it's sharp, bladed nose to cut clean through it's foes with the cold precision of a lumberjack...", "Der sonderbare Axtstielhund. Mit seiner scharfen, klingenartigen Nase zerschneidet er Feinde mit der kalten Präzision eines Holzfällers ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Axe Murderer", "Axtmörder", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Through night he hunts, in blackened brush, the bite of an axe heralds a blood red stream.", "Nachts jagt er im schwarzen Gestrüpp; der Biss einer Axt kündigt einen blutroten Strom an.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Babai", "Babai", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baboon", "Pavian", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Far more vicious than its name and appearance would betray- it needs only a reason to strike.", "Viel grausamer, als Name und Aussehen vermuten lassen: Es braucht nur einen Grund zuzuschlagen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bakunawa", "Bakunawa", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The lengthy Bakunawa, terror of the sea and skies.", "Der lange Bakunawa, Schrecken von Meer und Himmel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Balaur", "Balaur", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The three-headed Balaur dragon. It lashes out with each of it's maws when threatened.", "Der dreiköpfige Drache Balaur. Wird er bedroht, schlägt er mit jedem seiner Mäuler zu.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bald Eagle", "Weißkopfseeadler", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Truly the most patriotic of birds.", "Wahrlich der patriotischste aller Vögel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ball Droid", "Kugeldroide", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Balloondroid", "Ballondroide", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bandito", "Bandit", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A peculiar deathcard- no matter how many times I tear it to pieces, I always find it back in my deck...", "Eine seltsame Todeskarte. Ganz gleich, wie oft ich sie zerreiße, ich finde sie immer wieder in meinem Stapel ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bannana", "Banane", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such a small, sweet spider... It couldn't hurt a fl- ...oh", "Eine so kleine, süße Spinne ... Sie könnte keiner Flie... oh.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Barnacle", "Seepocke", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The unimpressive barnacle. Anything that strikes it will be torn to shreds on it's rough shell.", "Die unscheinbare Seepocke. Alles, was sie trifft, wird an ihrer rauen Schale zerfetzt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Basilisk", "Basilisk", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The grim basilisk. Life withers and dies under it's mere gaze.", "Der düstere Basilisk. Schon sein Blick lässt Leben verwelken und sterben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning Bat", "Brennende Fledermaus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The first... and last time one of my... associates attempted to use living organisms to it's own advantage.", "Das erste ... und letzte Mal, dass einer meiner ... Partner Lebewesen zu seinem Vorteil einzusetzen versuchte.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Batfly", "Flederfliege", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The perturbing batfly. It clings to airborne creatures for a free ride.", "Die verstörende Flederfliege. Sie klammert sich an fliegende Kreaturen und fährt kostenlos mit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bat Tery", "Flederbatterie", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beached Whale", "Gestrandeter Wal", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The poor thing, completely out of it's element... it bursts upon death.", "Das arme Ding, völlig fehl am Platz ... Es platzt, wenn es stirbt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beast Of Exmoor", "Bestie von Exmoor", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The illusory exmoor cat... hard to catch, harder to kill.", "Die schemenhafte Exmoor-Katze ... schwer zu fangen, noch schwerer zu töten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Belladin", "Glockenpaladin", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bellbird", "Glockenvogel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Their cry is melodic, like the ringing of a great chime.", "Ihr Ruf klingt melodisch wie das Läuten einer großen Glocke.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bellbot", "Glockenbot", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bhoot", "Bhoot", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How she floats above the holy earth... I wonder what form she will take next!", "Wie sie über der heiligen Erde schwebt ... Welche Gestalt wird sie wohl als Nächstes annehmen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bind Warden", "Fesselwächter", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Biscione", "Biscione", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vicious biscione, it is insatiable in it's lust for flesh.", "Der grausame Biscione, dessen Verlangen nach Fleisch unersättlich ist.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bishop", "Bischof", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bison", "Bison", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The trampling Bison. It destroys anything in it's path, and becomes more enraged as it becomes more soaked with blood...", "Der niedertrampelnde Bison vernichtet alles auf seinem Weg und wird umso wütender, je mehr Blut ihn bedeckt ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Black Dog", "Schwarzer Hund", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The grim black dog, haunter of graveyards... omen incarnate.", "Der düstere schwarze Hund sucht Friedhöfe heim ... ein Omen in Fleisch und Blut.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Black Egg", "Schwarzes Ei", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Something pulses dimly, below the surface...", "Unter der Oberfläche pulsiert etwas schwach ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Black Giant Squirrel", "Schwarzes Riesenhörnchen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The shadowy Black Giant Squirrel. It hits hard and is easily deployed, but perishes with no brothers or sisters by it's side...", "Das schattenhafte schwarze Riesenhörnchen schlägt kräftig zu und ist leicht auszuspielen, stirbt aber ohne Geschwister an seiner Seite ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Black Kite", "Schwarzmilan", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It carries the flames of a previous inferno to drive prey from cover...", "Er trägt Flammen eines früheren Feuers, um Beute aus ihrem Versteck zu treiben ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Black Widow", "Schwarze Witwe", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The black widow spider. It's infamous bite kills swiftly.", "Die Schwarze Witwe. Ihr berüchtigter Biss tötet rasch.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blank Obelisk", "Leerer Obelisk", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A blank obelisk. Unremarkable.", "Ein leerer Obelisk. Unauffällig.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blast Termite", "Sprengtermite", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The disgusting blasting termite. It explodes it's foes upon death.", "Die widerliche Sprengtermite sprengt bei ihrem Tod ihre Feinde.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blind Mouse", "Blinde Maus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Those blind mice... always travelling in a group. See how they run...", "Diese blinden Mäuse ... immer in Gruppen unterwegs. Sieh sie laufen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blind Scorpion", "Blinder Skorpion", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The poor blinded scorpion. It's venom is immaculate, but it's aim?... less so.", "Der arme blinde Skorpion. Sein Gift ist tadellos, aber seine Treffsicherheit ... weniger.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloated Leech", "Aufgeblähter Blutegel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The disquieting leech. It has reached full maturity.", "Der beunruhigende Blutegel ist ausgewachsen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blockhead", "Dummkopf", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A comically frontheavy insect.", "Ein Insekt, dessen Vorderseite lächerlich schwer ist.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloodbag", "Blutbeutel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Cell", "Blutzelle", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Knight", "Blutritter", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Red Dog", "Blutroter Hund", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The infamous blood red dog, nothing can stop it's lust for combat. We'll have tea in hell today...", "Der berüchtigte blutrote Hund. Nichts kann seine Kampflust stoppen. Heute trinken wir Tee in der Hölle ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloodstopper", "Blutstiller", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Witch", "Bluthexe", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The bloodstarved beast. It will wither and die if it does not taste violence each turn.", "Die bluthungrige Bestie verdorrt und stirbt, wenn sie nicht in jedem Zug Gewalt schmeckt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloody Sack", "Blutiger Sack", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blowfly", "Schmeißfliege", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Disgusting.", "Widerlich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bluebottle", "Schmeißfliege", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The bluebottle... what secrets lie beyond it's squishy facade?", "Die Schmeißfliege ... welche Geheimnisse verbirgt ihre weiche Fassade?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue-Ringed", "Blaugeringelter Krake", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Blue-Ringed Octopus. It's venom is one of the most potent in the world...", "Der blaugeringelte Krake. Sein Gift gehört zu den stärksten der Welt ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue Whale", "Blauwal", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The greatest mortal beast ever to roam the seas... but not the greatest immortal one.", "Die größte sterbliche Bestie, die je die Meere durchstreifte ... aber nicht die größte unsterbliche.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BoardWipe", "Brettbereinigung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bobbit Worm", "Bobbitwurm", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The terrifying bobbit worm. It leaps from it's aquatic burrow to attack with it's razor sharp jaws.", "Der furchterregende Bobbitwurm springt aus seinem Wasserbau und greift mit messerscharfen Kiefern an.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bobcat", "Rotluchs", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Often underestimated, the Bobcat will strike the moment it is played.", "Der oft unterschätzte Rotluchs schlägt zu, sobald er ausgespielt wird.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Body Snatcher", "Körperräuber", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boil", "Furunkel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A festering little blotch.", "Ein kleiner, eiternder Fleck.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bolotnik", "Bolotnik", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The bloated swampman. It drags others down to hades- returning for more.", "Der aufgeblähte Sumpfmensch zieht andere in die Unterwelt und kehrt zurück, um weitere zu holen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bombardier Beetle", "Bombardierkäfer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The incandescant bombardier beetle. It's boiling hot secretions scald it's prey.", "Der glühende Bombardierkäfer. Seine kochend heißen Sekrete verbrühen seine Beute.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Cell", "Knochenzelle", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Clutter", "Knochenhaufen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boneworm", "Knochenwurm", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The morbid boneworm. It excells in bringing remains to the surface of the churning soil...", "Der unheimliche Knochenwurm bringt Überreste geschickt an die Oberfläche der aufgewühlten Erde ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Booting Bot", "Start-Bot", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bot Printer", "Botdrucker", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bowerbird", "Laubenvogel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The crafty bowerbird, master of manipulating materials around itself.", "Der listige Laubenvogel beherrscht den Umgang mit den Materialien seiner Umgebung.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Box Jelly", "Würfelqualle", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Small, but possessing of a crippling set of stingers.", "Klein, aber mit lähmenden Nesselzellen ausgestattet.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Proceed", "Weiter", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brazen Bull", "Eherner Stier", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The horrific brazen bull. A true metric of human depravity.", "Der schreckliche eherne Stier. Ein wahres Maß menschlicher Verderbtheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's go!", "Los geht's!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Play me properly", "Spiele mich richtig aus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAHAHAHAHAAH, YES!", "HAHAHAHA, JA!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YES, YES!", "JA, JA!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LET'S MAKE A RING", "LASST UNS EINEN RING", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OF FIRE", "AUS FEUER SCHAFFEN", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAHAHAHAHAH", "HAHAHAHAHA", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BURN", "BRENNEN", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I want to", "Ich will", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "see the fire", "das Feuer sehen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "for glory!", "Für den Ruhm!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yes, very well", "Ja, sehr gut", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's get to work", "Machen wir uns an die Arbeit", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAHAHAHAHA", "HAHAHAHA", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAHAHAHAHAHAHAH", "HAHAHAHAHAHA", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TO GLORY", "FÜR DEN RUHM", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAHAHAHAHAHAH", "HAHAHAHAHA", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAHAHAH, YES!", "HAHAHA, JA!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IMPROVE ME", "VERBESSERE MICH", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can be", "Ich kann", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So much more!", "So viel mehr sein!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you want.", "Wenn du willst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SACRIFICE ME!", "OPFERE MICH!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YES", "JA", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I WILL DIE", "ICH STERBE", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FOR YOU", "FÜR DICH", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's up to you", "Du entscheidest", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harder!", "Stärker!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DO IT!", "TU ES!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAHAHAHAHAHA!", "HAHAHAHAHA!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YES! MORE!", "JA! MEHR!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Very good.", "Sehr gut.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THANK YOU, THANK YOU!", "DANKE, DANKE!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "VICTORY?", "SIEG?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TO GLORY!", "FÜR DEN RUHM!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YES, YES", "JA, JA", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brine Shrimp", "Salzkrebs", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The tiny, fleeting brine shrimp, so small it's as if it's not even there...", "Der winzige, flüchtige Salzkrebs, so klein, als wäre er gar nicht da ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brollachan", "Brollachan", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The wicked Brollachan. It can take many powerful forms...", "Der böse Brollachan kann viele mächtige Gestalten annehmen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brown Recluse", "Braune Einsiedlerspinne", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The unassuming Brown Recluse. It attacks when threatened.", "Die unscheinbare Braune Einsiedlerspinne greift an, wenn sie bedroht wird.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Budgerigar", "Wellensittich", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A friendly bird of domesticated breed, the Budgerigar will follow your command...", "Der freundliche domestizierte Wellensittich folgt deinen Befehlen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bugbear", "Bugbear", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The horrifying Bugbear. No creatures wish to remain in it's presence.", "Der schreckliche Bugbear. Keine Kreatur möchte in seiner Nähe bleiben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Busted Bot", "Ausgemusterter Bot", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Busted Conduit", "Ausgemusterter Leiter", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Buzzard", "Bussard", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The shameless buzzard- an inescapable symbol of death in the sands.", "Der schamlose Bussard, ein unausweichliches Symbol des Todes im Sand.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spiny Ant", "Stachelameise", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A friendly ant covered in sharp thorns.", "Eine freundliche Ameise, die von scharfen Dornen bedeckt ist.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The splifficated Cactus Cat, it roams the desert drinking the fermented juice of it's lookalike plant...", "Die betrunkene Kaktuskatze durchstreift die Wüste und trinkt den vergorenen Saft der Pflanze, der sie ähnelt ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Caged Beasts", "Bestien im Käfig", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Poor, caged animals. Won't you set them free?", "Arme Tiere im Käfig. Willst du sie nicht befreien?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Calygreyhound", "Calygreyhound", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The calygreyhound- a confusing chimeric clash which nonetheless stirs the loyalties of it's comrades.", "Der Calygreyhound, ein verwirrendes chimärisches Mischwesen, das dennoch die Treue seiner Gefährten weckt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Camazotz", "Camazotz", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Camazotz, the bat god. He flies low amongst his enemies, slashing them with his bloodstained claws.", "Camazotz, der Fledermausgott. Er fliegt tief zwischen seinen Feinden und zerreißt sie mit blutigen Klauen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cam Drone", "Kameradrohne", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The stocky camel, it is resilient against most any threat", "Das stämmige Kamel trotzt beinahe jeder Bedrohung.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Camel Spider", "Walzenspinne", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Camel Spider... an unpleasant arachnid to even gaze upon.", "Die Walzenspinne ... ein Spinnentier, dessen Anblick schon unangenehm ist.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Candiru", "Candiru", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A bloodsucking fish with a terrifying reputation.", "Ein blutsaugender Fisch mit einem schrecklichen Ruf.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Canopic Hawk", "Kanopenhabicht", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A delicate ceramic bird, full of guts...", "Ein filigraner Keramikvogel voller Eingeweide ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The much-beloved Capybara... it's fighting spirit is closely tied to it's wellbeing.", "Das beliebte Wasserschwein ... sein Kampfgeist hängt eng mit seinem Wohlbefinden zusammen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Caracal", "Karakal", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A quizzacious predator, ready to leap at any unsuspecting prey.", "Ein neugieriges Raubtier, bereit, sich auf ahnungslose Beute zu stürzen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carrion Fly", "Aasfliege", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The disgusting carrion fly. Drawn to death.", "Die widerwärtige Aasfliege. Vom Tod angezogen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Catalogue Keeper", "Kataloghüter", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Catron", "Catron", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cattle Rustler", "Viehdieb", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cellar Spider", "Zitterspinne", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Cellar spider. An exemplar of all arachnida.", "Die Zitterspinne. Ein Musterbeispiel für alle Spinnentiere.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chameleon", "Chamäleon", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A chameleon always changes it's spots, as is the proverb.", "Wie das Sprichwort sagt: Das Chamäleon ändert stets seine Flecken.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enraged Fey", "Wütende Fee", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The development of the changeling is entirely dependant on it's early childhood... violence begets violence.", "Die Entwicklung des Wechselbalgs hängt ganz von seiner frühen Kindheit ab ... Gewalt erzeugt Gewalt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pitiful Fey", "Erbärmliche Fee", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Changeling", "Wechselbalg", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chaos Card", "Chaoskarte", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chaos Engine", "Chaosmaschine", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Charred Lump", "Verkohlter Klumpen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Charybdis", "Charybdis", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Charybdis, the infernal vortex. Sucks all around it into it's collossal maw.", "Charybdis, der höllische Strudel. Sie saugt alles um sich herum in ihren gewaltigen Schlund.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A vindictive, nasty little bird.", "Ein rachsüchtiger, gemeiner kleiner Vogel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chicken Bones", "Hühnerknochen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awfully sharp... and awfully disposable.", "Furchtbar scharf ... und furchtbar kurzlebig.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chimpanzee", "Schimpanse", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The true utility of the chimp lies in it's dilligent hands...", "Der wahre Nutzen des Schimpansen liegt in seinen fleißigen Händen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chiral Crawler", "Chiraler Kriecher", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Can a creature that drags its shackles along with it ever truly be free?", "Kann eine Kreatur, die ihre Fesseln mit sich schleppt, jemals wirklich frei sein?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chochin", "Chochin", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aha! The little lantern spook, such a mischevious little spirit it is!", "Aha! Der kleine Laternengeist, was für ein schelmischer Spuk!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chuman", "Chuman", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unholy union.", "Eine unheilige Verbindung.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This beast of the night will tear apart any small prey he finds...", "Diese Bestie der Nacht zerreißt jede kleine Beute, die sie findet ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clanklion", "Klapplöwe", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clumsy Pupil", "Ungeschickter Schüler", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cobra", "Kobra", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The swift cobra. Usually passive, but it delivers a nasty bite when startled.", "Die flinke Kobra. Meist friedlich, beißt sie jedoch heftig zu, wenn man sie erschreckt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cockle", "Herzmuschel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The unremarkable cockle, it feeds upon the remnants of the dead...", "Die unscheinbare Herzmuschel ernährt sich von den Überresten der Toten ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Code Thief", "Codedieb", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coinchenn", "Coinchenn", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It lurks in the shadows of history, and shows no mercy to its prey.", "Es lauert im Schatten der Geschichte und kennt keine Gnade mit seiner Beute.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Colossal Squid", "Koloss-Kalmar", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The colossal squid. It drags it's foes down to a watery grave.", "Der Koloss-Kalmar. Er zieht seine Feinde in ein nasses Grab.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tubular Bells", "Röhrenglocken", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cone Snail", "Kegelschnecke", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The venomous cone snail. Beware it's paralysing toxin.", "Die giftige Kegelschnecke. Hüte dich vor ihrem lähmenden Gift.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conjurer", "Beschwörer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Copepod", "Ruderfußkrebs", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The unassuming copepod, resilient to the last.", "Der unscheinbare Ruderfußkrebs, widerstandsfähig bis zuletzt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mysterious copycat. When it perishes, it... warps, to mimic it's murderer.", "Der geheimnisvolle Nachahmer. Wenn er umkommt, verformt er sich ... und nimmt die Gestalt seines Mörders an.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coral", "Koralle", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A stoic coral colony, akin more to the landscape around it than to any other beast...", "Eine stoische Korallenkolonie, die eher der Landschaft um sie herum als irgendeiner Bestie gleicht ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Counstabot", "Wachtbot", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cow", "Kuh", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Centuries of domestication have not made it any less stubborn...", "Jahrhunderte der Domestizierung haben sie nicht weniger stur gemacht ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cowardly lion. It attempts to live up to the ferocity of it's cousins, but with little success.", "Der feige Löwe. Er versucht, der Wildheit seiner Verwandten gerecht zu werden, doch mit wenig Erfolg.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cowardly Lion", "Feiger Löwe", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cowbird", "Kuhstärling", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Too cowardly to remain for long, the cowbird is always eager to cause trouble.", "Zu feige, um lange zu bleiben, ist der Kuhstärling stets bereit, Ärger zu machen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Time for crab.", "Zeit für Krabben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crab Spider", "Krabbenspinne", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The hardy crab spider, it clings relentlessly to any source of food or warmth.", "Die zähe Krabbenspinne klammert sich unablässig an jede Nahrungs- oder Wärmequelle.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crayfish", "Flusskrebs", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The unrelenting crayfish. It changes the orientation of it's claws each turn.", "Der unerbittliche Flusskrebs. Er ändert jede Runde die Ausrichtung seiner Scheren.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cremator", "Einäscherer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crimson Paladin", "Purpurpaladin", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crooked Mouse", "Verzerrte Maus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It was never the same after a run in with a crooked cat...", "Nach einer Begegnung mit einer verzerrten Katze war sie nie wieder dieselbe ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crooked Wraith", "Verzerrtes Gespenst", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A strange one, this. Even I don't know its twisted past.", "Ein seltsames Wesen. Selbst ich kenne seine verdrehte Vergangenheit nicht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crucibulum", "Tiegelteuerling", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A peculiar little snail, forever growing it's conical shell.", "Eine eigenartige kleine Schnecke, deren kegelförmiges Haus ständig weiterwächst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crystal Healer", "Kristallheiler", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cubit", "Kubit", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Curly-Legged Cat", "Katze mit krummen Beinen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its twisted legs coil and bend in ways inexplicable. It is full of potential.", "Seine verdrehten Beine winden und biegen sich auf unerklärliche Weise. Es steckt voller Potenzial.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Curruid", "Curruid", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clawed lord of the waves, the Curruid has but one blind spot.", "Der klauenbewehrte Herr der Wellen, der Curruid, hat nur einen blinden Fleck.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cursed Child", "Verfluchtes Kind", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That... should not be in my deck...", "Das ... sollte nicht in meinem Stapel sein ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Stunted... Wolf... I thought I threw him- ...I mean, this, away...", "Der verkümmerte ... Wolf ... Ich dachte, ich hätte ihn weggewor... ich meine, das Ding ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The... stoat. Did I leave this here?", "Das ... Hermelin. Habe ich es hier liegen lassen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The... pungent... stinkbug?..", "Die ... übelriechende ... Stinkwanze? ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cyclops", "Zyklop", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The diminutive cyclops. It's great eye holds a perfect image of the past.", "Der winzige Zyklop. Sein großes Auge bewahrt ein vollkommenes Abbild der Vergangenheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aim well.", "Ziele gut.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shoot with caution.", "Schieße vorsichtig.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aim me well.", "Ziele mit mir gut.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acceptable draw.", "Akzeptabler Zug.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Survive.", "Überlebe.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am your instrument.", "Ich bin dein Werkzeug.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I will succeed.", "Ich werde Erfolg haben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you are", "Wenn du", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "certain.", "sicher bist.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I trust", "Ich vertraue", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The bigger", "auf das große", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "picture.", "Ganze.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Over exposed.", "Überbelichtet.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This turn?", "Diesen Zug?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Temporal Misplay.", "Zeitlicher Fehlzug.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remember this.", "Merk dir das.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Certainly.", "Gewiss.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have", "Du hast", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "aimed... well.", "gut ... gezielt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Within acceptable", "Innerhalb akzeptabler", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "parameters.", "Parameter.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Betrayal.", "Verrat.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Judas.", "Judas.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once more?", "Noch einmal?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How many times...", "Wie oft noch ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acceptable.", "Akzeptabel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Modification.", "Modifikation.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is desirable.", "Das ist wünschenswert.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Picturesque.", "Malerisch.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Regards.", "Mit besten Grüßen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undesirable.", "Unerwünscht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cease.", "Hör auf.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is unfriendly.", "Das ist unfreundlich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cease considerations.", "Stelle die Überlegungen ein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Halt.", "Stopp.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have been...", "Ich habe ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...dealt a blow", "... einen Schlag erhalten", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...a blow", "... einen Schlag", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Suffered.", "Eingesteckt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Assessing damages.", "Schaden wird bewertet.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dealt a blow...", "Einen Schlag erhalten ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So... familiar...", "So ... vertraut ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is unfortunate", "Es ist bedauerlich,", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "that we must", "dass wir", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "trade blows...", "Schläge tauschen müssen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I feel... kinship.", "Ich spüre ... Verbundenheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am improved.", "Ich wurde verbessert.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Improvement", "Verbesserung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Edit in progress.", "Bearbeitung läuft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A new instrument.", "Ein neues Werkzeug.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Under analysis", "Wird analysiert", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "statistically viable", "statistisch sinnvoll", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A lineup?", "Eine Aufstellung?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Darter", "Schlangenhalsvogel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mind the splash.", "Achte auf die Spritzer.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "\"When the Lamb broke the fourth seal, I heard the voice of the fourth living creature saying, \"Come.\" I looked, and behold, an ashen horse; and he who sat on it had the name Death; and Hades was following with him.\"", "„Als das Lamm das vierte Siegel öffnete, hörte ich die Stimme des vierten lebendigen Wesens sagen: ‚Komm.‘ Ich sah hin, und siehe, ein fahles Pferd; sein Reiter hieß Tod, und die Unterwelt folgte ihm.“", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death", "Tod", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deaths Door", "Tor des Todes", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't worry, we'll pull you through.", "Keine Sorge, wir bringen dich da durch.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deathstalker", "Gelber Mittelmeerskorpion", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The deathstalker scorpion. It's tail packs a potent venom.", "Der gelbe Mittelmeerskorpion. Sein Schwanz enthält ein starkes Gift.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "De Bug", "Entwanzer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What... is that?", "Was ... ist das?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Decorator Crab", "Dekorateurkrabbe", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The lowly decorator crab. It scrounges the bottom of the ocean for detritus to stick to it's body.", "Die unscheinbare Dekorateurkrabbe. Sie sucht am Meeresboden nach Trümmern, die sie an ihrem Körper befestigt.", Language.German);


        }
    }
    public class NeedMoreWaterMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for NeedMoreWater Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Card Pack:NMW", "Kartenpaket: NMW", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cardumen", "Fischschwarm", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cuando una carta que lleve este sello mate a otra criatura en combate, se crea una copia de esa carta en tu mano.", "Wenn eine Karte mit diesem Siegel im Kampf eine andere Kreatur tötet, wird eine Kopie der Karte mit diesem Siegel auf deiner Hand erzeugt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rape", "Seeteufel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Engañoso y altamente peligroso ese Rape.", "Dieser Seeteufel ist hinterlistig und äußerst gefährlich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "La sangre derramada las atrae...", "Vergossenes Blut lockt sie an ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pez Arquero", "Schützenfisch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Su disparo de agua derriba a los insectos para comérselos.", "Er schießt Insekten mit einem Wasserstrahl herunter, um sie zu fressen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pez Beta", "Kampffisch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "El Pez Beta. Una belleza viva de las aguas.", "Der Kampffisch. Eine lebendige Schönheit des Wassers.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pez Gato", "Wels", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "El Pez Gato. Nunca te faltarán cebos.", "Der Wels. Dir werden nie die Köder ausgehen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cocodrilo", "Krokodil", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cocodrilo, gran cazador. Ningún nadador escapa de sus fauces.", "Das Krokodil, ein großer Jäger. Kein Schwimmer entkommt seinem Maul.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Morena", "Muräne", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acecha entre las grietas, esperando a que algo nade demasiado cerca.", "Sie lauert in den Spalten und wartet darauf, dass etwas zu nahe schwimmt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pez León", "Rotfeuerfisch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Su veneno no es letal, pero sacará a la vista tus puntos débiles.", "Sein Gift ist nicht tödlich, legt aber deine Schwachstellen offen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Piraña", "Piranha", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pirañas, nunca hay una sola en el agua.", "Piranhas sind im Wasser niemals allein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pez Globo", "Kugelfisch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Su combinación de veneno y espinas es letal para cualquier ser vivo.", "Die Kombination aus Gift und Stacheln ist für jedes Lebewesen tödlich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pez Remo", "Riemenfisch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Una de las bestias mas raras que he fotografiado jamás.", "Eine der seltensten Bestien, die ich je fotografiert habe.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rhyzostoma", "Wurzelmundqualle", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nada sobrevive a la Rhyzostoma, ni dentro ni fuera del agua.", "Nichts überlebt die Wurzelmundqualle, weder im noch außerhalb des Wassers.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Salmón", "Lachs", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "El salmón, pez difícil de pescar.", "Der Lachs, ein schwer zu fangender Fisch.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Esturión", "Stör", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "El inundible esturión, acorazado marino.", "Der unsinkbare Stör, das Panzerschiff des Meeres.", Language.German);



        }
    }
    public class SauriaSigilsMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for SauriaSigils Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Avenging", "Rachsüchtig", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever an adjacent card perishes during combat, a card bearing this sigil gains 1 Power.", "Immer wenn eine benachbarte Karte im Kampf umkommt, erhält eine Karte mit diesem Siegel 1 Kraft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Avenging Strike", "Rachsüchtiger Schlag", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The loss of its friend will not go unpunished.", "Der Verlust seines Freundes wird nicht ungestraft bleiben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever a friendly card is killed during combat by an opponent's card, a card bearing this sigil moves to that space and strikes the attacker.", "Immer wenn eine verbündete Karte im Kampf von einer gegnerischen Karte getötet wird, bewegt sich eine Karte mit diesem Siegel auf deren Feld und schlägt den Angreifer.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "To avenge the fallen...", "Um die Gefallenen zu rächen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bleeding", "Blutung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil loses 1 Health at the end of their owner's turn.", "Eine Karte mit diesem Siegel verliert am Ende des Zuges ihres Besitzers 1 Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How much longer can it endure?", "Wie lange kann sie noch durchhalten?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blessing", "Segen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 4 Bones to increase Health of this and adjacent creatures by 1 if they have less than 10.", "Bezahle 4 Knochen, um die Gesundheit dieser und benachbarter Kreaturen mit weniger als 10 Gesundheit um 1 zu erhöhen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your beasts feel better now.", "Deinen Bestien geht es jetzt besser.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blizzard", "Schneesturm", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is placed, unoccupied spaces on its owner's side are filled with blocks of ice.", "Wenn eine Karte mit diesem Siegel platziert wird, werden freie Felder auf der Seite ihres Besitzers mit Eisblöcken gefüllt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Winter is coming.", "Der Winter naht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A bone to gnaw on.", "Ein Knochen zum Nagen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Blast", "Knochenexplosion", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When initiating combat, a card bearing this sigil dies. Upon death, all other cards take damage equal to the amount of owner's bones.", "Zu Beginn des Kampfes stirbt eine Karte mit diesem Siegel. Bei ihrem Tod erleiden alle anderen Karten Schaden in Höhe der Knochenzahl ihres Besitzers.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not a pretty sight", "Kein schöner Anblick", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Gift", "Knochengeschenk", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is placed, a Bone is created in your hand. [define:Sauria_Bone]", "Wenn eine Karte mit diesem Siegel platziert wird, wird ein Knochen auf deiner Hand erzeugt. [define:Sauria_Bone]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A gift for its master.", "Ein Geschenk für seinen Meister.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Offering", "Knochenopfer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card on the opponent's side of board that costs Bones or Blood. Pay its price in Bones to add it to your hand. Blood is counted as 3 Bones, cannot choose cards that cost neither resource.", "Wähle eine Karte auf der gegnerischen Seite des Bretts, die Knochen oder Blut kostet. Bezahle ihren Preis in Knochen, um sie auf deine Hand zu nehmen. Jedes Blut zählt als 3 Knochen; Karten, die keine dieser Ressourcen kosten, sind nicht wählbar.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You've managed to entice one of my beasts.", "Du hast es geschafft, eine meiner Bestien zu verführen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cannibalistic", "Kannibalisch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When another card on the owner's side of board takes damage and its Health no longer exceeds Power of the bearer of this sigil, this card attacks it.", "Wenn eine andere Karte auf der Seite des Besitzers Schaden erleidet und ihre Gesundheit die Kraft des Trägers dieses Siegels nicht mehr übersteigt, greift diese Karte sie an.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A grim opportunity to feast.", "Eine düstere Gelegenheit zum Schmausen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Caretaker", "Betreuer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, all other cards on the owner's side of board heal 1 Health while a card bearing this sigil is alive.", "Solange eine Karte mit diesem Siegel lebt, heilen alle anderen Karten auf der Seite ihres Besitzers am Ende des Zuges 1 Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It tends to their wounds.", "Es versorgt ihre Wunden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Catapult", "Katapult", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Bone to select another card on your side of the board to move to another space, including opponent's side of the board.", "Bezahle 1 Knochen, um eine andere Karte auf deiner Seite des Bretts auf ein anderes Feld zu bewegen, auch auf die gegnerische Seite.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Watch out for falling beasts.", "Vorsicht vor fallenden Bestien.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Change Form", "Formwechsel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil transform into an alternate form.", "Eine Karte mit diesem Siegel verwandelt sich in eine andere Form.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Watch it shift its form.", "Sieh zu, wie sie ihre Form wechselt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Shifter", "Knochenwandler", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 3 Bones to transform this card into an alternate form.", "Bezahle 3 Knochen, um diese Karte in eine andere Form zu verwandeln.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Concerned", "Besorgt", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a friendly card takes damage, a card bearing this sigil attempts to move to its closest adjacent space. If that space is occupied, it attempts to move one space in that direction instead.", "Wenn eine verbündete Karte Schaden erleidet, versucht eine Karte mit diesem Siegel, sich auf das nächstgelegene Nachbarfeld dieser Karte zu bewegen. Ist es besetzt, versucht sie stattdessen, ein Feld in diese Richtung zu ziehen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It responds to its ally's distress.", "Es reagiert auf die Not seines Verbündeten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cruelty", "Grausamkeit", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals damage to another card through any other means, it deals 1 damage to its target.", "Wenn eine Karte mit diesem Siegel einer anderen Karte auf irgendeine andere Weise Schaden zufügt, fügt sie ihrem Ziel zusätzlich 1 Schaden zu.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This beasts wishes to inflict more grievous injuries.", "Diese Bestie will schwerere Wunden zufügen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deep Freeze", "Tiefgefroren", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil perishes within 2 turns, the creature within is released.", "Wenn eine Karte mit diesem Siegel innerhalb von 2 Zügen umkommt, wird die Kreatur in ihr freigesetzt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Free at last.", "Endlich frei.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Desperate Push", "Verzweifelter Stoß", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil perishes during combat while opposing space is occupied, it pushes the opposing cards back.", "Wenn eine Karte mit diesem Siegel im Kampf umkommt und das gegenüberliegende Feld besetzt ist, stößt sie die gegnerischen Karten zurück.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps its sacrifice will pay off.", "Vielleicht zahlt sich sein Opfer aus.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dismember", "Zerstückeln", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals damage to another card, gain bones equal to the damage dealt, up to 5 bones at once.", "Wenn eine Karte mit diesem Siegel einer anderen Karte Schaden zufügt, erhältst du Knochen in Höhe des Schadens, höchstens 5 auf einmal.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How gruesome.", "Wie grausig.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Embolden", "Ermutigen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, if there are adjacent cards with less Power than the bearer of this sigil, lose 1 Power and give 1 Power to them.", "Wenn am Ende des Zuges des Besitzers benachbarte Karten weniger Kraft als der Träger dieses Siegels haben, verliert er 1 Kraft und gibt ihnen 1 Kraft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It shares its strength with its allies.", "Es teilt seine Stärke mit seinen Verbündeten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enduring", "Beständig", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil gains 2 Health at the start of its third turn on the board.", "Eine Karte mit diesem Siegel erhält zu Beginn ihres dritten Zuges auf dem Brett 2 Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prolonged combat is fortifying this beast.", "Der lange Kampf stärkt diese Bestie.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Erratic March", "Unberechenbarer Marsch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will move in the direction inscribed on the sigil at the end of its owner's turn. If there are cards in its way or this card is at edge of the board, it will try to move to the opponent's side of board first.", "Am Ende des Zuges ihres Besitzers bewegt sich eine Karte mit diesem Siegel in die angegebene Richtung. Stehen Karten im Weg oder ist sie am Rand des Bretts, versucht sie zuerst, auf die gegnerische Seite zu wechseln.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its movements are unpredictable.", "Seine Bewegungen sind unvorhersehbar.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fervor", "Eifer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil gains 1 Power at the start of its third turn on the board.", "Eine Karte mit diesem Siegel erhält zu Beginn ihres dritten Zuges auf dem Brett 1 Kraft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prolonged combat is making this beast grow more ferocious.", "Der lange Kampf macht diese Bestie immer wilder.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Genetic Flaw", "Gendefekt", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil loses 1 Health at the end of their owner's turn.", "Eine Karte mit diesem Siegel verliert am Ende des Zuges ihres Besitzers 1 Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps it's not meant to live.", "Vielleicht soll es nicht leben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Genetic Perfection", "Genetische Perfektion", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If card bearing this sigil has its stats reduced below their normal values, it gains 1 Power and/or Health at the end of its owner's turn. If this card has Genetic Flaw sigil, remove it.", "Sind die Werte einer Karte mit diesem Siegel unter ihre Normalwerte gesunken, erhält sie am Ende des Zuges ihres Besitzers 1 Kraft und/oder Gesundheit. Hat sie das Siegel Gendefekt, entferne es.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is perfection incarnate.", "Es ist die Perfektion in Person.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater Catapult", "Großes Katapult", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 3 Bones to select another card on your side of the board to move to another space, including opponent's side of the board. If there is an obstruction with a free opposing space, it takes damage equal to this card's Attack first. If obstruction remains, selected card attempts to move to its opposing space instead.", "Bezahle 3 Knochen, um eine andere Karte deiner Seite auf ein anderes Feld zu bewegen, auch auf die gegnerische Seite. Steht dort ein Hindernis, dessen gegenüberliegendes Feld frei oder von der gewählten Karte belegt ist, erleidet es zuerst Schaden in Höhe des Angriffs des Siegelträgers. Bleibt es bestehen, versucht die gewählte Karte, auf das gegenüberliegende Feld zu gelangen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good aim.", "Gut gezielt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater Embolden", "Große Ermutigung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, if there are any cards on owner's side of the board with less Power than the bearer of this sigil, lose 1 Power and give 1 Power to them.", "Wenn am Ende des Zuges des Besitzers Karten auf seiner Seite weniger Kraft als der Träger dieses Siegels haben, verliert er 1 Kraft und gibt ihnen 1 Kraft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It shares its strength with all of its allies.", "Es teilt seine Stärke mit all seinen Verbündeten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater Grudge Bearer", "Großer Grollträger", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever cards belonging to the owner of the card bearing this sigil are struck, the attacker is marked. At the start of the owner's turn, this card attacks all marked cards owned by the opponent.", "Immer wenn Karten des Besitzers einer Karte mit diesem Siegel getroffen werden, wird der Angreifer markiert. Zu Beginn des Zuges des Besitzers greift diese Karte alle markierten gegnerischen Karten an.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death is the only suitable punishment.", "Der Tod ist die einzig angemessene Strafe.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater Nurture", "Große Aufzucht", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, if there are any cards on owner's side of the board with less Health than the bearer of this sigil, lose 1 Health and give 1 Health to them.", "Wenn am Ende des Zuges des Besitzers Karten auf seiner Seite weniger Gesundheit als der Träger dieses Siegels haben, verliert er 1 Gesundheit und gibt ihnen 1 Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It shares its essence with all of its allies.", "Es teilt seine Essenz mit all seinen Verbündeten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grievous Display", "Schreckensbild", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil attacks an opposing creature and it perishes, creatures to the left and right of the target lose 1 Power.", "Wenn eine Karte mit diesem Siegel eine gegnerische Kreatur angreift und diese umkommt, verlieren die Kreaturen links und rechts des Ziels 1 Kraft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not easy on the eyes.", "Kein schöner Anblick.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ground Pound", "Bodenstoß", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is placed, cards in opposing and adjacent spaces take 1 damage. This effect is additionally activated when moving 2 spaces away from last position or the opponent's side of board.", "Wird eine Karte mit diesem Siegel platziert, erleiden die Karten links und rechts von ihr in derselben Reihe sowie die gegenüberliegende Karte 1 Schaden. Der Effekt tritt auch ein, wenn sie die Seite wechselt oder sich in derselben Reihe mindestens 2 Felder bewegt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A less than graceful landing.", "Eine wenig elegante Landung.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ground Smash", "Bodenschmettern", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is placed, it deals damage to cards in opposing and adjacent spaces equal to its Attack or at least 1 damage. This effect is additionally activated when moving 2 spaces away from last position or the opponent's side of board.", "Wird eine Karte mit diesem Siegel platziert, fügt sie den Karten links und rechts in derselben Reihe sowie der gegenüberliegenden Karte Schaden in Höhe ihres Angriffs zu, mindestens 1. Der Effekt tritt auch ein, wenn sie die Seite wechselt oder sich in derselben Reihe mindestens 2 Felder bewegt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What a nasty shockwave.", "Was für eine heftige Druckwelle.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grudge Bearer", "Grollträger", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is struck, the attacker is marked. At the start of the owner's turn, this card attacks a random marked card owned by the opponent.", "Wird eine Karte mit diesem Siegel getroffen, wird der Angreifer markiert. Zu Beginn des Zuges ihres Besitzers greift diese Karte eine zufällige markierte gegnerische Karte an.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It will remember this.", "Es wird sich daran erinnern.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grudge-Powered", "Grollgespeist", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of opponent's creatures marked by Grudge Bearer sigils and the number of said creatures killed by the bearer of this sigil.", "Der Wert dieses Siegels entspricht der Anzahl gegnerischer Kreaturen, die von Grollträger-Siegeln markiert wurden, plus der Anzahl solcher Kreaturen, die der Träger dieses Siegels getötet hat.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of opponent's creatures marked by Grudge Bearer sigils and the number of said creatures killed by [creature].", "Die Kraft von [creature] entspricht der Anzahl gegnerischer Kreaturen, die von Grollträger-Siegeln markiert wurden, plus der Anzahl solcher Kreaturen, die [creature] getötet hat.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grudge Target", "Grollziel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will be attacked by opponent's cards bearing Grudge Bearer sigils.", "Eine Karte mit diesem Siegel wird von gegnerischen Karten mit Grollträger-Siegeln angegriffen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A permanent stain.", "Ein unauslöschlicher Makel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hasty Escape", "Hastige Flucht", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Upon taking damage, the bearer of this sigil returns to owner's hand if it's still alive.", "Erleidet der Träger dieses Siegels Schaden, kehrt er auf die Hand seines Besitzers zurück, falls er noch lebt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sometimes, cowards do survive.", "Manchmal überleben Feiglinge.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bigger Block of Ice", "Größerer Eisblock", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A block of ice, nothing to see", "Ein Eisblock, hier gibt es nichts zu sehen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It shares its meal with its newfound family.", "Es teilt seine Mahlzeit mit seiner neuen Familie.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Knock Back", "Zurückstoßen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals damage to another card, it attempts to move its target to an adjacent space, prioritizing right.", "Fügt eine Karte mit diesem Siegel einer anderen Karte Schaden zu, versucht sie, ihr Ziel auf ein benachbartes Feld zu bewegen, bevorzugt nach rechts.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A nasty blow.", "Ein übler Schlag.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Juicy Meat", "Saftiges Fleisch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Meat", "Fleisch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Makes you salivate.", "Da läuft einem das Wasser im Mund zusammen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Memento", "Andenken", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil perishes during combat, adjacent cards gain 1 Power.", "Kommt eine Karte mit diesem Siegel im Kampf um, erhalten benachbarte Karten 1 Kraft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its friends will not forgive those fiends.", "Seine Freunde werden diesen Ungeheuern nicht vergeben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Complete and total extermination is the only reasonable response.", "Die vollständige und totale Vernichtung ist die einzig vernünftige Antwort.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Micro", "Mikro", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Movement Command", "Bewegungsbefehl", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once per turn, move the bearer of this sigil to a selected empty space.", "Bewege den Träger dieses Siegels einmal pro Zug auf ein ausgewähltes leeres Feld.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The beast follows your command.", "Die Bestie folgt deinem Befehl.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nurture", "Aufziehen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, if there are adjacent cards with less Health than the bearer of this sigil, lose 1 Health and give 1 Health to them.", "Wenn am Ende des Zuges des Besitzers benachbarte Karten weniger Gesundheit als der Träger dieses Siegels haben, verliert er 1 Gesundheit und gibt ihnen 1 Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It shares its essence with its allies.", "Es teilt seine Essenz mit seinen Verbündeten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Outburst", "Ausbruch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, a card bearing this sigil performs an additional attack against opposing space if it's occupied by a card whose Attack is above 0.", "Am Ende des Zuges ihres Besitzers greift eine Karte mit diesem Siegel das gegenüberliegende Feld zusätzlich an, wenn dort eine Karte mit mehr als 0 Angriff steht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It won't be moving for long at this rate.", "Bei diesem Tempo wird es nicht mehr lange laufen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasitoid Propagation", "Parasitoide Vermehrung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil kills another creature, a copy of this card is created in your hand.", "Tötet eine Karte mit diesem Siegel eine andere Kreatur, wird eine Kopie dieser Karte auf deiner Hand erzeugt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Life can be unsightly at times.", "Das Leben kann manchmal unschön sein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parental Care", "Elterliche Fürsorge", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, creatures with Fledgling sigil adjacent to a card bearing this sigil gain 1 Health.", "Am Ende des Zuges des Besitzers erhalten Kreaturen mit dem Siegel Entwicklung, die an eine Karte mit diesem Siegel angrenzen, 1 Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good parent.", "Ein gutes Elternteil.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parting Bone", "Abschiedsknochen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil dies or is sacrificed, a Bone is created in your hand. [define:Sauria_Bone]", "Wenn eine Karte mit diesem Siegel stirbt oder geopfert wird, wird ein Knochen auf deiner Hand erzeugt. [define:Sauria_Bone]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A parting gift for its master.", "Ein Abschiedsgeschenk für seinen Meister.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Persistent", "Fortbestehen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil would die during combat for the first time, it revives and gains 2 Power.", "Wenn eine Karte mit diesem Siegel zum ersten Mal im Kampf sterben würde, erwacht sie wieder zum Leben und erhält 2 Kraft.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That creature will not give up so easily.", "Diese Kreatur gibt nicht so leicht auf.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protective", "Beschützend", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When an adjacent card is struck, a card bearing this sigil strikes the attacker.", "Wird eine benachbarte Karte getroffen, schlägt eine Karte mit diesem Siegel den Angreifer.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It doesn't appreciate having its comrades hurt.", "Es duldet nicht, dass seine Gefährten verletzt werden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protective Parent", "Beschützendes Elternteil", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When owner's cards with Fledgling sigil are struck, bearer of this sigil strikes the attacker.", "Werden Karten des Besitzers mit dem Siegel Entwicklung getroffen, schlägt der Träger dieses Siegels den Angreifer.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Few things inspire more awe and fear than a protective parent.", "Weniges weckt so viel Ehrfurcht und Furcht wie ein beschützendes Elternteil.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pursuer", "Verfolger", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever an opponent's card moves to another space, a card bearing this sigil attempts to move to its current opposing space. If successful, it deals 1 damage to its opposing space.", "Bewegt sich eine gegnerische Karte, versucht eine Karte mit diesem Siegel, das Feld gegenüber ihrer neuen Position zu erreichen. Gelingt das, fügt sie der noch lebenden Karte dort 1 Schaden zu.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is no escape...", "Es gibt kein Entkommen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quake", "Beben", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 4 Bones to deal 1 damage to all enemy cards. This sigil is removed afterwards.", "Bezahle 4 Knochen, um allen gegnerischen Karten 1 Schaden zuzufügen. Danach wird dieses Siegel entfernt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Terrifying display of power.", "Eine furchterregende Machtdemonstration.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Served Dinner", "Abendessen serviert", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card on the owner's side of board. Add stats of the card bearing this sigil to the selected card. This card dies afterwards. This effect can also be activated by sacrificing or killing this page directly.", "Wähle eine Karte auf der Seite des Besitzers. Addiere die Werte der Karte mit diesem Siegel zu der gewählten Karte. Diese Karte stirbt danach. Der Effekt kann auch durch ihr direktes Opfern oder Töten ausgelöst werden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dinner is served.", "Das Abendessen ist serviert.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shoal Strike", "Schwarmschlag", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is placed, it deals 1 damage to all of opponent's submerged cards and forces them to surface.", "Wird eine Karte mit diesem Siegel platziert, fügt sie allen abgetauchten gegnerischen Karten 1 Schaden zu und zwingt sie aufzutauchen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The hunt begins...", "Die Jagd beginnt ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skittish", "Schreckhaft", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card moves into space opposing the one bearing this sigil, deal 1 damage to it, then move to a random unoccupied space on the owner's side of board if possible.", "Bewegt sich eine Karte auf das Feld gegenüber dem Träger dieses Siegels, fügt er ihr 1 Schaden zu und bewegt sich danach, falls möglich, auf ein zufälliges freies Feld auf der Seite seines Besitzers.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This creature appears to be rather skittish.", "Diese Kreatur scheint ziemlich schreckhaft zu sein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sprinter Strike", "Sprinterschlag", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenener a card bearing this sigil moves, it deals 1 damage to its opposing space. If said space is not occupied, the opponent is deald 1 damage immediately.", "Immer wenn sich eine Karte mit diesem Siegel bewegt, fügt sie dem gegenüberliegenden Feld 1 Schaden zu. Ist es leer, erleidet der Gegner sofort 1 Schaden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A swift strike.", "Ein schneller Schlag.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sticky Tongue", "Klebrige Zunge", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owners turn, a card bearing this sigil attempts to drag creatures adjacent to opposing space or queued behind it in front of itself, prioritizing the latter. If affected card has 1 Health, this card immediately attacks it.", "Zu Beginn des Zuges ihres Besitzers versucht eine Karte mit diesem Siegel, Kreaturen neben dem gegenüberliegenden Feld oder in der Warteschlange dahinter vor sich zu ziehen, wobei letztere Vorrang haben. Hat die gezogene Karte 1 Gesundheit, greift sie sie sofort an.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What a sticky situation.", "Eine klebrige Angelegenheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tactical Retreat", "Taktischer Rückzug", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, the bearer of this sigil returns to owner's hand if it's still alive.", "Am Ende des Zuges seines Besitzers kehrt der Träger dieses Siegels auf dessen Hand zurück, falls er noch lebt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It doesn't feel the need to stay on the board.", "Es sieht keinen Grund, auf dem Brett zu bleiben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TearThrough", "Durchbrechen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If opposing space is occupied, a card bearing this sigil will move in the direction inscribed on the sigil at the end of its owner's turn, dealing 1 damage to the card in that space and trying to move it as well.", "Ist das gegenüberliegende Feld besetzt, bewegt sich eine Karte mit diesem Siegel am Ende des Zuges ihres Besitzers in die angegebene Richtung, fügt der Karte auf diesem Feld 1 Schaden zu und versucht, sie ebenfalls zu bewegen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A brutal display", "Eine brutale Darbietung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Territorial", "Revierverteidigend", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When another creature moves into an adjacent or opposing space, a card bearing this sigil attacks it.", "Bewegt sich eine andere Kreatur auf ein benachbartes oder gegenüberliegendes Feld, greift eine Karte mit diesem Siegel sie an.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "To intrude upon its territory...", "Sein Revier zu betreten ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tyranny", "Tyrannei", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Blood to increase Attack and Health of this and adjacent creatures by 1, then remove this sigil.", "Bezahle 2 Blut, um Angriff und Gesundheit dieser und benachbarter Kreaturen um 1 zu erhöhen. Entferne danach dieses Siegel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A sacrifice this beast is willing to make.", "Ein Opfer, das diese Bestie bereitwillig bringt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vicious Growth", "Bösartiges Wachstum", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil kills another creature, it gains 1 Power and 1 Health.", "Tötet eine Karte mit diesem Siegel eine andere Kreatur, erhält sie 1 Kraft und 1 Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One life to nourish another.", "Ein Leben nährt ein anderes.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wounding", "Verwunden", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals damage to another card without Made of Stone, its target gains Bleeding effect. Bleeding cards lose 1 Health at the end of their owner's turn.", "Fügt eine Karte mit diesem Siegel einer Karte ohne Steinern Schaden zu, erhält das Ziel den Effekt Blutung. Blutende Karten verlieren am Ende des Zuges ihres Besitzers 1 Gesundheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This must sting.", "Das muss wehtun.", Language.German);



            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's a Grudgin'", "Das gibt Groll", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have a card collect grudges from 10 marked cards in a single battle", "Lass eine Karte in einem Kampf Groll von 10 markierten Karten sammeln.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Complete and Total Extermination", "Vollständige und totale Vernichtung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have a card with Greater Grudge Bearer wipe out 4 marked cards at once.", "Lass eine Karte mit Großem Grollträger 4 markierte Karten auf einmal vernichten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Completely Boned", "Völlig entbeint", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wipe out the whole board via Bone Blast.", "Räume das ganze Brett mit Knochenexplosion ab.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plateosaurus School of Thought", "Die Denkschule des Plateosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have a philosopher bother 10 cards with questions in a single battle.", "Lass einen Philosophen in einem Kampf 10 Karten mit Fragen belästigen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Terrible Roommate", "Schrecklicher Mitbewohner", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have a territorial card lash out at friendly cards in a single battle", "Lass eine revierverteidigende Karte in einem Kampf verbündete Karten angreifen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beast Cannon", "Bestienkanone", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kill at least 2 enemy cards by throwing a hefty beast at them.", "Töte mindestens 2 gegnerische Karten, indem du eine schwere Bestie auf sie wirfst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Et Tu, Majungasaurus?", "Auch du, Majungasaurus?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have a cannibalistic card devour 10 friendly cards in a single battle.", "Lass eine kannibalische Karte in einem Kampf 10 verbündete Karten verschlingen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "'Tis But A Scratch", "Nur ein Kratzer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have one of your cards survive 10 turns while bleeding.", "Lass eine deiner Karten 10 Züge lang blutend überleben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Empathetic", "Einfühlsam", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have a nurturing card sacrifice 10 Health in a single battle.", "Lass eine aufziehende Karte in einem Kampf 10 Gesundheit opfern.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rally", "Sammeln", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have an emboldening card sacrifice 10 Power in a single battle.", "Lass eine ermutigende Karte in einem Kampf 10 Kraft opfern.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ascended Arts", "Aufgestiegene Künste", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have a certain card fully remove cost of 6 cards in a single run.", "Lass eine bestimmte Karte in einem Durchlauf die Kosten von 6 Karten vollständig entfernen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raptor Attack", "Raptorenangriff", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obtain at least 10 Raptor cards in a single run.", "Erhalte mindestens 10 Raptor-Karten in einem Durchlauf.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jurassic World", "Jurassic World", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Finish a run with 3 secret cards. Life finds a way.", "Schließe einen Durchlauf mit 3 geheimen Karten ab. Das Leben findet einen Weg.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Apex Predators", "Spitzenprädatoren", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have three biggest theropods in your deck in a single run.", "Habe in einem Durchlauf die drei größten Theropoden in deinem Stapel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "King of the Monsters", "König der Monster", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unleash the King of the Monsters upon the enemy.", "Entfessle den König der Monster gegen den Feind.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ballad of Big Al", "Die Ballade vom großen Al", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Help get the big girl back on her feet. Poor thing.", "Hilf der Großen wieder auf die Beine. Die Arme.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Indomitable One", "Der Unbeugsame", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Create a genetic abomination with more teeth.", "Erschaffe eine genetische Abscheulichkeit mit mehr Zähnen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Monster Resurrected", "Das Monster lebt wieder", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Make Spinosaurus feel like a monster.", "Lass Spinosaurus sich wie ein Monster fühlen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jurassic Painter", "Jurassic-Maler", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Promote Stokesosaurus to a painter.", "Befördere Stokesosaurus zum Maler.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All Outta Gum", "Kaugummi alle", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Give the little guy balls of steel.", "Verleihe dem Kleinen Eier aus Stahl.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Novel Look", "Neues Aussehen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Take the frills off the crested critter.", "Nimm dem Tier mit dem Kamm seine Halskrause ab.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bird Up", "Vogel voraus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Put too many feathers where they don't belong.", "Bringe viel zu viele Federn dort an, wo sie nicht hingehören.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wu's Secrets", "Wus Geheimnisse", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have Compstegnathus, Spinoraptor and Ankylodocus in your deck in a single run.", "Habe Compstegnathus, Spinoraptor und Ankylodocus in einem Durchlauf in deinem Stapel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Welcome to Jurassic Park", "Willkommen im Jurassic Park", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Finish a run with Jurassic Park deck and at least 7 related cards.", "Schließe einen Durchlauf mit dem Jurassic-Park-Stapel und mindestens 7 zugehörigen Karten ab.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prehistoric Collection", "Prähistorische Sammlung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Play a copy of every common Sauria card.", "Spiele je ein Exemplar jeder gewöhnlichen Sauria-Karte.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rare Fossils", "Seltene Fossilien", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Play a copy of every rare Sauria card.", "Spiele je ein Exemplar jeder seltenen Sauria-Karte.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Paleo-Novice", "Paläo-Neuling", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Finish a run with 5 Sauria decks.", "Schließe Durchläufe mit mindestens 5 verschiedenen Sauria-Startstapeln ab.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dino-Fan", "Dino-Fan", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Finish a run with 20 Sauria decks.", "Schließe Durchläufe mit mindestens 20 verschiedenen Sauria-Startstapeln ab.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deck-O-Saurus", "Stapel-O-Saurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Finish a run with every available Sauria deck.", "Schließe je einen Durchlauf mit jedem verfügbaren Sauria-Stapel ab.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gyarouucore", "Gyarouucore", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obtained every other achievement! Good job!", "Du hast alle anderen Erfolge errungen! Gut gemacht!", Language.German);

        }
    }
    public class SauriaCardsMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for SauriaCards Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acrocanthosaurus", "Acrocanthosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acrocanthosaurus, terror of the North. It does not take much to provoke this giant into attacking.", "Acrocanthosaurus, der Schrecken des Nordens. Es braucht nicht viel, um diesen Riesen zu einem Angriff zu reizen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Allosaurus", "Allosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This tenacious predator doesn't know when to stop its assault.", "Dieses hartnäckige Raubtier weiß nicht, wann es seinen Angriff beenden soll.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amargasaurus", "Amargasaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amargasaurus, a surprisingly small beast for its kind. Size is relative, however.", "Amargasaurus, eine für seine Art überraschend kleine Bestie. Größe ist allerdings relativ.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "American Lion", "Amerikanischer Löwe", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The American Lion, a vicious feline predator with a soft heart. It does not extend its kindness towards its prey, however.", "Der amerikanische Löwe, ein grausames Raubtier mit weichem Herzen. Seiner Beute gegenüber zeigt er allerdings keine Güte.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "American Lion Cub", "Amerikanisches Löwenjunges", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An American Lion Cub, an adorable kitten. It's hard to imagine something like this growing up to become a terrifying predator", "Ein amerikanisches Löwenjunges, ein entzückendes Kätzchen. Man kann sich kaum vorstellen, dass daraus ein furchterregendes Raubtier wird.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ankylosaurus", "Ankylosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sturdy Ankylosaurus. It may not feel claws and teeth strike its hide, but it does not appreciate being pestered during mealtime.", "Der robuste Ankylosaurus. Vielleicht spürt er Klauen und Zähne auf seiner Haut nicht, doch beim Fressen lässt er sich ungern stören.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anomalocaris", "Anomalocaris", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ancient Anomalocaris, one of the first apex predators to live in this world. It does its best against modern beasts.", "Der uralte Anomalocaris, einer der ersten Spitzenprädatoren dieser Welt. Gegen moderne Bestien gibt er sein Bestes.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Apatosaurus", "Apatosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The formidable Apatosaurus. It doesn't need to be the biggest of its kind to crush enemies into dust.", "Der gewaltige Apatosaurus. Er muss nicht der größte seiner Art sein, um Feinde zu Staub zu zermalmen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Argentinosaurus", "Argentinosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The titanic Argentinosaurus, truly a sight to behold. Make sure to keep your distance if you do not wish to be crushed.", "Der titanische Argentinosaurus, wahrlich ein beeindruckender Anblick. Halte Abstand, wenn du nicht zerquetscht werden willst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Arthropleura", "Arthropleura", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Arthropleura, an oversized centipede with a taste for decaying plants. Its movements are unpredictable.", "Arthropleura, ein übergroßer Tausendfüßer mit Vorliebe für verrottende Pflanzen. Seine Bewegungen sind unberechenbar.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aspidorhynchus", "Aspidorhynchus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is much bigger fish out there, but Aspidorhynchus is still perfectly capable of biting your fingers off.", "Es gibt viel größere Fische, aber Aspidorhynchus kann dir trotzdem mühelos die Finger abbeißen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Australovenator", "Australovenator", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vicious Australovenator. It pierces and tears through the hide of its victims with its enlarged claws.", "Der grausame Australovenator. Mit seinen vergrößerten Klauen durchbohrt und zerreißt er die Haut seiner Opfer.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Austroraptor", "Austroraptor", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The keen-eyed Austroraptor, a skilled fisher of light build. It's far from harmless, however.", "Der scharfsichtige Austroraptor, ein geschickter Fischer mit leichtem Körperbau. Harmlos ist er dennoch keineswegs.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baryonyx", "Baryonyx", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baryonyx, a crocodile-faced beast with a taste for fish. Refrain from smiling if you do not wish to expand its diet.", "Baryonyx, eine Bestie mit Krokodilgesicht und Vorliebe für Fisch. Verzichte aufs Lächeln, wenn du seinen Speiseplan nicht erweitern willst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beipiaosaurus", "Beipiaosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Beipiaosaurus is armed with sharp claws to rend its foes apart...but it does not have the courage to stand up to anything bigger.", "Dieser Beipiaosaurus hat scharfe Klauen, um seine Feinde zu zerreißen ... doch ihm fehlt der Mut, sich größeren Gegnern zu stellen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brachiosaurus", "Brachiosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mighty Brachiosaurus. It can use its immense size to draw aggressors away from allies.", "Der mächtige Brachiosaurus. Mit seiner gewaltigen Größe kann er Angreifer von Verbündeten weglocken.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brachiosaurus Hatchling", "Brachiosaurus-Junges", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Brachiosaurus hatchling. It will take some time for it to reach its full size.", "Ein Brachiosaurus-Junges. Es wird einige Zeit brauchen, bis es ausgewachsen ist.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brachytrachelopan", "Brachytrachelopan", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brachytrachelopan, a bizarre creature for its kind. Though it lacks their characteristic long neck, its long tail makes up for its absence.", "Brachytrachelopan, eine für seine Art seltsame Kreatur. Ihm fehlt zwar der typische lange Hals, doch sein langer Schwanz gleicht das aus.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Camarasaurus", "Camarasaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ginormous Camarasaurus. Though it does not wish to bring harm directly, its great size allows it to fling beasts across the battlefield.", "Der riesige Camarasaurus. Er will niemanden direkt verletzen, doch seine Größe erlaubt ihm, Bestien über das Schlachtfeld zu schleudern.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sauria", "Sauria", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carnotaurus", "Carnotaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though not as swift as commonly believed, this beast can hardly be stopped once it gains momentum.", "Obwohl sie nicht so schnell ist, wie man gemeinhin glaubt, lässt sich diese Bestie kaum aufhalten, sobald sie Schwung aufgenommen hat.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cartorhynchus", "Cartorhynchus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Cartorhynchus may be tiny, but there is bigger fish following its trail.", "Dieser Cartorhynchus mag winzig sein, doch ein größerer Fisch folgt seiner Spur.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Caturus", "Caturus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Caturus, an imposing predator to some, an enticing snack for others.", "Caturus, für manche ein imposantes Raubtier, für andere ein verlockender Happen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cearadactylus", "Cearadactylus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Too busy fretting over its meals, Cearadactylus does not make for a great fighter.", "Cearadactylus ist zu sehr mit der Sorge um seine Mahlzeiten beschäftigt, um ein guter Kämpfer zu sein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cephalaspis", "Cephalaspis", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cephalaspis, an armored fish shaped like a shovel. Its thick armor lets it feed in peace.", "Cephalaspis, ein gepanzerter Fisch in Form einer Schaufel. Seine dicke Panzerung lässt ihn in Ruhe fressen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ceratodus", "Ceratodus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The peculiar Ceratodus, a fish with the ability to live on land. Makes for a fine meal.", "Der eigentümliche Ceratodus, ein Fisch, der an Land leben kann. Er gibt eine gute Mahlzeit ab.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ceratosaurus", "Ceratosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though often overshadowed by its bigger competitors, Ceratosaurus is a formidable threat in its own right.", "Obwohl er oft von größeren Konkurrenten überschattet wird, ist Ceratosaurus selbst eine beachtliche Bedrohung.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chasmosaurus", "Chasmosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The stalwart Chasmosaurus. It uses its shield-like frill to protect allies.", "Der standhafte Chasmosaurus. Er schützt seine Verbündeten mit seinem schildförmigen Nackenschild.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chungkingosaurus", "Chungkingosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though it may not be eager to hurt other creatures, you do not want to get near the tail of Chungkingosaurus.", "Auch wenn Chungkingosaurus andere Kreaturen nicht unbedingt verletzen will, solltest du seinem Schwanz fernbleiben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coelophysis", "Coelophysis", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coelophysis, one of the first of its kind. Many more terrible beasts have spawned from its lineage.", "Coelophysis, einer der ersten seiner Art. Aus seiner Linie gingen viele weitere schreckliche Bestien hervor.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Compsognathus", "Compsognathus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The diminutive Compsognathus. It can hardly pose a threat while alone.", "Der winzige Compsognathus. Allein stellt er kaum eine Bedrohung dar.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Corythosaurus", "Corythosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Corythosaurus, a cautious beast that does not travel alone. It finds safety in a herd.", "Corythosaurus, eine vorsichtige Bestie, die nicht allein umherzieht. In der Herde findet sie Sicherheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dacentrurus", "Dacentrurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dacentrurus, a beast with an oddly elongated neck that fiercely protects its allies.", "Dacentrurus, eine Bestie mit ungewöhnlich langem Hals, die ihre Verbündeten entschlossen beschützt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Daeodon", "Daeodon", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The terrible Daeodon. It may not be a pig, but it is certainly prepared for war.", "Der schreckliche Daeodon. Er ist vielleicht kein Schwein, aber er ist gewiss bereit für den Krieg.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deinocheirus", "Deinocheirus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once thought to be a terrible beast, Deinocheirus turned out to be far more bizarre than anyone expected. Its strength is not to be underestimated, however.", "Einst für eine schreckliche Bestie gehalten, erwies sich Deinocheirus als viel seltsamer als erwartet. Seine Stärke sollte man trotzdem nicht unterschätzen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deinonychus", "Deinonychus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deinonychus, a vicious hunter known for the enlarged claws adorning its feet. How's that for a 'six-foot turkey'?", "Deinonychus, ein grausamer Jäger, bekannt für die vergrößerten Klauen an seinen Füßen. Was sagst du zu diesem „sechs Fuß großen Truthahn“?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sicilian Dwarf Elephant", "Sizilianischer Zwergelefant", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sicilian Dwarf Elephant, a severely undersized counterpart of one of the biggest animals to roam the land today. Such is life on small island.", "Der sizilianische Zwergelefant, eine winzige Version eines der größten heutigen Landtiere. So ist das Leben auf einer kleinen Insel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Desmatosuchus", "Desmatosuchus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though not blessed with sharp teeth or claws, Desmatosuchus tries to make up for it with its thick hide", "Obwohl Desmatosuchus keine scharfen Zähne oder Klauen besitzt, versucht er das mit seiner dicken Haut auszugleichen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dilophosaurus", "Dilophosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This little critter cripples prey by spitting its uncharacteristic venom.", "Dieses kleine Tier lähmt seine Beute, indem es sein ungewöhnliches Gift spuckt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dilophosaurus, a terror of the Early Jurassic period. Losing its ridiculous frill does not hinder its venomous nature.", "Dilophosaurus, ein Schrecken des frühen Jura. Der Verlust seiner lächerlichen Halskrause beeinträchtigt seine giftige Natur nicht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dimetrodon", "Dimetrodon", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dimetrodon, a reptilian mammal with an impressive sail. Its sharp teeth are a far bigger concern, however.", "Dimetrodon, ein säugetierähnliches Reptil mit einem eindrucksvollen Segel. Seine scharfen Zähne sind allerdings eine viel größere Sorge.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dimorphodon", "Dimorphodon", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dimorphodon, a mostly unremarkable little critter. Do not startle it, those teeth will leave a mark during its hasty retreat.", "Dimorphodon, ein weitgehend unscheinbares kleines Tier. Erschrecke es nicht, seine Zähne hinterlassen bei seiner hastigen Flucht Spuren.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dinosaur Egg", "Dinosaurierei", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bigger Dinosaur Egg", "Größeres Dinosaurierei", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An egg left behind by some dinosaur. I wonder what will hatch from it?", "Ein Ei, das ein Dinosaurier zurückgelassen hat. Was wohl daraus schlüpft?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Diplodocus", "Diplodocus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If sheer size alone is not enough to deter predators, then perhaps a mighty tail whip will make them reconsider.", "Wenn seine schiere Größe Raubtiere nicht abschreckt, bringt ein kräftiger Schwanzhieb sie vielleicht zum Umdenken.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dryosaurus", "Dryosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dryosaurus, an adorable creature with a flighty attitude.", "Dryosaurus, eine liebenswerte Kreatur mit schreckhaftem Wesen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dunkleosteus", "Dunkleosteus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ravenous Dunkleosteus, an armored fish from distant past. Its true length has little bearing on its crushing jaws.", "Der gefräßige Dunkleosteus, ein Panzerfisch aus ferner Vergangenheit. Seine tatsächliche Länge ändert wenig an seinen zermalmenden Kiefern.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Edmontosaurus", "Edmontosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Edmontosaurus, a massive creature with very few natural predators. Do not expect to find it alone.", "Edmontosaurus, eine riesige Kreatur mit sehr wenigen natürlichen Feinden. Erwarte nicht, sie allein anzutreffen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elasmosaurus", "Elasmosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elasmosaurus, a prehistoric beast with an incredibly long neck. It can snatch prey far out of the reach of others.", "Elasmosaurus, eine prähistorische Bestie mit unglaublich langem Hals. Sie kann Beute weit außerhalb der Reichweite anderer schnappen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eobasileus", "Eobasileus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eobasileus, the largest of its kind. Do not stand in its path if you wish to see the sun rise again.", "Eobasileus, der größte seiner Art. Stell dich ihm nicht in den Weg, wenn du die Sonne noch einmal aufgehen sehen willst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Euoplocephalus", "Euoplocephalus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The thick hide of this Euoplocephalus and the equally hefty club at the end of its tail protect it from most predators", "Die dicke Haut dieses Euoplocephalus und die ebenso schwere Keule an seinem Schwanz schützen ihn vor den meisten Raubtieren.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gallimimus", "Gallimimus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gallimimus, a bird-like beast that is rather quick on its feet. It is about as friendly as it looks.", "Gallimimus, eine vogelähnliche Bestie, die recht schnell auf den Beinen ist. Sie ist ungefähr so freundlich, wie sie aussieht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gastornis", "Gastornis", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vigilant Gastornis. It watches over its comrades, growing furious if it loses any.", "Der wachsame Gastornis. Er wacht über seine Gefährten und wird wütend, wenn er einen verliert.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant Ground Sloth", "Riesenfaultier", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Giant Ground Sloth, a massive beast far surpassing its modern relatives. It is much less friendly than you would think.", "Das Riesenfaultier, eine gewaltige Bestie, die ihre heutigen Verwandten weit übertrifft. Es ist viel weniger freundlich, als man denkt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gigantoraptor", "Gigantoraptor", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gigantoraptor, a disturbingly large beast. Any attempts to resist will only further provoke it.", "Gigantoraptor, eine beunruhigend große Bestie. Jeder Widerstand wird sie nur noch mehr reizen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gojirasaurus", "Gojirasaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once the biggest predator to roam the land, Gojirasaurus' reign did not last. It's hard to match the titans that followed it.", "Einst das größte Landraubtier, währte die Herrschaft des Gojirasaurus nicht lange. Mit den nachfolgenden Titanen kann er kaum mithalten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guanlong", "Guanlong", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guanlong, a vicious predator emboldened by the thrill of combat. Many more terrible beasts have spawned from its lineage.", "Guanlong, ein grausames Raubtier, das der Nervenkitzel des Kampfes ermutigt. Aus seiner Linie gingen viele weitere schreckliche Bestien hervor.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hadrosaurus", "Hadrosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vengeful Hadrosaurus. It makes quick work of those who harm members of its herd.", "Der rachsüchtige Hadrosaurus. Er macht kurzen Prozess mit denen, die Mitglieder seiner Herde verletzen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haolong", "Haolong", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haolong, a bizarre beast covered in many sharp quills. Very few predators dare to clamp their jaws around its prickly hide.", "Haolong, eine bizarre Bestie voller spitzer Stacheln. Nur wenige Raubtiere wagen es, in seine stachelige Haut zu beißen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Herrerasaurus", "Herrerasaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Herrerasaurus hails from the age before dinosaurs took over the world. Being more primitive does not make it any less successful.", "Dieser Herrerasaurus stammt aus der Zeit, bevor Dinosaurier die Welt beherrschten. Dass er primitiver ist, macht ihn nicht weniger erfolgreich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hesperornis", "Hesperornis", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hesperornis, a swimming bird with a taste for fish. It has yet to lose its teeth.", "Hesperornis, ein schwimmender Vogel mit Vorliebe für Fisch. Er hat seine Zähne noch nicht verloren.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Homalocephale", "Homalocephale", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What an adorable Homalocephale. Alas, a grim fate awaits this poor creature. Will your heart sink when you hear its cries?", "Was für ein liebenswerter Homalocephale. Ach, dieser armen Kreatur steht ein düsteres Schicksal bevor. Wird dir beim Klang ihrer Schreie das Herz schwer?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichthyornis", "Ichthyornis", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichthyornis, a prehistoric bird with sharp teeth. It is no less annoying than its modern counterparts.", "Ichthyornis, ein prähistorischer Vogel mit scharfen Zähnen. Er ist genauso lästig wie seine heutigen Verwandten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichthyosaurus", "Ichthyosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The swift Ichthyosaurus. It can attack submerged foes in the blink of an eye.", "Der flinke Ichthyosaurus. Er kann abgetauchte Gegner im Handumdrehen angreifen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Iguanodon", "Iguanodon", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mind your manners before this Iguanodon if you do not wish to feel its clawed thumb pierce you.", "Benimm dich vor diesem Iguanodon, wenn du nicht von seiner Daumenkralle durchbohrt werden willst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inostrancevia", "Inostrancevia", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inostrancevia, a surprisingly agile apex predator of its age. The grievous injuries left by the beast's fangs are far less suprising.", "Inostrancevia, ein überraschend wendiger Spitzenprädator seiner Zeit. Die schweren Wunden seiner Fangzähne überraschen weit weniger.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Irish Elk", "Irischer Riesenhirsch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The majestic Irish Elk, the biggest of its kind. Its massive horns grant it extended reach.", "Der majestätische irische Riesenhirsch, der größte seiner Art. Sein gewaltiges Geweih vergrößert seine Reichweite.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Irritator", "Irritator", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The patient Irritator. Though it primarily feeds on fish, its claws are perfectly suited for tearing into other beasts.", "Der geduldige Irritator. Obwohl er sich hauptsächlich von Fisch ernährt, eignen sich seine Klauen bestens, um andere Bestien zu zerreißen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Isisaurus", "Isisaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Isisaurus leads a herd of its own. Though they do not belong to its kind, those beasts trust this experienced titan.", "Dieser Isisaurus führt eine eigene Herde an. Obwohl die Bestien nicht seiner Art angehören, vertrauen sie diesem erfahrenen Titanen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jeholopterus", "Jeholopterus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jeholopterus, nothing more than a bug-eating critter. Don't expect much else out of it.", "Jeholopterus, nichts weiter als ein kleines insektenfressendes Tier. Erwarte nicht mehr von ihm.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Katifelis", "Katifelis", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Katifelis, an unremarkable feline. It does not respond well to approaching strangers.", "Katifelis, eine unscheinbare Katze. Auf sich nähernde Fremde reagiert sie nicht gut.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kentrosaurus", "Kentrosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kentrosaurus, a herbivore with a threatening appearance. Said appearance is far from deceiving, however.", "Kentrosaurus, ein Pflanzenfresser mit bedrohlichem Aussehen. Dieser Eindruck täuscht keineswegs.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Koolasuchus", "Koolasuchus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Koolasuchus, a dreadfull creature lurking in the water. It does not pass up any opportunity to feast.", "Koolasuchus, eine furchtbare Kreatur, die im Wasser lauert. Sie lässt keine Gelegenheit zum Schmausen aus.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lambeosaurus", "Lambeosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The solitary Lambeosaurus. It strikes its foes multiple times when disturbed.", "Der einzelgängerische Lambeosaurus. Wird er gestört, schlägt er seine Feinde mehrfach.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Liopleurodon", "Liopleurodon", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While much smaller than some may believe, Liopleurodon is still a vicious predator, always ready to tear its prey apart.", "Obwohl Liopleurodon viel kleiner ist, als manche glauben, bleibt er ein grausames Raubtier, stets bereit, seine Beute zu zerreißen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Majungasaurus", "Majungasaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The voracious Majungasaurus. It will not hesitate to devour its own comrades to sate its hunger.", "Der gefräßige Majungasaurus. Er zögert nicht, seine eigenen Gefährten zu verschlingen, um seinen Hunger zu stillen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Masiakasaurus", "Masiakasaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Masiakasaurus, a bizarre dinosaur of unimpressive size. It does not stay in battle for long.", "Masiakasaurus, ein bizarrer Dinosaurier von wenig beeindruckender Größe. Er bleibt nicht lange im Kampf.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mawsonia", "Mawsonia", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mawsonia, an enormous fish drifting in search of prey. Pray you do not bump into one while swimming.", "Mawsonia, ein riesiger Fisch, der auf der Suche nach Beute umhertreibt. Hoffe, dass du beim Schwimmen keinem begegnest.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Megalania", "Megalania", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The monstrous Megalania. A single bite from this oversized reptile is enough to cripple most beasts.", "Die monströse Megalania. Ein einziger Biss dieses riesigen Reptils genügt, um die meisten Bestien außer Gefecht zu setzen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Metriacanthosaurus", "Metriacanthosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Metriacanthosaurus mercilessly tears into its prey, unwilling to let any meal get away from its jaws.", "Dieser Metriacanthosaurus zerreißt seine Beute gnadenlos und lässt sich keine Mahlzeit entgehen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Microceratus", "Microceratus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unlike its bigger relatives, Microceratus stands on two legs and lacks any meaningful protection against predators. The best it can do is draw attention of something bigger.", "Anders als seine größeren Verwandten steht Microceratus auf zwei Beinen und hat keinen nennenswerten Schutz vor Raubtieren. Bestenfalls kann er die Aufmerksamkeit von etwas Größerem erregen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Minmi", "Minmi", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Minmi may seem adorable, but it is far from defenseless. In fact, defense might be all it has.", "Dieser Minmi mag niedlich aussehen, doch er ist keineswegs wehrlos. Tatsächlich ist Verteidigung vielleicht alles, was er hat.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Muttaburrasaurus", "Muttaburrasaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The persistent Muttaburrasaurus. It does not fall in battle while its herd is still in danger.", "Der beharrliche Muttaburrasaurus. Er fällt im Kampf nicht, solange seine Herde in Gefahr ist.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nanotyrannus", "Nanotyrannus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Living in the shadow of the King does not make this beast any less formidable.", "Im Schatten des Königs zu leben macht diese Bestie nicht weniger gefährlich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nigersaurus", "Nigersaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nigersaurus, a beast with countless teeth. It loses many while feeding, but they regrow just as quickly.", "Nigersaurus, eine Bestie mit zahllosen Zähnen. Beim Fressen verliert sie viele davon, doch sie wachsen ebenso schnell nach.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothosaurus", "Nothosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though this Nothosaurus is clumsy on land, it is an adept swimmer with a mouth full of sharp teeth.", "Dieser Nothosaurus ist an Land ungeschickt, aber ein geschickter Schwimmer mit einem Maul voller scharfer Zähne.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Olorotitan", "Olorotitan", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Olorotitan is more concerned about helping its allies than itself. Such altruism.", "Dieser Olorotitan sorgt sich mehr um seine Verbündeten als um sich selbst. Was für ein Altruismus.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Othnielia", "Othnielia", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Othnielia, hardly more than a snack for more ferocious beasts.", "Othnielia, für wildere Bestien kaum mehr als ein kleiner Happen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ouranosaurus", "Ouranosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though it is not an outstanding fighter, this Ouranosaurus encourages its comrades to fight with greater strength.", "Dieser Ouranosaurus ist kein herausragender Kämpfer, ermutigt seine Gefährten aber, mit größerer Kraft zu kämpfen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oviraptor", "Oviraptor", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once thought to be a mere egg thief, this feathered fiend takes great care of its young.", "Einst für einen bloßen Eierdieb gehalten, kümmert sich dieser gefiederte Teufel liebevoll um seinen Nachwuchs.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pachycephalosaurus", "Pachycephalosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The stubborn Pachycephalosaurus. It will attack anything that intrudes upon its territory regardless of size.", "Der sture Pachycephalosaurus. Er greift alles an, was in sein Revier eindringt, unabhängig von der Größe.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pachyrhinosaurus", "Pachyrhinosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The nomadic Pachyrhinosaurus. It lost many brothers during its travels. It cannot bear to lose more.", "Der nomadische Pachyrhinosaurus. Er hat auf seinen Reisen viele Brüder verloren und kann nicht noch mehr Verluste ertragen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasaurolophus", "Parasaurolophus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The peaceful Parasaurolophus. Its peculiar crest allows it to call upon its allies when in trouble.", "Der friedliche Parasaurolophus. Mit seinem eigentümlichen Kamm kann er bei Gefahr seine Verbündeten rufen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasaurolophus Hatchling", "Parasaurolophus-Jungtier", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A meek Parasaurolophus hatchling. It has yet to develop a prominent crest to match its parents.", "Ein sanftmütiges Parasaurolophus-Jungtier. Sein auffälliger Kamm ist noch nicht so ausgeprägt wie der seiner Eltern.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Patagopelta", "Patagopelta", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While far from the biggest armored dinosaur, Patagopelta is still perfectly capable of enduring blows.", "Patagopelta ist zwar nicht der größte gepanzerte Dinosaurier, kann aber dennoch problemlos Schläge einstecken.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plateosaurus", "Plateosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plateosaurus, one of the first titans to roam the land. Though its descendants have far surpassed its size, it is by no means small.", "Plateosaurus, einer der ersten Titanen, die das Land durchstreiften. Obwohl seine Nachfahren viel größer wurden, ist er keineswegs klein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Platybelodon", "Platybelodon", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Platybelodon, a beast so bizarre that few would believe it existed. It can use its unsightly skull to uproot obstacles in your path.", "Platybelodon, eine so bizarre Bestie, dass kaum jemand an ihre Existenz glauben würde. Mit ihrem unschönen Schädel kann sie Hindernisse aus deinem Weg reißen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raptor Plushie", "Raptor-Plüschtier", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A cute little toy, nothing more.", "Ein niedliches kleines Spielzeug, nichts weiter.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stuffing", "Füllung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All that's left of a toy.", "Alles, was von einem Spielzeug übrig ist.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Postosuchus", "Postosuchus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Postosuchus, a bipedal crocodilian. Its bite is no less devastating than that of its modern relatives.", "Postosuchus, ein zweibeiniges Krokodiltier. Sein Biss ist nicht weniger verheerend als der seiner heutigen Verwandten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Proceratosaurus", "Proceratosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The deceptive Proceratosaurus. It makes up for its lacking offense with whatever wit you may attribute to a beast.", "Der täuschende Proceratosaurus. Seine schwache Angriffskraft gleicht er mit so viel List aus, wie man einer Bestie zutrauen kann.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Procompsognathus", "Procompsognathus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Procompsognathus, a tiny terror with a surprisingly potent venom. It's particularly fond of feasting on greedy old men.", "Procompsognathus, ein winziger Schrecken mit erstaunlich starkem Gift. Besonders gern verspeist er gierige alte Männer.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prongdeer", "Gabelhornhirsch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prongdeer, a relatively small horned creature with an ill-fitting pair of fangs. They are not just for show, however.", "Der Gabelhornhirsch, eine relativ kleine gehörnte Kreatur mit einem unpassend wirkenden Paar Fangzähne. Diese sind jedoch nicht nur zur Schau.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protoceratops", "Protoceratops", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Protoceratops may not seem like a threat, but the ferocity it displays when desperate is a sight to behold.", "Dieser Protoceratops sieht vielleicht nicht bedrohlich aus, doch seine Wildheit in verzweifelter Lage ist beeindruckend.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protosphyraena", "Protosphyraena", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protosphyraena, a lightning-fast predator that cleaves its prey in half with its extended snout.", "Protosphyraena, ein blitzschnelles Raubtier, das seine Beute mit der langen Schnauze in zwei Hälften teilt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Psittacosaurus", "Psittacosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The timid Psittacosaurus. Many beasts form bonds with this adorable creature. Few wish to see it hurt.", "Der scheue Psittacosaurus. Viele Bestien schließen Freundschaft mit dieser liebenswerten Kreatur. Kaum jemand möchte sie verletzt sehen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pteranodon", "Pteranodon", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pteranodon, an iconic flying reptile. It may not have teeth to maul you with, but that beak spells trouble.", "Pteranodon, ein legendäres fliegendes Reptil. Es hat vielleicht keine Zähne, um dich zu zerfleischen, doch sein Schnabel macht Ärger.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pterodaustro", "Pterodaustro", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...No, I did not fabricate this creature. Even the most bizarre forms can serve their own purposes.", "... Nein, diese Kreatur habe ich nicht erfunden. Selbst die bizarrsten Formen können ihren eigenen Zweck erfüllen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Qianzhousaurus", "Qianzhousaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ambitious Qianzhousaurus. Though yet to reach the true King's might, it has potential for growth.", "Der ehrgeizige Qianzhousaurus. Er erreicht zwar noch nicht die Macht des wahren Königs, hat aber Wachstumspotenzial.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quercylurus", "Quercylurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quercylurus, a massive beast resembling saber-toothed cats. It gnaws on the many bones of its numerous victims.", "Quercylurus, eine gewaltige Bestie, die Säbelzahnkatzen ähnelt. Sie nagt an den vielen Knochen ihrer zahlreichen Opfer.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rhamphorhynchus", "Rhamphorhynchus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rhamphorhynchus, a tiny flying reptile with a mouth full of sharp teeth. Though it prefers fish, it can and will bite your fingers.", "Rhamphorhynchus, ein winziges fliegendes Reptil mit einem Maul voller scharfer Zähne. Es bevorzugt Fisch, kann und wird dir aber in die Finger beißen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacabambaspis", "Sacabambaspis", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The jawless Sacabambaspis, an adorable little fish with an armored hide.", "Der kieferlose Sacabambaspis, ein liebenswerter kleiner Fisch mit gepanzerter Haut.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sansanosmilus", "Sansanosmilus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sansanosmilus, a cat-like predator with a particularly wounding bite. Smaller size does not make it any less dangerous.", "Sansanosmilus, ein katzenähnliches Raubtier mit einem besonders verletzenden Biss. Seine kleinere Größe macht es nicht weniger gefährlich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sarcoprion", "Sarcoprion", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sarcoprion, a monstrous shark with a bizarre set of jaws. It uses them to cut its prey in half.", "Sarcoprion, ein monströser Hai mit bizarren Kiefern. Er benutzt sie, um seine Beute zu halbieren.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Segisaurus", "Segisaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Segisaurus, hardly more than a pest. It comes in great numbers, however.", "Segisaurus, kaum mehr als eine Plage. Allerdings treten sie in großer Zahl auf.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shringasaurus", "Shringasaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shringasaurus, a horned reptile from the distant past. It shoves its attackers back in retaliation.", "Shringasaurus, ein gehörntes Reptil aus ferner Vergangenheit. Zur Vergeltung stößt es seine Angreifer zurück.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shunosaurus", "Shunosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shunosaurus, a long-necked creature with a club at the end of its tail. It can land debilitating strikes upon its enemies.", "Shunosaurus, eine langhalsige Kreatur mit einer Keule am Schwanzende. Er kann seinen Feinden schwächende Schläge versetzen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Simosuchus", "Simosuchus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Simosuchus, an adorable and completely harmless crocodilian. It protects itself with its thick scales.", "Simosuchus, ein liebenswertes und völlig harmloses Krokodiltier. Es schützt sich mit seinen dicken Schuppen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sinosauropteryx", "Sinosauropteryx", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sneaky Sinosauropteryx, a feathered reptilian pest resembling a racoon in more than appearance.", "Der heimliche Sinosauropteryx, eine gefiederte reptilienartige Plage, die nicht nur äußerlich einem Waschbären ähnelt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stegosaurus", "Stegosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This territorial Stegosaurus is not willing to share room with anyone, friend or foe.", "Dieser revierverteidigende Stegosaurus will seinen Platz mit niemandem teilen, weder Freund noch Feind.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stokesosaurus", "Stokesosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stokesosaurus, an unassuming predator. Perhaps it is more intelligent than it appears at a glance.", "Stokesosaurus, ein unscheinbares Raubtier. Vielleicht ist er intelligenter, als er auf den ersten Blick wirkt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stygimoloch", "Stygimoloch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stygimoloch, a stubborn beast with an unpleasant attitude. It won't go down without a fight.", "Stygimoloch, eine sture Bestie mit unangenehmem Wesen. Sie gibt nicht kampflos auf.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Styracosaurus", "Styracosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The tenacious Styracosaurus. It's not content with simply fending off its attackers.", "Der zähe Styracosaurus. Er gibt sich nicht damit zufrieden, seine Angreifer nur abzuwehren.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Suchomimus", "Suchomimus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Suchomimus, a beats with a narrow snout that primarily hunts fish. It is no stranger to hunting prey on land, however.", "Suchomimus, eine Bestie mit schmaler Schnauze, die vor allem Fisch jagt. Die Jagd an Land ist ihr jedoch nicht fremd.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Supersaurus", "Supersaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The altruistic Supersaurus. It is determined to use what's left of its essence to support its comrades.", "Der selbstlose Supersaurus. Er ist entschlossen, den Rest seiner Essenz zu nutzen, um seine Gefährten zu unterstützen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tapejara", "Tapejara", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The illustrious Tapejara. It calls upon its kin to aid it in battle.", "Der prächtige Tapejara. Er ruft seine Artgenossen zu Hilfe im Kampf.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tiktaalik", "Tiktaalik", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tiktaalik, the great progenitor. You may thank it for your ability to live on land.", "Tiktaalik, der große Vorfahr. Ihm verdankst du, dass du an Land leben kannst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Titanis", "Titanis", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Titanis, an oversized carnivorous bird with a foul temper. Don't expect to outrun this beast.", "Titanis, ein riesiger fleischfressender Vogel mit üblem Temperament. Erwarte nicht, dieser Bestie davonzulaufen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Torosaurus", "Torosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This elderly beast can hardly muster the will to retaliate. I advise against testing its patience, however.", "Diese alte Bestie kann kaum den Willen zur Gegenwehr aufbringen. Ich rate trotzdem davon ab, ihre Geduld zu prüfen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Triceratops", "Triceratops", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Many have tried to best this lone Triceratops. Few could walk away.", "Viele haben versucht, diesen einsamen Triceratops zu besiegen. Nur wenige konnten davonlaufen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Triceratops Hatchling", "Triceratops-Jungtier", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A playful Triceratops hatchling. Cherish these moments before it turns into a fierce behemoth.", "Ein verspieltes Triceratops-Jungtier. Schätze diese Augenblicke, bevor es zu einem wilden Koloss heranwächst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Troodon", "Troodon", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "New life shall spring from those unfortunate to feel its venomous bite.", "Neues Leben wird aus jenen sprießen, die das Unglück haben, seinen giftigen Biss zu spüren.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tyrannosaurus Hatchling", "Tyrannosaurus-Jungtier", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The innocent Tyrannosaurus hatchling. When the time comes, the throne will belong to this little creature.", "Das unschuldige Tyrannosaurus-Jungtier. Wenn die Zeit gekommen ist, wird der Thron dieser kleinen Kreatur gehören.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Utahraptor", "Utahraptor", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Utahraptor, an unpleasantly large beast for its kind. It can disembowel you in seconds.", "Utahraptor, eine unangenehm große Bestie für ihre Art. Sie kann dich in Sekunden ausweiden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Utatsusaurus", "Utatsusaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The nimble Utatsusaurus. It has little trouble passing over obstacles.", "Der flinke Utatsusaurus. Hindernisse überwindet er mühelos.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Velociraptor", "Velociraptor", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The swift Velociraptor, a tiny menace of the desert. Were you expecting something bigger?", "Der flinke Velociraptor, eine winzige Bedrohung der Wüste. Hast du etwas Größeres erwartet?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woolly Rhinoceros", "Wollnashorn", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woolly Rhinoceros, a particularly hairy beast with eyesight that does not help its temper. Its long horn can pierce multiple foes.", "Das Wollnashorn, eine besonders haarige Bestie, deren Sehschwäche ihrem Temperament nicht hilft. Sein langes Horn kann mehrere Feinde durchbohren.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Xiphactinus", "Xiphactinus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Xiphactinus, a monstrous fish with endless appetite. A single bite is not enough to sate it.", "Xiphactinus, ein monströser Fisch mit endlosem Appetit. Ein einziger Bissen genügt nicht, um ihn zu sättigen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yutyrannus", "Yutyrannus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The fiendish Yutyrannus. It tears its prey apart while it's still alive.", "Der teuflische Yutyrannus. Er zerreißt seine Beute, während sie noch lebt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zhenyuanopterus", "Zhenyuanopterus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zhenyuanopterus, a flying pest with a mouth full of needle-like teeth. It accompanies larger beasts into battle.", "Zhenyuanopterus, eine fliegende Plage mit einem Maul voller nadelartiger Zähne. Er begleitet größere Bestien in den Kampf.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sauria Cards", "Sauria-Karten", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A collection of around [count] cards consisting of a random assortment of prehistoric animals, mostly reptiles.", "Eine Sammlung von etwa [count] Karten mit einer zufälligen Auswahl prähistorischer Tiere, hauptsächlich Reptilien.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A set of [summary] exclusively featuring a random assortment of prehistoric animals, mostly reptiles.", "Ein Set von [summary] mit ausschließlich zufällig ausgewählten prähistorischen Tieren, hauptsächlich Reptilien.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fisher", "Fischer", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is placed, a Ceratodus is created in your hand. [define:Sauria_Ceratodus]", "Wird eine Karte mit diesem Siegel platziert, wird ein Ceratodus auf deiner Hand erzeugt. [define:Sauria_Ceratodus]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A successful hunt for fish.", "Ein erfolgreicher Fischfang.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fisher Strike", "Fischerschlag", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil kills another creature, a Ceratodus is created in your hand. [define:Sauria_Ceratodus]", "Tötet eine Karte mit diesem Siegel eine andere Kreatur, wird ein Ceratodus auf deiner Hand erzeugt. [define:Sauria_Ceratodus]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It appears the beast caught something.", "Die Bestie scheint etwas gefangen zu haben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Promise of such a feast is too enticing for them to ignore.", "Das Versprechen eines solchen Festmahls ist zu verlockend, um es zu ignorieren.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mysterious power infuses your beast.", "Eine geheimnisvolle Kraft erfüllt deine Bestie.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Something is off...", "Irgendetwas stimmt nicht ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looks like it left something precious.", "Es scheint etwas Wertvolles zurückgelassen zu haben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Marine Shuffle", "Meeresmischung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil kills another creature, a free Ceratodus is shuffled into your side deck. [define:Sauria_Ceratodus]", "Tötet eine Karte mit diesem Siegel eine andere Kreatur, wird ein kostenloser Ceratodus in deinen Nebenstapel gemischt. [define:Sauria_Ceratodus]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A surprise awaits you.", "Eine Überraschung wartet auf dich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looks like it lost some teeth while grazing. They are yours to keep.", "Es scheint beim Grasen einige Zähne verloren zu haben. Du darfst sie behalten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not alone anymore.", "Es ist nicht mehr allein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nourishment", "Nahrung", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A small sacrifice for small growth.", "Ein kleines Opfer für ein kleines Wachstum.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What an abhorent creature, crafted by the hands of madmen...", "Was für eine abscheuliche Kreatur, von Wahnsinnigen erschaffen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parting Fish", "Abschiedsfisch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil dies or is sacrificed, a Ceratodus is created in your hand. [define:Sauria_Ceratodus]", "Stirbt eine Karte mit diesem Siegel oder wird sie geopfert, wird ein Ceratodus auf deiner Hand erzeugt. [define:Sauria_Ceratodus]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So many questions to ask.", "So viele Fragen zu stellen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Another beast rises from its ashes.", "Eine weitere Bestie erhebt sich aus ihrer Asche.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A fatal mistake.", "Ein fataler Fehler.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Can you feel the ground beneath your feet rumble?", "Spürst du den Boden unter deinen Füßen beben?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everything will be dragged to the depths.", "Alles wird in die Tiefe gezogen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not satisfied with its stolen goods just yet.", "Mit seinem Diebesgut ist es noch nicht zufrieden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Being in the presence of that animal is making it feel like a monster.", "Die Nähe dieses Tieres lässt es sich wie ein Monster fühlen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Taking up the arts? Interesting.", "Du widmest dich der Kunst? Interessant.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such is the might of a titan.", "Das ist die Macht eines Titanen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The king has no need for restraint. More sacrifices must be made.", "Der König muss sich nicht zurückhalten. Weitere Opfer sind nötig.", Language.German);


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ancient Iguanodon", "Uralter Iguanodon", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A remnant of an old belief and proof of science's perpetual march, this beast has much to learn.", "Als Überrest eines alten Glaubens und Beweis für den stetigen Fortschritt der Wissenschaft hat diese Bestie noch viel zu lernen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ankylodocus", "Ankylodocus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Far less abominable than most of its artificial kin, Ankylodocus can almost be called a gentle giant.", "Weit weniger abscheulich als die meisten seiner künstlichen Verwandten kann Ankylodocus fast als sanfter Riese gelten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anzu", "Anzu", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anzu, the vicious beast that brings thunder. Do not invite its wrath upon yourself.", "Anzu, die grausame Bestie, die den Donner bringt. Zieh ihren Zorn nicht auf dich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Archelon", "Archelon", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The wise Archelon. It fortifies its allies upon entering the battle.", "Der weise Archelon. Er stärkt seine Verbündeten, wenn er den Kampf betritt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Basilosaurus", "Basilosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Basilosaurus, the King Lizard. While not even remotely related to reptiles, it certainly earns the title of royalty.", "Basilosaurus, der König der Echsen. Obwohl er mit Reptilien nicht im Entferntesten verwandt ist, verdient er seinen königlichen Titel.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beautiful Feather", "Schöne Feder", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dazzling.", "Blendend.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brontosaurus", "Brontosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brontosaurus, the so-called thunderbringer. Its name may not be entirely unearned.", "Brontosaurus, der sogenannte Donnerbringer. Seinen Namen trägt er vielleicht nicht ganz zu Unrecht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carchadontosaurus", "Carcharodontosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The bloodthirsty Carcharodontosaurus. The smell of blood drives it into a frenzy.", "Der blutrünstige Carcharodontosaurus. Der Geruch von Blut versetzt ihn in Raserei.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cave Bear", "Höhlenbär", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The reclusive Cave Bear. Though it may not be a vicious predator, it gives shelter to a fair share of beasts craving flesh.", "Der zurückgezogen lebende Höhlenbär. Er ist vielleicht kein grausames Raubtier, bietet aber vielen fleischhungrigen Bestien Zuflucht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Compstegnathus", "Compstegnathus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Compstegnathus, a deformed beast bred for nefarious deeds. I do not enjoy looking at it.", "Compstegnathus, eine missgestaltete Bestie, die für ruchlose Taten gezüchtet wurde. Ich sehe sie nicht gern an.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cryolophosaurus", "Cryolophosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This crested beast brings the unforgiving cold of winter with it. When it enters battle, you may find some poor creatures trapped in ice as a result.", "Diese Bestie mit Kamm bringt die unerbittliche Kälte des Winters mit sich. Wenn sie den Kampf betritt, könnten arme Kreaturen im Eis gefangen sein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What an unsightly beast, truly an eyesore. Who could have spawned it?", "Was für eine unansehnliche Bestie, wahrlich ein Schandfleck. Wer mag sie erschaffen haben?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deinosuchus Hatchling", "Deinosuchus-Jungtier", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A helpless Deinosuchus hatchling. It has yet to grow into a fearsome apex predator.", "Ein hilfloses Deinosuchus-Jungtier. Es muss erst noch zu einem furchterregenden Spitzenprädator heranwachsen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fish Meat", "Fischfleisch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Juicy Fish Meat", "Saftiges Fischfleisch", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giganotosaurus", "Giganotosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The horrifying Giganotosaurus. Though it normally hunts alone, big enough prey may attract more of its kind.", "Der furchterregende Giganotosaurus. Obwohl er normalerweise allein jagt, kann ausreichend große Beute weitere Artgenossen anlocken.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Godzilla", "Godzilla", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The legendary King of the Monsters. It will take more than claws and fangs to take it down.", "Der legendäre König der Monster. Um ihn zu besiegen, braucht es mehr als Klauen und Zähne.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Godzillasaurus", "Godzillasaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once a relatively peaceful beast, Godzillasaurus would go down in history as the King of the Monsters.", "Einst eine recht friedliche Bestie, wird Godzillasaurus als König der Monster in die Geschichte eingehen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gwangi", "Gwangi", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The voracious Gwangi, a relic of the past. Do not attribute malice to this poor creature, it merely wishes to live.", "Der gefräßige Gwangi, ein Überbleibsel der Vergangenheit. Unterstelle dieser armen Kreatur keine Bosheit, sie will nur leben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Homotherium", "Homotherium", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Homotherium, a vicious pack hunter. It will endlessly pursue its prey to nourish its kin.", "Homotherium, ein grausamer Rudeljäger. Er verfolgt seine Beute endlos, um seine Artgenossen zu ernähren.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hypsilophodon", "Hypsilophodon", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Hypsilophodon should be little more than prey for most beast... However...", "Dieser Hypsilophodon sollte für die meisten Bestien kaum mehr als Beute sein ... Jedoch ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichthyotitan", "Ichthyotitan", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichthyotitan, an awe-inspiring aquatic titan. Its sheer size alone dictates the flow of tides.", "Ichthyotitan, ein ehrfurchtgebietender Wassertitan. Allein seine Größe bestimmt den Lauf der Gezeiten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Indominus", "Indominus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such is the power of science...", "So groß ist die Macht der Wissenschaft ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leaellynasaura", "Leaellynasaura", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mysterious Leaellynasaura. Other beasts seem to undergo drastic changes in its presence.", "Der geheimnisvolle Leaellynasaura. Andere Bestien scheinen sich in seiner Gegenwart drastisch zu verändern.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leedsichthys", "Leedsichthys", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The gigantic Leedsichthys, one of the biggest fish to ever inhabit the oceans. However, it is hardly one of the most dangerous.", "Der riesige Leedsichthys, einer der größten Fische, die je die Ozeane bewohnten. Zu den gefährlichsten gehört er jedoch kaum.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maiasaura", "Maiasaura", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maiasaura, the 'Good Mother Lizard'. It will not let harm befall the little ones as long as it breathes.", "Maiasaura, die „gute Echsenmutter“. Solange sie atmet, lässt sie den Kleinen nichts zustoßen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Megalodon", "Megalodon", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The titanic Megalodon, an apex predator plagued by insatiable hunger. Make sure it always has prey to feast on.", "Der titanische Megalodon, ein Spitzenprädator, den unstillbarer Hunger plagt. Sorge dafür, dass er immer Beute zum Fressen hat.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Megalosaurus", "Megalosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Megalosaurus, one of the first to be discovered. Though its own fame did not last, it paves the path for others to attain it.", "Megalosaurus, einer der ersten Entdeckten. Obwohl sein eigener Ruhm nicht anhielt, ebnet er anderen den Weg dorthin.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Microraptor", "Microraptor", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This particularly petty Microraptor resembles ravens in more than its appearance. Do not get on its bad side.", "Dieser besonders kleinliche Microraptor ähnelt Raben nicht nur im Aussehen. Verscherze es dir nicht mit ihm.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mosasaurus", "Mosasaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This aquatic behemoth is no less vicious than any land-dwelling titan of its time.", "Dieser Wasserkoloss ist nicht weniger grausam als jeder landbewohnende Titan seiner Zeit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bigger Mysterious Egg", "Größeres geheimnisvolles Ei", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Something about this egg doesn't seem right...", "Irgendetwas an diesem Ei scheint nicht zu stimmen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Noasaurus", "Noasaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Valley of the Dinosaurs is in danger... Alas, few heed its words.", "Das Tal der Dinosaurier ist in Gefahr ... Doch leider hören nur wenige auf seine Worte.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ornithomimus", "Ornithomimus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vain Ornithomimus, a feast for the eyes. When threatened, it flees and leaves behind colorful feathers for predators to marvel at.", "Der eitle Ornithomimus, eine Augenweide. Bei Gefahr flieht er und lässt bunte Federn zurück, die seine Verfolger bestaunen können.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Paraceratherium", "Paraceratherium", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Paraceratherium, one of the largest mammals to set foot on land. Kindred beasts walk by its side.", "Paraceratherium, eines der größten Säugetiere, die je Land betraten. Verwandte Bestien gehen an seiner Seite.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Philosoraptor", "Philosoraptor", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The pensive Philosoraptor, always asking the questions none dare to voice aloud.", "Der nachdenkliche Philosoraptor stellt stets die Fragen, die niemand laut auszusprechen wagt.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pyroraptor", "Pyroraptor", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Like a bird of legend, Pyroraptor rose from the ashes to greet the world. Perhaps it could use a bit more fire?", "Wie ein Vogel aus der Sage erhob sich Pyroraptor aus der Asche, um die Welt zu begrüßen. Vielleicht könnte er etwas mehr Feuer gebrauchen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quetzalcoatlus", "Quetzalcoatlus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The terrible Quetzalcoatlus, an alarmingly massive ruler of skies with an appetite to match.", "Der schreckliche Quetzalcoatlus, ein beunruhigend gewaltiger Herrscher der Lüfte mit entsprechend großem Appetit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Real Parasaurolophus", "Echter Parasaurolophus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Definitely Real Parasaurolophus", "Absolut echter Parasaurolophus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasaurolophus, a dragon with a bizarre appearance. It produces flames by igniting the fuel stored in its crest via flint-like teeth.", "Parasaurolophus, ein Drache mit bizarrer Erscheinung. Mit feuersteinartigen Zähnen entzündet er den in seinem Kamm gelagerten Treibstoff und erzeugt Flammen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rhedosaurus", "Rhedosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Rhedosaurus from a distant world. The plague it carries in its blood is much too alien for most creatures to bear.", "Ein Rhedosaurus aus einer fernen Welt. Die Seuche in seinem Blut ist für die meisten Kreaturen zu fremdartig, um sie zu ertragen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shantungosaurus", "Shantungosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shantungosaurus, absurdly massive for something that can stand on its rear legs. Their herds are as awe-inspiring as they are terrifying.", "Shantungosaurus, absurd massig für ein Wesen, das auf den Hinterbeinen stehen kann. Seine Herden sind ebenso beeindruckend wie furchteinflößend.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spicomellus", "Spicomellus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spicomellus, a beast covered in numerous spikes. It does not look pleasant to touch and it is even less pleasant to strike.", "Spicomellus, eine Bestie voller Stacheln. Sie anzufassen sieht unangenehm aus, sie zu schlagen ist noch schlimmer.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spinoraptor", "Spinoraptor", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An abomination born of science, Spinoraptor is an adept fisher and hunter.", "Spinoraptor, eine der Wissenschaft entsprungene Abscheulichkeit, ist ein geschickter Fischer und Jäger.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spinosaurus", "Spinosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A bizarre reptile of monstrous size, few marine animals can evade its narrow jaws.", "Ein bizarres Reptil von monströser Größe. Nur wenige Meerestiere entkommen seinen schmalen Kiefern.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The monstrous Spinosaurus, the only being worthy of challenging the King.", "Der monströse Spinosaurus, das einzige Wesen, das würdig ist, den König herauszufordern.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thanatosdrakon", "Thanatosdrakon", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thanatosdrakon, a beast that has breached the boundary between life and death... Hm... Perhaps this creature has been blessed by...", "Thanatosdrakon, eine Bestie, die die Grenze zwischen Leben und Tod überschritten hat ... Hm ... Vielleicht wurde diese Kreatur gesegnet von ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big Al", "Großer Al", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big Al, a female Allosaurus that has suffered greatly during its short life. Perhaps you can help this poor creature?", "Großer Al, ein weiblicher Allosaurus, der in seinem kurzen Leben viel gelitten hat. Vielleicht kannst du dieser armen Kreatur helfen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Wars", "Knochenkriege", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They fought to protect their pride, sparing no expense. In the end, what were they left with?", "Sie kämpften um ihren Stolz, ohne Kosten zu scheuen. Was blieb ihnen am Ende?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Therizinosaurus", "Therizinosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Therizinosaurus can hardly see these days. However, you do not want to approach a half-blind giant with claws of such length.", "Dieser Therizinosaurus sieht heutzutage kaum noch. Doch du solltest dich keinem halbblinden Riesen mit so langen Klauen nähern.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Titanosaurus", "Titanosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Life was not meant to reach such sizes on land. This titan bears more resemblance to a force of nature than a beast.", "Das Leben an Land war nicht für solche Größen bestimmt. Dieser Titan gleicht eher einer Naturgewalt als einer Bestie.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tupandactylus", "Tupandactylus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The majestic Tupandactylus. Many flying creatures find themselves drawn to its exceptional crest.", "Der majestätische Tupandactylus. Viele fliegende Kreaturen fühlen sich von seinem außergewöhnlichen Kamm angezogen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tyrannosaurus", "Tyrannosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The infamous Tyrant Lizard King. Do you have the courage to oppose the largest land predator the world has ever seen?", "Der berüchtigte Tyrannenechsenkönig. Hast du den Mut, dich dem größten Landraubtier zu stellen, das die Welt je gesehen hat?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feathered Tyrannosaurus", "Gefiederter Tyrannosaurus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This whole...feather thing is getting out of hand. Have you considered that not every dinosaur was covered in them?", "Diese ganze ... Federsache gerät außer Kontrolle. Hast du bedacht, dass nicht jeder Dinosaurier damit bedeckt war?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Velocipastor", "Velocipastor", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I... uh... I'm afraid there's little I can say to explain this. It was worth the time.", "Ich ... äh ... Ich fürchte, ich kann das kaum erklären. Die Zeit war es wert.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woolly Mammoth", "Wollhaarmammut", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woolly Mammoth, an iconic beast of the Ice Age. They are never alone.", "Das Wollhaarmammut, eine typische Bestie der Eiszeit. Sie sind niemals allein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So many bones to claim...", "So viele Knochen einzusammeln ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deinosuchus Juvenile", "Deinosuchus-Jungtier", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A juvenile Deinosuchus. It is still growing, but it is already a fearsome predator.", "Ein junger Deinosuchus. Er wächst noch, ist aber bereits ein furchteinflößendes Raubtier.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deinosuchus", "Deinosuchus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deinosuchus, a fearsome apex predator. Not even prehistoric giants could escape from its jaws.", "Deinosuchus, ein furchteinflößender Spitzenprädator. Nicht einmal prähistorische Riesen konnten seinen Kiefern entkommen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater defense is more than sufficient.", "Mehr Verteidigung ist mehr als ausreichend.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not satisfied yet...", "Es ist noch nicht zufrieden ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Astonishing recovery.", "Erstaunliche Erholung.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The beast is offering comrades to assist you in this battle.", "Die Bestie bietet dir Gefährten an, die dich in diesem Kampf unterstützen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is getting out of hand.", "Das gerät außer Kontrolle.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is strength in numbers.", "Stärke durch Anzahl.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Something wicked lurks in these waters.", "Etwas Böses lauert in diesen Gewässern.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There are more of them now? End this before it gets any worse.", "Es gibt jetzt noch mehr davon? Beende es, bevor es schlimmer wird.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What a voracious little beast.", "Was für eine gefräßige kleine Bestie.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It still has room for growth.", "Es hat noch Raum zum Wachsen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What did you do to that beast?", "Was hast du dieser Bestie angetan?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's... It's Godzilla!!!", "Es ist ... Es ist Godzilla!!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's done being a victim.", "Es hat genug davon, ein Opfer zu sein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A feast for its kin.", "Ein Festmahl für seine Artgenossen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It still clings to its glory, unwilling to be surpassed.", "Es klammert sich an seinen Ruhm und will nicht übertroffen werden.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sauria Cards (Blood)", "Sauria-Karten (Blut)", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A collection of around [count] cards that cost Blood. Features a random assortment of prehistoric animals, mostly reptiles.", "Eine Sammlung von etwa [count] Karten, die Blut kosten. Sie enthält eine zufällige Auswahl prähistorischer Tiere, hauptsächlich Reptilien.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sauria Cards (Bones)", "Sauria-Karten (Knochen)", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A collection of around [count] cards that cost Bones. Features a random assortment of prehistoric animals, mostly reptiles.", "Eine Sammlung von etwa [count] Karten, die Knochen kosten. Sie enthält eine zufällige Auswahl prähistorischer Tiere, hauptsächlich Reptilien.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sauria Cards (Mixed)", "Sauria-Karten (gemischt)", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A collection of around [count] cards that cost Blood and Bones. Features a random assortment of prehistoric animals, mostly reptiles.", "Eine Sammlung von etwa [count] Karten, die Blut und Knochen kosten. Sie enthält eine zufällige Auswahl prähistorischer Tiere, hauptsächlich Reptilien.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ginormous Camarasaurus. Its great size allows it to fling beasts across the battlefield.", "Der riesige Camarasaurus. Seine Größe erlaubt ihm, Bestien über das Schlachtfeld zu schleudern.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Blood to increase Health of a card bearing this sigil by 1, then remove this sigil.", "Bezahle 1 Blut, um die Gesundheit einer Karte mit diesem Siegel um 1 zu erhöhen. Entferne danach dieses Siegel.", Language.German);


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue, the most reliable among the r... This beast shouldn't be human... Hm...", "Blue, die zuverlässigste unter den R... Diese Bestie sollte kein Mensch sein ... Hm ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Hm?[w:0.5]", "[e:Curious]Hm?[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]You're...[w:0.3][e:Anger] You're not Owen.[w:0.5]", "[e:Curious]Du bist ...[w:0.3][e:Anger] Du bist nicht Owen.[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I could tear you to bits right now[w:0.5].[w:0.5].[w:0.5].[w:0.5]", "[e:Anger]Ich könnte dich sofort in Stücke reißen[w:0.5].[w:0.5].[w:0.5].[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]But Owen doesn't like it when we do that.[w:0.5]", "[e:Anger]Aber Owen mag es nicht, wenn wir das tun.[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Maybe if he", "[e:Quiet]Vielleicht, wenn er", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Pleased to meet you!", "[e:Laughter]Freut mich, dich kennenzulernen!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Take good care of me and everything will be fine.", "[e:Neutral]Kümmere dich gut um mich, dann wird alles gut.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Hey there!", "[e:Neutral]Hallo!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I can make quick work of 'em.", "[e:Laughter]Mit denen mache ich kurzen Prozess.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Ready to go!", "[e:Neutral]Bereit!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]If you want them dead, let me know!", "[e:Laughter]Wenn sie sterben sollen, sag Bescheid!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Another task? I can handle it.", "[e:Neutral]Noch eine Aufgabe? Ich schaffe das.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]I've never been in a place like this...[w:0.5]", "[e:Curious]Ich war noch nie an einem solchen Ort ...[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]But hey, if there are no fences here[w:0.5]", "[e:Laughter]Aber wenn es hier keine Zäune gibt[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Then I don't need to restrain myself.", "[e:Quiet]Dann muss ich mich nicht zurückhalten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I don't get to just kill things often.", "[e:Laughter]Ich bekomme nicht oft die Gelegenheit, einfach zu töten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Roger that!", "[e:Laughter]Verstanden!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]I'm excited to tear into prey again.", "[e:Neutral]Ich freue mich darauf, wieder Beute zu zerreißen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Got it!", "[e:Neutral]Alles klar!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Weakness means death.", "[e:Quiet]Schwäche bedeutet Tod.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Consider it done!", "[e:Neutral]Betrachte es als erledigt!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Is this the right choice?", "[e:Curious]Ist das die richtige Wahl?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger][c:R]I'll remember this.[c:]", "[e:Anger][c:R]Das werde ich mir merken.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Don't expect to get away with this.", "[e:Quiet]Glaub nicht, dass du damit davonkommst.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]So be it.", "[e:Anger]Dann soll es so sein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Wuh?", "[e:Surprise]Hä?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Oooh, what's this?", "[e:Curious]Oh, was ist das?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]What's going to happen next?", "[e:Curious]Was passiert als Nächstes?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I trust your decisions.", "[e:Laughter]Ich vertraue deinen Entscheidungen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I don't feel like participating.", "[e:Anger]Ich habe keine Lust mitzumachen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]No.", "[e:Anger]Nein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Think again.", "[e:Anger]Denk noch mal nach.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Can't say I didn't expect this.[w:0.4]", "[e:Anger]Ich kann nicht sagen, dass ich das nicht erwartet hätte.[w:0.4]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]It's okay, I've done this with the rest of my pack", "[e:Neutral]Schon gut, das habe ich mit dem Rest meines Rudels", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]plenty of times, this is nothing", "[e:Neutral]schon oft getan, das ist nichts Besonderes", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]You're dead.", "[e:Anger]Du bist tot.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I did not appreciate that.", "[e:Anger]Das hat mir nicht gefallen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I'll return the favour.", "[e:Quiet]Das werde ich dir heimzahlen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Just a natural part of the hunt.", "[e:Neutral]Ein ganz natürlicher Teil der Jagd.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]I'll return the favour.", "[e:Neutral]Das werde ich dir heimzahlen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Oh, a test?[w:0.5]", "[e:Surprise]Oh, eine Prüfung?[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I've always been good at those!", "[e:Laughter]Darin war ich immer gut!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Is it done?", "[e:Curious]Ist es erledigt?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Did I do good?", "[e:Laughter]Habe ich das gut gemacht?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]How did it go?", "[e:Neutral]Wie ist es gelaufen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Ooooh...[w:0.5]", "[e:Surprise]Ooooh ...[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Don't mind if I do!", "[e:Laughter]Wenn du meinst, gern!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I've been looking forward to this.", "[e:Quiet]Darauf habe ich mich gefreut.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]You were simply not good enough.", "[e:Laughter]Du warst einfach nicht gut genug.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Where are the others?[w:0.3].[leshy:I might have made a mistake... Very well.][w:2]", "[e:Anger]Wo sind die anderen?[w:0.3].[leshy:Vielleicht habe ich einen Fehler gemacht ... Nun gut.][w:2]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Oh, hi!", "[e:Laughter]Oh, hallo!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Didn't expect to see you again!", "[e:Laughter]Ich hätte nicht erwartet, dich wiederzusehen!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How are you?", "Wie geht es dir?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Huh?", "[e:Surprise]Hä?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I'll remember this.", "[e:Anger]Das werde ich mir merken.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Don't get cocky.", "[e:Anger]Werd nicht übermütig.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Angry]I don't like the way he smells...[w:0.5]", "[e:Angry]Ich mag seinen Geruch nicht ...[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Let's kill him!", "[e:Laughter]Töten wir ihn!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This guy...[w:0.5]", "[e:Anger]Dieser Kerl ...[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Make it hurt this time.", "[e:Neutral]Diesmal soll es wehtun.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I hate the noise.", "[e:Anger]Ich hasse den Lärm.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Kill him.", "[e:Anger]Töte ihn.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Fish...[w:0.3]?[w:0.5]", "[e:Surprise]Fisch ...[w:0.3]?[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]I never really liked that stuff.[w:0.3]", "[e:Neutral]Das mochte ich noch nie besonders.[w:0.3]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I'll eat him instead.", "[e:Quiet]Ich fresse stattdessen ihn.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I won't fall for his tricks.", "[e:Anger]Ich falle nicht auf seine Tricks herein.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Can't even enjoy eating him...", "[e:Anger]Ich kann es nicht einmal genießen, ihn zu fressen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]We've done this before, let's kill him again!", "[e:Neutral]Das haben wir schon getan, töten wir ihn noch einmal!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Wuh?[w:0.5] He wasn't on our side?[w:0.5]", "[e:Curious]Hä?[w:0.5] Er war nicht auf unserer Seite?[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Then I can kill him?", "[e:Quiet]Dann darf ich ihn töten?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Oh, the two-faced guy again! Let's beat him up!", "[e:Laughter]Oh, schon wieder der Kerl mit den zwei Gesichtern! Verprügeln wir ihn!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Two birds with one stone!", "[e:Laughter]Zwei Fliegen mit einer Klappe!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Let's get rid of him.", "[e:Neutral]Werden wir ihn los.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Oh, this is the end?[w:0.5]", "[e:Curious]Oh, ist das das Ende?[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Well, it's been fun.[w:0.5]", "[e:Neutral]Nun, es hat Spaß gemacht.[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]We'll see each other again, right?[w:0.5]", "[e:Neutral]Wir sehen uns wieder, oder?[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I hope we get to have a good time later!", "[e:Laughter]Ich hoffe, wir haben später noch viel Spaß!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]The finale![w:0.5]", "[e:Laughter]Das Finale![w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]This should be fun!", "[e:Neutral]Das dürfte Spaß machen!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]It sucks having to part ways...[w:0.5]", "[e:Anger]Es ist mies, dass wir uns trennen müssen ...[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I hope to see you again!", "[e:Laughter]Ich hoffe, wir sehen uns wieder!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Let's end this with a bang!", "[e:Laughter]Beenden wir das mit einem Knall!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]I think...[w:0.3]", "[e:Curious]Ich glaube ...[w:0.3]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]I think I've seen somebody like this before.[w:0.5]", "[e:Curious]Ich glaube, ich habe schon mal jemanden wie ihn gesehen.[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Owen scolded me for snarling at that guy.", "[e:Anger]Owen hat mich ausgeschimpft, weil ich den Kerl angeknurrt habe.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I'd rather not deal with those cannons.", "[e:Anger]Ich würde mich lieber nicht mit diesen Kanonen anlegen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Not again...", "[e:Anger]Nicht schon wieder ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This isn't particularly fun.", "[e:Anger]Das macht nicht besonders viel Spaß.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Oh, what's this?[w:0.5]", "[e:Surprise]Oh, was ist das?[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Well, I guess my task is still the same!", "[e:Laughter]Nun, meine Aufgabe ist wohl immer noch dieselbe!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]I like when they struggle more.", "[e:Neutral]Ich mag es, wenn sie sich stärker wehren.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Oh, this one looks fun!", "[e:Laughter]Oh, der sieht lustig aus!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Let's just kill them.", "[e:Neutral]Töten wir sie einfach.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Oh, another one!", "[e:Laughter]Oh, noch einer!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]What will it be this time?", "[e:Neutral]Was wird es diesmal sein?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]This woman?[w:0.5]", "[e:Surprise]Diese Frau?[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Owen always told me to be more gentle with the elderly.[w:0.4]", "[e:Neutral]Owen sagte immer, ich solle mit älteren Leuten sanfter umgehen.[w:0.4]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Y'know, don't startle them and all that?[w:0.5]", "[e:Neutral]Du weißt schon, sie nicht erschrecken und so?[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I didn't listen.", "[e:Quiet]Ich habe nicht zugehört.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Weakness means death.", "[e:Laughter]Schwäche bedeutet Tod.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]If she's our enemy, then we should kill her!", "[e:Laughter]Wenn sie unsere Feindin ist, sollten wir sie töten!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]No hesitation!", "[e:Neutral]Kein Zögern!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I've never liked their smell.[w:0.5]", "[e:Anger]Ich mochte ihren Geruch noch nie.[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Reminded me of him.[w:0.3]", "[e:Anger]Er erinnerte mich an ihn.[w:0.3]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Now, let's kill them!", "[e:Laughter]Jetzt töten wir sie!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]More faces means more to bite!", "[e:Neutral]Mehr Gesichter bedeuten mehr zum Zubeißen!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]You think they'll live with one of his faces clawed off?", "[e:Curious]Glaubst du, sie überleben es, wenn ich ihm eines seiner Gesichter mit den Krallen abreiße?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]I wonder if he'll feel spongy...", "[e:Neutral]Ob er sich wohl schwammig anfühlt ...", Language.German);


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm... Maybe something got mixed up in there...", "Hm ... Vielleicht wurde da etwas durcheinandergebracht ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You.[w:0.5]", "Du.[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't know who you are.", "Ich weiß nicht, wer du bist.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't particularly care either.", "Es ist mir auch ziemlich egal.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Either you get me out of this mess or[w:0.5].[w:0.5].[w:0.5][e:Laughter].[w:0.5]", "Entweder holst du mich aus diesem Schlamassel oder[w:0.5].[w:0.5].[w:0.5][e:Laughter].[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]No, I [e:Quiet]don't[w:0.5][e:Laughter] need to spell it out.[w:0.5]", "[e:Laughter]Nein, ich muss es [e:Quiet]nicht[w:0.5][e:Laughter] ausbuchstabieren.[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet][c:R]Know your place and you will live.[c:]", "[e:Quiet][c:R]Kenn deinen Platz, dann wirst du leben.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Make it quick.", "[e:Neutral]Mach schnell.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Morsels, all for me.", "[e:Laughter]Leckerbissen, alle für mich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]A fine opportunity.", "[e:Neutral]Eine gute Gelegenheit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Now is a good time to feed me.", "[e:Laughter]Jetzt wäre ein guter Zeitpunkt, mich zu füttern.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Good timing. I was feeling quite peckish.", "[e:Laughter]Gutes Timing. Ich hatte gerade etwas Hunger.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I've been looking for something", "[e:Laughter]Ich suche schon nach etwas", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]to tear into since I got into this mess.", "[e:Laughter]zum Zerreißen, seit ich in diesen Schlamassel geraten bin.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I won't make it quick.", "[e:Quiet]Ich werde mir Zeit lassen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I won't leave anything behind.", "[e:Laughter]Ich werde nichts übrig lassen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]A feast, just for me.", "[e:Laughter]Ein Festmahl, nur für mich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Don't expect to survive.", "[e:Neutral]Erwarte nicht zu überleben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Who wishes to die first?", "[e:Quiet]Wer möchte zuerst sterben?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I've been itching for a fight.", "[e:Quiet]Ich brenne darauf zu kämpfen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Are you sure about this choice?", "[e:Curious]Bist du dir bei dieser Wahl sicher?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger][c:R]You traitor!!![c:]", "[e:Anger][c:R]Du Verräter!!![c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I'll remember this.", "[e:Quiet]Das werde ich mir merken.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger][c:R]You bastard!!![c:]", "[e:Anger][c:R]Du Mistkerl!!![c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise][c:R]You...![c:]", "[e:Surprise][c:R]Du ...![c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Oh, what's this now?", "[e:Curious]Oh, was ist das nun?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Who will die this time?", "[e:Curious]Wer wird diesmal sterben?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]There is only one correct choice.", "[e:Laughter]Es gibt nur eine richtige Wahl.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Do not make any choices I would make you regret.", "[e:Quiet]Triff keine Wahl, die ich dich bereuen lassen würde.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Let's get this done and over with.", "[e:Neutral]Bringen wir es hinter uns.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Pick anyone else.", "[e:Neutral]Wähle irgendjemand anderen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]You did this on purpose...[w:0.4]", "[e:Anger]Das hast du mit Absicht getan ...[w:0.4]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:R]Didn't you!?[c:][w:0.5]", "[c:R]Nicht wahr!?[c:][w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]I'll let it slide for now.", "[e:Neutral]Diesmal lasse ich es durchgehen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger][c:R]You dare...![c:]", "[e:Anger][c:R]Wie kannst du es wagen ...![c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger][c:R]I'll tear you limb from limb!!![c:]", "[e:Anger][c:R]Ich reiße dich Glied für Glied auseinander!!![c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]You've made your choice.", "[e:Quiet]Du hast deine Wahl getroffen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Tsk!", "[e:Anger]Tss!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Gh!", "[e:Anger]Grr!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Is this some kind of a test?[w:0.5]", "[e:Surprise]Ist das eine Art Prüfung?[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I don't expect to fail.", "[e:Laughter]Ich erwarte nicht zu scheitern.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Are we done?", "[e:Curious]Sind wir fertig?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I shall aid you.", "[e:Laughter]Ich werde dir helfen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Waste of my time.", "[e:Neutral]Verschwendung meiner Zeit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Interesting...[w:0.5]", "[e:Curious]Interessant ...[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]There are enough voices screaming from within my blood.", "[e:Neutral]In meinem Blut schreien bereits genug Stimmen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]What's another one?", "[e:Quiet]Was macht da eine weitere aus?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Become a part of me.", "[e:Laughter]Werde ein Teil von mir.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I shall claim your power.", "[e:Quiet]Ich werde mir deine Kraft nehmen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]It is only natural.", "[e:Laughter]Das ist nur natürlich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger][c:R]What did you do to me!?[c:][w:0.5].[leshy:It appears that this beast is... more human than it appeared. No matter.][w:2]", "[e:Anger][c:R]Was hast du mir angetan!?[c:][w:0.5].[leshy:Diese Bestie scheint ... menschlicher zu sein, als es den Anschein hatte. Einerlei.][w:2]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]We meet again.", "[e:Laughter]Wir treffen uns wieder.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]You shall serve me once more.", "[e:Laughter]Du wirst mir wieder dienen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do not disappoint me this time.", "Enttäusche mich diesmal nicht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]No, you can't...!", "[e:Surprise]Nein, das kannst du nicht ...!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Curse you!!!", "[e:Anger]Sei verflucht!!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I will remember this!!!", "[e:Anger]Das werde ich mir merken!!!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]What an eyesore...", "[e:Neutral]Was für ein Schandfleck ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Get rid of him.[w:0.5]", "Schaff ihn mir aus den Augen.[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The noise bothers me.", "Der Lärm stört mich.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]You...[w:0.5]", "[e:Anger]Du ...[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Do not make the same mistakes.", "[e:Neutral]Mach nicht dieselben Fehler.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This noise again...", "[e:Anger]Schon wieder dieser Lärm ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Get him out of my sight.", "[e:Anger]Schaff ihn mir aus den Augen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]This...[w:0.5] This smell...[w:0.5]", "[e:Surprise]Dieser ...[w:0.5] Dieser Geruch ...[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]I remember a smell like this...[w:0.5]", "[e:Surprise]Ich erinnere mich an einen solchen Geruch ...[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]We must get out of here.", "[e:Surprise]Wir müssen hier raus.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Don't let those things near me!", "[e:Surprise]Lass diese Dinger nicht in meine Nähe!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]I won't die like this again!", "[e:Surprise]Ich sterbe nicht noch einmal auf diese Weise!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]There's something lurking in the waters...", "[e:Surprise]Etwas lauert im Wasser ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I have little patience for traitors.[w:0.5]", "[e:Anger]Ich habe wenig Geduld mit Verrätern.[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet][c:R]Skin him alive.[c:]", "[e:Quiet][c:R]Häute ihn bei lebendigem Leib.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]He'll make for a fine pelt.", "[e:Laughter]Aus ihm wird ein schönes Fell.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]The smell in the air is pleasant.", "[e:Laughter]Der Geruch in der Luft ist angenehm.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet][c:R]Let's enrich it further with his blood.[c:]", "[e:Quiet][c:R]Reichern wir ihn weiter mit seinem Blut an.[c:]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]You should know how this works by now.", "[e:Laughter]Du solltest inzwischen wissen, wie das funktioniert.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]This is it...[w:0.5]", "[e:Curious]Jetzt ist es so weit ...[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]We've made it this far.[w:0.5]", "[e:Neutral]Wir sind so weit gekommen.[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I suppose you weren't too bad.[w:0.5]", "Ich nehme an, du warst nicht allzu schlecht.[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I won't miss you[w:0.5], but I've seen worse humans.[w:0.5]", "Ich werde dich nicht vermissen[w:0.5], aber ich habe schlimmere Menschen gesehen.[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Let's put an end to his games.", "[e:Quiet]Beenden wir seine Spielchen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]You can do this.[w:0.5]", "[e:Laughter]Du schaffst das.[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Be of service to me once again.", "[e:Laughter]Diene mir noch einmal.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]We shall part soon.[w:0.5]", "[e:Laughter]Bald werden sich unsere Wege trennen.[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I hope to see you again.", "[e:Laughter]Ich hoffe, wir sehen uns wieder.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]It's been fun so far.[w:0.5]", "[e:Laughter]Bisher hat es Spaß gemacht.[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Let's have some more fun in the future.", "[e:Laughter]Haben wir künftig noch mehr Spaß zusammen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Not...[w:0.5] Not the water again...[w:0.5]", "[e:Surprise]Nicht ...[w:0.5] Nicht schon wieder das Wasser ...[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]What will attack me this time?", "[e:Surprise]Was wird mich diesmal angreifen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I don't appreciate getting shot with cannons. Kill him quickly.", "[e:Anger]Ich mag es nicht, mit Kanonen beschossen zu werden. Töte ihn schnell.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This moron again...", "[e:Anger]Schon wieder dieser Idiot ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]There isn't even anything to gnaw on.", "[e:Anger]Es gibt nicht einmal etwas zum Nagen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]The air is different.[w:0.5]", "[e:Surprise]Die Luft ist anders.[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]They are prey all the same.", "[e:Laughter]Sie sind dennoch alle Beute.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]What a chore.", "[e:Neutral]Was für eine Plage.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Perhaps something bigger to chew on?", "[e:Laughter]Vielleicht etwas Größeres zum Kauen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Eyesore.", "[e:Neutral]Ein Schandfleck.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]This changes nothing.", "[e:Laughter]Das ändert nichts.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]They should know their place.", "[e:Laughter]Sie sollten ihren Platz kennen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Hmph.[w:0.5]", "[e:Neutral]Hmpf.[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]This foolish hag has outlived her usefulness.[w:0.5]", "[e:Neutral]Diese törichte Alte hat ihren Nutzen überlebt.[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Her skull would be a fine decoration for a totem.", "[e:Quiet]Ihr Schädel wäre eine schöne Verzierung für ein Totem.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Let's shave off what few years she has left.", "[e:Laughter]Verkürzen wir die wenigen Jahre, die ihr noch bleiben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]One foot in the grave, another soon to come.", "[e:Laughter]Ein Fuß steht im Grab, der andere folgt bald.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]She'd die in a few years regardless.", "[e:Laughter]In ein paar Jahren würde sie ohnehin sterben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Not particularly surprising.[w:0.5]", "[e:Neutral]Nicht besonders überraschend.[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]These experimental types don't know loyalty.[w:0.5]", "[e:Neutral]Diese experimentellen Typen kennen keine Loyalität.[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I'd rather get my claws on that bastard Wu", "[e:Quiet]Ich würde lieber meine Klauen in diesen Mistkerl Wu schlagen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]but this shall do for now.", "[e:Laughter]aber das muss vorerst genügen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Let's return the favour.", "[e:Neutral]Zahlen wir es ihm heim.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]There won't be much left to stitch together.", "[e:Laughter]Es wird nicht viel zum Zusammennähen übrig bleiben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Two heads to tear off.[e:Quiet]What a treat.", "[e:Neutral]Zwei Köpfe zum Abreißen.[e:Quiet]Was für ein Genuss.", Language.German);


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Owen", "Owen", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A human? ...No matter. I have a feeling this man will prove himself capable against claws and fangs of your opponents.", "Ein Mensch? ... Einerlei. Ich habe das Gefühl, dieser Mann wird sich gegen Klauen und Zähne deiner Gegner behaupten.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]I don't know what this whole thing is about[w:0.3]", "[e:Curious]Ich weiß nicht, worum es hier geht[w:0.3]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]but we'll make it", "[e:Laughter]aber wir schaffen das", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]trust me.", "[e:Laughter]vertrau mir.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Stay on guard.", "[e:Anger]Bleib wachsam.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]So much for taking a break, huh.", "[e:Laughter]So viel zur Pause, was?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]You can count on me.", "[e:Laughter]Du kannst auf mich zählen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Let's hope working at Jurassic World didn't make me rusty...", "[e:Quiet]Hoffentlich hat mich die Arbeit in Jurassic World nicht einrosten lassen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I don't like doing this, but it's us or them here.", "[e:Anger]Ich tue das nicht gern, aber hier geht es um uns oder sie.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This rifle better not act up on me now...", "[e:Anger]Dieses Gewehr sollte mich jetzt besser nicht im Stich lassen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Let's do this.", "[e:Neutral]Los geht's.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Gotta focus if we both want to keep our skins.", "[e:Quiet]Wir müssen uns konzentrieren, wenn wir beide unsere Haut retten wollen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Not sure about this position, but I can make it work.", "[e:Quiet]Ich bin mir bei dieser Position nicht sicher, aber ich komme damit zurecht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Now would be a bad time to forget my training.", "[e:Quiet]Jetzt wäre ein schlechter Zeitpunkt, meine Ausbildung zu vergessen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Wait, what are you doing!?", "[e:Surprise]Warte, was tust du da!?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Huh, why me?", "[e:Surprise]Hä, warum ich?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I haven't told her I-", "[e:Anger]Ich habe ihr noch nicht gesagt, dass ich ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]What kind of-", "[e:Anger]Was für ein ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Whatever this is, I don't like it.", "[e:Anger]Was auch immer das ist, es gefällt mir nicht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I'd rather sit this one out.", "[e:Quiet]Ich würde das lieber aussetzen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]If I have to...", "[e:Quiet]Wenn es sein muss ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I have a bad feeling about this one.", "[e:Anger]Ich habe ein ungutes Gefühl dabei.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Could you pick anyone else?", "[e:Quiet]Könntest du jemand anderen wählen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I'd rather not...", "[e:Quiet]Ich würde lieber nicht ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Damn...[w:0.3]", "[e:Anger]Verdammt ...[w:0.3]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]The situation is worse than I thought.[w:0.3]", "[e:Anger]Die Lage ist schlimmer als gedacht.[w:0.3]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I can still handle this, don't worry.", "[e:Laughter]Ich komme noch klar, keine Sorge.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Shit!", "[e:Anger]Scheiße!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This will leave a mark.", "[e:Anger]Das wird eine Narbe geben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Sure, I could use another scar.", "[e:Anger]Klar, eine Narbe mehr kann ich gut gebrauchen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Ow!", "[e:Anger]Aua!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Tsk, got careless.", "[e:Anger]Tss, ich war unvorsichtig.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]A trial?[w:0.3]", "[e:Surprise]Eine Prüfung?[w:0.3]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Well, did we pass it?", "[e:Curious]Nun, haben wir bestanden?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]How did we do?", "[e:Curious]Wie haben wir uns geschlagen?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I have a good feeling about this one.", "[e:Laughter]Ich habe ein gutes Gefühl dabei.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I didn't just blow it, did I?", "[e:Quiet]Ich habe es doch nicht vermasselt, oder?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Me?[w:0.3]", "[e:Surprise]Ich?[w:0.3]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Well... Sorry, buddy", "[e:Quiet]Nun ... Tut mir leid, Kumpel", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]but it looks like there's no other choice.", "[e:Quiet]aber es scheint keine andere Wahl zu geben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I hate doing this.", "[e:Quiet]Ich hasse es, das zu tun.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]If we want to survive...", "[e:Quiet]Wenn wir überleben wollen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Really wish we could avoid this, but...", "[e:Quiet]Ich würde das wirklich gern vermeiden, aber ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]What is this place?[w:0.3]", "[e:Curious]Was ist das für ein Ort?[w:0.3]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Well, you look like a reasonable fellow.", "[e:Laughter]Nun, du siehst nach einem vernünftigen Kerl aus.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]If we stick together", "[e:Laughter]Wenn wir zusammenhalten", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]we can escape in one piece", "[e:Laughter]kommen wir an einem Stück hier raus", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Hello again.", "[e:Laughter]Hallo nochmal.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Did you miss me?", "[e:Laughter]Hast du mich vermisst?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guess we're doing this again...", "Sieht aus, als machen wir das noch einmal ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Hold on, this looks bad!", "[e:Surprise]Moment, das sieht übel aus!", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]A prospector?[w:0.5]", "[e:Curious]Ein Goldgräber?[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This feels like some kind of an attraction[w:0.5]", "Das fühlt sich wie eine Art Attraktion an[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]But we won't be having fun here, are we?", "[e:Anger]Aber wir werden hier keinen Spaß haben, oder?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This guy again?[w:0.3]", "[e:Anger]Schon wieder dieser Kerl?[w:0.3]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Let's be a bit more careful this time.", "[e:Anger]Seien wir diesmal etwas vorsichtiger.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I'll keep hearing this ringing for the rest of my life.", "[e:Anger]Dieses Klingeln werde ich mein Leben lang hören.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]You know what's gonna happen soon. Get ready.", "[e:Anger]Du weißt, was gleich passiert. Mach dich bereit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Woah![w:0.5]", "[e:Surprise]Wow![w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]This guy's huge![w:0.5]", "[e:Surprise]Der Kerl ist riesig![w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]But I've dealt with bigger fish than this.", "[e:Laughter]Aber ich habe schon größere Fische bezwungen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Let's do this.", "[e:Laughter]Los geht's.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]This guy again...[w:0.3]", "[e:Curious]Schon wieder dieser Kerl ...[w:0.3]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]We've done this before, let's get him.", "[e:Laughter]Das haben wir schon geschafft, schnappen wir ihn uns.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]You know...[w:0.3]", "[e:Anger]Weißt du ...[w:0.3]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]maybe I don't need to feel so bad about the sharks we fed to that thing.", "[e:Anger]Vielleicht muss ich mich wegen der Haie, die wir diesem Ding verfüttert haben, nicht so schlecht fühlen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]The smell doesn't get any better...", "[e:Anger]Der Geruch wird nicht besser ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I knew something was off[w:0.3]", "[e:Anger]Ich wusste, dass etwas nicht stimmt[w:0.3]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Guess I've got a good grasp of people too.", "[e:Laughter]Ich kann Menschen wohl auch gut einschätzen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Get ready.", "[e:Laughter]Mach dich bereit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Nothing to worry about", "[e:Laughter]Kein Grund zur Sorge", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I can disarm the traps from afar.", "[e:Laughter]ich kann die Fallen aus der Ferne entschärfen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]We shouldn't have any trouble at all.", "[e:Laughter]Wir sollten überhaupt keine Probleme haben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Here we go.", "[e:Laughter]Los geht's.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]If you don't want to sacrifice anybody", "[e:Laughter]Wenn du niemanden opfern willst", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]let me get rid of these things myself.", "[e:Laughter]lass mich diese Dinger selbst beseitigen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]So this is the guy behind everything?[w:0.3]", "[e:Curious]Das ist also der Kerl hinter allem?[w:0.3]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Not sure what I was expecting", "[e:Curious]Ich weiß nicht, was ich erwartet habe", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]But it doesn't matter.[w:0.3]", "[e:Anger]Aber das ist egal.[w:0.3]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Let's end this.", "[e:Anger]Bringen wir es zu Ende.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]We've done this before", "[e:Laughter]Das haben wir schon getan", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]let's do it again.", "[e:Laughter]tun wir es wieder.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This guy's no joke.", "[e:Anger]Mit diesem Kerl ist nicht zu spaßen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Don't let your guard down.", "[e:Anger]Lass deine Deckung nicht fallen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]We've got this, don't worry.", "[e:Laughter]Wir schaffen das, keine Sorge.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]A...[w:0.3]pirate?", "[e:Surprise]Ein ...[w:0.3] Pirat?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Hah, good one![w:0.3]", "[e:Laughter]Ha, guter Witz![w:0.3]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Well, there's only one thing left to do.", "[e:Laughter]Nun, es bleibt nur noch eine Sache zu tun.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Watch out for the cannons.", "[e:Anger]Achte auf die Kanonen.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This will be tough, but we can do this.", "[e:Anger]Das wird hart, aber wir schaffen das.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This guy isn't playing around, stay on guard.", "[e:Anger]Der Kerl macht keine Scherze, bleib wachsam.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Is this some kind of...[w:0.5] Magic?[w:0.5]", "[e:Surprise]Ist das eine Art ...[w:0.5] Magie?[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Well, I guess this is going to get much weirder.", "[e:Quiet]Nun, ich schätze, es wird noch viel seltsamer.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]They're getting empowered. Stay alert.", "[e:Anger]Sie werden stärker. Bleib wachsam.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Not this thing again...", "[e:Anger]Nicht schon wieder dieses Ding ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]How come I don't get fancy toys like this?", "[e:Curious]Warum bekomme ich keine schicken Spielzeuge wie dieses?", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Just a little handicap, nothing more.", "[e:Laughter]Nur ein kleiner Nachteil, mehr nicht.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Let's not give up just yet.", "[e:Laughter]Geben wir noch nicht auf.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]What?[w:0.5] You of all people?[w:0.5]", "[e:Surprise]Was?[w:0.5] Ausgerechnet du?[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]I wish it didn't come down to this, but...[w:0.3]", "[e:Neutral]Ich wünschte, es wäre nicht so weit gekommen, aber ...[w:0.3]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Guess we've got no choice.", "[e:Quiet]Wir haben wohl keine Wahl.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This one's tough. Get ready.", "[e:Anger]Der ist zäh. Mach dich bereit.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]One wrong move and we're done for.", "[e:Anger]Ein falscher Zug und es ist aus mit uns.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I really don't like dealing with her...", "[e:Anger]Ich lege mich wirklich nicht gern mit ihr an ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I always got bad vibes from these guys.[w:0.5]", "[e:Anger]Diese Typen haben mir schon immer ein schlechtes Gefühl gegeben.[w:0.5]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I've seen people like them.[w:0.3]", "[e:Anger]Ich habe schon Leute wie sie gesehen.[w:0.3]", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Whatever drives them,", "[e:Anger]Was immer sie antreibt,", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]we can get through just fine.", "[e:Laughter]wir kommen gut hindurch.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]These guys again...", "[e:Neutral]Schon wieder diese Typen ...", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Come on, we didn't get this far just to kick the bucket here.", "[e:Laughter]Komm, wir sind nicht so weit gekommen, um hier den Löffel abzugeben.", Language.German);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]This is getting dangerous. Get ready.", "[e:Neutral]Es wird gefährlich. Mach dich bereit.", Language.German);


        }
    }
}
